# 🆕 NOUVEAU : Sous-matières — chaque matière (ex: Arabe) peut être décomposée en plusieurs
# sous-matières (ex: Dictée, Participation, Conjugaison...), chacune avec son propre coefficient.
# Une note peut désormais être rattachée à une sous-matière précise (sous_matiere_id sur "notes"),
# tout en restant compatible avec les notes existantes (sous_matiere_id NULL = note "globale" de la matière).
def upgrade_db_sous_matieres():
    conn = get_db()
    try:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS sous_matieres (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                matiere_id INTEGER NOT NULL,
                nom TEXT NOT NULL,
                coefficient REAL DEFAULT 1,
                actif INTEGER DEFAULT 1,
                ordre INTEGER DEFAULT 0,
                FOREIGN KEY (matiere_id) REFERENCES matieres (id) ON DELETE CASCADE
            )
        """)
        conn.commit()
    except sqlite3.OperationalError:
        pass

    # 🔧 FIX ROBUSTE : si la table "sous_matieres" existait déjà avec un schéma incomplet
    # (créée par une version antérieure/partielle), on la RECONSTRUIT proprement plutôt que
    # de dépendre d'ALTER TABLE (qui peut échouer silencieusement selon la version de SQLite
    # ou l'état exact de la table). On récupère les données déjà présentes avant de reconstruire.
    try:
        cols_info = conn.execute("PRAGMA table_info(sous_matieres)").fetchall()
        existing_cols = {c[1] for c in cols_info}
    except sqlite3.OperationalError:
        existing_cols = set()
    expected_cols = {'id', 'matiere_id', 'nom', 'coefficient', 'actif', 'ordre'}
    if not expected_cols.issubset(existing_cols):
        try:
            conn.execute("ALTER TABLE sous_matieres RENAME TO sous_matieres_old_tmp")
            conn.execute("""
                CREATE TABLE sous_matieres (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    matiere_id INTEGER NOT NULL,
                    nom TEXT NOT NULL,
                    coefficient REAL DEFAULT 1,
                    actif INTEGER DEFAULT 1,
                    ordre INTEGER DEFAULT 0
                )
            """)
            # On ne recopie que les colonnes qui existaient réellement dans l'ancienne table,
            # les colonnes manquantes reprendront leur valeur par défaut (coefficient=1, etc.)
            common_cols = [c for c in ('id', 'matiere_id', 'nom', 'coefficient', 'actif', 'ordre')
                           if c in existing_cols]
            if common_cols:
                collist = ", ".join(common_cols)
                conn.execute(f"INSERT INTO sous_matieres ({collist}) SELECT {collist} FROM sous_matieres_old_tmp")
            conn.execute("DROP TABLE sous_matieres_old_tmp")
            conn.commit()
        except sqlite3.OperationalError as ex:
            conn.rollback()
            print(f"  ⚠️  Impossible de réparer automatiquement la table sous_matieres : {ex}")

    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_sous_matieres_matiere_id ON sous_matieres(matiere_id)")
        conn.commit()
    except sqlite3.OperationalError:
        pass
    try:
        conn.execute("ALTER TABLE notes ADD COLUMN sous_matiere_id INTEGER REFERENCES sous_matieres(id)")
        conn.commit()
    except sqlite3.OperationalError:
        pass  # Colonne déjà existante
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_notes_sous_matiere_id ON notes(sous_matiere_id)")
        conn.commit()
    except sqlite3.OperationalError:
        pass

    # 🩹 CORRECTIF (filet de sécurité) : si pour une raison quelconque la colonne "coefficient"
    # manque ENCORE à ce stade (ex : la réparation par RENAME/rebuild ci-dessus a échoué en
    # cours de route et a fait un rollback qui a annulé le rebuild), on l'ajoute directement
    # avec un simple ALTER TABLE. C'est beaucoup plus robuste que le rebuild par renommage et
    # ça garantit que /analyse-notes ne peut plus planter avec "no such column: sm.coefficient".
    try:
        cols_final = {c[1] for c in conn.execute("PRAGMA table_info(sous_matieres)").fetchall()}
    except sqlite3.OperationalError:
        cols_final = set()
    if 'coefficient' not in cols_final:
        try:
            conn.execute("ALTER TABLE sous_matieres ADD COLUMN coefficient REAL DEFAULT 1")
            conn.commit()
            print("  🩹 Colonne 'coefficient' ajoutée à sous_matieres via le filet de sécurité.")
        except sqlite3.OperationalError as ex_fallback:
            print(f"  ❌ Échec de l'ajout de la colonne coefficient à sous_matieres : {ex_fallback}")

    conn.close()


# 🆕 NOUVEAU : Système d'évaluation par lettres (A/B/C) pour le cycle Maternelle.
# Les tout-petits ne sont pas notés sur 20 : on utilise 3 niveaux qualitatifs.
# En interne, on continue de stocker une valeur numérique dans la colonne `notes.note`
# (pour rester compatible avec tout le moteur de calcul existant : moyennes, bulletins,
# graphiques...), mais on la convertit en lettre à la saisie et à l'affichage pour ce cycle.
NOTE_LETTRES_MATERNELLE = {'A': 16.0, 'B': 10.0, 'C': 4.0}
LIBELLES_LETTRES_MATERNELLE = {'A': 'Bon', 'B': 'Moyen', 'C': 'Bas'}


def _lettre_depuis_note(note):
    """Convertit une note numérique interne (échelle /20) en lettre A/B/C (Maternelle)."""
    if note is None:
        return ''
    try:
        note = float(note)
    except (TypeError, ValueError):
        return ''
    if note >= 13:
        return 'A'
    elif note >= 7:
        return 'B'
    else:
        return 'C'


def _libelle_lettre(note):
    """Ex: 16 -> 'A — Bon'."""
    l = _lettre_depuis_note(note)
    if not l:
        return ''
    return f"{l} — {LIBELLES_LETTRES_MATERNELLE[l]}"


# 🆕 NOUVEAU : Helper central pour la moyenne pondérée à deux niveaux (sous-matière puis matière),
# utilisé partout où une moyenne d'élève est calculée (fiche élève, bulletin PDF, espace parent,
# espace enseignant, classement de classe...) afin que le résultat soit toujours cohérent.
# Chaque ligne de `notes_rows` doit exposer au minimum : note, coefficient (coef matière),
# matiere (nom) ou matiere_id, sous_matiere_id, sm_coefficient.
def _moyenne_ponderee_matieres(notes_rows):
    par_matiere = {}
    for n in notes_rows:
        keys = n.keys()
        cle = n['matiere_id'] if 'matiere_id' in keys else n['matiere']
        nom = n['matiere'] if 'matiere' in keys else str(cle)
        coef_mat = n['coefficient'] if n['coefficient'] else 1
        d = par_matiere.setdefault(cle, {'nom': nom, 'coef_matiere': coef_mat, 'pts': 0.0, 'coef_sum': 0.0})
        sous_id = n['sous_matiere_id'] if 'sous_matiere_id' in keys else None
        sm_coef = n['sm_coefficient'] if 'sm_coefficient' in keys else None
        coef_sm = sm_coef if (sous_id and sm_coef) else 1
        d['pts'] += n['note'] * coef_sm
        d['coef_sum'] += coef_sm
    total_pts, total_coef = 0.0, 0.0
    moys_par_matiere = {}
    for d in par_matiere.values():
        moy = d['pts'] / d['coef_sum'] if d['coef_sum'] else 0
        moys_par_matiere[d['nom']] = moy
        total_pts += moy * d['coef_matiere']
        total_coef += d['coef_matiere']
    moyenne = round(total_pts / total_coef, 2) if total_coef else 0
    return moyenne, moys_par_matiere


# 🆕 NOUVEAU : Sous-requête SQL réutilisable pour classer les élèves d'une classe en tenant
# compte du coefficient des sous-matières PUIS du coefficient des matières (même logique que
# _moyenne_ponderee_matieres, mais calculée côté SQL pour rester performante sur un classement).
SQL_CLASSEMENT_PONDERE = """
    SELECT e.id,
           SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) AS moyenne
    FROM eleves e
    LEFT JOIN (
        SELECT eleve_id, matiere_id, coef_matiere,
               SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) AS matiere_moy
        FROM (
            SELECT n.eleve_id, n.matiere_id, m.coefficient AS coef_matiere, n.note,
                   COALESCE(sm.coefficient, 1) AS coef_sm
            FROM notes n
            JOIN matieres m ON m.id = n.matiere_id
            LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
        ) raw
        GROUP BY eleve_id, matiere_id, coef_matiere
    ) y ON y.eleve_id = e.id
    WHERE e.classe_id = ?
    GROUP BY e.id
    HAVING moyenne IS NOT NULL
    ORDER BY moyenne DESC
"""


# 🆕 NOUVEAU : Helper Python réutilisable — moyenne pondérée (sous-matière puis matière) de
# TOUS les élèves ayant au moins une note correspondant au filtre `where_notes` (appliqué sur
# les notes n, jointes à matieres m / eleves e / classes c / users u). Utilisé partout où l'on
# a besoin d'un classement, d'une moyenne d'établissement/de classe, ou d'un contexte IA basé
# sur les notes (chatbot WhatsApp, exports PDF/Excel, dataset analyse avancée...).
def _eleves_moyennes_ponderees(conn, where_notes="1=1", params=()):
    rows = conn.execute(f"""
        SELECT y.eleve_id as eleve_id,
               SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) AS moyenne
        FROM (
            SELECT eleve_id, matiere_id, coef_matiere,
                   SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) AS matiere_moy
            FROM (
                SELECT n.eleve_id, n.matiere_id, m.coefficient AS coef_matiere, n.note,
                       COALESCE(sm.coefficient, 1) AS coef_sm
                FROM notes n
                JOIN matieres m ON m.id = n.matiere_id
                JOIN eleves e ON n.eleve_id = e.id
                LEFT JOIN classes c ON e.classe_id = c.id
                LEFT JOIN users u ON n.enseignant_id = u.id
                LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                WHERE {where_notes}
            ) raw GROUP BY eleve_id, matiere_id, coef_matiere
        ) y
        GROUP BY y.eleve_id
    """, params).fetchall()
    return {r['eleve_id']: r['moyenne'] for r in rows}


# 🆕 NOUVEAU : Helper Python réutilisable — moyenne par MATIÈRE (une seule matière, donc
# uniquement pondérée par le coefficient des sous-matières, pas de second niveau) sur
# l'ensemble filtré par `where_notes`. Retourne une liste de dicts {matiere, moyenne, nb_notes}.
def _matieres_moyennes_ponderees(conn, where_notes="1=1", params=()):
    rows = conn.execute(f"""
        SELECT y.matiere as matiere,
               SUM(y.note * y.coef_sm) * 1.0 / NULLIF(SUM(y.coef_sm), 0) AS moyenne,
               COUNT(*) as nb_notes
        FROM (
            SELECT m.nom as matiere, n.note, COALESCE(sm.coefficient, 1) AS coef_sm
            FROM notes n
            JOIN matieres m ON m.id = n.matiere_id
            JOIN eleves e ON n.eleve_id = e.id
            LEFT JOIN classes c ON e.classe_id = c.id
            LEFT JOIN users u ON n.enseignant_id = u.id
            LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
            WHERE {where_notes}
        ) y GROUP BY y.matiere ORDER BY moyenne DESC
    """, params).fetchall()
    return [dict(r) for r in rows]


