# Idempotente : CREATE TABLE IF NOT EXISTS + seed uniquement si la table est vide.
def upgrade_db_cycles_table():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    try:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS cycles (
                id      INTEGER PRIMARY KEY AUTOINCREMENT,
                nom     TEXT UNIQUE NOT NULL,
                icone   TEXT DEFAULT '🏫',
                couleur TEXT DEFAULT 'blue-mid',
                ordre   INTEGER DEFAULT 0
            )
        """)
        conn.commit()
        nb = conn.execute("SELECT COUNT(*) FROM cycles").fetchone()[0]
        if nb == 0:
            # On seed avec les 3 cycles historiques, pour rester cohérent avec les
            # valeurs déjà utilisées dans la colonne classes.cycle et le reste de l'app.
            conn.executemany(
                "INSERT INTO cycles (nom, icone, couleur, ordre) VALUES (?, ?, ?, ?)",
                [
                    ('Maternelle', '🧸', 'amber', 1),
                    ('Primaire', '🎒', 'blue-mid', 2),
                    ('College', '📚', 'green', 3),
                ]
            )
            conn.commit()
    except sqlite3.OperationalError:
        pass
    conn.close()


