# 🆕 NOUVEAU : convertit un fichier image uploadé (photo de hub/cycle) en data URI
# base64, en le redimensionnant/compressant via PIL pour rester léger dans la base.
def _traiter_photo_cycle(fichier):
    if not fichier or not getattr(fichier, 'filename', ''):
        return None
    try:
        from PIL import Image
        img = Image.open(fichier.stream)
        img = img.convert('RGB')
        img.thumbnail((400, 400), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format='JPEG', quality=85)
        b64 = base64.b64encode(buf.getvalue()).decode('ascii')
        return f'data:image/jpeg;base64,{b64}'
    except Exception:
        return None


# 🆕 COMPRESSION AUTOMATIQUE DES IMAGES À L'UPLOAD ────────────────────────────────
# Toutes les images envoyées par l'app (photos élèves, personnel, patrimoine, logo,
# bannière, pièces jointes de communications/devoirs/messages) passaient jusqu'ici
# telles quelles (résolution d'origine du téléphone/appareil photo, parfois plusieurs
# Mo par photo) — ce qui gonfle le volume des sauvegardes (et la bande passante) à
# chaque backup. Cette fonction redimensionne et recompresse une image AVANT de
# l'écrire sur le disque, tout en restant totalement transparente pour l'appelant :
#   - Si le fichier n'est pas une image reconnue (PDF, Word, GIF animé...) ou si PIL
#     échoue pour une raison quelconque, on sauvegarde le fichier ORIGINAL sans y
#     toucher (aucune fonctionnalité cassée : rien n'est jamais perdu).
#   - Le format d'origine (PNG/JPEG/WEBP) est conservé (important pour les logos
#     avec transparence) — seules la résolution et la compression sont optimisées.
_EXTENSIONS_IMAGE_COMPRESSIBLES = {'jpg', 'jpeg', 'png', 'webp'}


def _sauvegarder_image_compressee(fichier, chemin_destination, max_dimension=1600, qualite=82):
    """Redimensionne (si besoin) + recompresse `fichier` (objet Werkzeug FileStorage) puis
    l'écrit à `chemin_destination`. Retombe sur une sauvegarde brute si ce n'est pas une image
    compressible ou si la compression échoue pour une raison quelconque."""
    ext = chemin_destination.rsplit('.', 1)[-1].lower() if '.' in chemin_destination else ''
    if ext not in _EXTENSIONS_IMAGE_COMPRESSIBLES:
        fichier.save(chemin_destination)
        return
    try:
        from PIL import Image
        img = Image.open(fichier.stream)
        img_format = (img.format or ('PNG' if ext == 'png' else 'JPEG'))
        # Redimensionne uniquement si l'image dépasse la taille maximale (ne jamais agrandir).
        if img.width > max_dimension or img.height > max_dimension:
            img.thumbnail((max_dimension, max_dimension), Image.LANCZOS)
        if img_format == 'JPEG' and img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')  # JPEG ne supporte pas la transparence
        parametres = {'optimize': True}
        if img_format == 'JPEG':
            parametres['quality'] = qualite
        elif img_format == 'PNG':
            parametres['compress_level'] = 8
        elif img_format == 'WEBP':
            parametres['quality'] = qualite
        img.save(chemin_destination, format=img_format, **parametres)
    except Exception as e:
        print(f"  ⚠️  Compression image échouée ({os.path.basename(chemin_destination)}) : {e} — sauvegarde brute.")
        try:
            fichier.stream.seek(0)
        except Exception:
            pass
        fichier.save(chemin_destination)


# 🆕 NOUVEAU : affiche la photo (ou l'emoji à défaut) d'un cycle sur les boutons des
# 4 pages hub (Élèves / Notes / Paiements / Classes), dans un cadre CIRCULAIRE façon
# "badge/sticker" (anneau coloré + ombre), comme le modèle demandé par l'école.
# `c` est un dict de cycle (issu de get_all_cycles / nav_cycles).
def cycle_icon_html(c, size='84px', bordure='5px'):
    from markupsafe import Markup, escape
    photo = None
    try:
        photo = c.get('photo') if hasattr(c, 'get') else c['photo']
    except (KeyError, IndexError, TypeError):
        photo = None
    couleur = 'blue-mid'
    try:
        couleur = (c.get('couleur') if hasattr(c, 'get') else c['couleur']) or 'blue-mid'
    except (KeyError, IndexError, TypeError):
        pass
    icone = '🏫'
    try:
        icone = (c.get('icone') if hasattr(c, 'get') else c['icone']) or '🏫'
    except (KeyError, IndexError, TypeError):
        pass

    cadre_style = (
        f'width:{size};height:{size};border-radius:50%;overflow:hidden;'
        f'display:inline-flex;align-items:center;justify-content:center;'
        f'background:#fff;border:{bordure} solid var(--{couleur}, #FFD60A);'
        f'box-shadow:0 4px 14px rgba(0,0,0,.18), inset 0 0 0 3px rgba(255,255,255,.75);'
        f'flex-shrink:0;'
    )
    if photo:
        contenu = f'<img src="{escape(photo)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;">'
    else:
        contenu = f'<span style="font-size:calc({size} * 0.5); line-height:1;">{escape(icone)}</span>'
    return Markup(f'<div style="{cadre_style}">{contenu}</div>')


app.jinja_env.globals['cycle_icon_html'] = cycle_icon_html
app.jinja_env.globals['lettre_note'] = _lettre_depuis_note
