def type_fichier_depuis_extension(nom_fichier):
    ext = nom_fichier.rsplit('.', 1)[-1].lower() if '.' in nom_fichier else ''
    if ext in EXT_PDF: return 'pdf'
    if ext in EXT_WORD: return 'word'
    if ext in EXT_IMAGE: return 'image'
    if ext in EXT_VIDEO: return 'video'
    if ext in EXT_AUDIO: return 'audio'
    if ext in EXT_EXCEL: return 'excel'
    return 'autre'


