def upgrade_db_devoirs_v2():
    conn = get_db()
    # --- Colonnes supplémentaires sur devoirs ---
    colonnes = [
        ("type", "TEXT DEFAULT 'exercice'"),
        ("priorite", "TEXT DEFAULT 'normale'"),
        ("date_publication", "TEXT"),
        ("heure_limite", "TEXT DEFAULT '23:59'"),
        ("statut", "TEXT DEFAULT 'publie'"),
        ("bareme", "TEXT DEFAULT ''"),
        ("difficulte", "TEXT DEFAULT 'moyen'"),
        ("consignes", "TEXT DEFAULT ''"),
        ("updated_at", "TEXT"),
        ("notif_publication_envoyee", "INTEGER DEFAULT 0"),
    ]
    for col, type_col in colonnes:
        try:
            conn.execute(f"ALTER TABLE devoirs ADD COLUMN {col} {type_col}")
        except sqlite3.OperationalError:
            pass

    # Anciens devoirs : considérés publiés dès leur création
    conn.execute("UPDATE devoirs SET date_publication = created_at WHERE date_publication IS NULL")
    conn.execute("UPDATE devoirs SET statut = 'publie' WHERE statut IS NULL")
    conn.execute("UPDATE devoirs SET notif_publication_envoyee = 1 WHERE notif_publication_envoyee IS NULL")

    # --- Attribution à plusieurs classes ---
    conn.execute("""
        CREATE TABLE IF NOT EXISTS devoir_classes (
            devoir_id INTEGER NOT NULL REFERENCES devoirs(id) ON DELETE CASCADE,
            classe_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
            PRIMARY KEY (devoir_id, classe_id)
        )
    """)
    # Migration : chaque devoir existant est rattaché à sa classe unique d'origine
    conn.execute("""
        INSERT OR IGNORE INTO devoir_classes (devoir_id, classe_id)
        SELECT id, classe_id FROM devoirs
    """)

    # --- Pièces jointes multiples (PDF / Word / Image / Vidéo / Audio / Lien) ---
    conn.execute("""
        CREATE TABLE IF NOT EXISTS devoir_fichiers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            devoir_id INTEGER NOT NULL REFERENCES devoirs(id) ON DELETE CASCADE,
            type_fichier TEXT NOT NULL,
            nom_original TEXT,
            nom_fichier TEXT,
            url_externe TEXT,
            libelle TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    # Migration : ancien fichier unique -> nouvelle table
    anciens = conn.execute("SELECT id, fichier, fichier_nom_original FROM devoirs WHERE fichier IS NOT NULL AND fichier != ''").fetchall()
    for d in anciens:
        existe = conn.execute("SELECT COUNT(*) FROM devoir_fichiers WHERE devoir_id=? AND nom_fichier=?",
                               (d['id'], d['fichier'])).fetchone()[0]
        if not existe:
            conn.execute("""
                INSERT INTO devoir_fichiers (devoir_id, type_fichier, nom_original, nom_fichier)
                VALUES (?, ?, ?, ?)
            """, (d['id'], type_fichier_depuis_extension(d['fichier_nom_original'] or d['fichier']),
                  d['fichier_nom_original'], d['fichier']))

    # --- Suivi des remises (une ligne par élève concerné par le devoir) ---
    conn.execute("""
        CREATE TABLE IF NOT EXISTS devoir_remises (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            devoir_id INTEGER NOT NULL REFERENCES devoirs(id) ON DELETE CASCADE,
            eleve_id INTEGER NOT NULL REFERENCES eleves(id) ON DELETE CASCADE,
            statut TEXT NOT NULL DEFAULT 'non_remis',
            date_remise TEXT,
            heure_remise TEXT,
            note TEXT,
            commentaire TEXT,
            rappel_envoye INTEGER DEFAULT 0,
            UNIQUE(devoir_id, eleve_id)
        )
    """)
    conn.commit()
    conn.close()


