def devoir_generer_remises_manquantes(conn, devoir_id):
    """Crée une ligne de suivi 'non_remis' pour chaque élève des classes assignées
    à ce devoir, si elle n'existe pas déjà (roster toujours complet)."""
    eleves = conn.execute("""
        SELECT DISTINCT e.id FROM eleves e
        JOIN devoir_classes dc ON dc.classe_id = e.classe_id
        WHERE dc.devoir_id = ?
    """, (devoir_id,)).fetchall()
    for e in eleves:
        conn.execute("INSERT OR IGNORE INTO devoir_remises (devoir_id, eleve_id, statut) VALUES (?, ?, 'non_remis')",
                      (devoir_id, e['id']))


def devoir_notifier_publication(conn, devoir_id):
    """Envoie une notification in-app à chaque parent concerné, une seule fois."""
    d = conn.execute("SELECT * FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
    if not d or d['notif_publication_envoyee']:
        return
    parents = conn.execute("""
        SELECT DISTINCT e.parent_id FROM eleves e
        JOIN devoir_classes dc ON dc.classe_id = e.classe_id
        WHERE dc.devoir_id = ? AND e.parent_id IS NOT NULL
    """, (devoir_id,)).fetchall()
    msg = f"📚 Nouveau devoir « {d['titre']} »" + (f" — à rendre le {d['date_limite']}" if d['date_limite'] else "")
    for p in parents:
        notif_to_parent(p['parent_id'], msg, conn)
    conn.execute("UPDATE devoirs SET notif_publication_envoyee=1 WHERE id=?", (devoir_id,))


def devoirs_publier_devoirs_programmes(conn):
    """Fait passer au statut 'publie' les devoirs programmés dont l'heure est arrivée,
    génère leur suivi de remises et envoie les notifications. Appelé à chaque chargement
    de la page (pas besoin d'un scheduler fiable en tâche de fond)."""
    maintenant = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    a_publier = conn.execute(
        "SELECT id FROM devoirs WHERE statut='programme' AND date_publication <= ?", (maintenant,)
    ).fetchall()
    for d in a_publier:
        conn.execute("UPDATE devoirs SET statut='publie' WHERE id=?", (d['id'],))
        devoir_generer_remises_manquantes(conn, d['id'])
        devoir_notifier_publication(conn, d['id'])
    if a_publier:
        conn.commit()


def devoirs_marquer_en_retard_auto(conn):
    """Fait automatiquement passer au statut 'en_retard' les remises encore 'non_remis'
    dont l'échéance du devoir est dépassée (pas besoin d'action manuelle)."""
    maintenant = datetime.datetime.now().strftime('%Y-%m-%d %H:%M')
    conn.execute("""
        UPDATE devoir_remises SET statut='en_retard'
        WHERE statut='non_remis' AND devoir_id IN (
            SELECT id FROM devoirs WHERE statut='publie' AND date_limite IS NOT NULL
            AND (date_limite || ' ' || COALESCE(heure_limite,'23:59')) < ?
        )
    """, (maintenant,))
    conn.commit()


def devoirs_envoyer_rappels_echeance(conn, parent_id):
    """Envoie un rappel in-app (une seule fois) pour chaque devoir non remis d'un
    enfant du parent, dont l'échéance est à moins de 24h."""
    maintenant = datetime.datetime.now()
    seuil = (maintenant + datetime.timedelta(hours=24)).strftime('%Y-%m-%d %H:%M')
    a_rappeler = conn.execute("""
        SELECT dr.id as remise_id, d.titre, d.date_limite, d.heure_limite, e.prenom
        FROM devoir_remises dr
        JOIN devoirs d ON d.id = dr.devoir_id
        JOIN eleves e ON e.id = dr.eleve_id
        WHERE e.parent_id = ? AND dr.statut = 'non_remis' AND dr.rappel_envoye = 0
          AND d.statut='publie' AND d.date_limite IS NOT NULL
          AND (d.date_limite || ' ' || COALESCE(d.heure_limite,'23:59')) <= ?
          AND (d.date_limite || ' ' || COALESCE(d.heure_limite,'23:59')) >= ?
    """, (parent_id, seuil, maintenant.strftime('%Y-%m-%d %H:%M'))).fetchall()
    for r in a_rappeler:
        notif_to_parent(parent_id, f"⏰ Rappel : « {r['titre']} » ({r['prenom']}) est à rendre bientôt !", conn)
        conn.execute("UPDATE devoir_remises SET rappel_envoye=1 WHERE id=?", (r['remise_id'],))
    if a_rappeler:
        conn.commit()


