def luxe_3d_style_html():
    """🆕 Construit le <style> qui donne à TOUTE l'application des mouvements en 3D et un
    rendu "lux" (cartes qui basculent légèrement en profondeur au survol, boutons avec reflet
    lumineux et effet de levée, liens de menu qui glissent en 3D, modales qui apparaissent en
    profondeur, contenu de page qui monte en fondu à l'ouverture). Injecté par nav_html() sur
    chaque page, donc appliqué automatiquement partout sans dépendre d'un fichier séparé.
    Respecte prefers-reduced-motion pour l'accessibilité."""
    return """<style>
:root{ --ease-luxe:cubic-bezier(.19,1,.22,1); --ease-luxe-soft:cubic-bezier(.16,1,.3,1); }

/* 🆕 Cartes : la pulsation de zoom est maintenant gérée par Framer Motion (JS),
   voir motionZoomCards() plus bas — ici on garde juste l'ombre de profondeur au survol.
   Les cartes contenant un graphique/courbe (canvas Chart.js) sont exclues côté JS. */
.card{ will-change:transform; }
.card:hover{
  box-shadow:0 20px 25px -5px rgba(0,0,0,.1), 0 8px 10px -6px rgba(0,0,0,.1) !important;
  z-index:2;
}
html.theme-neon .card:hover{
  box-shadow:0 22px 45px -12px rgba(0,229,255,.20), 0 0 0 1px rgba(0,229,255,.16) !important;
}

/* 🆕 Boutons : levée 3D + reflet lumineux "lux" qui traverse au survol */
.btn{
  position:relative; overflow:hidden;
  transition:transform .3s var(--ease-luxe-soft), box-shadow .3s var(--ease-luxe-soft) !important;
}
.btn::after{
  content:''; position:absolute; top:0; left:-60%; width:35%; height:100%;
  background:linear-gradient(120deg, transparent, rgba(255,255,255,.55), transparent);
  transform:skewX(-20deg); transition:left .65s var(--ease-luxe); pointer-events:none;
}
.btn:hover::after{ left:130%; }
.btn:hover{ transform:perspective(600px) translateY(-3px) scale(1.025) !important; }
.btn:active{ transform:translateY(0) scale(.97) !important; transition-duration:.1s !important; }

/* 🆕 Liens du menu : glissement en 3D au survol */
.nav-link{ transition:transform .3s var(--ease-luxe-soft), background .3s var(--ease-luxe-soft) !important; }
.nav-link:hover{ transform:perspective(500px) translateX(4px) rotateY(-3deg); }

/* 🆕 Modales : apparition en profondeur */
.modal{ animation:luxeModalIn .5s var(--ease-luxe-soft); }
@keyframes luxeModalIn{
  from{ opacity:0; transform:perspective(1000px) translateY(24px) rotateX(6deg) scale(.96); }
  to{ opacity:1; transform:perspective(1000px) translateY(0) rotateX(0) scale(1); }
}

/* 🆕 Avatars, badges, icônes de cycle : petit pop 3D au survol */
.badge{ transition:transform .25s var(--ease-luxe-soft); }
.badge:hover{ transform:translateY(-2px) scale(1.05); }

/* 🆕 Contenu de page : montée en fondu à l'ouverture de chaque page */
.content{ animation:luxeContentIn .5s var(--ease-luxe-soft); }
@keyframes luxeContentIn{
  from{ opacity:0; transform:perspective(800px) translateY(14px) rotateX(2deg); }
  to{ opacity:1; transform:none; }
}

/* 🆕 Lignes de tableau : légère élévation au survol */
table tbody tr{ transition:transform .25s var(--ease-luxe-soft), box-shadow .25s var(--ease-luxe-soft); }
table tbody tr:hover{ transform:translateX(2px); box-shadow:0 4px 14px -8px rgba(0,0,0,.18); position:relative; z-index:1; }

@media (prefers-reduced-motion: reduce){
  .card, .btn, .btn::after, .nav-link, table tbody tr, .modal, .content{
    animation:none !important; transition:none !important; transform:none !important;
  }
}
</style>"""


def get_ecole_coords(conn):
    """Retourne l'adresse/coordonnées de référence de l'école (point de départ des chauffeurs)."""
    row = conn.execute("SELECT adresse, latitude, longitude FROM parametres_ecole WHERE id=1").fetchone()
    if row:
        return {'adresse': row['adresse'], 'lat': row['latitude'], 'lon': row['longitude']}
    return {'adresse': '', 'lat': None, 'lon': None}


def distance_km(lat1, lon1, lat2, lon2):
    """Distance à vol d'oiseau (formule de haversine), en kilomètres."""
    from math import radians, sin, cos, sqrt, atan2
    r = 6371.0
    phi1, phi2 = radians(lat1), radians(lat2)
    dphi = radians(lat2 - lat1)
    dlambda = radians(lon2 - lon1)
    a = sin(dphi / 2) ** 2 + cos(phi1) * cos(phi2) * sin(dlambda / 2) ** 2
    return 2 * r * atan2(sqrt(a), sqrt(1 - a))


# 🆕 Seuil de détection "arrivée chez l'élève" pour le suivi chauffeur en direct (admin) :
# quand la position GPS du chauffeur passe sous cette distance de l'adresse d'un élève,
# on considère qu'il est arrivé chez cet élève (marqueur qui change de couleur + notification).
ARRIVEE_ELEVE_SEUIL_KM = 0.15  # 150 mètres


def ordonner_trajet_ramassage(ecole_lat, ecole_lon, eleves):
    """
    Ordonne les élèves (liste de dicts avec 'lat'/'lon') pour un trajet de ramassage scolaire :
    1) on part TOUJOURS de l'élève le PLUS ÉLOIGNÉ de l'école (1er ramassage),
    2) on termine TOUJOURS par l'élève le PLUS PROCHE de l'école (dernier ramassage, juste avant le retour),
    3) entre les deux, à chaque étape, on enchaîne vers l'élève non visité le PLUS PROCHE du point courant
       (sans jamais choisir l'élève le plus proche de l'école tant qu'il en reste d'autres à ramasser).
    Retourne la liste réordonnée, avec pour chaque élève sa distance (km) par rapport à l'école.
    """
    restants = [dict(e) for e in eleves]
    if not restants:
        return []
    for e in restants:
        e['distance_ecole_km'] = round(distance_km(ecole_lat, ecole_lon, e['lat'], e['lon']), 2)

    if len(restants) == 1:
        return restants

    # 🏁 L'élève le plus proche de l'école est réservé pour la toute dernière étape.
    restants.sort(key=lambda e: e['distance_ecole_km'])
    dernier = restants.pop(0)

    # 🚩 Parmi les élèves restants, on démarre par le plus éloigné de l'école.
    restants.sort(key=lambda e: -e['distance_ecole_km'])
    ordre = [restants.pop(0)]
    courant = ordre[0]
    while restants:
        restants.sort(key=lambda e: distance_km(courant['lat'], courant['lon'], e['lat'], e['lon']))
        suivant = restants.pop(0)
        ordre.append(suivant)
        courant = suivant

    # 🏁 On ajoute enfin l'élève le plus proche de l'école, en dernière position.
    ordre.append(dernier)
    return ordre


def distance_totale_trajet_km(ecole_lat, ecole_lon, eleves_ordonnes):
    """
    Calcule la distance RÉELLE totale du trajet complet du chauffeur (à vol d'oiseau) :
    École ➝ élève le plus éloigné (1er ramassage) ➝ ... ➝ élève le plus proche ➝ retour à l'École.
    `eleves_ordonnes` doit déjà être dans l'ordre de ramassage (sortie de ordonner_trajet_ramassage).
    Retourne un float arrondi en km, ou None si le calcul n'est pas possible.
    """
    if not eleves_ordonnes or ecole_lat is None or ecole_lon is None:
        return None

    total = 0.0
    point_precedent = (ecole_lat, ecole_lon)
    # École ➝ 1er élève, puis élève ➝ élève suivant, dans l'ordre de ramassage
    for e in eleves_ordonnes:
        total += distance_km(point_precedent[0], point_precedent[1], e['lat'], e['lon'])
        point_precedent = (e['lat'], e['lon'])
    # Dernier élève ➝ retour à l'école
    total += distance_km(point_precedent[0], point_precedent[1], ecole_lat, ecole_lon)

    return round(total, 1)


def construire_donnees_trajet_chauffeur(chauffeur_id, conn):
    """
    Construit les données du trajet de ramassage d'un chauffeur (élèves assignés,
    élèves localisés/ordonnés pour la carte, distance totale estimée). Utilisé à la
    fois par la fiche admin du chauffeur et par l'espace personnel du chauffeur.
    """
    eleves_assignes = conn.execute("""
                                    SELECT e.id, e.nom, e.prenom, e.transport_abonne, e.adresse as eleve_adresse,
                                           e.latitude, e.longitude,
                                           c.nom as classe_nom, c.niveau as classe_niveau,
                                           u.adresse as parent_adresse, u.telephone as parent_telephone,
                                           u.prenom || ' ' || u.nom as parent_nom
                                    FROM transport_eleves t
                                             JOIN eleves e ON t.eleve_id = e.id
                                             LEFT JOIN classes c ON e.classe_id = c.id
                                             LEFT JOIN users u ON e.parent_id = u.id
                                    WHERE t.chauffeur_id = ?
                                    ORDER BY c.niveau, c.nom, e.nom
                                    """, (chauffeur_id,)).fetchall()

    ecole = get_ecole_coords(conn)

    eleves_localises = [
        {
            'id': e['id'],
            'nom': f"{e['prenom']} {e['nom']}",
            'adresse': e['eleve_adresse'] or e['parent_adresse'] or '',
            'lat': e['latitude'],
            'lon': e['longitude'],
            # 🆕 Champs complémentaires (classe, contact parent) pour l'affichage de la liste
            # ordonnée (élève le plus éloigné en premier), utilisés à la fois par la fiche
            # admin du chauffeur et par l'espace personnel du chauffeur.
            'classe_nom': e['classe_nom'],
            'classe_niveau': e['classe_niveau'],
            'parent_nom': e['parent_nom'],
            'parent_telephone': e['parent_telephone'],
        }
        for e in eleves_assignes if e['latitude'] is not None and e['longitude'] is not None
    ]

    ecole_localisee = ecole['lat'] is not None and ecole['lon'] is not None
    if ecole_localisee:
        eleves_carte = ordonner_trajet_ramassage(ecole['lat'], ecole['lon'], eleves_localises)
    else:
        eleves_carte = eleves_localises

    distance_totale_trajet = None
    if ecole_localisee and eleves_carte:
        distance_totale_trajet = distance_totale_trajet_km(ecole['lat'], ecole['lon'], eleves_carte)

    return {
        'eleves_assignes': eleves_assignes,
        'eleves_carte': eleves_carte,
        'ecole': ecole,
        'ecole_localisee': ecole_localisee,
        'distance_totale_trajet': distance_totale_trajet,
    }


# 🆕 Score de performance du chauffeur — calculé UNIQUEMENT à partir de données réellement
# enregistrées (trajets GPS, conformité du permis). Aucune donnée n'est inventée : un critère
# sans donnée disponible (ex : pas de date de permis renseignée) est simplement exclu du calcul,
# et le total est ramené sur 100 en fonction des critères réellement disponibles.
def calculer_score_chauffeur(chauffeur_id, conn):
    p = conn.execute("SELECT * FROM personnel_hors_prof WHERE id=?", (chauffeur_id,)).fetchone()
    if not p:
        return None

    criteres = []  # (label, points_obtenus, points_max, detail)
    aujourdhui = datetime.date.today()

    # 1) Activité récente : jours distincts avec au moins un trajet enregistré sur 30 jours
    jours_actifs = conn.execute(
        "SELECT COUNT(DISTINCT date_trajet) FROM chauffeur_trajets "
        "WHERE chauffeur_id=? AND date_trajet >= date('now','-30 days')",
        (chauffeur_id,)
    ).fetchone()[0]
    pts_activite = round(min(jours_actifs, 20) / 20 * 40, 1)
    criteres.append(('Activité (30 derniers jours)', pts_activite, 40, f"{jours_actifs} jour(s) avec trajet enregistré"))

    # 2) Expérience : volume total de trajets réalisés (plafonné à 150)
    nb_trajets = conn.execute(
        "SELECT COUNT(*) FROM chauffeur_trajets WHERE chauffeur_id=?", (chauffeur_id,)
    ).fetchone()[0]
    pts_volume = round(min(nb_trajets, 150) / 150 * 30, 1)
    criteres.append(('Expérience (trajets réalisés)', pts_volume, 30, f"{nb_trajets} trajet(s) enregistré(s) au total"))

    # 3) Conformité du permis — seulement si une date d'expiration a été renseignée
    permis_expire = False
    if p['permis_expiration']:
        try:
            exp = datetime.datetime.strptime(p['permis_expiration'], '%Y-%m-%d').date()
        except ValueError:
            exp = None
        if exp:
            jours_restants = (exp - aujourdhui).days
            if jours_restants < 0:
                pts_permis, detail, permis_expire = 0, 'Permis expiré', True
            elif jours_restants < 30:
                pts_permis, detail = 10, f"Permis expire dans {jours_restants} j"
            else:
                pts_permis, detail = 30, f"Permis valide (expire le {p['permis_expiration']})"
            criteres.append(('Conformité du permis', pts_permis, 30, detail))

    max_total = sum(c[2] for c in criteres)
    if max_total == 0:
        return {'score': None, 'badge': 'Non évalué', 'emoji': '⚪', 'criteres': [], 'donnees_suffisantes': False}

    obtenu_total = sum(c[1] for c in criteres)
    score = round(obtenu_total / max_total * 100)

    if score >= 85:
        badge, emoji = 'Chauffeur Excellence', '🏆'
    elif score >= 70:
        badge, emoji = 'Chauffeur Fiable', '🟢'
    elif score >= 50:
        badge, emoji = 'Chauffeur Régulier', '🔵'
    elif score >= 30:
        badge, emoji = 'À surveiller', '🟡'
    else:
        badge, emoji = 'Performance faible', '🟠'

    if permis_expire:
        badge, emoji = 'Priorité sécurité', '🔴'

    return {
        'score': score, 'badge': badge, 'emoji': emoji,
        'criteres': criteres, 'donnees_suffisantes': True,
    }


def parser_coordonnees_ou_lien(texte):
    """
    Détecte si le texte saisi dans le champ "Adresse" est en réalité des coordonnées GPS
    ou un lien OpenStreetMap, et retourne (lat, lon) si c'est le cas, sinon (None, None).
    Formats reconnus :
      - Lien OSM  : https://www.openstreetmap.org/#map=18/34.0066014/-5.0066006
      - Lien OSM  : https://www.openstreetmap.org/?mlat=34.0066014&mlon=-5.0066006
      - Coordonnées format FR (virgule décimale) : 34,0066014 ; -5,0066006
      - Coordonnées format international (point décimal) : 34.0066014, -5.0066006  /  34.0066014 -5.0066006
    """
    if not texte:
        return None, None
    t = texte.strip()

    # Lien OSM : .../#map=zoom/lat/lon
    m = re.search(r'#map=\d+/(-?\d+\.\d+)/(-?\d+\.\d+)', t)
    if m:
        return float(m.group(1)), float(m.group(2))

    # Lien OSM : ...?mlat=..&mlon=..
    m = re.search(r'mlat=(-?\d+\.\d+)[^0-9\-]+mlon=(-?\d+\.\d+)', t)
    if m:
        return float(m.group(1)), float(m.group(2))

    # Coordonnées "34,0066014 ; -5,0066006" (virgule décimale FR, séparées par un point-virgule)
    m = re.match(r'^\s*(-?\d+),(\d+)\s*[;]\s*(-?\d+),(\d+)\s*$', t)
    if m:
        try:
            lat = float(f"{m.group(1)}.{m.group(2)}")
            lon = float(f"{m.group(3)}.{m.group(4)}")
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except ValueError:
            pass

    # Coordonnées "34.0066014, -5.0066006" ou "34.0066014 -5.0066006" (point décimal)
    m = re.match(r'^\s*(-?\d+\.\d+)\s*[,;\s]\s*(-?\d+\.\d+)\s*$', t)
    if m:
        try:
            lat, lon = float(m.group(1)), float(m.group(2))
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except ValueError:
            pass

    return None, None


def geocoder_adresse(adresse):
    """
    Convertit une adresse (texte, coordonnées GPS ou lien OpenStreetMap) en (lat, lon).
    - Si l'utilisateur a directement collé des coordonnées ou un lien OSM, elles sont utilisées
      telles quelles, sans appel réseau (plus rapide et plus précis).
    - Sinon, l'adresse texte est géocodée via Nominatim (OpenStreetMap). Respecte la politique
      d'usage de Nominatim (User-Agent identifié, 1 requête/seconde max gérée par l'appelant
      via time.sleep).
    Retourne (lat, lon) ou (None, None).
    """
    if not adresse or not adresse.strip():
        return None, None

    lat, lon = parser_coordonnees_ou_lien(adresse)
    if lat is not None and lon is not None:
        return lat, lon

    try:
        resp = requests.get(
            "https://nominatim.openstreetmap.org/search",
            params={"q": adresse, "format": "json", "limit": 1},
            headers={"User-Agent": "EcoleApp/1.0 (gestion-scolaire ; transport-eleves)"},
            timeout=8
        )
        data = resp.json()
        if data:
            return float(data[0]["lat"]), float(data[0]["lon"])
    except Exception:
        pass
    return None, None


