# ─── [ANCIEN] WhatsApp : envoi d'un message texte via API Meta ──
# Conservé mais non utilisé par les pages admin : l'appli n'utilise plus
# l'API WhatsApp Business, tout passe désormais par des liens wa.me
# (voir lien_whatsapp ci-dessus) ouverts dans le navigateur.
def envoyer_whatsapp(telephone, message):
    """
    Envoie un message WhatsApp via Meta Business API.
    telephone : numéro international sans '+' ex: '212612345678'
    Retourne (True, '') en succès ou (False, erreur) en échec.
    """
    if not telephone or not telephone.strip():
        return False, "Numéro de téléphone manquant"
    if WA_TOKEN == 'VOTRE_TOKEN_ICI':
        return False, "WA_TOKEN non configuré"

    # Nettoyage du numéro : retire +, espaces, tirets
    numero = telephone.strip().replace('+', '').replace(' ', '').replace('-', '')

    payload = {
        "messaging_product": "whatsapp",
        "to": numero,
        "type": "text",
        "text": {"body": message}
    }
    headers = {
        "Authorization": f"Bearer {WA_TOKEN}",
        "Content-Type": "application/json"
    }
    try:
        resp = requests.post(WA_API_URL, json=payload, headers=headers, timeout=10)
        data = resp.json()
        if resp.status_code == 200 and 'messages' in data:
            return True, data['messages'][0].get('id', '')
        else:
            erreur = data.get('error', {}).get('message', str(data))
            return False, erreur
    except Exception as e:
        return False, str(e)


# ─── WhatsApp : envoi d'un fichier (document/image) ─────────────
def envoyer_whatsapp_fichier(telephone, filepath, filename, caption=''):
    """
    Envoie un fichier (PDF, Word, Excel, image...) via WhatsApp Business API.
    Étape 1 : upload du fichier vers les serveurs Meta -> media_id
    Étape 2 : envoi du message référençant ce media_id
    Retourne (True, '') en succès ou (False, erreur) en échec.
    """
    if not telephone or not telephone.strip():
        return False, "Numéro de téléphone manquant"
    if WA_TOKEN == 'VOTRE_TOKEN_ICI':
        return False, "WA_TOKEN non configuré"
    if not os.path.exists(filepath):
        return False, "Fichier introuvable"

    numero = telephone.strip().replace('+', '').replace(' ', '').replace('-', '')
    mime_type, _ = mimetypes.guess_type(filename)
    mime_type = mime_type or 'application/octet-stream'
    # Les images jpeg/png bénéficient du type "image" (aperçu dans la conversation),
    # tous les autres formats (pdf, docx, xlsx...) passent en type "document"
    wa_type = 'image' if mime_type in ('image/jpeg', 'image/png') else 'document'

    # Étape 1 : upload du média
    try:
        with open(filepath, 'rb') as f:
            files = {'file': (filename, f, mime_type)}
            data = {'messaging_product': 'whatsapp', 'type': mime_type}
            headers_upload = {"Authorization": f"Bearer {WA_TOKEN}"}
            resp_up = requests.post(WA_MEDIA_URL, headers=headers_upload, files=files, data=data, timeout=30)
        media_data = resp_up.json()
        if resp_up.status_code != 200 or 'id' not in media_data:
            erreur = media_data.get('error', {}).get('message', str(media_data))
            return False, f"Échec de l'envoi du fichier : {erreur}"
        media_id = media_data['id']
    except Exception as e:
        return False, f"Erreur d'envoi du fichier : {e}"

    # Étape 2 : envoi du message avec le média
    contenu = {"id": media_id}
    if wa_type == 'document':
        contenu['filename'] = filename
    if caption:
        contenu['caption'] = caption

    payload = {
        "messaging_product": "whatsapp",
        "to": numero,
        "type": wa_type,
        wa_type: contenu
    }
    headers = {
        "Authorization": f"Bearer {WA_TOKEN}",
        "Content-Type": "application/json"
    }
    try:
        resp = requests.post(WA_API_URL, json=payload, headers=headers, timeout=15)
        data = resp.json()
        if resp.status_code == 200 and 'messages' in data:
            return True, data['messages'][0].get('id', '')
        else:
            erreur = data.get('error', {}).get('message', str(data))
            return False, erreur
    except Exception as e:
        return False, str(e)


# ─── Construction des rappels impayés (SANS envoi, SANS API) ────
def construire_rappels_impayes(parent_id=None):
    """
    Parcourt les élèves avec un paiement non_paye ou partiel et construit,
    pour chaque parent ayant un numéro renseigné, le message de rappel.
    Ne contacte AUCUNE API : retourne juste une liste prête pour l'assistant
    d'envoi WhatsApp Web (wa.me), qui ouvrira chaque conversation un par un.
    Si parent_id est fourni, ne construit le rappel que pour ce parent.
    """
    conn = get_db()
    try:
        query = """
                SELECT e.prenom || ' ' || e.nom AS eleve_nom,
                       p.montant_total,
                       p.montant_paye,
                       p.description,
                       p.date_echeance,
                       u.id                      AS parent_id,
                       u.nom || ' ' || u.prenom   AS parent_nom,
                       u.telephone
                FROM paiements p
                         JOIN eleves e ON p.eleve_id = e.id
                         LEFT JOIN users u ON e.parent_id = u.id
                WHERE p.statut IN ('non_paye', 'partiel')
                  AND u.telephone IS NOT NULL
                  AND u.telephone != ''
                """
        params = []
        if parent_id:
            query += " AND u.id = ?"
            params.append(parent_id)

        impayes = conn.execute(query, params).fetchall()

        queue = []
        for row in impayes:
            reste = row['montant_total'] - row['montant_paye']
            echeance = row['date_echeance'] or 'non précisée'
            msg = (
                f"🏫 École — Rappel de paiement\n\n"
                f"Cher(e) {row['parent_nom']},\n\n"
                f"Le paiement de votre enfant *{row['eleve_nom']}* "
                f"n'est pas encore réglé.\n\n"
                f"📋 Désignation : {row['description'] or 'Mensualité'}\n"
                f"💰 Montant restant : *{reste:.2f} MAD*\n"
                f"📅 Échéance : {echeance}\n\n"
                f"Merci de régulariser votre situation dès que possible.\n"
                f"Cordialement, l'Administration"
            )
            queue.append({
                'parent_id': row['parent_id'],
                'nom': row['parent_nom'],
                'telephone': row['telephone'],
                'message': msg
            })
        return queue
    finally:
        conn.close()


