@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        pw = request.form.get('password', '')
        conn = get_db()
        user = conn.execute("SELECT * FROM users WHERE email=? AND password=?", (email, hash_pw(pw))).fetchone()
        if user:
            session.permanent = True
            session['user_id'] = user['id']
            session['role'] = user['role']
            session['nom_complet'] = f"{user['prenom']} {user['nom']}"
            conn.close()
            return redirect(url_for('dashboard'))

        # 🆕 Comptes chauffeurs (personnel_hors_prof avec mission='Chauffeur' + accès activé)
        chauffeur = conn.execute(
            "SELECT * FROM personnel_hors_prof WHERE mission='Chauffeur' AND email=? "
            "AND email IS NOT NULL AND email != '' AND password=?",
            (email, hash_pw(pw))
        ).fetchone()
        conn.close()
        if chauffeur:
            session.permanent = True
            session['user_id'] = chauffeur['id']
            session['role'] = 'chauffeur'
            session['nom_complet'] = f"{chauffeur['prenom']} {chauffeur['nom']}"
            return redirect(url_for('espace_chauffeur'))

        flash('Email ou mot de passe incorrect.', 'error')
    return render_template_string(LOGIN_HTML)


