# 🆕 NOUVEAU : Ajout / suppression d'un cycle depuis le hub Élèves (réservé à l'admin).
@app.route('/cycles/action', methods=['POST'])
@login_required
@role_required('admin')
def cycles_action():
    conn = get_db()
    action = request.form.get('action')

    if action == 'add':
        nom = (request.form.get('nom') or '').strip()
        icone = (request.form.get('icone') or '🏫').strip() or '🏫'
        couleur = (request.form.get('couleur') or 'blue-mid').strip() or 'blue-mid'
        # 🆕 Photo optionnelle dès la création du cycle (remplace l'emoji sur les 4 hubs)
        photo = _traiter_photo_cycle(request.files.get('photo'))
        if not nom:
            flash("Merci de saisir un nom de cycle.", "error")
        else:
            existe = conn.execute("SELECT id FROM cycles WHERE nom = ?", (nom,)).fetchone()
            if existe:
                flash(f"Le cycle « {nom} » existe déjà.", "error")
            else:
                ordre_max = conn.execute("SELECT COALESCE(MAX(ordre), 0) FROM cycles").fetchone()[0]
                conn.execute(
                    "INSERT INTO cycles (nom, icone, couleur, ordre, photo) VALUES (?, ?, ?, ?, ?)",
                    (nom, icone, couleur, ordre_max + 1, photo)
                )
                conn.commit()
                flash(f"Cycle « {nom} » ajouté avec succès !", "success")

    elif action == 'photo':
        # 🆕 NOUVEAU : upload / remplacement de la photo d'un cycle existant, à la
        # place de son emoji, depuis le hub Élèves (bouton 📷 sur chaque carte).
        cycle_id = request.form.get('cycle_id')
        cyc = conn.execute("SELECT * FROM cycles WHERE id = ?", (cycle_id,)).fetchone()
        if not cyc:
            flash("Cycle introuvable.", "error")
        else:
            photo = _traiter_photo_cycle(request.files.get('photo'))
            if not photo:
                flash("Merci de sélectionner une image valide.", "error")
            else:
                conn.execute("UPDATE cycles SET photo = ? WHERE id = ?", (photo, cycle_id))
                conn.commit()
                flash(f"Photo du cycle « {cyc['nom']} » mise à jour !", "success")

    elif action == 'remove_photo':
        # 🆕 Revenir à l'emoji par défaut pour ce cycle
        cycle_id = request.form.get('cycle_id')
        cyc = conn.execute("SELECT * FROM cycles WHERE id = ?", (cycle_id,)).fetchone()
        if not cyc:
            flash("Cycle introuvable.", "error")
        else:
            conn.execute("UPDATE cycles SET photo = NULL WHERE id = ?", (cycle_id,))
            conn.commit()
            flash(f"Photo du cycle « {cyc['nom']} » retirée (retour à l'emoji).", "success")

    elif action == 'delete':
        cycle_id = request.form.get('cycle_id')
        cyc = conn.execute("SELECT * FROM cycles WHERE id = ?", (cycle_id,)).fetchone()
        if not cyc:
            flash("Cycle introuvable.", "error")
        else:
            # 🔒 SÉCURITÉ : on empêche la suppression d'un cycle encore utilisé par des
            # classes, pour ne jamais laisser des classes/élèves orphelins d'un cycle.
            nb_classes = conn.execute(
                "SELECT COUNT(*) FROM classes WHERE cycle = ?", (cyc['nom'],)
            ).fetchone()[0]
            if nb_classes > 0:
                flash(
                    f"Impossible de supprimer « {cyc['nom']} » : {nb_classes} classe(s) y sont "
                    f"encore rattachées. Déplacez ou supprimez-les d'abord.", "error"
                )
            else:
                conn.execute("DELETE FROM cycles WHERE id = ?", (cycle_id,))
                conn.commit()
                flash(f"Cycle « {cyc['nom']} » supprimé avec succès !", "success")

    conn.close()
    return redirect(url_for('gestion_eleves'))


