@app.route('/eleves', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'enseignant', 'parent')
def gestion_eleves():
    conn = get_db()

    if request.method == 'POST':
        # SÉCURITÉ : On bloque toute modification si ce n'est pas un admin
        if session['role'] not in ('admin', 'agent_admin'):
            flash("Action non autorisée.", "error")
            conn.close()
            return redirect(url_for('gestion_eleves', cycle=request.form.get('cycle', 'Primaire'),
                                    classe_id=request.form.get('classe_id'),
                                    tous=request.form.get('tous')))

        action = request.form.get('action')
        eleve_id = request.form.get('eleve_id')
        cycle = request.form.get('cycle', 'Primaire')
        tous_form = request.form.get('tous')  # 🆕 NOUVEAU : préserve la vue "Tous les élèves" après une action

        # 🔄 NOUVEAU : On récupère l'ID de la classe pour y revenir après le POST
        form_classe_id = request.form.get('classe_id')

        if action == 'edit':
            nom = request.form.get('nom')
            prenom = request.form.get('prenom')
            nom_arabe = request.form.get('nom_arabe', '')
            prenom_arabe = request.form.get('prenom_arabe', '')
            sexe = request.form.get('sexe', 'M')
            date_naissance = request.form.get('date_naissance')
            lieu_naissance = request.form.get('lieu_naissance', '')
            adresse = request.form.get('adresse', '')
            adresse2 = request.form.get('adresse2', '')
            date_inscription = request.form.get('date_inscription')

            transport_abonne = request.form.get('transport_abonne', 'non')
            try:
                montant_transport = float(
                    request.form.get('montant_transport') or 0) if transport_abonne == 'oui' else 0
            except ValueError:
                montant_transport = 0

            nom_pere = request.form.get('nom_pere', '')
            profession_pere = request.form.get('profession_pere', '')
            nom_mere = request.form.get('nom_mere', '')
            profession_mere = request.form.get('profession_mere', '')

            # 🆕 Informations santé / contact d'urgence
            groupe_sanguin = request.form.get('groupe_sanguin', '')
            allergies = request.form.get('allergies', '')
            contact_urgence_nom = request.form.get('contact_urgence_nom', '')
            contact_urgence_tel = request.form.get('contact_urgence_tel', '')

            numero_matricule = request.form.get('numero_matricule')
            classe_id = request.form.get('classe_id')
            parent_id = request.form.get('parent_id')
            montant_mensualite = request.form.get('montant_mensualite', 800)

            # 🆕 Réduction (remise) sur la facture + date de validité
            try:
                reduction_pourcentage = float(request.form.get('reduction_pourcentage') or 0)
            except ValueError:
                reduction_pourcentage = 0
            reduction_pourcentage = max(0, min(100, reduction_pourcentage))
            reduction_validite = request.form.get('reduction_validite') or None

            classe_id = int(classe_id) if classe_id else None
            parent_id = int(parent_id) if parent_id else None

            conn.execute("""
                         UPDATE eleves
                         SET nom=?, prenom=?, nom_arabe=?, prenom_arabe=?, sexe=?, date_naissance=?, lieu_naissance=?,
                             adresse=?, adresse2=?, date_inscription=?, nom_pere=?, profession_pere=?, nom_mere=?, profession_mere=?,
                             classe_id=?, parent_id=?, montant_mensualite=?, numero_matricule=?,
                             transport_abonne=?, montant_transport=?, groupe_sanguin=?, allergies=?,
                             contact_urgence_nom=?, contact_urgence_tel=?, reduction_pourcentage=?, reduction_validite=?,
                             latitude=CASE WHEN adresse=? THEN latitude ELSE NULL END,
                             longitude=CASE WHEN adresse=? THEN longitude ELSE NULL END
                         WHERE id = ?
                         """, (nom, prenom, nom_arabe, prenom_arabe, sexe, date_naissance, lieu_naissance,
                               adresse, adresse2, date_inscription, nom_pere, profession_pere, nom_mere, profession_mere,
                               classe_id, parent_id, montant_mensualite, numero_matricule,
                               transport_abonne, montant_transport, groupe_sanguin, allergies,
                               contact_urgence_nom, contact_urgence_tel, reduction_pourcentage, reduction_validite,
                               adresse, adresse, eleve_id))
            conn.commit()
            flash('Fiche élève mise à jour avec succès !', 'success')

        elif action == 'delete':
            conn.execute("DELETE FROM notes WHERE eleve_id=?", (eleve_id,))
            conn.execute("DELETE FROM eleves WHERE id=?", (eleve_id,))
            conn.commit()
            flash('Élève supprimé avec succès !', 'success')

        else:  # Action d'ajout (Add)
            nom = request.form.get('nom')
            prenom = request.form.get('prenom')
            nom_arabe = request.form.get('nom_arabe', '')
            prenom_arabe = request.form.get('prenom_arabe', '')
            sexe = request.form.get('sexe', 'M')
            date_naissance = request.form.get('date_naissance')
            lieu_naissance = request.form.get('lieu_naissance', '')
            adresse = request.form.get('adresse', '')
            import datetime
            date_inscription = request.form.get('date_inscription', datetime.datetime.now().strftime('%Y-%m-%d'))

            transport_abonne = request.form.get('transport_abonne', 'non')
            try:
                montant_transport = float(
                    request.form.get('montant_transport') or 0) if transport_abonne == 'oui' else 0
            except ValueError:
                montant_transport = 0

            nom_pere = request.form.get('nom_pere', '')
            profession_pere = request.form.get('profession_pere', '')
            nom_mere = request.form.get('nom_mere', '')
            profession_mere = request.form.get('profession_mere', '')

            # 🆕 Informations santé / contact d'urgence
            groupe_sanguin = request.form.get('groupe_sanguin', '')
            allergies = request.form.get('allergies', '')
            contact_urgence_nom = request.form.get('contact_urgence_nom', '')
            contact_urgence_tel = request.form.get('contact_urgence_tel', '')

            classe_id = request.form.get('classe_id')
            parent_id = request.form.get('parent_id')
            montant_mensualite = request.form.get('montant_mensualite', 800)

            # 🆕 Réduction (remise) sur la facture + date de validité
            try:
                reduction_pourcentage = float(request.form.get('reduction_pourcentage') or 0)
            except ValueError:
                reduction_pourcentage = 0
            reduction_pourcentage = max(0, min(100, reduction_pourcentage))
            reduction_validite = request.form.get('reduction_validite') or None

            import random
            numero_matricule = request.form.get('numero_matricule', f'EL{random.randint(100, 9999)}')

            classe_id = int(classe_id) if classe_id else None
            parent_id = int(parent_id) if parent_id else None

            if nom and prenom:
                conn.execute("""
                             INSERT INTO eleves (nom, prenom, nom_arabe, prenom_arabe, sexe, date_naissance, lieu_naissance, 
                                                 adresse, date_inscription, nom_pere, profession_pere, nom_mere, profession_mere, 
                                                 classe_id, parent_id, montant_mensualite, numero_matricule, 
                                                 transport_abonne, montant_transport, groupe_sanguin, allergies,
                                                 contact_urgence_nom, contact_urgence_tel, reduction_pourcentage, reduction_validite) 
                             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                             """, (
                    nom, prenom, nom_arabe, prenom_arabe, sexe, date_naissance, lieu_naissance,
                    adresse, date_inscription, nom_pere, profession_pere, nom_mere, profession_mere,
                    classe_id, parent_id, montant_mensualite, numero_matricule, transport_abonne, montant_transport,
                    groupe_sanguin, allergies, contact_urgence_nom, contact_urgence_tel,
                    reduction_pourcentage, reduction_validite
                ))
                conn.commit()
                flash('Élève inscrit avec succès !', 'success')

        conn.close()
        # 🔄 MODIFIÉ : On renvoie vers la classe spécifique si on a l'ID
        return redirect(url_for('gestion_eleves', cycle=cycle, classe_id=form_classe_id, tous=tous_form))

    # --- MÉTHODE GET ---
    cycle_filter = request.args.get('cycle')
    classe_filter = request.args.get('classe_id')  # 🔄 NOUVEAU
    search_query = request.args.get('q', '').strip()
    tous_filter = request.args.get('tous') == '1'  # 🆕 NOUVEAU : afficher tous les élèves, tous cycles/classes confondus
    # 🆕 NOUVEAU : filtre par statut de paiement (tous / paye / partiel / non_paye) et tri de la liste
    statut_paiement_filter = request.args.get('statut_paiement', '')
    sort_by = request.args.get('sort', '')

    # 🆕 VUE PARENT : "Mes enfants" — accès direct à la fiche de ses propres enfants,
    # sans passer par le sélecteur de cycle/classe (réservé à l'admin/enseignant).
    if session['role'] == 'parent':
        pay_join_parent = """
            LEFT JOIN (
                SELECT eleve_id, SUM(montant_total) as total_du, SUM(montant_paye) as total_paye
                FROM paiements GROUP BY eleve_id
            ) pay ON pay.eleve_id = e.id
        """
        eleves_raw = conn.execute("""
            SELECT e.*, c.nom as classe_nom, c.niveau as classe_niveau, u.nom as parent_nom, u.prenom as parent_prenom,
                   u.telephone as parent_telephone, pay.total_du, pay.total_paye
            FROM eleves e
            LEFT JOIN classes c ON e.classe_id = c.id
            LEFT JOIN users u ON e.parent_id = u.id
            """ + pay_join_parent + """
            WHERE e.parent_id = ?
            ORDER BY e.nom, e.prenom
        """, (session['user_id'],)).fetchall()

        eleves = []
        for row in eleves_raw:
            e = dict(row)
            total_du = e.get('total_du') or 0
            total_paye = e.get('total_paye') or 0
            if not e.get('total_du'):
                e['statut_paiement'] = 'aucun'
                e['reste_paiement'] = 0
            else:
                reste = total_du - total_paye
                e['reste_paiement'] = reste
                if reste <= 0:
                    e['statut_paiement'] = 'paye'
                elif total_paye > 0:
                    e['statut_paiement'] = 'partiel'
                else:
                    e['statut_paiement'] = 'non_paye'
            eleves.append(e)

        stats_classe = {
            'total': len(eleves),
            'garcons': sum(1 for e in eleves if (e['sexe'] or 'M') == 'M'),
            'filles': sum(1 for e in eleves if e['sexe'] == 'F'),
            'transport': sum(1 for e in eleves if e['transport_abonne'] == 'oui'),
            'impayes': sum(1 for e in eleves if e['statut_paiement'] in ('non_paye', 'partiel')),
        }

        conn.close()
        return render_template_string(ELEVES_HTML, eleves=eleves, classes=[], parents=[], cycle=None,
                                      classe_id=None, classe_actuelle=None, search_query='',
                                      tous_filter=True, stats_classe=stats_classe, notif_count=get_notif_count(),
                                      statut_paiement_filter='', sort_by='')

    # 1. Aucun cycle (Uniquement si aucune recherche globale n'est demandée, ni "tous les élèves")
    if not cycle_filter and not search_query and not tous_filter:
        cycles_liste = conn.execute("SELECT * FROM cycles ORDER BY ordre, nom").fetchall()
        conn.close()
        return render_template_string(ELEVES_HUB_HTML, notif_count=get_notif_count(), cycles=cycles_liste)

    # 2. 🔄 NOUVEAU : Cycle choisi mais aucune classe (Uniquement si aucune recherche n'est demandée)
    if cycle_filter and not classe_filter and not search_query and not tous_filter:
        classes_cycle = conn.execute(
            "SELECT * FROM classes WHERE cycle = ? OR (cycle IS NULL AND ? = 'Primaire') ORDER BY niveau, nom",
            (cycle_filter, cycle_filter)
        ).fetchall()
        conn.close()
        return render_template_string(CHOIX_CLASSE_ELEVES_HTML, classes=classes_cycle, cycle=cycle_filter,
                                      notif_count=get_notif_count())

    # 3. 🔄 MODIFIÉ : Construction adaptative de la requête pour supporter la recherche avec ou sans filtres de classe
    # 🆕 Sous-requête d'agrégation des paiements par élève, réutilisée pour afficher
    # un badge de statut de paiement directement dans la liste (facilite le suivi sans
    # devoir ouvrir chaque fiche élève).
    pay_join = """
            LEFT JOIN (
                SELECT eleve_id, SUM(montant_total) as total_du, SUM(montant_paye) as total_paye
                FROM paiements GROUP BY eleve_id
            ) pay ON pay.eleve_id = e.id
    """

    if session['role'] == 'enseignant':
        query = """
            SELECT e.*, c.nom as classe_nom, c.niveau as classe_niveau, u.nom as parent_nom, u.prenom as parent_prenom,
                   u.telephone as parent_telephone, pay.total_du, pay.total_paye
            FROM eleves e
            LEFT JOIN classes c ON e.classe_id = c.id
            LEFT JOIN users u ON e.parent_id = u.id
            """ + pay_join + """
            WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
        """
        params = [session['user_id']]
        if not tous_filter:
            if classe_filter:
                query += " AND c.id = ?"
                params.append(classe_filter)
            elif cycle_filter:
                query += " AND (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))"
                params.extend([cycle_filter, cycle_filter])
    else:
        query = """
            SELECT e.*, c.nom as classe_nom, c.niveau as classe_niveau, u.nom as parent_nom, u.prenom as parent_prenom,
                   u.telephone as parent_telephone, pay.total_du, pay.total_paye
            FROM eleves e
            LEFT JOIN classes c ON e.classe_id = c.id
            LEFT JOIN users u ON e.parent_id = u.id
            """ + pay_join + """
            WHERE 1=1
        """
        params = []
        if not tous_filter:
            if classe_filter:
                query += " AND c.id = ?"
                params.append(classe_filter)
            elif cycle_filter:
                query += " AND (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))"
                params.extend([cycle_filter, cycle_filter])

    if search_query:
        query += " AND (e.nom LIKE ? OR e.prenom LIKE ?)"
        params.extend([f"%{search_query}%", f"%{search_query}%"])

    # 🆕 Tri configurable : nom A-Z (défaut), nom Z-A, ou classe/niveau
    if sort_by == 'nom_desc':
        query += " ORDER BY e.nom DESC, e.prenom DESC"
    elif sort_by == 'nom_asc':
        query += " ORDER BY e.nom ASC, e.prenom ASC"
    else:
        query += " ORDER BY c.niveau, c.nom, e.nom, e.prenom"
    eleves_raw = conn.execute(query, params).fetchall()

    # 🆕 On calcule le statut de paiement de chaque élève (payé / partiel / non payé / aucun paiement
    # enregistré) pour l'afficher directement dans la liste et permettre de filtrer dessus.
    eleves = []
    for row in eleves_raw:
        e = dict(row)
        total_du = e.get('total_du') or 0
        total_paye = e.get('total_paye') or 0
        if not e.get('total_du'):
            e['statut_paiement'] = 'aucun'
            e['reste_paiement'] = 0
        else:
            reste = total_du - total_paye
            e['reste_paiement'] = reste
            if reste <= 0:
                e['statut_paiement'] = 'paye'
            elif total_paye > 0:
                e['statut_paiement'] = 'partiel'
            else:
                e['statut_paiement'] = 'non_paye'
        eleves.append(e)

    # 🆕 Filtre par statut de paiement (appliqué après calcul, sur la liste déjà chargée)
    if statut_paiement_filter and statut_paiement_filter in ('paye', 'partiel', 'non_paye', 'aucun'):
        eleves = [e for e in eleves if e['statut_paiement'] == statut_paiement_filter]

    # On récupère toutes les classes du cycle pour les menus déroulants d'ajout/modification
    classes = conn.execute("SELECT * FROM classes ORDER BY cycle, niveau, nom").fetchall()
    parents = conn.execute("SELECT * FROM users WHERE role='parent' ORDER BY nom").fetchall()

    # 🔄 NOUVEAU : Sécurisé pour éviter une requête vide si classe_filter n'est pas fourni lors d'une recherche globale
    classe_actuelle = conn.execute("SELECT niveau, nom FROM classes WHERE id=?",
                                   (classe_filter,)).fetchone() if classe_filter else None

    conn.close()

    # 🆕 PERF : stats calculées en mémoire (pas de requête SQL en plus) pour l'en-tête de la liste
    stats_classe = {
        'total': len(eleves),
        'garcons': sum(1 for e in eleves if (e['sexe'] or 'M') == 'M'),
        'filles': sum(1 for e in eleves if e['sexe'] == 'F'),
        'transport': sum(1 for e in eleves if e['transport_abonne'] == 'oui'),
        'impayes': sum(1 for e in eleves if e['statut_paiement'] in ('non_paye', 'partiel')),  # 🆕
    }

    # 🔄 MODIFIÉ : On passe classe_id, classe_actuelle, le filtre paiement et le tri au template final
    return render_template_string(ELEVES_HTML, eleves=eleves, classes=classes, parents=parents, cycle=cycle_filter,
                                  classe_id=classe_filter, classe_actuelle=classe_actuelle, search_query=search_query,
                                  tous_filter=tous_filter, stats_classe=stats_classe, notif_count=get_notif_count(),
                                  statut_paiement_filter=statut_paiement_filter, sort_by=sort_by)


@app.route('/eleves/add', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def add_eleve():
    conn = get_db()
    if request.method == 'POST':
        f = request.form
        import random

        # --- ADAPTATION : Récupération des nouveaux champs ---
        nom_arabe = f.get('nom_arabe', '')
        prenom_arabe = f.get('prenom_arabe', '')
        sexe = f.get('sexe', 'M')
        adresse = f.get('adresse', '')
        adresse2 = f.get('adresse2', '')
        date_inscription = f.get('date_inscription', datetime.datetime.now().strftime('%Y-%m-%d'))

        nom_pere = f.get('nom_pere', '')
        profession_pere = f.get('profession_pere', '')
        nom_mere = f.get('nom_mere', '')
        profession_mere = f.get('profession_mere', '')

        # 🆕 Informations santé / contact d'urgence
        groupe_sanguin = f.get('groupe_sanguin', '')
        allergies = f.get('allergies', '')
        contact_urgence_nom = f.get('contact_urgence_nom', '')
        contact_urgence_tel = f.get('contact_urgence_tel', '')

        # 🆕 GESTION DU PARENT DIRECTEMENT DEPUIS LA FICHE ÉLÈVE
        # ─────────────────────────────────────────────────────────
        # parent_mode = 'nouveau'  -> on crée un nouveau compte parent (users, role='parent')
        #                             avec les champs saisis sur ce même formulaire, et on
        #                             l'assigne automatiquement au nouvel élève.
        # parent_mode = 'existant' -> comportement d'origine : on choisit un parent déjà créé
        #                             dans la liste déroulante (utile pour les fratries).
        parent_mode = f.get('parent_mode', 'existant')
        parent_id_final = None

        if parent_mode == 'nouveau':
            p_nom = (f.get('nouveau_parent_nom') or '').strip()
            p_prenom = (f.get('nouveau_parent_prenom') or '').strip()
            p_email = (f.get('nouveau_parent_email') or '').strip()
            p_password = f.get('nouveau_parent_password') or ''
            p_telephone = f.get('nouveau_parent_telephone', '')
            p_cin = f.get('nouveau_parent_cin', '')

            if not (p_nom and p_prenom and p_email and p_password):
                flash("Merci de compléter tous les champs obligatoires (*) du compte parent, ou de choisir un parent existant.", 'error')
                conn.close()
                return redirect(url_for('add_eleve'))

            existing_parent = conn.execute("SELECT id FROM users WHERE email=?", (p_email,)).fetchone()
            if existing_parent:
                flash("Email déjà utilisé pour un autre compte parent ! Choisissez un autre email, ou sélectionnez ce parent dans la liste \"Parent existant\".", 'error')
                conn.close()
                return redirect(url_for('add_eleve'))

            cur_parent = conn.cursor()
            cur_parent.execute("""
                INSERT INTO users (nom, prenom, email, password, role, telephone, cin,
                                   nom_pere, profession_pere, nom_mere, profession_mere)
                VALUES (?, ?, ?, ?, 'parent', ?, ?, ?, ?, ?, ?)
                """,
                               (p_nom, p_prenom, p_email, hash_pw(p_password), p_telephone, p_cin,
                                nom_pere, profession_pere, nom_mere, profession_mere))
            parent_id_final = cur_parent.lastrowid
        else:
            parent_id_final = f.get('parent_id') or None

        montant_mensualite = f.get('montant_mensualite', 800)

        # 🆕 Réduction (remise) sur la mensualité + date de validité
        try:
            reduction_pourcentage = float(f.get('reduction_pourcentage') or 0)
        except ValueError:
            reduction_pourcentage = 0
        reduction_pourcentage = max(0, min(100, reduction_pourcentage))
        reduction_validite = f.get('reduction_validite') or None

        # 🆕 Réduction (remise) indépendante sur le transport + date de validité
        try:
            reduction_transport_pourcentage = float(f.get('reduction_transport_pourcentage') or 0)
        except ValueError:
            reduction_transport_pourcentage = 0
        reduction_transport_pourcentage = max(0, min(100, reduction_transport_pourcentage))
        reduction_transport_validite = f.get('reduction_transport_validite') or None

        transport_abonne = f.get('transport_abonne', 'non')
        try:
            montant_transport = float(f.get('montant_transport') or 0)
        except ValueError:
            montant_transport = 0

        # Matricule : on prend celui saisi, ou on en génère un s'il est vide
        mat = f.get('numero_matricule')
        if not mat:
            mat = f'EL{random.randint(100, 9999)}'

        # 1. Création de l'élève (mise à jour de la requête INSERT)
        cursor = conn.cursor()
        cursor.execute("""
            INSERT INTO eleves (nom, prenom, nom_arabe, prenom_arabe, sexe, date_naissance, adresse, adresse2, date_inscription, 
                                nom_pere, profession_pere, nom_mere, profession_mere, 
                                classe_id, parent_id, montant_mensualite, numero_matricule,
                                groupe_sanguin, allergies, contact_urgence_nom, contact_urgence_tel,
                                reduction_pourcentage, reduction_validite,
                                reduction_transport_pourcentage, reduction_transport_validite,
                                transport_abonne, montant_transport) 
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
                       (f['nom'], f['prenom'], nom_arabe, prenom_arabe, sexe, f.get('date_naissance'), adresse, adresse2, date_inscription,
                        nom_pere, profession_pere, nom_mere, profession_mere,
                        f.get('classe_id') or None, parent_id_final, montant_mensualite, mat,
                        groupe_sanguin, allergies, contact_urgence_nom, contact_urgence_tel,
                        reduction_pourcentage, reduction_validite,
                        reduction_transport_pourcentage, reduction_transport_validite,
                        transport_abonne, montant_transport))

        eleve_id = cursor.lastrowid  # Récupérer l'ID du nouvel élève

        # 🆕 2. FRAIS D'INSCRIPTION (au lieu de générer automatiquement la 1ère mensualité)
        # ─────────────────────────────────────────────────────────────────────────────────
        # On reprend exactement le même calcul/format que l'action "Frais d'inscription" de
        # la page /paiements (catégorie "Frais d'inscription"), avec les montants saisis ici
        # sur la fiche d'inscription : montant, réduction (%) et montant déjà payé.
        try:
            montant_inscription = float(f.get('montant_inscription') or 0)
        except ValueError:
            montant_inscription = 0.0
        try:
            reduction_inscription_pourcentage = float(f.get('reduction_inscription_pourcentage') or 0)
        except ValueError:
            reduction_inscription_pourcentage = 0.0
        reduction_inscription_pourcentage = max(0, min(100, reduction_inscription_pourcentage))
        try:
            montant_paye_inscription = float(f.get('montant_paye_inscription') or 0)
        except ValueError:
            montant_paye_inscription = 0.0

        if montant_inscription > 0:
            description_inscription = "[Frais d'inscription] Inscription"
            reduction_appliquee_inscription = 0.0
            montant_total_inscription = montant_inscription
            if reduction_inscription_pourcentage > 0:
                reduction_appliquee_inscription = round(montant_total_inscription * (reduction_inscription_pourcentage / 100), 2)
                montant_total_inscription = round(montant_total_inscription - reduction_appliquee_inscription, 2)
                description_inscription += f" (Réduction {reduction_inscription_pourcentage:g}% appliquée)"

            montant_paye_inscription = min(montant_paye_inscription, montant_total_inscription) if montant_total_inscription > 0 else montant_paye_inscription
            statut_inscription = 'paye' if montant_paye_inscription >= montant_total_inscription and montant_total_inscription > 0 \
                else ('partiel' if montant_paye_inscription > 0 else 'non_paye')
            # 🆕 Si des frais sont déjà réglés (partiellement ou en totalité) dès l'inscription,
            # on renseigne tout de suite la date de paiement (date du jour) plutôt que de la
            # laisser vide — sinon le reçu affiche "—" en Date de paiement malgré un statut payé/partiel.
            date_paiement_inscription = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S') \
                if statut_inscription in ('partiel', 'paye') else None

            cursor.execute(
                "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut,reduction_appliquee,date_paiement) VALUES (?,?,?,?,?,?,?,?)",
                (eleve_id, montant_total_inscription, montant_paye_inscription, description_inscription,
                 date_inscription, statut_inscription, reduction_appliquee_inscription, date_paiement_inscription))

        notif_to_parent(parent_id_final, f"Votre enfant {f['prenom']} {f['nom']} a été inscrit.", conn)
        conn.commit()
        conn.close()

        flash('Élève ajouté avec succès !', 'success')
        return redirect(url_for('gestion_eleves'))

    classes = conn.execute("SELECT * FROM classes ORDER BY niveau,nom").fetchall()
    parents = conn.execute(
        "SELECT id, prenom||' '||nom as nom_complet FROM users WHERE role='parent' ORDER BY nom").fetchall()
    conn.close()

    return render_template_string(ADD_ELEVE_HTML, classes=classes, parents=parents, notif_count=get_notif_count())


# ═══════════════════════════════════════════════════════════════
# 🆕 IMPORT D'ÉLÈVES DEPUIS UN FICHIER EXCEL (type liste Massar/AGDIL)
# ═══════════════════════════════════════════════════════════════
import unicodedata as _ud_import


def _norm_txt_import(v):
    """Nettoie une valeur de cellule Excel -> chaîne texte sans espaces inutiles."""
    if v is None:
        return ''
    if isinstance(v, (int, float)):
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)
    return str(v).strip()


def _split_date_lieu_import(v):
    """Sépare une cellule du type '13/02/2017فاس' ou '13-08-2016 AZROU' en (date_iso, lieu)."""
    if v is None:
        return '', ''
    if isinstance(v, (datetime.datetime, datetime.date)):
        return v.strftime('%Y-%m-%d'), ''
    s = str(v).strip()
    m = re.search(r'(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})', s)
    if not m:
        return '', s
    j, mo, a = m.groups()
    try:
        date_iso = datetime.date(int(a), int(mo), int(j)).strftime('%Y-%m-%d')
    except ValueError:
        date_iso = ''
    lieu = (s[:m.start()] + s[m.end():]).strip(' -,:')
    return date_iso, lieu


def _split_date_import(v):
    """Convertit une cellule date (objet datetime ou texte) en 'YYYY-MM-DD'."""
    if v is None or v == '':
        return ''
    if isinstance(v, (datetime.datetime, datetime.date)):
        return v.strftime('%Y-%m-%d')
    s = str(v).strip()
    m = re.search(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if m:
        a, mo, j = m.groups()
        return f"{int(a):04d}-{int(mo):02d}-{int(j):02d}"
    m = re.search(r'(\d{1,2})[/\-](\d{1,2})[/\-](\d{4})', s)
    if m:
        j, mo, a = m.groups()
        return f"{int(a):04d}-{int(mo):02d}-{int(j):02d}"
    return ''


def _split_nom_prenom_import(nom_complet):
    """Découpage approximatif 'PRENOM NOM(S)' -> (prenom, nom). À vérifier/corriger à l'écran."""
    s = re.sub(r'\s+', ' ', (nom_complet or '')).strip()
    if not s:
        return '', ''
    parts = s.split(' ')
    if len(parts) == 1:
        return parts[0], ''
    return parts[0], ' '.join(parts[1:])


def _parser_fichier_eleves_excel(fichier):
    """Lit un export Excel (type liste Massar/AGDIL : n°, nom AR, nom FR, date+lieu naissance,
    n° inscription, date inscription, père, métier père, mère, métier mère, tél, montant, transport)
    et retourne une liste de dictionnaires prêts à être affichés/édités avant import."""
    wb = openpyxl.load_workbook(fichier, data_only=True)
    ws = wb.active
    lignes = []
    for row in ws.iter_rows():
        valeurs = [c.value for c in row]
        # On cherche les lignes "données" : une colonne contient un numéro d'ordre (int)
        # et une colonne voisine contient un nom en caractères arabes.
        idx_num = None
        for i, v in enumerate(valeurs):
            if isinstance(v, (int, float)) and not isinstance(v, bool) and float(v).is_integer():
                idx_num = i
                break
        if idx_num is None:
            continue
        # Le nom arabe est la première cellule suivante contenant des caractères arabes
        idx_nom_ar = None
        for i in range(idx_num + 1, len(valeurs)):
            v = valeurs[i]
            if isinstance(v, str) and re.search(r'[\u0600-\u06FF]', v):
                idx_nom_ar = i
                break
        if idx_nom_ar is None:
            continue
        nom_ar = _norm_txt_import(valeurs[idx_nom_ar])
        # Le nom français est la cellule suivante non vide (texte latin)
        nom_fr = ''
        idx_nom_fr = None
        for i in range(idx_nom_ar + 1, len(valeurs)):
            v = valeurs[i]
            if isinstance(v, str) and v.strip() and re.search(r'[A-Za-z]', v):
                nom_fr = _norm_txt_import(v)
                idx_nom_fr = i
                break
        if idx_nom_fr is None:
            continue

        reste = valeurs[idx_nom_fr + 1:]
        # reste attendu : [naissance+lieu, n°inscription, date_inscription, père, métier père,
        #                  mère, métier mère, téléphone, montant, transport, ...]
        def g(i):
            return reste[i] if i < len(reste) else None

        date_naiss, lieu_naiss = _split_date_lieu_import(g(0))
        matricule = _norm_txt_import(g(1))
        date_inscription = _split_date_import(g(2))
        nom_pere = _norm_txt_import(g(3))
        profession_pere = _norm_txt_import(g(4))
        nom_mere = _norm_txt_import(g(5))
        profession_mere = _norm_txt_import(g(6))
        telephone = _norm_txt_import(g(7))
        montant_txt = _norm_txt_import(g(8))
        transport_txt = _norm_txt_import(g(9))

        try:
            montant_mensualite = float(montant_txt) if montant_txt else 800
        except ValueError:
            montant_mensualite = 800

        transport_abonne = 'non'
        montant_transport = 0
        try:
            montant_transport = float(transport_txt)
            transport_abonne = 'oui'
        except ValueError:
            transport_abonne = 'non'
            montant_transport = 0

        prenom_ar, nom_ar_famille = _split_nom_prenom_import(nom_ar)
        prenom_fr, nom_fr_famille = _split_nom_prenom_import(nom_fr)

        lignes.append({
            'nom': nom_fr_famille or nom_fr, 'prenom': prenom_fr,
            'nom_arabe': nom_ar_famille or nom_ar, 'prenom_arabe': prenom_ar,
            'date_naissance': date_naiss, 'lieu_naissance': lieu_naiss,
            'numero_matricule': matricule, 'date_inscription': date_inscription,
            'nom_pere': nom_pere, 'profession_pere': profession_pere,
            'nom_mere': nom_mere, 'profession_mere': profession_mere,
            'contact_urgence_tel': telephone,
            'montant_mensualite': montant_mensualite,
            'transport_abonne': transport_abonne, 'montant_transport': montant_transport,
        })
    return lignes


@app.route('/eleves/importer', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def importer_eleves():
    conn = get_db()
    classes = conn.execute("SELECT * FROM classes ORDER BY niveau,nom").fetchall()

    if request.method == 'POST':
        fichier = request.files.get('fichier')
        classe_id_defaut = request.form.get('classe_id') or ''
        if not fichier or not fichier.filename:
            flash("Merci de sélectionner un fichier Excel.", "error")
            conn.close()
            return redirect(url_for('importer_eleves'))
        try:
            lignes = _parser_fichier_eleves_excel(fichier)
        except Exception as ex:
            flash(f"Impossible de lire ce fichier Excel : {ex}", "error")
            conn.close()
            return redirect(url_for('importer_eleves'))
        conn.close()
        return render_template_string(IMPORT_ELEVES_PREVIEW_HTML, lignes=lignes, classes=classes,
                                      classe_id_defaut=classe_id_defaut, notif_count=get_notif_count())

    conn.close()
    return render_template_string(IMPORT_ELEVES_HTML, classes=classes, notif_count=get_notif_count())


@app.route('/eleves/importer/confirmer', methods=['POST'])
@login_required
@role_required('admin')
def importer_eleves_confirmer():
    import random
    conn = get_db()
    nb_lignes = int(request.form.get('nb_lignes') or 0)
    f = request.form
    ajoutes = 0
    ignores = 0

    for i in range(nb_lignes):
        if not f.get(f'garder_{i}'):
            continue
        nom = (f.get(f'nom_{i}') or '').strip()
        prenom = (f.get(f'prenom_{i}') or '').strip()
        if not nom or not prenom:
            ignores += 1
            continue

        nom_arabe = f.get(f'nom_arabe_{i}', '')
        prenom_arabe = f.get(f'prenom_arabe_{i}', '')
        date_naissance = f.get(f'date_naissance_{i}') or None
        lieu_naissance = f.get(f'lieu_naissance_{i}', '')
        classe_id = f.get(f'classe_id_{i}') or None
        nom_pere = f.get(f'nom_pere_{i}', '')
        profession_pere = f.get(f'profession_pere_{i}', '')
        nom_mere = f.get(f'nom_mere_{i}', '')
        profession_mere = f.get(f'profession_mere_{i}', '')
        contact_urgence_tel = f.get(f'contact_urgence_tel_{i}', '')

        try:
            montant_mensualite = float(f.get(f'montant_mensualite_{i}') or 800)
        except ValueError:
            montant_mensualite = 800

        montant_transport_txt = f.get(f'montant_transport_{i}', '')
        try:
            montant_transport = float(montant_transport_txt) if montant_transport_txt else 0
            transport_abonne = 'oui' if montant_transport_txt else 'non'
        except ValueError:
            montant_transport = 0
            transport_abonne = 'non'

        mat = (f.get(f'numero_matricule_{i}') or '').strip()
        if not mat:
            mat = f'EL{random.randint(1000, 999999)}'

        cursor = conn.cursor()
        try:
            cursor.execute("""
                INSERT INTO eleves (nom, prenom, nom_arabe, prenom_arabe, date_naissance, lieu_naissance,
                                    classe_id, numero_matricule, nom_pere, profession_pere, nom_mere, profession_mere,
                                    contact_urgence_tel, montant_mensualite, transport_abonne, montant_transport)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (nom, prenom, nom_arabe, prenom_arabe, date_naissance, lieu_naissance,
                      classe_id, mat, nom_pere, profession_pere, nom_mere, profession_mere,
                      contact_urgence_tel, montant_mensualite, transport_abonne, montant_transport))
        except sqlite3.IntegrityError:
            # Matricule déjà utilisé -> on en génère un nouveau et on réessaie une fois
            mat = f'EL{random.randint(1000, 999999)}'
            cursor.execute("""
                INSERT INTO eleves (nom, prenom, nom_arabe, prenom_arabe, date_naissance, lieu_naissance,
                                    classe_id, numero_matricule, nom_pere, profession_pere, nom_mere, profession_mere,
                                    contact_urgence_tel, montant_mensualite, transport_abonne, montant_transport)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (nom, prenom, nom_arabe, prenom_arabe, date_naissance, lieu_naissance,
                      classe_id, mat, nom_pere, profession_pere, nom_mere, profession_mere,
                      contact_urgence_tel, montant_mensualite, transport_abonne, montant_transport))

        eleve_id = cursor.lastrowid
        mois_courant = datetime.datetime.now().strftime('%Y-%m')
        description_frais = f"[Scolarité] Mensualité - {mois_courant}"
        cursor.execute(
            "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut) VALUES (?,?,?,?,?,?)",
            (eleve_id, montant_mensualite, 0, description_frais, f"{mois_courant}-01", 'non_paye'))
        ajoutes += 1

    conn.commit()
    conn.close()
    msg = f'{ajoutes} élève(s) importé(s) avec succès (1ère mensualité générée pour chacun).'
    if ignores:
        msg += f' {ignores} ligne(s) ignorée(s) (nom ou prénom manquant).'
    flash(msg, 'success')
    return redirect(url_for('gestion_eleves'))


