@app.route('/eleves/<int:eleve_id>/edit', methods=['POST'])
@login_required
@role_required('admin')
def edit_eleve(eleve_id):
    conn = get_db()
    f = request.form

    # 🔧 CORRECTION : la fiche élève complète (dossier /eleves/<id>) ne sauvegardait
    # que 5 champs sur ~20 disponibles. On aligne désormais cette route sur l'intégralité
    # des informations affichées sur la page (État civil, Scolarité, Famille, Santé/Urgence).
    nom = f.get('nom')
    prenom = f.get('prenom')
    nom_arabe = f.get('nom_arabe', '')
    prenom_arabe = f.get('prenom_arabe', '')
    sexe = f.get('sexe', 'M')
    date_naissance = f.get('date_naissance')
    lieu_naissance = f.get('lieu_naissance', '')
    adresse = f.get('adresse', '')
    adresse2 = f.get('adresse2', '')
    date_inscription = f.get('date_inscription') or None
    numero_matricule = f.get('numero_matricule')

    classe_id = f.get('classe_id') or None
    parent_id = f.get('parent_id') or None
    montant_mensualite = f.get('montant_mensualite', 800)

    # 🆕 Réduction (remise) sur la facture + date de validité
    try:
        reduction_pourcentage = float(f.get('reduction_pourcentage') or 0)
    except ValueError:
        reduction_pourcentage = 0
    reduction_pourcentage = max(0, min(100, reduction_pourcentage))
    reduction_validite = f.get('reduction_validite') or None

    # 🆕 Réduction (remise) indépendante sur le transport + date de validité
    try:
        reduction_transport_pourcentage = float(f.get('reduction_transport_pourcentage') or 0)
    except ValueError:
        reduction_transport_pourcentage = 0
    reduction_transport_pourcentage = max(0, min(100, reduction_transport_pourcentage))
    reduction_transport_validite = f.get('reduction_transport_validite') or None

    transport_abonne = f.get('transport_abonne', 'non')
    try:
        montant_transport = float(f.get('montant_transport') or 0) if transport_abonne == 'oui' else 0
    except ValueError:
        montant_transport = 0

    nom_pere = f.get('nom_pere', '')
    profession_pere = f.get('profession_pere', '')
    nom_mere = f.get('nom_mere', '')
    profession_mere = f.get('profession_mere', '')

    groupe_sanguin = f.get('groupe_sanguin', '')
    allergies = f.get('allergies', '')
    contact_urgence_nom = f.get('contact_urgence_nom', '')
    contact_urgence_tel = f.get('contact_urgence_tel', '')

    conn.execute("""
        UPDATE eleves
        SET nom=?, prenom=?, nom_arabe=?, prenom_arabe=?, sexe=?, date_naissance=?, lieu_naissance=?,
            adresse=?, adresse2=?, date_inscription=?, numero_matricule=?, classe_id=?, parent_id=?, montant_mensualite=?,
            transport_abonne=?, montant_transport=?, nom_pere=?, profession_pere=?, nom_mere=?, profession_mere=?,
            groupe_sanguin=?, allergies=?, contact_urgence_nom=?, contact_urgence_tel=?,
            reduction_pourcentage=?, reduction_validite=?,
            reduction_transport_pourcentage=?, reduction_transport_validite=?,
            latitude=CASE WHEN adresse=? THEN latitude ELSE NULL END,
            longitude=CASE WHEN adresse=? THEN longitude ELSE NULL END
        WHERE id=?
        """,
                 (nom, prenom, nom_arabe, prenom_arabe, sexe, date_naissance, lieu_naissance,
                  adresse, adresse2, date_inscription, numero_matricule, classe_id, parent_id, montant_mensualite,
                  transport_abonne, montant_transport, nom_pere, profession_pere, nom_mere, profession_mere,
                  groupe_sanguin, allergies, contact_urgence_nom, contact_urgence_tel,
                  reduction_pourcentage, reduction_validite,
                  reduction_transport_pourcentage, reduction_transport_validite, adresse, adresse, eleve_id))

    # 🆕 Frais d'inscription : on applique désormais EXACTEMENT la même logique de
    # réduction (montant de référence + "montant convenu" -> % calculé automatiquement)
    # que sur la fiche d'ajout d'élève (cf. add_eleve ci-dessus). On ne touche à cette
    # facture que si le formulaire de modification envoie ce champ (case "Frais
    # d'inscription" cochée/activée côté fiche élève) — sinon une facture déjà existante
    # (ou l'absence de facture) reste inchangée.
    if 'montant_inscription' in f:
        try:
            montant_inscription = float(f.get('montant_inscription') or 0)
        except ValueError:
            montant_inscription = 0.0
        try:
            reduction_inscription_pourcentage = float(f.get('reduction_inscription_pourcentage') or 0)
        except ValueError:
            reduction_inscription_pourcentage = 0.0
        reduction_inscription_pourcentage = max(0, min(100, reduction_inscription_pourcentage))
        try:
            montant_paye_inscription = float(f.get('montant_paye_inscription') or 0)
        except ValueError:
            montant_paye_inscription = 0.0

        if montant_inscription > 0:
            description_inscription = "[Frais d'inscription] Inscription"
            reduction_appliquee_inscription = 0.0
            montant_total_inscription = montant_inscription
            if reduction_inscription_pourcentage > 0:
                reduction_appliquee_inscription = round(montant_total_inscription * (reduction_inscription_pourcentage / 100), 2)
                montant_total_inscription = round(montant_total_inscription - reduction_appliquee_inscription, 2)
                description_inscription += f" (Réduction {reduction_inscription_pourcentage:g}% appliquée)"

            montant_paye_inscription = min(montant_paye_inscription, montant_total_inscription) if montant_total_inscription > 0 else montant_paye_inscription
            statut_inscription = 'paye' if montant_paye_inscription >= montant_total_inscription and montant_total_inscription > 0 \
                else ('partiel' if montant_paye_inscription > 0 else 'non_paye')

            # On retrouve la facture "Frais d'inscription" déjà créée pour cet élève (à
            # l'ajout, ou lors d'une modification précédente) pour la mettre à jour au lieu
            # d'en recréer une nouvelle en double.
            paiement_inscription_existant = conn.execute(
                "SELECT id, date_paiement FROM paiements WHERE eleve_id=? AND description LIKE ? "
                "ORDER BY created_at DESC LIMIT 1",
                (eleve_id, "[Frais d'inscription]%")).fetchone()

            date_paiement_inscription = None
            if statut_inscription in ('partiel', 'paye'):
                # Si la facture était déjà (partiellement) réglée, on conserve sa date de
                # paiement d'origine plutôt que de la remplacer par la date du jour à chaque
                # modification de la fiche.
                if paiement_inscription_existant and paiement_inscription_existant['date_paiement']:
                    date_paiement_inscription = paiement_inscription_existant['date_paiement']
                else:
                    date_paiement_inscription = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

            if paiement_inscription_existant:
                conn.execute(
                    "UPDATE paiements SET montant_total=?, montant_paye=?, description=?, statut=?, "
                    "reduction_appliquee=?, date_paiement=? WHERE id=?",
                    (montant_total_inscription, montant_paye_inscription, description_inscription,
                     statut_inscription, reduction_appliquee_inscription, date_paiement_inscription,
                     paiement_inscription_existant['id']))
            else:
                cursor_insc = conn.cursor()
                cursor_insc.execute(
                    "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut,reduction_appliquee,date_paiement) "
                    "VALUES (?,?,?,?,?,?,?,?)",
                    (eleve_id, montant_total_inscription, montant_paye_inscription, description_inscription,
                     date_inscription or datetime.datetime.now().strftime('%Y-%m-%d'), statut_inscription,
                     reduction_appliquee_inscription, date_paiement_inscription))

    db_commit_avec_retry(conn)
    conn.close()
    flash("Informations de l'élève mises à jour!", 'success')
    return redirect(url_for('eleve_detail', eleve_id=eleve_id))


