@app.route('/parents/<int:parent_id>')
@login_required
@role_required('admin', 'parent')
def parent_detail(parent_id):
    # Sécurité : un parent ne peut voir que son propre profil
    if session['role'] == 'parent' and session['user_id'] != parent_id:
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))

    conn = get_db()
    # Récupération de toutes les infos du parent depuis la table users
    parent = conn.execute("SELECT * FROM users WHERE id=? AND role='parent'", (parent_id,)).fetchone()

    if not parent:
        flash('Parent introuvable.', 'error')
        return redirect(url_for('dashboard'))

    # Récupération des enfants associés à ce parent
    enfants = conn.execute("""
        SELECT e.*, c.nom as classe 
        FROM eleves e 
        LEFT JOIN classes c ON e.classe_id=c.id 
        WHERE e.parent_id=?
    """, (parent_id,)).fetchall()
    # 🆕 Documents administratifs déjà déposés pour ce parent (CIN, contrat, etc.)
    documents_parent = conn.execute(
        "SELECT * FROM documents WHERE proprietaire_type='parent' AND proprietaire_id=? ORDER BY uploaded_at DESC",
        (parent_id,)).fetchall()

    # 🆕 SUIVI DES PAIEMENTS : badge de ponctualité calculé sur toutes les échéances des
    # enfants de ce parent (visible par l'admin ET par le parent lui-même, comme les paiements).
    indic_paiement = _indicateurs_paiement_parent(conn, parent_id)
    seuil_bloque = get_seuil_compte_bloque(conn)
    badge_paiement = _badge_paiement_parent(indic_paiement, seuil_bloque)

    # 🆕 FEEDBACK RENCONTRES : uniquement visible/gérable par l'admin (relation admin ↔ parent).
    feedbacks_parent = []
    badge_feedback = None
    indic_feedback = None
    if session['role'] in ('admin', 'agent_admin'):
        feedbacks_parent = conn.execute(
            "SELECT * FROM parent_feedback WHERE parent_id=? ORDER BY date_rencontre DESC",
            (parent_id,)).fetchall()
        indic_feedback = _indicateurs_feedback_parent(conn, parent_id)
        badge_feedback = _badge_feedback_parent(indic_feedback)

    conn.close()

    return render_template_string(PARENT_DETAIL_HTML, parent=parent, enfants=enfants,
                                  documents_parent=documents_parent, notif_count=get_notif_count(),
                                  indic_paiement=indic_paiement, badge_paiement=badge_paiement,
                                  feedbacks_parent=feedbacks_parent, badge_feedback=badge_feedback,
                                  indic_feedback=indic_feedback, feedback_labels=FEEDBACK_LABELS)


@app.route('/eleves/<int:eleve_id>')
@login_required
def eleve_detail(eleve_id):
    conn = get_db()

    # 🔧 CORRECTION 1 : Ajout de u.nom_pere, u.nom_mere, u.profession_pere, u.profession_mere dans la requête
    eleve = conn.execute(
        """
        SELECT e.*, 
               c.nom as classe, 
               u.prenom||' '||u.nom as parent_nom,
               u.telephone as parent_telephone,
               u.nom_pere as user_nom_pere,
               u.profession_pere as user_profession_pere,
               u.nom_mere as user_nom_mere,
               u.profession_mere as user_profession_mere
        FROM eleves e 
        LEFT JOIN classes c ON e.classe_id=c.id 
        LEFT JOIN users u ON e.parent_id=u.id 
        WHERE e.id=?
        """,
        (eleve_id,)
    ).fetchone()

    if not eleve:
        flash('Élève introuvable.', 'error')
        return redirect(url_for('eleves'))

    if session['role'] == 'parent' and eleve['parent_id'] != session['user_id']:
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('eleves'))

    # 🆕 Moyenne pondérée à deux niveaux : d'abord au sein de chaque matière en tenant compte
    # du coefficient de la sous-matière (ex: Dictée coef 2, Participation coef 1 dans "Arabe"),
    # puis entre matières en tenant compte du coefficient de la matière elle-même.
    # Reste 100% rétrocompatible : les notes sans sous-matière comptent avec un coefficient de 1.
    _moyenne_ponderee = _moyenne_ponderee_matieres

    notes_by_trimestre = {}
    for t in [1, 2]:
        notes = conn.execute(
            """SELECT n.*, m.nom as matiere, m.coefficient, sm.coefficient as sm_coefficient
               FROM notes n JOIN matieres m ON n.matiere_id=m.id
               LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id
               WHERE n.eleve_id=? AND n.trimestre=?""",
            (eleve_id, t)).fetchall()
        if notes:
            avg, _ = _moyenne_ponderee(notes)
        else:
            avg = 0
        # 🆕 Appréciation générale (admin/agent-admin) & observations des enseignants, saisies
        # pour ce trimestre — affichées et éditables directement sous le tableau de notes.
        appr_row = conn.execute(
            "SELECT appreciation_generale, observation_enseignant FROM bulletin_appreciations WHERE eleve_id=? AND trimestre=?",
            (eleve_id, str(t))).fetchone()
        notes_by_trimestre[t] = {
            'notes': notes, 'moyenne': avg,
            'appreciation_generale': appr_row['appreciation_generale'] if appr_row else '',
            'observation_enseignant': appr_row['observation_enseignant'] if appr_row else '',
        }

    # Seuls les admins (ou les parents) récupèrent les données de paiement
    paiement_inscription = None
    if session.get('role') in ('admin', 'agent_admin'):
        paiements = conn.execute("SELECT * FROM paiements WHERE eleve_id=? ORDER BY created_at DESC",
                                 (eleve_id,)).fetchall()
        # 🆕 Facture "Frais d'inscription" déjà créée pour cet élève (à l'ajout ou lors d'une
        # modification précédente), utilisée pour préremplir le bloc "Frais d'inscription"
        # de la modale de modification avec le même comportement que la fiche d'ajout.
        paiement_inscription = conn.execute(
            "SELECT * FROM paiements WHERE eleve_id=? AND description LIKE ? "
            "ORDER BY created_at DESC LIMIT 1",
            (eleve_id, "[Frais d'inscription]%")).fetchone()
    else:
        paiements = []

    absences = conn.execute("SELECT * FROM absences WHERE eleve_id=? ORDER BY date_absence DESC",
                            (eleve_id,)).fetchall()

    # 🆕 Retards : la table existait déjà dans la base (créée pour l'analyse globale)
    # mais n'était jamais affichée sur la fiche élève. On l'exploite ici.
    retards = conn.execute("SELECT * FROM retards WHERE eleve_id=? ORDER BY date_retard DESC",
                           (eleve_id,)).fetchall()

    classes = conn.execute("SELECT * FROM classes ORDER BY niveau, nom").fetchall()
    parents = conn.execute(
        "SELECT id, prenom||' '||nom as nom_complet FROM users WHERE role='parent' ORDER BY nom").fetchall()

    # Matières pour cet élève
    matieres = conn.execute(
        "SELECT m.* FROM matieres m JOIN classes c ON m.classe_id=c.id JOIN eleves e ON e.classe_id=c.id WHERE e.id=? ORDER BY m.nom",
        (eleve_id,)).fetchall()

    # 🆕 Âge et ancienneté calculés à la volée (pas de colonne à maintenir en base)
    def _calc_annees(date_str):
        if not date_str:
            return None
        try:
            d = datetime.datetime.strptime(date_str[:10], '%Y-%m-%d').date()
            today = datetime.date.today()
            return today.year - d.year - ((today.month, today.day) < (d.month, d.day))
        except (ValueError, TypeError):
            return None

    age = _calc_annees(eleve['date_naissance'])
    anciennete_annees = _calc_annees(eleve['date_inscription'])

    # 🆕 Moyenne générale = moyenne des trimestres réellement notés
    moyennes_valides = [d['moyenne'] for d in notes_by_trimestre.values() if d['notes']]
    moyenne_generale = round(sum(moyennes_valides) / len(moyennes_valides), 2) if moyennes_valides else None

    # 🆕 Badge de profil (Critique/Fragile/Stable/Leader/Champion) + matière qui le justifie —
    # moyenne par matière pondérée : sous-matière d'abord, puis coefficient de la matière.
    toutes_les_notes = notes_by_trimestre[1]['notes'] + notes_by_trimestre[2]['notes']
    _, moys_par_matiere = _moyenne_ponderee(toutes_les_notes) if toutes_les_notes else (0, {})
    matieres_badge = list(moys_par_matiere.items())
    profil_badge = _badge_profil(moyenne_generale, matieres_badge)

    # 🆕 Données pour le tableau de bord graphique (jauge de moyenne, évolution T1→T2,
    # moyenne par matière) — sérialisées en JSON pour être consommées par Chart.js côté client.
    matieres_chart_json = json.dumps({
        nom: round(moy, 2) for nom, moy in sorted(moys_par_matiere.items())
    }, ensure_ascii=False)
    evolution_chart_json = json.dumps({
        't1': round(notes_by_trimestre[1]['moyenne'], 2) if notes_by_trimestre[1]['notes'] else None,
        't2': round(notes_by_trimestre[2]['moyenne'], 2) if notes_by_trimestre[2]['notes'] else None,
    })
    nb_matieres_notees = len(moys_par_matiere)

    # 🆕 Classement dans la classe : une seule requête groupée (rapide grâce aux index
    # idx_notes_eleve_id / idx_eleves_classe_id ajoutés ci-dessus), calculée en SQL plutôt
    # qu'en boucle Python pour rester performant même avec beaucoup d'élèves.
    rang, total_classe = None, None
    if eleve['classe_id']:
        classement = conn.execute(SQL_CLASSEMENT_PONDERE, (eleve['classe_id'],)).fetchall()
        total_classe = len(classement)
        for i, row in enumerate(classement, start=1):
            if row['id'] == eleve_id:
                rang = i
                break

    # 🆕 Indicateurs d'assiduité
    nb_absences_total = len(absences)
    nb_absences_injustifiees = sum(1 for a in absences if not a['justifiee'])
    nb_retards_total = len(retards)

    # 🆕 Solde impayé (uniquement visible par l'admin, comme le reste des données financières)
    solde_impaye = None
    statut_paiement_eleve = None
    if session.get('role') in ('admin', 'agent_admin'):
        solde_impaye = sum((p['montant_total'] or 0) - (p['montant_paye'] or 0) for p in paiements)
        total_paye_eleve = sum((p['montant_paye'] or 0) for p in paiements)
        if not paiements:
            statut_paiement_eleve = 'aucun'
        elif solde_impaye <= 0:
            statut_paiement_eleve = 'paye'
        elif total_paye_eleve > 0:
            statut_paiement_eleve = 'partiel'
        else:
            statut_paiement_eleve = 'non_paye'

    # 🆕 Documents administratifs déjà déposés pour cet élève (CIN, contrat, etc.)
    documents_eleve = conn.execute(
        "SELECT * FROM documents WHERE proprietaire_type='eleve' AND proprietaire_id=? ORDER BY uploaded_at DESC",
        (eleve_id,)).fetchall()

    # 🆕 Emploi du temps de la classe de l'élève, en lecture seule sur la fiche
    # (utile notamment pour le parent, qui n'a pas accès à la page d'administration /emploi-temps).
    emploi_temps_eleve = {jour: [] for jour in JOURS_SEMAINE}
    if eleve['classe_id']:
        creneaux_eleve = conn.execute("""
            SELECT et.*, m.nom as matiere_nom
            FROM emploi_temps et
            LEFT JOIN matieres m ON et.matiere_id = m.id
            WHERE et.classe_id = ?
            ORDER BY et.heure_debut
        """, (eleve['classe_id'],)).fetchall()
        for c in creneaux_eleve:
            if c['jour'] in emploi_temps_eleve:
                emploi_temps_eleve[c['jour']].append(dict(c))

    conn.close()

    # 🔧 CORRECTION 2 : Utilisation de ELEVE_DETAIL_HTML au lieu de ELEVES_HTML
    return render_template_string(ELEVE_DETAIL_HTML,
                                  eleve=eleve, notes_by_trimestre=notes_by_trimestre, paiements=paiements,
                                  absences=absences, retards=retards, classes=classes, parents=parents,
                                  matieres=matieres, age=age, anciennete_annees=anciennete_annees,
                                  moyenne_generale=moyenne_generale, profil_badge=profil_badge,
                                  rang=rang, total_classe=total_classe,
                                  nb_absences_total=nb_absences_total,
                                  nb_absences_injustifiees=nb_absences_injustifiees,
                                  nb_retards_total=nb_retards_total, solde_impaye=solde_impaye,
                                  statut_paiement_eleve=statut_paiement_eleve,
                                  documents_eleve=documents_eleve,
                                  emploi_temps_eleve=emploi_temps_eleve, jours_semaine=JOURS_SEMAINE,
                                  matieres_chart_json=matieres_chart_json,
                                  evolution_chart_json=evolution_chart_json,
                                  nb_matieres_notees=nb_matieres_notees,
                                  paiement_inscription=paiement_inscription,
                                  notif_count=get_notif_count())


# 🆕 FICHE / FICHIER MÉDICAL DE L'ÉLÈVE (téléchargement direct en PDF)
# Contient : nom, prénom, nom du père, nom de la mère, groupe sanguin,
# allergies / besoins particuliers, nom et téléphone du contact d'urgence.
# ─────────────────────────────────────────────
# 🆕 DOCUMENTS (CIN, contrat de scolarité, etc.) — profil parent et profil élève
# ─────────────────────────────────────────────
TYPES_DOCUMENTS = ['CIN', 'Contrat de scolarité', 'Acte de naissance', 'Certificat médical', 'Autre']


def _peut_gerer_documents(proprietaire_type, proprietaire_id, conn):
    """Vérifie que l'utilisateur courant a le droit d'ajouter/voir/supprimer les documents
    d'un parent ou d'un élève : admin toujours autorisé ; un parent uniquement pour son
    propre profil ou celui de ses enfants."""
    if session.get('role') == 'admin':
        return True
    if session.get('role') != 'parent':
        return False
    if proprietaire_type == 'parent':
        return session['user_id'] == proprietaire_id
    if proprietaire_type == 'eleve':
        row = conn.execute("SELECT parent_id FROM eleves WHERE id=?", (proprietaire_id,)).fetchone()
        return bool(row) and row['parent_id'] == session['user_id']
    return False


def _enregistrer_document(proprietaire_type, proprietaire_id):
    conn = get_db()
    try:
        if not _peut_gerer_documents(proprietaire_type, proprietaire_id, conn):
            flash('Accès non autorisé.', 'error')
            return

        type_document = request.form.get('type_document', '').strip() or 'Autre'
        fichier = request.files.get('fichier')
        if not fichier or fichier.filename == '':
            flash('Veuillez sélectionner un fichier.', 'error')
            return

        ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
        if ext not in ALLOWED_DOC_EXTENSIONS:
            flash(f"Type de fichier .{ext} non autorisé. Formats acceptés : "
                  f"{', '.join(sorted(ALLOWED_DOC_EXTENSIONS))}.", 'error')
            return

        nom_original = secure_filename(fichier.filename)
        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
        nom_fichier = f"{proprietaire_type}_{proprietaire_id}_{ts}_{nom_original}"
        _sauvegarder_image_compressee(fichier, os.path.join(UPLOAD_FOLDER_DOCS, nom_fichier), max_dimension=1800, qualite=84)

        conn.execute(
            """INSERT INTO documents (proprietaire_type, proprietaire_id, type_document,
                                      nom_original, nom_fichier, uploaded_by)
               VALUES (?, ?, ?, ?, ?, ?)""",
            (proprietaire_type, proprietaire_id, type_document, nom_original, nom_fichier,
             session.get('user_id')))
        conn.commit()
        flash(f'Document "{type_document}" ajouté avec succès !', 'success')
    finally:
        conn.close()


@app.route('/parents/<int:parent_id>/documents/add', methods=['POST'])
@login_required
@role_required('admin', 'parent')
def parent_document_add(parent_id):
    _enregistrer_document('parent', parent_id)
    return redirect(url_for('parent_detail', parent_id=parent_id))


# 🆕 FEEDBACK RENCONTRE PARENT (personnalité / relation, réservé à l'admin)
@app.route('/parents/<int:parent_id>/feedback/add', methods=['POST'])
@login_required
@role_required('admin')
def parent_feedback_add(parent_id):
    feedback = request.form.get('feedback', '').strip()
    commentaire = request.form.get('commentaire', '').strip()
    date_rencontre = request.form.get('date_rencontre', '').strip()

    if feedback not in ('Bon', 'Neutre', 'Enerve'):
        flash('Veuillez choisir un feedback valide.', 'error')
        return redirect(url_for('parent_detail', parent_id=parent_id))

    conn = get_db()
    parent = conn.execute("SELECT prenom||' '||nom as nom FROM users WHERE id=? AND role='parent'",
                          (parent_id,)).fetchone()
    if not parent:
        conn.close()
        flash('Parent introuvable.', 'error')
        return redirect(url_for('dashboard'))

    if date_rencontre:
        try:
            # On garde l'heure actuelle si seule la date est fournie, pour préserver l'ordre chronologique
            d = datetime.datetime.strptime(date_rencontre, '%Y-%m-%d')
            date_rencontre_sql = d.strftime('%Y-%m-%d') + ' ' + datetime.datetime.now().strftime('%H:%M:%S')
        except ValueError:
            date_rencontre_sql = None
    else:
        date_rencontre_sql = None

    if date_rencontre_sql:
        conn.execute(
            "INSERT INTO parent_feedback (parent_id, admin_id, admin_nom, feedback, commentaire, date_rencontre) "
            "VALUES (?,?,?,?,?,?)",
            (parent_id, session.get('user_id'), session.get('nom_complet', ''), feedback, commentaire,
             date_rencontre_sql))
    else:
        conn.execute(
            "INSERT INTO parent_feedback (parent_id, admin_id, admin_nom, feedback, commentaire) "
            "VALUES (?,?,?,?,?)",
            (parent_id, session.get('user_id'), session.get('nom_complet', ''), feedback, commentaire))

    log_action(conn, 'creation', 'parent_feedback', parent_id,
               f"Feedback '{feedback}' ajouté pour {parent['nom']}")
    conn.commit()
    conn.close()
    flash('Feedback enregistré avec succès !', 'success')
    return redirect(url_for('parent_detail', parent_id=parent_id))


@app.route('/parents/<int:parent_id>/feedback/<int:feedback_id>/delete', methods=['POST'])
@login_required
@role_required('admin')
def parent_feedback_delete(parent_id, feedback_id):
    conn = get_db()
    conn.execute("DELETE FROM parent_feedback WHERE id=? AND parent_id=?", (feedback_id, parent_id))
    log_action(conn, 'suppression', 'parent_feedback', feedback_id, f"Feedback supprimé (parent #{parent_id})")
