@app.route('/eleves/<int:eleve_id>/fichier-medical')
@login_required
def fichier_medical_eleve(eleve_id):
    conn = get_db()
    eleve = conn.execute(
        """
        SELECT e.*,
               u.nom_pere as user_nom_pere,
               u.nom_mere as user_nom_mere
        FROM eleves e
        LEFT JOIN users u ON e.parent_id = u.id
        WHERE e.id = ?
        """,
        (eleve_id,)
    ).fetchone()
    conn.close()

    if not eleve:
        flash('Élève introuvable.', 'error')
        return redirect(url_for('eleves'))

    # Même règle d'accès que la fiche élève : un parent ne peut télécharger que la fiche de son enfant
    if session['role'] == 'parent' and eleve['parent_id'] != session['user_id']:
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('eleves'))

    # On privilégie l'info saisie directement sur la fiche élève, sinon on retombe sur celle du compte parent
    nom_pere = eleve['nom_pere'] or eleve['user_nom_pere'] or 'Non renseigné'
    nom_mere = eleve['nom_mere'] or eleve['user_nom_mere'] or 'Non renseigné'

    try:
        headers = ['Champ', 'Information']
        rows = [
            ['Nom', eleve['nom'] or '—'],
            ['Prénom', eleve['prenom'] or '—'],
            ['Nom du père', nom_pere],
            ['Nom de la mère', nom_mere],
            ['Groupe sanguin', eleve['groupe_sanguin'] or 'Non renseigné'],
            ['Allergies / besoins particuliers', eleve['allergies'] or 'Aucun renseigné'],
            ["Nom du contact d'urgence", eleve['contact_urgence_nom'] or 'Non renseigné'],
            ["Téléphone du contact d'urgence", eleve['contact_urgence_tel'] or 'Non renseigné'],
        ]
        subtitle = f"Élève : {eleve['prenom']} {eleve['nom']} — Document confidentiel à usage interne / secours"
        from reportlab.lib.units import cm
        nom_fichier = f"fichier_medical_{eleve['prenom']}_{eleve['nom']}.pdf".replace(' ', '_')
        return _pdf_table_report('Fichier Médical', subtitle, headers, rows, [7 * cm, 9.5 * cm], nom_fichier)
    except Exception as ex:
        flash(f'Erreur génération du fichier médical: {ex}', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))


# ─────────────────────────────────────────────
# NOTES
# ─────────────────────────────────────────────
@app.route('/notes', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'enseignant', 'parent')
def gestion_notes():
    conn = get_db()

    if request.method == 'POST':
        # CORRECTION 3 : On cherche le cycle et la classe dans le formulaire (form) OU dans l'URL (args)
        cycle = request.form.get('cycle') or request.args.get('cycle') or 'Primaire'
        form_classe_id = request.form.get('classe_id') or request.args.get('classe_id')

        if session['role'] == 'parent':
            flash("Action non autorisée.", "error")
            conn.close()
            return redirect(url_for('gestion_notes', cycle=cycle))

        if session['role'] == 'enseignant':
            has_access = conn.execute("""
                                      SELECT COUNT(*)
                                      FROM classes c
                                      LEFT JOIN matieres m ON m.classe_id = c.id
                                      WHERE (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
                                        AND (
                                            EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
                                            OR m.enseignant_id = ?
                                        )
                                      """, (cycle, cycle, session['user_id'], session['user_id'])).fetchone()[0]

            if has_access == 0:
                flash("Action non autorisée : Vous n'êtes pas assigné à ce cycle.", "error")
                conn.close()
                return redirect(url_for('gestion_notes'))

        action = request.form.get('action')
        note_id = request.form.get('note_id')

        if action == 'edit':
            note_lettre = request.form.get('note_lettre')
            if note_lettre:
                nouvelle_note = NOTE_LETTRES_MATERNELLE.get(note_lettre.upper(), 10.0)
            else:
                nouvelle_note = float(request.form.get('note'))
            commentaire = request.form.get('commentaire', '').strip()

            if session['role'] == 'enseignant':
                check = conn.execute("SELECT modifiee, enseignant_id FROM notes WHERE id=?", (note_id,)).fetchone()
                if not check:
                    flash("Note introuvable.", "error")
                elif check['enseignant_id'] != session['user_id']:
                    flash("Erreur : Vous ne pouvez modifier que les notes que vous avez saisies.", "error")
                elif check['modifiee'] == 1:
                    flash("Erreur : Vous avez déjà utilisé votre unique tentative de modification pour cette note.",
                          "error")
                elif not commentaire:
                    flash("Erreur : Un commentaire est obligatoire pour justifier votre modification.", "error")
                else:
                    conn.execute("UPDATE notes SET note=?, modifiee=1, commentaire=? WHERE id=?",
                                 (nouvelle_note, commentaire, note_id))
                    conn.commit()
                    flash("Note modifiée avec succès ! (Votre unique tentative a été utilisée)", "success")

            elif session['role'] in ('admin', 'agent_admin'):
                comm_admin = commentaire if commentaire else "Modifié par l'administrateur"
                conn.execute("UPDATE notes SET note=?, commentaire=? WHERE id=?", (nouvelle_note, comm_admin, note_id))
                conn.commit()
                flash("Note modifiée par l'administrateur.", "success")

        elif action == 'delete':
            if session['role'] in ('admin', 'agent_admin'):
                conn.execute("DELETE FROM notes WHERE id=?", (note_id,))
                conn.commit()
                flash("Note supprimée définitivement.", "success")
            else:
                flash("Erreur : Seul l'administrateur est autorisé à supprimer des notes.", "error")

        else:
            eleve_id = request.form.get('eleve_id')
            matiere_id = request.form.get('matiere_id')
            note_lettre = request.form.get('note_lettre')
            if note_lettre:
                note_val = NOTE_LETTRES_MATERNELLE.get(note_lettre.upper(), 10.0)
            else:
                note_val = request.form.get('note')
            trimestre = request.form.get('trimestre')
            ens_id = session['user_id'] if session['role'] == 'enseignant' else request.form.get('enseignant_id')
            # 🆕 Sous-matière optionnelle (ex: "Dictée" pour la matière "Arabe") — vide = note globale de la matière
            sous_matiere_id = request.form.get('sous_matiere_id') or None

            conn.execute(
                "INSERT INTO notes (eleve_id, matiere_id, sous_matiere_id, enseignant_id, note, trimestre) VALUES (?, ?, ?, ?, ?, ?)",
                (eleve_id, matiere_id, sous_matiere_id, ens_id, note_val, trimestre))
            conn.commit()
            flash("Note enregistrée avec succès !", "success")

        conn.close()
        # 🔄 MODIFIÉ : On renvoie vers la vue filtrée sur la classe (si connue)
        return redirect(url_for('gestion_notes', cycle=cycle, classe_id=form_classe_id))

    # --- CODE MÉTHODE GET ---
    cycle_filter = request.args.get('cycle')
    classe_filter = request.args.get('classe_id')  # 🔄 NOUVEAU

    if not cycle_filter:
        conn.close()
        return render_template_string(NOTES_HUB_HTML, notif_count=get_notif_count())

    # 🔄 NOUVEAU : Si l'utilisateur n'est pas un parent, et qu'aucune classe n'est sélectionnée -> Page Choix
    if session['role'] != 'parent' and not classe_filter:
        classes_cycle = conn.execute(
            "SELECT * FROM classes WHERE cycle = ? OR (cycle IS NULL AND ? = 'Primaire') ORDER BY niveau, nom",
            (cycle_filter, cycle_filter)
        ).fetchall()
        conn.close()
        return render_template_string(CHOIX_CLASSE_NOTES_HTML, classes=classes_cycle, cycle=cycle_filter,
                                      notif_count=get_notif_count())

    # Si on arrive ici : Soit c'est un parent, soit c'est un enseignant/admin AVEC une classe_id sélectionnée.

    if session['role'] == 'enseignant':
        # 🔄 MODIFIÉ : On vérifie l'assignation pour cette classe spécifique, plus juste pour le cycle !
        has_access = conn.execute("""
                                  SELECT COUNT(*)
                                  FROM classes c
                                  LEFT JOIN matieres m ON m.classe_id = c.id
                                  WHERE c.id = ?
                                    AND (
                                        EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
                                        OR m.enseignant_id = ?
                                    )
                                  """, (classe_filter, session['user_id'], session['user_id'])).fetchone()[0]

        if has_access == 0:
            flash(f"Accès refusé : Vous n'êtes pas assigné à cette classe.", "error")
            conn.close()
            return redirect(url_for('gestion_notes', cycle=cycle_filter))

    query = """
            SELECT n.*, e.nom as el_nom, e.prenom as el_prenom, m.nom as mat_nom, u.nom as ens_nom, u.prenom as ens_prenom,
                   sm.nom as sous_mat_nom
            FROM notes n
            JOIN eleves e ON n.eleve_id = e.id
            JOIN matieres m ON n.matiere_id = m.id
            JOIN users u ON n.enseignant_id = u.id
            LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id
            LEFT JOIN classes c ON e.classe_id = c.id 
            """

    # 🔄 MODIFIÉ : Filtrage sur la classe (sauf pour le parent qui garde une vue globale par cycle)
    if session['role'] == 'enseignant':
        query += " WHERE c.id = ? AND n.enseignant_id = ?"
        notes = conn.execute(query + " ORDER BY n.date_saisie DESC", (classe_filter, session['user_id'],)).fetchall()
    elif session['role'] == 'parent':
        query += " WHERE (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire')) AND e.parent_id = ?"
        notes = conn.execute(query + " ORDER BY m.nom, n.trimestre",
                             (cycle_filter, cycle_filter, session['user_id'],)).fetchall()
    else:  # admin
        query += " WHERE c.id = ?"
        notes = conn.execute(query + " ORDER BY n.date_saisie DESC", (classe_filter,)).fetchall()

    # 🔄 MODIFIÉ : Récupération des dropdowns limitée à la classe
    if session['role'] in ('admin', 'agent_admin'):
        eleves = conn.execute("""
                              SELECT e.id, e.nom, e.prenom
                              FROM eleves e 
                              WHERE e.classe_id = ?
                              ORDER BY e.nom
                              """, (classe_filter,)).fetchall()

        matieres = conn.execute("""
                                SELECT m.id, m.nom
                                FROM matieres m 
                                WHERE m.classe_id = ?
                                ORDER BY m.nom
                                """, (classe_filter,)).fetchall()

    elif session['role'] == 'enseignant':
        eleves = conn.execute("""
                              SELECT DISTINCT e.id, e.nom, e.prenom
                              FROM eleves e
                              WHERE e.classe_id = ?
                              ORDER BY e.nom
                              """, (classe_filter,)).fetchall()

        matieres = conn.execute("""
                                SELECT DISTINCT m.id, m.nom
                                FROM matieres m
                                WHERE m.classe_id = ? AND m.enseignant_id = ?
                                ORDER BY m.nom
                                """, (classe_filter, session['user_id'])).fetchall()
    else:
        # 🆕 Vue parent : on liste explicitement ses propres enfants du cycle (même ceux sans note)
        eleves = conn.execute("""
                              SELECT e.id, e.nom, e.prenom, c.nom as classe_nom
                              FROM eleves e
                              LEFT JOIN classes c ON e.classe_id = c.id
                              WHERE e.parent_id = ? AND (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
                              ORDER BY e.nom
                              """, (session['user_id'], cycle_filter, cycle_filter)).fetchall()
        matieres = []

    # 🆕 Carte matière → sous-matières (utilisée en JS pour afficher dynamiquement le bon
    # sélecteur de sous-matière selon la matière choisie dans le formulaire de saisie de note)
    sous_matieres_map = {}
    for m in matieres:
        sm_rows = conn.execute(
            "SELECT id, nom, coefficient FROM sous_matieres WHERE matiere_id=? AND actif=1 ORDER BY ordre, nom",
            (m['id'],)).fetchall()
        if sm_rows:
            sous_matieres_map[m['id']] = [dict(r) for r in sm_rows]

    enseignants = conn.execute("SELECT id, nom, prenom FROM users WHERE role='enseignant' ORDER BY nom").fetchall()

    # 🆕 Regroupement des notes par élève, façon "une carte par élève" (avec les élèves sans note inclus)
    notes_par_eleve = {}
    for e in eleves:
        notes_par_eleve[e['id']] = []
    for n in notes:
        notes_par_eleve.setdefault(n['eleve_id'], []).append(n)

    # 🔄 NOUVEAU : Récupération des infos de la classe
    classe_actuelle = conn.execute("SELECT niveau, nom FROM classes WHERE id=?",
                                   (classe_filter,)).fetchone() if classe_filter else None

    conn.close()

    # 🆕 Données agrégées pour les graphiques de l'en-tête : répartition des profils
    # (Critique/Fragile/Stable/Leader/Champion) et moyenne globale T1 vs T2, calculées
    # une seule fois côté serveur pour rester rapides même avec beaucoup d'élèves.
    profil_ordre = ['Critique', 'Fragile', 'Stable', 'Leader', 'Champion']
    profil_counts = {k: 0 for k in profil_ordre}
    notes_t1, notes_t2 = [], []
    for e in eleves:
        mes_notes_e = notes_par_eleve.get(e['id'], [])
        if not mes_notes_e:
            continue
        moy_e = sum(n['note'] for n in mes_notes_e) / len(mes_notes_e)
        if moy_e < 4:
            profil_counts['Critique'] += 1
        elif moy_e < 8:
            profil_counts['Fragile'] += 1
        elif moy_e < 12:
            profil_counts['Stable'] += 1
        elif moy_e < 16:
            profil_counts['Leader'] += 1
        else:
            profil_counts['Champion'] += 1
        for n in mes_notes_e:
            (notes_t1 if str(n['trimestre']) == '1' else notes_t2).append(n['note'])

    profils_chart_json = json.dumps(profil_counts)
    evolution_classe_json = json.dumps({
        't1': round(sum(notes_t1) / len(notes_t1), 2) if notes_t1 else None,
        't2': round(sum(notes_t2) / len(notes_t2), 2) if notes_t2 else None,
    })

    return render_template_string(NOTES_HTML, notes=notes, eleves=eleves, matieres=matieres, enseignants=enseignants,
                                  notes_par_eleve=notes_par_eleve,
                                  sous_matieres_json=json.dumps(sous_matieres_map),
                                  cycle=cycle_filter, classe_id=classe_filter, classe_actuelle=classe_actuelle,
                                  profils_chart_json=profils_chart_json,
                                  evolution_classe_json=evolution_classe_json,
                                  notif_count=get_notif_count())


# ─────────────────────────────────────────────
# 🆕 DEVOIRS / TRAVAUX À FAIRE — v2 (Admin premium + Parent premium)
# ─────────────────────────────────────────────
def _devoir_enseignant_a_acces_classe(conn, classe_id, user_id):
    return conn.execute("""
        SELECT COUNT(*) FROM classes c
        WHERE c.id = ? AND (
            EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
            OR EXISTS (SELECT 1 FROM matieres m WHERE m.classe_id = c.id AND m.enseignant_id = ?)
        )
    """, (classe_id, user_id, user_id)).fetchone()[0] > 0


def _devoir_classes_accessibles(conn, role, user_id):
    if role in ('admin', 'agent_admin'):
        return conn.execute("SELECT id, nom, niveau, cycle FROM classes ORDER BY niveau, nom").fetchall()
    if role == 'enseignant':
        return conn.execute("""
            SELECT DISTINCT c.id, c.nom, c.niveau, c.cycle FROM classes c
            WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id=c.id AND cp.enseignant_id=?)
               OR EXISTS (SELECT 1 FROM matieres m WHERE m.classe_id=c.id AND m.enseignant_id=?)
            ORDER BY c.niveau, c.nom
        """, (user_id, user_id)).fetchall()
    if role == 'secretaire':
        # 🆕 Secrétaire : uniquement les classes qui lui sont assignées (classe_secretaires)
        return conn.execute("""
            SELECT DISTINCT c.id, c.nom, c.niveau, c.cycle FROM classes c
            WHERE EXISTS (SELECT 1 FROM classe_secretaires cs WHERE cs.classe_id=c.id AND cs.secretaire_id=?)
            ORDER BY c.niveau, c.nom
        """, (user_id,)).fetchall()
    # parent
    enfants = conn.execute("SELECT classe_id FROM eleves WHERE parent_id=?", (user_id,)).fetchall()
    classe_ids = list({e['classe_id'] for e in enfants if e['classe_id']})
    if not classe_ids:
        return []
    return conn.execute(
        f"SELECT id, nom, niveau, cycle FROM classes WHERE id IN ({','.join('?' * len(classe_ids))}) ORDER BY niveau, nom",
        classe_ids).fetchall()


def _devoir_matieres_accessibles(conn, role, user_id):
    if role in ('admin', 'agent_admin'):
        return conn.execute("SELECT id, nom, classe_id FROM matieres ORDER BY nom").fetchall()
    if role == 'enseignant':
        return conn.execute("SELECT id, nom, classe_id FROM matieres WHERE enseignant_id=? ORDER BY nom",
                             (user_id,)).fetchall()
    if role == 'secretaire':
        # 🆕 Secrétaire : matières des classes qui lui sont assignées
        classe_ids = [c['id'] for c in _devoir_classes_accessibles(conn, role, user_id)]
        if not classe_ids:
            return []
        ph = ','.join('?' * len(classe_ids))
        return conn.execute(
            f"SELECT id, nom, classe_id FROM matieres WHERE classe_id IN ({ph}) ORDER BY nom", classe_ids).fetchall()
    return conn.execute("SELECT DISTINCT id, nom, classe_id FROM matieres ORDER BY nom").fetchall()


def _devoir_a_acces_classe(conn, role, classe_id, user_id):
    """🆕 Vérifie l'accès à une classe pour l'enseignant OU la secrétaire, selon le rôle."""
    if role == 'secretaire':
        return conn.execute(
            "SELECT COUNT(*) FROM classe_secretaires WHERE classe_id=? AND secretaire_id=?",
            (classe_id, user_id)).fetchone()[0] > 0
    return _devoir_enseignant_a_acces_classe(conn, classe_id, user_id)


def _devoir_parse_classes_concat(row):
    """'12::6ème A::6ème,13::6ème B::6ème' -> [{'id':12,'nom':'6ème A','niveau':'6ème'}, ...]"""
    out = []
    if not row:
        return out
    for part in row.split(','):
        bits = part.split('::')
        if len(bits) == 3:
            out.append({'id': int(bits[0]), 'nom': bits[1], 'niveau': bits[2]})
    return out


@app.route('/devoirs', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent', 'secretaire')
def gestion_devoirs():
    conn = get_db()
    role = session['role']
    today = datetime.date.today().isoformat()

    # ═══ POST : créer / modifier / supprimer / publier ═══
    if request.method == 'POST':
        action = request.form.get('action')

        if role == 'parent':
            flash("Action non autorisée.", "error")
            conn.close()
            return redirect(url_for('gestion_devoirs'))

        # 🆕 SECRÉTAIRE : peut uniquement modifier (voir + éditer) les devoirs de ses classes
        # assignées — pas de création, publication ou suppression.
        if role == 'secretaire' and action != 'edit':
            flash("Vous pouvez uniquement modifier les devoirs existants de vos classes.", "error")
            conn.close()
            return redirect(url_for('gestion_devoirs'))

        if action in ('add', 'edit'):
            devoir_id = request.form.get('devoir_id') if action == 'edit' else None
            classes_ids = [c for c in request.form.getlist('classes_ids') if c]
            matiere_id = request.form.get('matiere_id') or None
            titre = request.form.get('titre', '').strip()
            description = request.form.get('description', '').strip()
            consignes = request.form.get('consignes', '').strip()
            type_devoir = request.form.get('type') if request.form.get('type') in TYPES_DEVOIR else 'exercice'
            priorite = request.form.get('priorite') if request.form.get('priorite') in PRIORITES_DEVOIR else 'normale'
            difficulte = request.form.get('difficulte') if request.form.get('difficulte') in DIFFICULTES_DEVOIR else 'moyen'
            bareme = request.form.get('bareme', '').strip()
            date_limite = request.form.get('date_limite') or None
            heure_limite = request.form.get('heure_limite') or '23:59'
            date_pub_input = request.form.get('date_publication') or ''
            heure_pub_input = request.form.get('heure_publication') or '00:00'
            mode_publication = request.form.get('publication', 'maintenant')

            if not classes_ids or not titre:
                flash("Au moins une classe et un titre sont obligatoires.", "error")
                conn.close()
                return redirect(url_for('gestion_devoirs'))

            if role in ('enseignant', 'secretaire'):
                for cid in classes_ids:
                    if not _devoir_a_acces_classe(conn, role, cid, session['user_id']):
                        flash("Vous n'êtes pas assigné à une des classes sélectionnées.", "error")
                        conn.close()
                        return redirect(url_for('gestion_devoirs'))

            maintenant_dt = datetime.datetime.now()
            if mode_publication == 'brouillon':
                statut = 'brouillon'
                dt_pub = maintenant_dt
            elif mode_publication == 'programmee' and date_pub_input:
                try:
                    dt_pub = datetime.datetime.strptime(f"{date_pub_input} {heure_pub_input}", '%Y-%m-%d %H:%M')
                except ValueError:
                    dt_pub = maintenant_dt
                statut = 'programme' if dt_pub > maintenant_dt else 'publie'
            else:
                statut = 'publie'
                dt_pub = maintenant_dt

            date_publication_str = dt_pub.strftime('%Y-%m-%d %H:%M:%S')
            now_str = maintenant_dt.strftime('%Y-%m-%d %H:%M:%S')

            if action == 'add':
                cur = conn.execute("""
                    INSERT INTO devoirs (classe_id, matiere_id, titre, description, consignes, type, priorite,
                                          difficulte, bareme, date_limite, heure_limite, date_publication, statut,
                                          assigne_par, created_at, updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """, (classes_ids[0], matiere_id, titre, description, consignes, type_devoir, priorite, difficulte,
                      bareme, date_limite, heure_limite, date_publication_str, statut, session['user_id'],
                      now_str, now_str))
                devoir_id = cur.lastrowid
            else:
                d_existant = conn.execute("SELECT * FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
                if not d_existant:
                    flash("Devoir introuvable.", "error")
                    conn.close()
                    return redirect(url_for('gestion_devoirs'))
                if role == 'enseignant' and d_existant['assigne_par'] != session['user_id']:
                    flash("Vous ne pouvez modifier que vos propres devoirs.", "error")
                    conn.close()
                    return redirect(url_for('gestion_devoirs'))
                # 🆕 SECRÉTAIRE : pas de restriction par "propriétaire" du devoir — elle peut
                # éditer n'importe quel devoir de ses classes assignées (déjà vérifié ci-dessus).
                # Un devoir déjà publié le reste (on ne le repasse pas en brouillon/programmé)
                if d_existant['statut'] == 'publie':
                    statut = 'publie'
                    date_publication_str = d_existant['date_publication']
                conn.execute("""
                    UPDATE devoirs SET classe_id=?, matiere_id=?, titre=?, description=?, consignes=?, type=?,
                           priorite=?, difficulte=?, bareme=?, date_limite=?, heure_limite=?, date_publication=?,
                           statut=?, updated_at=?
                    WHERE id=?
                """, (classes_ids[0], matiere_id, titre, description, consignes, type_devoir, priorite, difficulte,
                      bareme, date_limite, heure_limite, date_publication_str, statut, now_str, devoir_id))
                conn.execute("DELETE FROM devoir_classes WHERE devoir_id=?", (devoir_id,))

            for cid in classes_ids:
                conn.execute("INSERT OR IGNORE INTO devoir_classes (devoir_id, classe_id) VALUES (?,?)",
                             (devoir_id, cid))

            # Pièces jointes (fichiers)
            for f in request.files.getlist('fichiers'):
                if f and f.filename:
                    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
                    if ext in ALLOWED_DEVOIR_EXTENSIONS:
                        original = secure_filename(f.filename)
                        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
                        nom_fichier = f"devoir_{ts}_{original}"
                        _sauvegarder_image_compressee(f, os.path.join(UPLOAD_FOLDER_DEVOIRS, nom_fichier), max_dimension=1800, qualite=84)
                        conn.execute("""INSERT INTO devoir_fichiers (devoir_id, type_fichier, nom_original, nom_fichier)
                                         VALUES (?,?,?,?)""",
                                     (devoir_id, type_fichier_depuis_extension(original), original, nom_fichier))
                    else:
                        flash(f"Fichier « {f.filename} » ignoré : extension .{ext} non autorisée.", "error")

            # Liens / ressources
            for label, url in zip(request.form.getlist('lien_label[]'), request.form.getlist('lien_url[]')):
                url = url.strip()
                if url:
                    conn.execute("""INSERT INTO devoir_fichiers (devoir_id, type_fichier, libelle, url_externe)
                                     VALUES (?, 'lien', ?, ?)""", (devoir_id, label.strip() or url, url))

            if statut == 'publie':
                devoir_generer_remises_manquantes(conn, devoir_id)
                devoir_notifier_publication(conn, devoir_id)

            conn.commit()
            libelle_statut = {'brouillon': 'enregistré en brouillon', 'programme': 'programmé',
                               'publie': 'publié'}[statut]
            flash(f'Devoir "{titre}" {libelle_statut} avec succès !', 'success')

        elif action == 'publier_maintenant':
            devoir_id = request.form.get('devoir_id')
            d = conn.execute("SELECT * FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
            if d and (role in ('admin', 'agent_admin') or d['assigne_par'] == session['user_id']):
                conn.execute("UPDATE devoirs SET statut='publie', date_publication=? WHERE id=?",
                             (datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'), devoir_id))
                devoir_generer_remises_manquantes(conn, devoir_id)
                devoir_notifier_publication(conn, devoir_id)
                conn.commit()
                flash("Devoir publié immédiatement.", "success")

        elif action == 'delete':
            devoir_id = request.form.get('devoir_id')
            d = conn.execute("SELECT * FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
            if not d:
                flash("Devoir introuvable.", "error")
            elif role == 'enseignant' and d['assigne_par'] != session['user_id']:
                flash("Vous ne pouvez supprimer que vos propres devoirs.", "error")
            else:
                for fl in conn.execute("SELECT * FROM devoir_fichiers WHERE devoir_id=?", (devoir_id,)).fetchall():
                    if fl['nom_fichier']:
                        p = os.path.join(UPLOAD_FOLDER_DEVOIRS, fl['nom_fichier'])
                        if os.path.exists(p):
                            try:
                                os.remove(p)
                            except OSError:
                                pass
                conn.execute("DELETE FROM devoir_fichiers WHERE devoir_id=?", (devoir_id,))
                conn.execute("DELETE FROM devoir_classes WHERE devoir_id=?", (devoir_id,))
                conn.execute("DELETE FROM devoir_remises WHERE devoir_id=?", (devoir_id,))
                conn.execute("DELETE FROM devoirs WHERE id=?", (devoir_id,))
                conn.commit()
                flash("Devoir supprimé.", "success")

        conn.close()
        return redirect(url_for('gestion_devoirs'))

    # ═══ GET ═══
    devoirs_publier_devoirs_programmes(conn)
    devoirs_marquer_en_retard_auto(conn)
    if role == 'parent':
        devoirs_envoyer_rappels_echeance(conn, session['user_id'])

    classes = _devoir_classes_accessibles(conn, role, session['user_id'])
    matieres = _devoir_matieres_accessibles(conn, role, session['user_id'])

    # ─── Filtres communs ───
    q = request.args.get('q', '').strip()
    classe_filter = request.args.get('classe_id', '')
    matiere_filter = request.args.get('matiere_id', '')
    statut_filter = request.args.get('statut', '')
    type_filter = request.args.get('type', '')
    priorite_filter = request.args.get('priorite', '')
    tri = request.args.get('tri', 'echeance')

    where_clauses = []
    params = []

    if role in ('enseignant', 'secretaire'):
        classe_ids = [c['id'] for c in classes]
        if classe_ids:
            where_clauses.append(f"d.id IN (SELECT devoir_id FROM devoir_classes WHERE classe_id IN ({','.join('?' * len(classe_ids))}))")
            params += classe_ids
        else:
            where_clauses.append("1=0")
    elif role == 'parent':
        classe_ids = [c['id'] for c in classes]
        if classe_ids:
            where_clauses.append(f"d.id IN (SELECT devoir_id FROM devoir_classes WHERE classe_id IN ({','.join('?' * len(classe_ids))}))")
            params += classe_ids
            where_clauses.append("d.statut='publie'")
        else:
            where_clauses.append("1=0")

    if q:
        where_clauses.append("(d.titre LIKE ? OR d.description LIKE ?)")
        params += [f"%{q}%", f"%{q}%"]
    if classe_filter:
        where_clauses.append("d.id IN (SELECT devoir_id FROM devoir_classes WHERE classe_id=?)")
        params.append(classe_filter)
    if matiere_filter:
        where_clauses.append("d.matiere_id=?")
        params.append(matiere_filter)
    if statut_filter and role != 'parent':
        where_clauses.append("d.statut=?")
        params.append(statut_filter)
    if type_filter:
        where_clauses.append("d.type=?")
        params.append(type_filter)
    if priorite_filter:
        where_clauses.append("d.priorite=?")
        params.append(priorite_filter)

    where_sql = " AND ".join(where_clauses) if where_clauses else "1=1"

    order_map = {
        'echeance': "d.date_limite IS NULL, d.date_limite ASC, d.heure_limite ASC",
        'recent': "d.created_at DESC",
        'titre': "d.titre COLLATE NOCASE ASC",
        'priorite': "CASE d.priorite WHEN 'urgente' THEN 0 WHEN 'haute' THEN 1 WHEN 'normale' THEN 2 ELSE 3 END, d.date_limite ASC",
    }
    order_sql = order_map.get(tri, order_map['echeance'])

    devoirs = conn.execute(f"""
        SELECT d.*,
               GROUP_CONCAT(DISTINCT c.id || '::' || c.nom || '::' || c.niveau) as classes_concat,
               m.nom as matiere_nom, u.nom as prof_nom, u.prenom as prof_prenom,
               (SELECT COUNT(*) FROM devoir_remises dr WHERE dr.devoir_id=d.id) as nb_attendus,
               (SELECT COUNT(*) FROM devoir_remises dr WHERE dr.devoir_id=d.id AND dr.statut='remis') as nb_remis,
               (SELECT COUNT(*) FROM devoir_remises dr WHERE dr.devoir_id=d.id AND dr.statut='en_retard') as nb_en_retard,
               (SELECT COUNT(*) FROM devoir_fichiers df WHERE df.devoir_id=d.id) as nb_fichiers
        FROM devoirs d
        JOIN devoir_classes dc ON dc.devoir_id = d.id
        JOIN classes c ON dc.classe_id = c.id
        LEFT JOIN matieres m ON d.matiere_id = m.id
        LEFT JOIN users u ON d.assigne_par = u.id
        WHERE {where_sql}
        GROUP BY d.id
        ORDER BY {order_sql}
    """, params).fetchall()

    devoirs_data = []
    for d in devoirs:
        item = dict(d)
        item['classes_liste'] = _devoir_parse_classes_concat(d['classes_concat'])
        item['taux_remise'] = round(100 * item['nb_remis'] / item['nb_attendus'], 1) if item['nb_attendus'] else None
        devoirs_data.append(item)

    if role == 'parent':
        # ─── Vue Parent : dashboard résumé + cartes + calendrier + IA ───
        enfants = conn.execute("SELECT id, nom, prenom, classe_id FROM eleves WHERE parent_id=?",
                               (session['user_id'],)).fetchall()
        eleve_ids = [e['id'] for e in enfants]
        remises_par_eleve_devoir = {}
        if eleve_ids:
            rows = conn.execute(f"""
                SELECT * FROM devoir_remises WHERE eleve_id IN ({','.join('?' * len(eleve_ids))})
            """, eleve_ids).fetchall()
            for r in rows:
                remises_par_eleve_devoir[(r['devoir_id'], r['eleve_id'])] = dict(r)

        eleves_par_classe = {}
        for e in enfants:
            eleves_par_classe.setdefault(e['classe_id'], []).append(e)

        cartes = []
        demain = (datetime.date.today() + datetime.timedelta(days=1)).isoformat()
        maintenant_dt = datetime.datetime.now()
        nb_aujourdhui = nb_demain = nb_termines = nb_en_retard_p = 0
        for d in devoirs_data:
            for classe in d['classes_liste']:
                for enf in eleves_par_classe.get(classe['id'], []):
                    remise = remises_par_eleve_devoir.get((d['id'], enf['id']))
                    statut_r = remise['statut'] if remise else 'non_remis'
                    date_limite_dt = None
                    if d['date_limite']:
                        try:
                            date_limite_dt = datetime.datetime.strptime(
                                f"{d['date_limite']} {d['heure_limite'] or '23:59'}", '%Y-%m-%d %H:%M')
                        except ValueError:
                            pass
                    if statut_r == 'remis':
                        statut_affiche, couleur = 'Terminé', '#30D158'
                        nb_termines += 1
                    elif statut_r == 'en_retard' or (date_limite_dt and date_limite_dt < maintenant_dt):
                        statut_affiche, couleur = 'En retard', '#FF453A'
                        nb_en_retard_p += 1
                    elif date_limite_dt and (date_limite_dt - maintenant_dt).total_seconds() <= 48 * 3600:
                        statut_affiche, couleur = 'En cours', '#FF9F0A'
                    else:
                        statut_affiche, couleur = 'Non commencé', '#0A84FF'
                    if d['date_limite'] == today:
                        nb_aujourdhui += 1
                    elif d['date_limite'] == demain:
                        nb_demain += 1
                    cartes.append({
                        'devoir': d, 'enfant': enf, 'statut_affiche': statut_affiche, 'couleur': couleur,
                        'date_limite_iso': f"{d['date_limite']}T{d['heure_limite'] or '23:59'}" if d['date_limite'] else None,
                        'remis': statut_r == 'remis',
                        'remise_id': remise['id'] if remise else None,
                    })

        conn.close()
        return render_template_string(
            DEVOIRS_PARENT_HTML, cartes=cartes, enfants=enfants, classes=classes, matieres=matieres,
            q=q, classe_filter=classe_filter, matiere_filter=matiere_filter, type_filter=type_filter,
            tri=tri, today=today,
            nb_aujourdhui=nb_aujourdhui, nb_demain=nb_demain, nb_termines=nb_termines,
            nb_en_retard=nb_en_retard_p, notif_count=get_notif_count(),
            LABELS_TYPE_DEVOIR=LABELS_TYPE_DEVOIR, LABELS_PRIORITE=LABELS_PRIORITE,
            COULEURS_PRIORITE=COULEURS_PRIORITE, LABELS_DIFFICULTE=LABELS_DIFFICULTE,
        )

    # ─── Vue Admin / Enseignant : dashboard + liste + CRUD ───
    stats = conn.execute(f"""
        SELECT COUNT(DISTINCT d.id) as total,
               COUNT(DISTINCT CASE WHEN d.date_limite = ? AND d.statut='publie' THEN d.id END) as aujourdhui,
               COUNT(DISTINCT CASE WHEN d.date_limite < ? AND d.statut='publie' THEN d.id END) as en_retard,
               COUNT(DISTINCT CASE WHEN d.statut='brouillon' THEN d.id END) as brouillons,
               COUNT(DISTINCT CASE WHEN d.statut='programme' THEN d.id END) as programmes
        FROM devoirs d
        JOIN devoir_classes dc ON dc.devoir_id = d.id
        JOIN classes c ON dc.classe_id = c.id
        WHERE {where_sql}
    """, [today, today] + params).fetchone()

    taux_row = conn.execute(f"""
        SELECT COUNT(*) as attendus, SUM(CASE WHEN dr.statut='remis' THEN 1 ELSE 0 END) as remis
        FROM devoir_remises dr
        WHERE dr.devoir_id IN (
            SELECT DISTINCT d.id FROM devoirs d
            JOIN devoir_classes dc ON dc.devoir_id=d.id JOIN classes c ON dc.classe_id=c.id
            WHERE {where_sql}
        )
    """, params).fetchone()
    taux_remise_global = round(100 * taux_row['remis'] / taux_row['attendus'], 1) if taux_row['attendus'] else 0

    repartition_matiere = conn.execute(f"""
        SELECT COALESCE(m.nom, 'Sans matière') as matiere, COUNT(DISTINCT d.id) as n
        FROM devoirs d
        JOIN devoir_classes dc ON dc.devoir_id = d.id
        JOIN classes c ON dc.classe_id = c.id
        LEFT JOIN matieres m ON d.matiere_id = m.id
        WHERE {where_sql}
        GROUP BY matiere ORDER BY n DESC LIMIT 8
    """, params).fetchall()

    conn.close()
    return render_template_string(
        DEVOIRS_ADMIN_HTML, devoirs=devoirs_data, classes=classes, matieres=matieres,
        q=q, classe_filter=classe_filter, matiere_filter=matiere_filter, statut_filter=statut_filter,
        type_filter=type_filter, priorite_filter=priorite_filter, tri=tri, today=today,
        stats=stats, taux_remise_global=taux_remise_global, repartition_matiere=repartition_matiere,
        notif_count=get_notif_count(), TYPES_DEVOIR=TYPES_DEVOIR, LABELS_TYPE_DEVOIR=LABELS_TYPE_DEVOIR,
        PRIORITES_DEVOIR=PRIORITES_DEVOIR, LABELS_PRIORITE=LABELS_PRIORITE, COULEURS_PRIORITE=COULEURS_PRIORITE,
        DIFFICULTES_DEVOIR=DIFFICULTES_DEVOIR, LABELS_DIFFICULTE=LABELS_DIFFICULTE,
    )


@app.route('/devoirs/<int:devoir_id>')
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent', 'secretaire')
def devoir_detail(devoir_id):
    conn = get_db()
    role = session['role']
    d = conn.execute("""
        SELECT d.*, m.nom as matiere_nom, u.nom as prof_nom, u.prenom as prof_prenom
        FROM devoirs d LEFT JOIN matieres m ON d.matiere_id = m.id LEFT JOIN users u ON d.assigne_par = u.id
        WHERE d.id=?
    """, (devoir_id,)).fetchone()
    if not d:
        conn.close()
        flash("Devoir introuvable.", "error")
        return redirect(url_for('gestion_devoirs'))

    classes_du_devoir = conn.execute("""
        SELECT c.id, c.nom, c.niveau FROM classes c
        JOIN devoir_classes dc ON dc.classe_id = c.id WHERE dc.devoir_id = ?
    """, (devoir_id,)).fetchall()
    classe_ids_devoir = [c['id'] for c in classes_du_devoir]

    if role == 'parent':
        enfants_concernes = conn.execute(f"""
            SELECT * FROM eleves WHERE parent_id=? AND classe_id IN ({','.join('?' * len(classe_ids_devoir)) or 'NULL'})
        """, [session['user_id']] + classe_ids_devoir).fetchall()
        if not enfants_concernes:
            conn.close()
            flash("Ce devoir ne concerne pas vos enfants.", "error")
            return redirect(url_for('gestion_devoirs'))
        for e in enfants_concernes:
            conn.execute("INSERT OR IGNORE INTO devoir_remises (devoir_id, eleve_id, statut) VALUES (?,?,'non_remis')",
                         (devoir_id, e['id']))
        conn.commit()
        remises = conn.execute(f"""
            SELECT dr.*, e.nom, e.prenom FROM devoir_remises dr JOIN eleves e ON e.id = dr.eleve_id
            WHERE dr.devoir_id=? AND dr.eleve_id IN ({','.join('?' * len(enfants_concernes))})
        """, [devoir_id] + [e['id'] for e in enfants_concernes]).fetchall()
    elif role == 'enseignant':
        if d['assigne_par'] != session['user_id'] and not any(
                _devoir_enseignant_a_acces_classe(conn, cid, session['user_id']) for cid in classe_ids_devoir):
            conn.close()
            flash("Accès non autorisé.", "error")
            return redirect(url_for('gestion_devoirs'))
        remises = conn.execute("""
            SELECT dr.*, e.nom, e.prenom, e.classe_id FROM devoir_remises dr JOIN eleves e ON e.id = dr.eleve_id
            WHERE dr.devoir_id=? ORDER BY e.nom, e.prenom
        """, (devoir_id,)).fetchall()
    elif role == 'secretaire':
        # 🆕 Secrétaire : accès si le devoir concerne une de ses classes assignées
        if not any(_devoir_a_acces_classe(conn, role, cid, session['user_id']) for cid in classe_ids_devoir):
            conn.close()
            flash("Accès non autorisé.", "error")
            return redirect(url_for('gestion_devoirs'))
        remises = conn.execute("""
            SELECT dr.*, e.nom, e.prenom, e.classe_id FROM devoir_remises dr JOIN eleves e ON e.id = dr.eleve_id
            WHERE dr.devoir_id=? ORDER BY e.nom, e.prenom
        """, (devoir_id,)).fetchall()
    else:
        remises = conn.execute("""
            SELECT dr.*, e.nom, e.prenom, e.classe_id FROM devoir_remises dr JOIN eleves e ON e.id = dr.eleve_id
            WHERE dr.devoir_id=? ORDER BY e.nom, e.prenom
        """, (devoir_id,)).fetchall()

    fichiers = conn.execute("SELECT * FROM devoir_fichiers WHERE devoir_id=? ORDER BY id", (devoir_id,)).fetchall()
    conn.close()

    nb_remis = sum(1 for r in remises if r['statut'] == 'remis')
    return render_template_string(
        DEVOIR_DETAIL_HTML, d=d, classes_du_devoir=classes_du_devoir, fichiers=fichiers, remises=remises,
        nb_remis=nb_remis, today=datetime.date.today().isoformat(), notif_count=get_notif_count(),
        LABELS_TYPE_DEVOIR=LABELS_TYPE_DEVOIR, LABELS_PRIORITE=LABELS_PRIORITE,
        COULEURS_PRIORITE=COULEURS_PRIORITE, LABELS_DIFFICULTE=LABELS_DIFFICULTE,
        ICONES_TYPE_FICHIER=ICONES_TYPE_FICHIER,
    )


