@app.route('/devoirs/fichier/<int:fichier_id>/supprimer', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant')
def devoir_fichier_supprimer(fichier_id):
    conn = get_db()
    fl = conn.execute("SELECT * FROM devoir_fichiers WHERE id=?", (fichier_id,)).fetchone()
    if fl:
        if fl['nom_fichier']:
            p = os.path.join(UPLOAD_FOLDER_DEVOIRS, fl['nom_fichier'])
            if os.path.exists(p):
                try:
                    os.remove(p)
                except OSError:
                    pass
        devoir_id = fl['devoir_id']
        conn.execute("DELETE FROM devoir_fichiers WHERE id=?", (fichier_id,))
        conn.commit()
    else:
        devoir_id = None
    conn.close()
    flash("Pièce jointe supprimée.", "success")
    return redirect(url_for('devoir_detail', devoir_id=devoir_id) if devoir_id else url_for('gestion_devoirs'))


@app.route('/devoirs/api/remise', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent', 'secretaire')
def devoir_api_remise():
    """Met à jour le suivi de remise d'un élève pour un devoir (AJAX).
    - admin/enseignant : peuvent fixer n'importe quel statut pour n'importe quel élève du devoir.
    - parent : peut uniquement marquer/démarquer le devoir de SON enfant comme 'Terminé'
      (suivi personnel ; l'enseignant garde la main sur le statut officiel)."""
    data = request.get_json(silent=True) or request.form
    devoir_id = data.get('devoir_id')
    eleve_id = data.get('eleve_id')
    nouveau_statut = data.get('statut')
    role = session['role']
    conn = get_db()

    if role == 'parent':
        eleve = conn.execute("SELECT * FROM eleves WHERE id=? AND parent_id=?",
                             (eleve_id, session['user_id'])).fetchone()
        if not eleve:
            conn.close()
            return jsonify({'erreur': "Accès non autorisé."}), 403
        if nouveau_statut not in ('remis', 'non_remis'):
            conn.close()
            return jsonify({'erreur': "Statut non autorisé."}), 400
    else:
        if nouveau_statut not in ('remis', 'non_remis', 'en_retard'):
            conn.close()
            return jsonify({'erreur': "Statut invalide."}), 400

    now = datetime.datetime.now()
    if nouveau_statut == 'remis':
        conn.execute("""
            INSERT INTO devoir_remises (devoir_id, eleve_id, statut, date_remise, heure_remise)
            VALUES (?,?,?,?,?)
            ON CONFLICT(devoir_id, eleve_id) DO UPDATE SET statut=excluded.statut,
                date_remise=excluded.date_remise, heure_remise=excluded.heure_remise
        """, (devoir_id, eleve_id, nouveau_statut, now.strftime('%Y-%m-%d'), now.strftime('%H:%M')))
    else:
        conn.execute("""
            INSERT INTO devoir_remises (devoir_id, eleve_id, statut, date_remise, heure_remise)
            VALUES (?,?,?,NULL,NULL)
            ON CONFLICT(devoir_id, eleve_id) DO UPDATE SET statut=excluded.statut,
                date_remise=NULL, heure_remise=NULL
        """, (devoir_id, eleve_id, nouveau_statut))
    conn.commit()

    counts = conn.execute("""
        SELECT COUNT(*) as attendus, SUM(CASE WHEN statut='remis' THEN 1 ELSE 0 END) as remis,
               SUM(CASE WHEN statut='en_retard' THEN 1 ELSE 0 END) as en_retard
        FROM devoir_remises WHERE devoir_id=?
    """, (devoir_id,)).fetchone()
    conn.close()
    return jsonify({'ok': True, 'statut': nouveau_statut, 'attendus': counts['attendus'],
                    'remis': counts['remis'] or 0, 'en_retard': counts['en_retard'] or 0})


def appeler_ia_analyse_devoirs(contexte):
    """Analyse IA (API Gemini, même schéma que le robot financier) : charge de travail,
    retards, conseils personnalisés pour le parent."""
    if not GEMINI_API_KEY or GEMINI_API_KEY == 'VOTRE_CLE_API_ICI':
        return {'erreur': "Clé API Gemini non configurée. Définissez la variable d'environnement "
                           "GEMINI_API_KEY pour activer l'analyse IA."}
    system_msg = (
        "Tu es un assistant IA pédagogique intégré à une plateforme scolaire. Tu analyses la charge de "
        "travail des devoirs d'un ou plusieurs enfants pour leur parent, en français, de façon claire, "
        "bienveillante et actionnable (pas de jargon). Réponds en 4 courtes sections avec des puces : "
        "1) Charge de travail actuelle, 2) Points de vigilance (retards, matières difficiles), "
        "3) Conseils personnalisés concrets, 4) Message d'encouragement court. "
        "Base-toi UNIQUEMENT sur les données fournies ci-dessous."
        f"\n\n=== DONNÉES ===\n{contexte}"
    )
    resp = None
    try:
        resp = requests.post(
            "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
            headers={"Authorization": f"Bearer {GEMINI_API_KEY}", "Content-Type": "application/json"},
            json={"model": GEMINI_MODEL_IA,
                  "messages": [{"role": "system", "content": system_msg},
                               {"role": "user", "content": "Analyse la charge de travail et donne tes conseils."}],
                  "temperature": 0.4, "max_tokens": 700},
            timeout=45,
        )
        resp.raise_for_status()
        data = resp.json()
        texte = data["choices"][0]["message"]["content"].strip()
        return {'analyse': texte}
    except requests.exceptions.RequestException as e:
        return {'erreur': f"Erreur de connexion à l'API Gemini : {e}"}
    except (KeyError, IndexError, ValueError):
        return {'erreur': "L'IA a renvoyé une réponse dans un format inattendu. Merci de réessayer."}
    except Exception as e:
        return {'erreur': f"Erreur inattendue lors de l'analyse IA : {e}"}


@app.route('/devoirs/api/analyse-ia', methods=['POST'])
@login_required
@role_required('parent')
def devoir_api_analyse_ia():
    conn = get_db()
    enfants = conn.execute("SELECT id, nom, prenom, classe_id FROM eleves WHERE parent_id=?",
                           (session['user_id'],)).fetchall()
    eleve_ids = [e['id'] for e in enfants]
    if not eleve_ids:
        conn.close()
        return jsonify({'erreur': "Aucun enfant rattaché à ce compte."}), 400

    lignes = []
    for e in enfants:
        rows = conn.execute("""
            SELECT d.titre, d.type, d.priorite, m.nom as matiere, d.date_limite, dr.statut
            FROM devoir_remises dr JOIN devoirs d ON d.id = dr.devoir_id
            LEFT JOIN matieres m ON d.matiere_id = m.id
            WHERE dr.eleve_id=? AND d.statut='publie'
            ORDER BY d.date_limite DESC LIMIT 25
        """, (e['id'],)).fetchall()
        for r in rows:
            lignes.append(f"- {e['prenom']} {e['nom']} | {r['matiere'] or '—'} | « {r['titre']} » "
                          f"| type={r['type']} | priorité={r['priorite']} | échéance={r['date_limite']} "
                          f"| statut={r['statut']}")
    conn.close()

    if not lignes:
        return jsonify({'erreur': "Pas encore assez de devoirs enregistrés pour générer une analyse."}), 400

    contexte = "\n".join(lignes)
    resultat = appeler_ia_analyse_devoirs(contexte)
    if 'erreur' in resultat:
        return jsonify(resultat), 502
    return jsonify(resultat)


# ═══════════════════════════════════════════════════════════════
# 🆕 SUPERVISION DES SAUVEGARDES — page admin (statut config, historique, déclenchement manuel)
# ═══════════════════════════════════════════════════════════════
def _taille_lisible(nb_octets):
    if not nb_octets:
        return '0 Ko'
    for unite in ['o', 'Ko', 'Mo', 'Go']:
        if abs(nb_octets) < 1024:
            return f"{nb_octets:.1f} {unite}" if unite != 'o' else f"{int(nb_octets)} {unite}"
        nb_octets /= 1024
    return f"{nb_octets:.1f} To"


@app.route('/admin/sauvegardes', methods=['GET'])
@login_required
@role_required('admin')
def admin_sauvegardes():
    """🆕 Supervision des sauvegardes automatiques (locale + Cloudflare R2) : statut de
    configuration, contenu des dossiers de sauvegarde locaux et historique des exécutions."""
    conn = get_db()
    historique = conn.execute(
        "SELECT * FROM sauvegardes_historique ORDER BY id DESC LIMIT 80").fetchall()
    conn.close()

    def _lister_dossier(dossier):
        fichiers = sorted(glob.glob(os.path.join(dossier, '*.zip')), key=os.path.getmtime, reverse=True)
        return [{
            'nom': os.path.basename(f),
            'taille': _taille_lisible(os.path.getsize(f)),
            'date': datetime.datetime.fromtimestamp(os.path.getmtime(f)).strftime('%d/%m/%Y %H:%M:%S'),
        } for f in fichiers]

    dossiers = {
        '2min': _lister_dossier(BACKUP_DIR_2MIN),
        '15h': _lister_dossier(BACKUP_DIR_15H),
        'manuel': _lister_dossier(BACKUP_DIR_MANUEL),
    }

    prochains_passages = {}
    for jid in ('sauvegarde_15h', 'backup_15h'):
        job = scheduler.get_job(jid)
        prochains_passages[jid] = job.next_run_time.strftime('%d/%m/%Y %H:%M:%S') if job and job.next_run_time else '—'

    # 🆕 Les sauvegardes "2min" ne sont plus planifiées à heure fixe : elles se déclenchent en
    # temps réel, quelques secondes après la dernière modification en base (voir
    # _boucle_sauvegarde_temps_reel). On expose ici un état lisible pour l'admin plutôt qu'un
    # "prochain passage" qui n'a plus de sens.
    if _dernier_commit_signal_ts is not None:
        secondes_restantes = max(0, int(DEBOUNCE_SAUVEGARDE_SECONDES - (time.time() - _dernier_commit_signal_ts)))
        statut_temps_reel = f"Modification détectée — sauvegarde dans ~{secondes_restantes}s"
    elif _SAUVEGARDE_TEMPS_REEL_EN_COURS.is_set():
        statut_temps_reel = "Sauvegarde en cours…"
    else:
        statut_temps_reel = "En veille — se déclenche à la prochaine modification"

    _jours_2min_inutilise, jours_15h = get_backup_retention_jours()

    return render_template_string(
        SAUVEGARDES_HTML, historique=historique, dossiers=dossiers, prochains_passages=prochains_passages,
        cloudflare_ok=cloudflare_est_configure(), boto3_ok=BOTO3_DISPONIBLE,
        scheduler_actif=scheduler.running, notif_count=get_notif_count(),
        retention_2min_nb=BACKUP_RETENTION_2MIN, retention_15h_jours=jours_15h,
        statut_temps_reel=statut_temps_reel, debounce_secondes=DEBOUNCE_SAUVEGARDE_SECONDES,
    )


@app.route('/admin/sauvegardes/retention', methods=['POST'])
@login_required
@role_required('admin')
def admin_sauvegardes_retention():
    """🆕 Permet à l'admin de configurer lui-même la durée de conservation (en jours) des
    sauvegardes quotidiennes (15h) sur Cloudflare R2 — auparavant fixée en dur (90 jours).
    Les sauvegardes « toutes les 15 min » ne sont plus configurables ici : elles suivent
    désormais une rotation FIXE des 4 dernières (voir BACKUP_RETENTION_2MIN), local et R2."""
    try:
        jours_15h = int(request.form.get('retention_15h_jours', '').strip())
        if not (1 <= jours_15h <= 365):
            raise ValueError
    except (TypeError, ValueError):
        flash("Merci de saisir un nombre de jours valide, entre 1 et 365.", "error")
        return redirect(url_for('admin_sauvegardes'))

    conn = get_db()
    conn.execute(
        "UPDATE parametres_ecole SET backup_retention_15h_jours=? WHERE id=1",
        (jours_15h,)
    )
    conn.commit()
    conn.close()
    flash(f"Durée de conservation mise à jour : {jours_15h} jour(s) pour les sauvegardes quotidiennes. "
          f"S'applique automatiquement à partir de la prochaine purge planifiée.", "success")
    return redirect(url_for('admin_sauvegardes'))


# 🩹 CORRECTIF : verrou anti-doublon pour la sauvegarde manuelle en arrière-plan.
# Avant : `sauvegarde_manuelle_complete()` s'exécutait DIRECTEMENT dans la requête HTTP
# (zip de la base + tous les uploads, PUIS envoi réseau vers Cloudflare). Sur Render
# (généralement 1 seul worker Gunicorn), ça bloquait l'unique worker pendant toute la
# durée de l'opération : plus AUCUN utilisateur ne pouvait charger la moindre page tant
# que la sauvegarde manuelle n'était pas terminée ("l'app cesse de fonctionner").
# Maintenant : on lance ce travail dans un thread séparé (même principe que les tâches
# planifiées sauvegarder_2min / sauvegarde_15h, qui elles n'ont jamais bloqué l'app) et on
# répond immédiatement à l'admin — le worker reste donc libre pour tous les autres.
SAUVEGARDE_MANUELLE_EN_COURS = threading.Event()


def _sauvegarde_manuelle_arriere_plan():
    try:
        sauvegarde_manuelle_complete()
    finally:
        SAUVEGARDE_MANUELLE_EN_COURS.clear()


@app.route('/admin/sauvegardes/lancer', methods=['POST'])
@login_required
@role_required('admin')
def admin_sauvegardes_lancer():
    if SAUVEGARDE_MANUELLE_EN_COURS.is_set():
        flash("Une sauvegarde manuelle est déjà en cours, merci de patienter quelques instants.", "error")
        return redirect(url_for('admin_sauvegardes'))
    SAUVEGARDE_MANUELLE_EN_COURS.set()
    threading.Thread(target=_sauvegarde_manuelle_arriere_plan, daemon=True).start()
    flash("Sauvegarde manuelle lancée en arrière-plan. Elle apparaîtra dans l'historique ci-dessous dans "
          "quelques instants — l'application reste utilisable normalement pendant ce temps.", "success")
    return redirect(url_for('admin_sauvegardes'))


# ═══════════════════════════════════════════════════════════════
# 🆕 RESTAURATION D'UNE SAUVEGARDE DEPUIS CLOUDFLARE R2 (page /admin/sauvegardes)
# Le client peut choisir une version précise à restaurer :
#   • "2min"   → granularité de 15 minutes, rotation FIXE des 4 dernières (le plus précis)
#   • "15h"    → sauvegardes quotidiennes (conservées 90 jours)
#   • "manuel" → sauvegardes manuelles déclenchées depuis cette page
# Ces sauvegardes vivent sur R2 (pas sur le disque local Render), donc restent disponibles
# même après un redéploiement qui efface le disque du conteneur.
# ═══════════════════════════════════════════════════════════════
@app.route('/admin/sauvegardes/liste_r2', methods=['GET'])
@login_required
@role_required('admin')
def admin_sauvegardes_liste_r2():
    type_demande = request.args.get('type', '2min')
    prefixes = {
        # 🆕 Plus de filtre par âge pour "2min" : la rotation garde déjà seulement les
        # BACKUP_RETENTION_2MIN (4) plus récentes sur R2, inutile de filtrer par jours ici.
        '2min': ('sauvegardes/2min', None),
        '15h': ('sauvegardes/quotidien_15h', None),
        'manuel': ('sauvegardes/manuel', None),
    }
    if type_demande not in prefixes:
        return jsonify({'erreur': "Type de sauvegarde inconnu."})
    prefixe, jours_max = prefixes[type_demande]

    if not cloudflare_est_configure():
        return jsonify({'erreur': "Cloudflare R2 n'est pas configuré (variables d'environnement manquantes)."})
    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    if not client:
        return jsonify({'erreur': "Impossible de se connecter à Cloudflare R2."})

    limite = None
    if jours_max is not None:
        limite = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=jours_max)

    objets = []
    try:
        continuation = None
        while True:
            kwargs = {'Bucket': bucket, 'Prefix': f"{prefixe}/"}
            if continuation:
                kwargs['ContinuationToken'] = continuation
            reponse = client.list_objects_v2(**kwargs)
            for o in reponse.get('Contents', []):
                if limite is None or o['LastModified'] >= limite:
                    objets.append(o)
            if reponse.get('IsTruncated'):
                continuation = reponse.get('NextContinuationToken')
            else:
                break
    except Exception as e:
        return jsonify({'erreur': f"Erreur lors de la lecture de Cloudflare R2 : {e}"})

    # Regroupement par jour pour un affichage plus lisible côté client
    groupes = {}
    for o in sorted(objets, key=lambda x: x['LastModified'], reverse=True):
        jour = o['LastModified'].strftime('%d/%m/%Y')
        heure = o['LastModified'].strftime('%H:%M:%S')
        groupes.setdefault(jour, []).append({
            'cle': o['Key'], 'heure': heure, 'taille': _taille_lisible(o['Size']),
        })
    jours_ordonnes = sorted(groupes.keys(), key=lambda j: datetime.datetime.strptime(j, '%d/%m/%Y'), reverse=True)
    return jsonify({
        'jours': [{'jour': j, 'sauvegardes': groupes[j]} for j in jours_ordonnes],
        'total': len(objets),
    })


def _restauration_arriere_plan(cle):
    """🩹 CORRECTIF : tout le travail de restauration (téléchargement R2 + extraction du zip +
    rejeu des migrations) tournait AVANT directement dans la requête HTTP du clic sur
    "Restaurer". Sur Render (généralement 1 seul worker Gunicorn), ce traitement dépassait
    souvent le délai d'attente du worker (~30s) — Gunicorn tuait alors le worker en plein
    milieu de l'écrasement du fichier school.db, ce qui provoquait à la fois une erreur
    "Internal Server Error" côté navigateur ET, parfois, une base à moitié restaurée.
    Maintenant ce travail tourne dans un thread séparé (même principe que la sauvegarde
    manuelle, voir `_sauvegarde_manuelle_arriere_plan`) : la requête répond IMMÉDIATEMENT
    par une redirection, qui tombe directement sur la page d'attente "Restauration en
    cours…" (voir `bloquer_pendant_restauration`, déclenchée tant que RESTAURATION_EN_COURS
    est actif) — laquelle se rafraîchit seule jusqu'à la fin du traitement."""
    # ⚡ Sécurité : on sauvegarde l'état ACTUEL avant de l'écraser, et on l'envoie aussi sur
    # R2 — si la version choisie pour la restauration s'avère être une erreur, rien n'est
    # perdu : l'état d'avant-restauration reste disponible dans "Sauvegardes manuelles".
    try:
        chemin_avant, _taille = creer_sauvegarde_locale(BACKUP_DIR_MANUEL, 'avant_restauration')
        if chemin_avant:
            _purger_anciennes_sauvegardes(BACKUP_DIR_MANUEL, BACKUP_RETENTION_MANUEL)
            uploader_vers_cloudflare(chemin_avant, 'sauvegardes/manuel', 'avant_restauration',
                                      garder_n_r2=BACKUP_RETENTION_MANUEL)
    except Exception:
        pass  # la sauvegarde de sécurité ne doit pas bloquer la restauration demandée

    # Le verrou de restauration (RESTAURATION_EN_COURS) est déjà actif à ce stade (posé par
    # la route AVANT de démarrer ce thread). On met aussi en pause le scheduler (sauvegardes
    # automatiques 2min/15h) pour qu'il n'ouvre pas non plus de connexion pendant l'écrasement
    # du fichier. Sans ça, une connexion ouverte entre la suppression des fichiers -wal/-shm et
    # l'extraction du zip pouvait recréer un WAL désynchronisé du nouveau school.db → base
    # corrompue → crash de toutes les requêtes suivantes ("external error" sur Render).
    try:
        scheduler.pause()
    except Exception:
        pass

    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    tmp_zip = os.path.join(os.path.dirname(__file__), '_restore_manuel_tmp.zip')
    try:
        client.download_file(bucket, cle, tmp_zip)

        # On supprime les fichiers WAL/SHM existants pour éviter tout conflit avec le
        # fichier school.db qu'on s'apprête à restaurer par-dessus.
        for suffixe in ('-wal', '-shm'):
            f = DB_PATH + suffixe
            if os.path.exists(f):
                os.remove(f)

        with zipfile.ZipFile(tmp_zip, 'r') as zf:
            zf.extractall(os.path.dirname(__file__))
        os.remove(tmp_zip)

        # 🩹 CORRECTIF : on rejoue immédiatement toutes les migrations de schéma sur la base
        # fraîchement restaurée. Si la sauvegarde restaurée est ancienne (schéma incomplet,
        # ex. table sous_matieres sans colonne "coefficient"), le schéma est réparé tout de
        # suite — plus besoin d'attendre un redémarrage manuel du service Render, et la page
        # Analyse (/analyse-notes) ne plante plus juste après une restauration.
        try:
            rejouer_migrations_schema_bdd()
        except Exception as ex_migration:
            print(f"  ⚠️  Erreur lors du rejeu des migrations après restauration : {ex_migration}")

        _log_sauvegarde('restauration_manuelle', 'succes', fichier=cle, message=f"Restauration depuis {cle}")
    except Exception as e:
        _log_sauvegarde('restauration_manuelle', 'erreur', fichier=cle, message=str(e))
        print(f"  ⚠️  Erreur lors de la restauration manuelle : {e}")
    finally:
        # 🩹 On relâche systématiquement le verrou et on relance le scheduler, même en cas
        # d'erreur : sinon l'application resterait bloquée en "restauration en cours" pour
        # toujours (page d'attente sur toutes les routes).
        try:
            scheduler.resume()
        except Exception:
            pass
        RESTAURATION_EN_COURS.clear()


@app.route('/admin/sauvegardes/restaurer', methods=['POST'])
@login_required
@role_required('admin')
def admin_sauvegardes_restaurer():
    cle = (request.form.get('cle') or '').strip()
    confirmation = (request.form.get('confirmation') or '').strip().upper()

    if not cle:
        flash("Aucune sauvegarde sélectionnée.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if confirmation != 'RESTAURER':
        flash("Restauration annulée : le mot de confirmation saisi est incorrect.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if not cloudflare_est_configure():
        flash("Cloudflare R2 n'est pas configuré.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if RESTAURATION_EN_COURS.is_set():
        flash("Une restauration est déjà en cours, merci de patienter quelques instants.", "error")
        return redirect(url_for('admin_sauvegardes'))

    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    if not client:
        flash("Impossible de se connecter à Cloudflare R2.", "error")
        return redirect(url_for('admin_sauvegardes'))

    # 🩹 CORRECTIF : on active le verrou de restauration ICI, AVANT de démarrer le thread —
    # donc avant même de toucher au fichier school.db. Toute requête HTTP entrante (y compris
    # la redirection ci-dessous, et un éventuel double-clic sur "Restaurer") reçoit
    # immédiatement la page d'attente tant que le verrou est actif (voir
    # `bloquer_pendant_restauration`). Le vrai travail (téléchargement + extraction +
    # migrations) se fait ensuite dans `_restauration_arriere_plan`, dans un thread séparé,
    # pour ne jamais bloquer le worker Gunicorn au point de le faire tuer par timeout.
    RESTAURATION_EN_COURS.set()
    threading.Thread(target=_restauration_arriere_plan, args=(cle,), daemon=True).start()
    return redirect(url_for('admin_sauvegardes'))


