def upgrade_db_communications():
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communications (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            titre TEXT NOT NULL,
            contenu TEXT NOT NULL,
            type TEXT DEFAULT 'info',
            priorite TEXT DEFAULT 'normale',
            statut TEXT DEFAULT 'publie',
            toutes_classes INTEGER DEFAULT 0,
            epingle INTEGER DEFAULT 0,
            date_publication TEXT,
            auteur_id INTEGER REFERENCES users(id),
            notif_envoyee INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_classes (
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            classe_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
            PRIMARY KEY (communication_id, classe_id)
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_fichiers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            type_fichier TEXT NOT NULL,
            nom_original TEXT,
            nom_fichier TEXT,
            url_externe TEXT,
            libelle TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_lectures (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            role TEXT,
            lu_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(communication_id, user_id)
        )
    """)
    # 🆕 « J'aime » sur une publication
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_likes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(communication_id, user_id)
        )
    """)
    # 🆕 Commentaires sur une publication
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_commentaires (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            role TEXT,
            contenu TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_classes_comm ON communication_classes(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_lectures_comm ON communication_lectures(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_likes_comm ON communication_likes(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_commentaires_comm ON communication_commentaires(communication_id)")
    except sqlite3.OperationalError:
        pass
    conn.commit()
    conn.close()


upgrade_db_communications()


def _comm_parents_cibles(conn, comm):
    """Retourne la liste des ID des parents concernés par une communication
    (tous les parents si diffusion « toute l'école », sinon uniquement les parents
    dont au moins un enfant est dans une des classes ciblées)."""
    if comm['toutes_classes']:
        rows = conn.execute("SELECT DISTINCT parent_id FROM eleves WHERE parent_id IS NOT NULL").fetchall()
    else:
        rows = conn.execute("""
            SELECT DISTINCT e.parent_id FROM eleves e
            JOIN communication_classes cc ON cc.classe_id = e.classe_id
            WHERE cc.communication_id=? AND e.parent_id IS NOT NULL
        """, (comm['id'],)).fetchall()
    return [r['parent_id'] for r in rows]


def _comm_enseignants_cibles(conn, comm):
    """Retourne la liste des ID des enseignants concernés (professeurs principaux ou
    de matière des classes ciblées, ou tous les enseignants si diffusion école entière)."""
    if comm['toutes_classes']:
        rows = conn.execute("SELECT id FROM users WHERE role='enseignant'").fetchall()
        return [r['id'] for r in rows]
    rows = conn.execute("""
        SELECT enseignant_id as id FROM classe_profs WHERE classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
        UNION
        SELECT enseignant_id as id FROM matieres WHERE enseignant_id IS NOT NULL AND classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
    """, (comm['id'], comm['id'])).fetchall()
    return [r['id'] for r in rows if r['id']]


def communication_notifier_publication(conn, comm_id):
    """Envoie une notification in-app à chaque parent et enseignant concerné, une seule fois."""
    comm = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
    if not comm or comm['notif_envoyee']:
        return
    icone = LABELS_TYPE_COMMUNICATION.get(comm['type'], '📢 Communication').split(' ')[0]
    msg = f"{icone} Nouvelle communication « {comm['titre']} »"
    destinataires = set(_comm_parents_cibles(conn, comm)) | set(_comm_enseignants_cibles(conn, comm))
    for uid in destinataires:
        notif_to_parent(uid, msg, conn)
    conn.execute("UPDATE communications SET notif_envoyee=1 WHERE id=?", (comm_id,))


def communications_publier_programmees(conn):
    """Publie automatiquement les communications programmées dont l'heure est arrivée
    (appelé à chaque chargement de la page, pas besoin d'un scheduler dédié)."""
    maintenant = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    a_publier = conn.execute(
        "SELECT id FROM communications WHERE statut='programme' AND date_publication <= ?", (maintenant,)
    ).fetchall()
    for c in a_publier:
        conn.execute("UPDATE communications SET statut='publie' WHERE id=?", (c['id'],))
        communication_notifier_publication(conn, c['id'])
    if a_publier:
        conn.commit()


@app.route('/communications', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent')
def communications():
    conn = get_db()
    role = session['role']
    peut_editer = role in ('admin', 'agent_admin')

    # ═══ POST : créer / modifier / publier / épingler / archiver / supprimer (admin uniquement) ═══
    if request.method == 'POST':
        if not peut_editer:
            flash("Action non autorisée.", "error")
            conn.close()
            return redirect(url_for('communications'))

        action = request.form.get('action')

        if action in ('add', 'edit'):
            comm_id = request.form.get('comm_id') if action == 'edit' else None
            titre = request.form.get('titre', '').strip()
            contenu = request.form.get('contenu', '').strip()
            type_comm = request.form.get('type') if request.form.get('type') in TYPES_COMMUNICATION else 'info'
            priorite = request.form.get('priorite') if request.form.get('priorite') in PRIORITES_COMMUNICATION else 'normale'
            toutes_classes = 1 if request.form.get('toutes_classes') == 'on' else 0
            classes_ids = [c for c in request.form.getlist('classes_ids') if c]
            epingle = 1 if request.form.get('epingle') == 'on' else 0
            date_pub_input = request.form.get('date_publication') or ''
            heure_pub_input = request.form.get('heure_publication') or '08:00'
            mode_publication = request.form.get('publication', 'maintenant')

            if not titre or not contenu:
                flash("Le titre et le contenu sont obligatoires.", "error")
                conn.close()
                return redirect(url_for('communications'))
            if not toutes_classes and not classes_ids:
                flash("Choisissez « Toute l'école » ou au moins une classe destinataire.", "error")
                conn.close()
                return redirect(url_for('communications'))

            maintenant_dt = datetime.datetime.now()
            if mode_publication == 'brouillon':
                statut = 'brouillon'
                dt_pub = maintenant_dt
            elif mode_publication == 'programmee' and date_pub_input:
                try:
                    dt_pub = datetime.datetime.strptime(f"{date_pub_input} {heure_pub_input}", '%Y-%m-%d %H:%M')
                except ValueError:
                    dt_pub = maintenant_dt
                statut = 'programme' if dt_pub > maintenant_dt else 'publie'
            else:
                statut = 'publie'
                dt_pub = maintenant_dt

            date_publication_str = dt_pub.strftime('%Y-%m-%d %H:%M:%S')
            now_str = maintenant_dt.strftime('%Y-%m-%d %H:%M:%S')

            if action == 'add':
                cur = conn.execute("""
                    INSERT INTO communications (titre, contenu, type, priorite, statut, toutes_classes, epingle,
                                                 date_publication, auteur_id, created_at, updated_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?)
                """, (titre, contenu, type_comm, priorite, statut, toutes_classes, epingle,
                      date_publication_str, session['user_id'], now_str, now_str))
                comm_id = cur.lastrowid
            else:
                existante = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
                if not existante:
                    flash("Communication introuvable.", "error")
                    conn.close()
                    return redirect(url_for('communications'))
                # Une communication déjà publiée le reste (on ne la repasse pas en brouillon/programmée)
                if existante['statut'] == 'publie':
                    statut = 'publie'
                    date_publication_str = existante['date_publication']
                conn.execute("""
                    UPDATE communications SET titre=?, contenu=?, type=?, priorite=?, statut=?, toutes_classes=?,
                           epingle=?, date_publication=?, updated_at=?
                    WHERE id=?
                """, (titre, contenu, type_comm, priorite, statut, toutes_classes, epingle,
                      date_publication_str, now_str, comm_id))
                conn.execute("DELETE FROM communication_classes WHERE communication_id=?", (comm_id,))

            if not toutes_classes:
                for cid in classes_ids:
                    conn.execute("INSERT OR IGNORE INTO communication_classes (communication_id, classe_id) VALUES (?,?)",
                                 (comm_id, cid))

            # Pièces jointes (fichiers)
            for f in request.files.getlist('fichiers'):
                if f and f.filename:
                    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
                    if ext in ALLOWED_COMM_EXTENSIONS:
                        original = secure_filename(f.filename)
                        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
                        nom_fichier = f"comm_{ts}_{original}"
                        _sauvegarder_image_compressee(f, os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, nom_fichier), max_dimension=1800, qualite=84)
                        conn.execute("""INSERT INTO communication_fichiers (communication_id, type_fichier, nom_original, nom_fichier)
                                         VALUES (?,?,?,?)""",
                                     (comm_id, type_fichier_depuis_extension(original), original, nom_fichier))
                    else:
                        flash(f"Fichier « {f.filename} » ignoré : extension .{ext} non autorisée.", "error")

            # Liens / ressources externes
            for label, url in zip(request.form.getlist('lien_label[]'), request.form.getlist('lien_url[]')):
                url = url.strip()
                if url:
                    conn.execute("""INSERT INTO communication_fichiers (communication_id, type_fichier, libelle, url_externe)
                                     VALUES (?, 'lien', ?, ?)""", (comm_id, label.strip() or url, url))

            if statut == 'publie':
                communication_notifier_publication(conn, comm_id)

            conn.commit()
            libelle_statut = {'brouillon': 'enregistrée en brouillon', 'programme': 'programmée',
                               'publie': 'publiée'}[statut]
            flash(f'Communication "{titre}" {libelle_statut} avec succès !', 'success')

        elif action == 'publier_maintenant':
            comm_id = request.form.get('comm_id')
            c = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
            if c:
                conn.execute("UPDATE communications SET statut='publie', date_publication=? WHERE id=?",
                             (datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'), comm_id))
                communication_notifier_publication(conn, comm_id)
                conn.commit()
                flash("Communication publiée immédiatement.", "success")

        elif action == 'toggle_epingle':
            comm_id = request.form.get('comm_id')
            c = conn.execute("SELECT epingle FROM communications WHERE id=?", (comm_id,)).fetchone()
            if c:
                conn.execute("UPDATE communications SET epingle=? WHERE id=?", (0 if c['epingle'] else 1, comm_id))
                conn.commit()

        elif action == 'archiver':
            comm_id = request.form.get('comm_id')
            conn.execute("UPDATE communications SET statut='archive' WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication archivée.", "success")

        elif action == 'desarchiver':
            comm_id = request.form.get('comm_id')
            conn.execute("UPDATE communications SET statut='publie' WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication restaurée dans les publiées.", "success")

        elif action == 'delete':
            comm_id = request.form.get('comm_id')
            for fl in conn.execute("SELECT * FROM communication_fichiers WHERE communication_id=?", (comm_id,)).fetchall():
                if fl['nom_fichier']:
                    p = os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, fl['nom_fichier'])
                    if os.path.exists(p):
                        try:
                            os.remove(p)
                        except OSError:
                            pass
            conn.execute("DELETE FROM communication_fichiers WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_classes WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_lectures WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_likes WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_commentaires WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communications WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication supprimée.", "success")

        conn.close()
        return redirect(url_for('communications'))

    # ═══ GET : liste + filtres + statistiques ═══
    communications_publier_programmees(conn)

    classes = _devoir_classes_accessibles(conn, role, session['user_id'])
    classe_ids_access = [c['id'] for c in classes]

    q = request.args.get('q', '').strip()
    classe_filter = request.args.get('classe_id', '')
    type_filter = request.args.get('type', '')
    priorite_filter = request.args.get('priorite', '')
    statut_filter = request.args.get('statut', '') if peut_editer else ''
    lecture_filter = request.args.get('lecture', '') if peut_editer else ''
    tri = request.args.get('tri', 'recent')

    where_clauses = []
    params = []

    if not peut_editer:
        if classe_ids_access:
            ph = ','.join('?' * len(classe_ids_access))
            where_clauses.append(
                f"(co.toutes_classes=1 OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id IN ({ph})))")
            params += classe_ids_access
        else:
            where_clauses.append("co.toutes_classes=1")
        where_clauses.append("co.statut='publie'")
    elif statut_filter:
        where_clauses.append("co.statut=?")
        params.append(statut_filter)
    else:
        where_clauses.append("co.statut != 'archive'")

    if q:
        where_clauses.append("(co.titre LIKE ? OR co.contenu LIKE ?)")
        params += [f"%{q}%", f"%{q}%"]
    if classe_filter:
        where_clauses.append(
            "(co.toutes_classes=1 OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id=?))")
        params.append(classe_filter)
    if type_filter:
        where_clauses.append("co.type=?")
        params.append(type_filter)
    if priorite_filter:
        where_clauses.append("co.priorite=?")
        params.append(priorite_filter)
    if lecture_filter == 'lu':
        where_clauses.append("EXISTS(SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id)")
    elif lecture_filter == 'non_lu':
        where_clauses.append("NOT EXISTS(SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id)")

    where_sql = " AND ".join(where_clauses) if where_clauses else "1=1"

    order_map = {
        'recent': "co.epingle DESC, co.date_publication DESC",
        'ancien': "co.epingle DESC, co.date_publication ASC",
        'titre': "co.epingle DESC, co.titre COLLATE NOCASE ASC",
        'priorite': "co.epingle DESC, CASE co.priorite WHEN 'urgente' THEN 0 WHEN 'importante' THEN 1 ELSE 2 END, co.date_publication DESC",
    }
    order_sql = order_map.get(tri, order_map['recent'])

    lignes = conn.execute(f"""
        SELECT co.*, GROUP_CONCAT(DISTINCT cl.id || '::' || cl.nom || '::' || cl.niveau) as classes_concat,
               u.nom as auteur_nom, u.prenom as auteur_prenom,
               (SELECT COUNT(*) FROM communication_fichiers cf WHERE cf.communication_id=co.id) as nb_fichiers,
               (SELECT COUNT(*) FROM communication_likes cli WHERE cli.communication_id=co.id) as nb_likes,
               (SELECT COUNT(*) FROM communication_commentaires cco WHERE cco.communication_id=co.id) as nb_commentaires
        FROM communications co
        LEFT JOIN communication_classes cc ON cc.communication_id = co.id
        LEFT JOIN classes cl ON cc.classe_id = cl.id
        LEFT JOIN users u ON co.auteur_id = u.id
        WHERE {where_sql}
        GROUP BY co.id
        ORDER BY {order_sql}
    """, params).fetchall()

    # 🆕 Aperçu des pièces jointes (pour le slider : image en avant, sinon nom du fichier)
    comm_ids_all = [c['id'] for c in lignes]
    fichiers_par_comm = {}
    if comm_ids_all:
        ph_ids = ','.join('?' * len(comm_ids_all))
        for f in conn.execute(
                f"SELECT * FROM communication_fichiers WHERE communication_id IN ({ph_ids}) ORDER BY id",
                comm_ids_all).fetchall():
            fichiers_par_comm.setdefault(f['communication_id'], []).append(dict(f))

    comms_data = []
    for c in lignes:
        item = dict(c)
        item['classes_liste'] = _devoir_parse_classes_concat(c['classes_concat'])
        fichiers_c = fichiers_par_comm.get(c['id'], [])
        item['image_apercu'] = next((f for f in fichiers_c if f['type_fichier'] == 'image'), None)
        item['fichier_apercu'] = next((f for f in fichiers_c if f['type_fichier'] != 'image'), None)
        item['user_a_aime'] = conn.execute(
            "SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
            (c['id'], session['user_id'])).fetchone() is not None
        if peut_editer:
            parents_cibles = _comm_parents_cibles(conn, c)
            nb_lu = 0
            lecteurs_noms = []
            if parents_cibles:
                ph = ','.join('?' * len(parents_cibles))
                nb_lu = conn.execute(
                    f"SELECT COUNT(DISTINCT user_id) FROM communication_lectures WHERE communication_id=? AND user_id IN ({ph})",
                    [c['id']] + parents_cibles).fetchone()[0]
                lecteurs_noms = [f"{r['prenom']} {r['nom']}" for r in conn.execute(
                    f"""SELECT u.prenom, u.nom FROM communication_lectures cl JOIN users u ON u.id=cl.user_id
                        WHERE cl.communication_id=? AND cl.user_id IN ({ph}) ORDER BY cl.lu_at DESC LIMIT 6""",
                    [c['id']] + parents_cibles).fetchall()]
            item['nb_destinataires'] = len(parents_cibles)
            item['nb_lu'] = nb_lu
            item['taux_lecture'] = round(100 * nb_lu / len(parents_cibles), 1) if parents_cibles else 0
            item['lecteurs_noms'] = lecteurs_noms
        else:
            item['lu'] = conn.execute(
                "SELECT 1 FROM communication_lectures WHERE communication_id=? AND user_id=?",
                (c['id'], session['user_id'])).fetchone() is not None
        comms_data.append(item)

    # 🆕 Slider « 5 dernières actualités » (aperçu, publications déjà publiées) + grille avec TOUTES les
    # communications (correspondant aux filtres) en dessous, comme demandé.
    # 🆕 Le slider "À la une" affiche désormais TOUTES les actualités publiées (pas juste les 5
    # dernières), pour que le parent/l'enseignant puisse tout parcourir directement depuis le slider.
    comms_publiees_pour_slider = [c for c in comms_data if c['statut'] == 'publie']
    comms_slider = comms_publiees_pour_slider
    comms_rest = comms_data

    stats = conn.execute(f"""
        SELECT COUNT(DISTINCT co.id) as total,
               COUNT(DISTINCT CASE WHEN co.statut='publie' THEN co.id END) as publiees,
               COUNT(DISTINCT CASE WHEN co.statut='brouillon' THEN co.id END) as brouillons,
               COUNT(DISTINCT CASE WHEN co.statut='programme' THEN co.id END) as programmees,
               COUNT(DISTINCT CASE WHEN co.epingle=1 THEN co.id END) as epinglees,
               COUNT(DISTINCT CASE WHEN co.priorite='urgente' AND co.statut='publie' THEN co.id END) as urgentes
        FROM communications co
        WHERE {where_sql}
    """, params).fetchone()

    # 🆕 Analyses cumulées (tableau de bord admin) : vues/likes/commentaires totaux sur les
    # communications actuellement filtrées, + top 3 des publications les plus engageantes.
    analytics = None
    top_comms = []
    if peut_editer:
        total_vues = sum(c.get('nb_lu', 0) for c in comms_data)
        total_destinataires = sum(c.get('nb_destinataires', 0) for c in comms_data)
        total_likes = sum(c.get('nb_likes', 0) for c in comms_data)
        total_commentaires = sum(c.get('nb_commentaires', 0) for c in comms_data)
        analytics = {
            'total_vues': total_vues,
            'taux_lecture_moyen': round(100 * total_vues / total_destinataires, 1) if total_destinataires else 0,
            'total_likes': total_likes,
            'total_commentaires': total_commentaires,
        }
        top_comms = sorted(
            [c for c in comms_data if c['statut'] == 'publie'],
            key=lambda c: c.get('nb_lu', 0) + c.get('nb_likes', 0) * 2 + c.get('nb_commentaires', 0) * 3,
            reverse=True
        )[:3]

    # 🆕 Prochain événement à venir (pour la carte "Prochain événement" du nouveau design luxe) :
    # on cherche parmi les publications déjà publiées de type "événement"/"sortie"/"sportive" la plus
    # proche dans le temps (aujourd'hui ou dans le futur) ; à défaut, la plus récente déjà publiée.
    prochain_evenement = None
    try:
        aujourdhui_str = datetime.date.today().strftime('%Y-%m-%d')
        prochain_evenement = conn.execute("""
            SELECT * FROM communications
            WHERE statut='publie' AND type IN ('evenement','sportive','pedagogique')
              AND date_publication >= ?
            ORDER BY date_publication ASC LIMIT 1
        """, (aujourdhui_str,)).fetchone()
        if not prochain_evenement:
            prochain_evenement = conn.execute("""
                SELECT * FROM communications WHERE statut='publie' AND type IN ('evenement','sportive','pedagogique')
                ORDER BY date_publication DESC LIMIT 1
            """).fetchone()
    except Exception:
        prochain_evenement = None

    # 🆕 Statistiques globales (vues, j'aime, commentaires) sur TOUTES les publications
    # actuellement publiées et filtrées — visibles par TOUS les rôles (contrairement aux
    # analyses détaillées ci-dessus, réservées à l'admin/enseignant). Utilisées pour la carte
    # "statistiques en cercle" de la colonne latérale.
    comm_ids_publies = [c['id'] for c in comms_data if c['statut'] == 'publie']
    total_vues_globales = 0
    if comm_ids_publies:
        ph_vues = ','.join('?' * len(comm_ids_publies))
        total_vues_globales = conn.execute(
            f"SELECT COUNT(*) FROM communication_lectures WHERE communication_id IN ({ph_vues})",
            comm_ids_publies).fetchone()[0]
    stats_globales = {
        'vues': total_vues_globales,
        'likes': sum(c.get('nb_likes', 0) for c in comms_data if c['statut'] == 'publie'),
        'commentaires': sum(c.get('nb_commentaires', 0) for c in comms_data if c['statut'] == 'publie'),
    }

    conn.close()
    _auj = datetime.date.today()
    annee_scolaire_courante = f"{_auj.year}-{_auj.year+1}" if _auj.month >= 8 else f"{_auj.year-1}-{_auj.year}"
    return render_template_string(
        COMMUNICATIONS_HTML, comms=comms_rest, comms_slider=comms_slider, classes=classes, q=q,
        classe_filter=classe_filter,
        type_filter=type_filter, priorite_filter=priorite_filter, statut_filter=statut_filter,
        lecture_filter=lecture_filter, tri=tri,
        stats=stats, analytics=analytics, top_comms=top_comms, peut_editer=peut_editer, notif_count=get_notif_count(),
        stats_globales=stats_globales,
        prochain_evenement=dict(prochain_evenement) if prochain_evenement else None, role=role,
        annee_scolaire_courante=annee_scolaire_courante, annee_courante=_auj.year,
        TYPES_COMMUNICATION=TYPES_COMMUNICATION, LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION,
        COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        PRIORITES_COMMUNICATION=PRIORITES_COMMUNICATION, LABELS_PRIORITE_COMMUNICATION=LABELS_PRIORITE_COMMUNICATION,
        COULEURS_PRIORITE_COMMUNICATION=COULEURS_PRIORITE_COMMUNICATION,
    )


@app.route('/communications/<int:comm_id>', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent')
def communication_detail(comm_id):
    conn = get_db()
    role = session['role']
    peut_editer = role in ('admin', 'agent_admin')

    comm = conn.execute("""
        SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
        FROM communications co LEFT JOIN users u ON co.auteur_id = u.id WHERE co.id=?
    """, (comm_id,)).fetchone()
    if not comm:
        conn.close()
        flash("Communication introuvable.", "error")
        return redirect(url_for('communications'))

    classes_comm = conn.execute("""
        SELECT c.id, c.nom, c.niveau FROM classes c
        JOIN communication_classes cc ON cc.classe_id = c.id WHERE cc.communication_id=?
        ORDER BY c.niveau, c.nom
    """, (comm_id,)).fetchall()
    classe_ids_comm = [c['id'] for c in classes_comm]

    # Contrôle d'accès pour les rôles en lecture seule
    if not peut_editer:
        if comm['statut'] != 'publie':
            conn.close()
            flash("Cette communication n'est pas encore publiée.", "error")
            return redirect(url_for('communications'))
        if not comm['toutes_classes']:
            classes_access = [c['id'] for c in _devoir_classes_accessibles(conn, role, session['user_id'])]
            if not any(cid in classes_access for cid in classe_ids_comm):
                conn.close()
                flash("Cette communication ne concerne pas vos classes.", "error")
                return redirect(url_for('communications'))

    if request.method == 'POST':
        action = request.form.get('action')
        ajax_payload = {'ok': True}
        if action == 'marquer_lu':
            # 🆕 Enregistre automatiquement la lecture : dès qu'un parent (ou enseignant) voit la
            # publication, elle apparaît « vue » côté admin — plus besoin de confirmation manuelle.
            conn.execute("""INSERT OR IGNORE INTO communication_lectures (communication_id, user_id, role, lu_at)
                             VALUES (?,?,?,?)""",
                         (comm_id, session['user_id'], role, datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
            conn.commit()
        elif action == 'toggle_like':
            # 🆕 Réponse AJAX enrichie (état du like + nouveau total) pour mise à jour instantanée
            # côté client, sans recharger la page.
            deja = conn.execute("SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
                                 (comm_id, session['user_id'])).fetchone()
            if deja:
                conn.execute("DELETE FROM communication_likes WHERE communication_id=? AND user_id=?",
                             (comm_id, session['user_id']))
                liked_now = False
            else:
                conn.execute("""INSERT OR IGNORE INTO communication_likes (communication_id, user_id, created_at)
                                 VALUES (?,?,?)""",
                             (comm_id, session['user_id'], datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                liked_now = True
            conn.commit()
            nb_likes_now = conn.execute("SELECT COUNT(*) FROM communication_likes WHERE communication_id=?",
                                         (comm_id,)).fetchone()[0]
            ajax_payload.update({'liked': liked_now, 'nb_likes': nb_likes_now})
        elif action == 'commenter':
            # 🆕 Réponse AJAX enrichie : renvoie le commentaire fraîchement créé (avec auteur et date)
            # pour l'insérer directement dans la liste côté client, sans recharger la page.
            texte = request.form.get('contenu', '').strip()
            if texte:
                cur = conn.execute("""INSERT INTO communication_commentaires (communication_id, user_id, role, contenu, created_at)
                                 VALUES (?,?,?,?,?)""",
                             (comm_id, session['user_id'], role, texte,
                              datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                conn.commit()
                nouveau_id = cur.lastrowid
                cm_row = conn.execute("""
                    SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
                    FROM communication_commentaires co LEFT JOIN users u ON u.id = co.user_id
                    WHERE co.id=?
                """, (nouveau_id,)).fetchone()
                if cm_row:
                    ajax_payload['commentaire'] = dict(cm_row)
                    ajax_payload['peut_supprimer'] = True
                flash("Commentaire publié.", "success")
            else:
                ajax_payload = {'ok': False, 'erreur': 'Le commentaire ne peut pas être vide.'}
        elif action == 'supprimer_commentaire':
            com_id = request.form.get('commentaire_id')
            com_row = conn.execute("SELECT * FROM communication_commentaires WHERE id=?", (com_id,)).fetchone()
            if com_row and (peut_editer or com_row['user_id'] == session['user_id']):
                conn.execute("DELETE FROM communication_commentaires WHERE id=?", (com_id,))
                conn.commit()
                flash("Commentaire supprimé.", "success")
            else:
                ajax_payload = {'ok': False}
        conn.close()
        # Requête AJAX silencieuse (like, commentaire, ping « vu » depuis le slider) : pas besoin
        # de redirection HTML, on renvoie directement les données utiles au client.
        if request.form.get('ajax') == '1':
            return jsonify(ajax_payload)
        return redirect(url_for('communication_detail', comm_id=comm_id))

    fichiers = conn.execute("SELECT * FROM communication_fichiers WHERE communication_id=? ORDER BY id",
                            (comm_id,)).fetchall()
    # 🆕 On sépare les images (affichées comme une véritable galerie) des autres pièces jointes
    images_comm = [dict(f) for f in fichiers if f['type_fichier'] == 'image']
    autres_fichiers = [dict(f) for f in fichiers if f['type_fichier'] != 'image']

    a_lu = conn.execute("SELECT 1 FROM communication_lectures WHERE communication_id=? AND user_id=?",
                        (comm_id, session['user_id'])).fetchone() is not None

    # 🆕 Un parent/enseignant qui consulte une publication publiée est automatiquement marqué comme
    # l'ayant vue — cela remonte immédiatement côté admin, sans action supplémentaire de sa part.
    if not peut_editer and not a_lu and comm['statut'] == 'publie':
        conn.execute("""INSERT OR IGNORE INTO communication_lectures (communication_id, user_id, role, lu_at)
                         VALUES (?,?,?,?)""",
                     (comm_id, session['user_id'], role, datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
        conn.commit()
        a_lu = True

    lecteurs_detail = None
    nb_lu_total = None
    if peut_editer:
        parents_cibles_ids = _comm_parents_cibles(conn, comm)
        if parents_cibles_ids:
            ph = ','.join('?' * len(parents_cibles_ids))
            # 🆕 Tri : ceux qui ont vu en premier (lu_at le plus ancien) apparaissent en tête,
            # dans l'ordre chronologique de consultation ; ceux qui n'ont pas encore vu suivent.
            parents_rows = conn.execute(f"""
                SELECT u.id, u.nom, u.prenom, u.telephone,
                       (SELECT lu_at FROM communication_lectures cl WHERE cl.communication_id=? AND cl.user_id=u.id) as lu_at
                FROM users u WHERE u.id IN ({ph}) ORDER BY (lu_at IS NULL) ASC, lu_at ASC, u.nom
            """, [comm_id] + parents_cibles_ids).fetchall()
            lecteurs_detail = [dict(r) for r in parents_rows]
        nb_lu_total = sum(1 for r in (lecteurs_detail or []) if r['lu_at'])

    nb_likes = conn.execute("SELECT COUNT(*) FROM communication_likes WHERE communication_id=?",
                             (comm_id,)).fetchone()[0]
    user_a_aime = conn.execute("SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
                                (comm_id, session['user_id'])).fetchone() is not None
    commentaires = conn.execute("""
        SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
        FROM communication_commentaires co LEFT JOIN users u ON u.id = co.user_id
        WHERE co.communication_id=? ORDER BY co.created_at ASC
    """, (comm_id,)).fetchall()

    # 🆕 Analyses admin : qui a aimé (détail) + taux d'engagement global, pour le tableau de bord
    likers_detail = None
    taux_engagement = 0
    if peut_editer:
        likers_rows = conn.execute("""
            SELECT u.id, u.nom, u.prenom, u.role as user_role, cl.created_at
            FROM communication_likes cl JOIN users u ON u.id = cl.user_id
            WHERE cl.communication_id=? ORDER BY cl.created_at DESC
        """, (comm_id,)).fetchall()
        likers_detail = [dict(r) for r in likers_rows]
        if nb_lu_total:
            taux_engagement = round(100 * (nb_likes + len(commentaires)) / nb_lu_total, 1)

    conn.close()
    return render_template_string(
        COMMUNICATION_DETAIL_HTML, comm=comm, comm_id=comm_id, classes_comm=classes_comm, fichiers=fichiers,
        images_comm=images_comm, autres_fichiers=autres_fichiers, a_lu=a_lu,
        peut_editer=peut_editer, lecteurs_detail=lecteurs_detail,
        nb_lu_total=nb_lu_total, nb_likes=nb_likes, user_a_aime=user_a_aime, commentaires=commentaires,
        likers_detail=likers_detail, taux_engagement=taux_engagement,
        today=datetime.date.today().isoformat(), notif_count=get_notif_count(),
        LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION, COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        LABELS_PRIORITE_COMMUNICATION=LABELS_PRIORITE_COMMUNICATION,
        COULEURS_PRIORITE_COMMUNICATION=COULEURS_PRIORITE_COMMUNICATION, ICONES_TYPE_FICHIER=ICONES_TYPE_FICHIER,
    )


@app.route('/communications/<int:comm_id>/likes')
@login_required
def communication_likes_json(comm_id):
    # 🆕 Liste (façon Instagram) des personnes ayant aimé une communication, affichée dans une
    # boîte au clic sur le nombre de j'aime — accessible à tous les utilisateurs connectés.
    conn = get_db()
    likers_rows = conn.execute("""
        SELECT u.nom, u.prenom, u.role as user_role, cl.created_at
        FROM communication_likes cl JOIN users u ON u.id = cl.user_id
        WHERE cl.communication_id=? ORDER BY cl.created_at DESC
    """, (comm_id,)).fetchall()
    conn.close()
    return jsonify({'ok': True, 'likers': [dict(r) for r in likers_rows]})


@app.route('/communications/fichier/<int:fichier_id>')
@login_required
def communication_fichier(fichier_id):
    conn = get_db()
    fl = conn.execute("SELECT * FROM communication_fichiers WHERE id=?", (fichier_id,)).fetchone()
    conn.close()
    if not fl or fl['type_fichier'] == 'lien':
        flash("Fichier introuvable.", "error")
        return redirect(url_for('communications'))
    path = os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, fl['nom_fichier'])
    if not os.path.exists(path):
        flash("Fichier introuvable sur le serveur.", "error")
        return redirect(url_for('communications'))
    return send_file(path, as_attachment=False, download_name=fl['nom_original'] or fl['nom_fichier'])


@app.route('/communications/fichier/<int:fichier_id>/supprimer', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def communication_fichier_supprimer(fichier_id):
    conn = get_db()
    fl = conn.execute("SELECT * FROM communication_fichiers WHERE id=?", (fichier_id,)).fetchone()
    comm_id = None
    if fl:
        if fl['nom_fichier']:
            p = os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, fl['nom_fichier'])
            if os.path.exists(p):
                try:
                    os.remove(p)
                except OSError:
                    pass
        comm_id = fl['communication_id']
        conn.execute("DELETE FROM communication_fichiers WHERE id=?", (fichier_id,))
        conn.commit()
    conn.close()
    flash("Pièce jointe supprimée.", "success")
    return redirect(url_for('communication_detail', comm_id=comm_id) if comm_id else url_for('communications'))


# ─────────────────────────────────────────────
# PAIEMENTS
# ─────────────────────────────────────────────
# ═══════════════════════════════════════════════════════════════
# 🤖 ROBOT IA — ANALYSE FINANCIÈRE AUTOMATIQUE (revenus 3 cycles + charges)
# ═══════════════════════════════════════════════════════════════
def _construire_prompt_analyse_financiere(analyse):
    """Transforme le dictionnaire d'analyse financière en un prompt texte détaillé,
    en français, destiné au modèle IA (Claude)."""
    ce = analyse['charge_eleve']
    ec = analyse['charge_ecole']
    rpc = analyse.get('revenue_par_cycle', {})
    cpc = analyse.get('charges_par_categorie', [])
    tendance = analyse.get('tendance_mensuelle', {})

    noms_cycles = {'Maternelle': 'Maternelle', 'Primaire': 'Primaire', 'College': 'Collège'}
    lignes_cycles = "\n".join(
        f"- {noms_cycles.get(cyc, cyc)} : attendu {d['total_attendu']:.2f} MAD, "
        f"encaissé {d['total_encaisse']:.2f} MAD ({d['taux']}%), "
        f"reste à percevoir {d['reste']:.2f} MAD"
        for cyc, d in rpc.items()
    ) or "Aucune donnée par cycle disponible."

    lignes_charges = "\n".join(
        f"- {c['categorie']} : {c['total']:.2f} MAD (dont {c['paye']:.2f} MAD déjà payés)"
        for c in cpc
    ) or "Aucune charge diverse enregistrée."

    tendance_txt = ""
    if tendance.get('labels'):
        tendance_txt = "\n".join(
            f"- {m} : revenus encaissés {r:.2f} MAD / dépenses payées {dep:.2f} MAD"
            for m, r, dep in zip(tendance['labels'], tendance['revenus'], tendance['depenses'])
        )

    return f"""Tu es un conseiller financier spécialisé dans la gestion des établissements scolaires privés au Maroc.
Analyse les données financières suivantes de l'école et rédige un compte rendu clair et actionnable pour la direction.

=== REVENUS PAR CYCLE (scolarité élèves — Maternelle / Primaire / Collège) ===
{lignes_cycles}

=== SYNTHÈSE REVENUS GLOBAUX (tous cycles) ===
Total attendu : {ce['total_attendu']:.2f} MAD
Total encaissé : {ce['total_encaisse']:.2f} MAD
Reste à percevoir : {ce['reste_a_percevoir']:.2f} MAD

=== CHARGES DE L'ÉCOLE ===
Total dépenses : {ec['total_depenses']:.2f} MAD
Total payé : {ec['total_paye']:.2f} MAD
Reste à payer : {ec['reste_a_payer']:.2f} MAD
  - Salaires enseignants payés : {ec['salaires_payes']:.2f} MAD
  - Personnel hors-prof payé (chauffeurs, ménage, sécurité, divers) : {ec['salaires_staff_payes']:.2f} MAD
  - Charges diverses payées : {ec['charges_payees']:.2f} MAD

Détail des charges diverses par catégorie :
{lignes_charges}

=== TRÉSORERIE NETTE ===
{analyse['bilan_tresorerie']:.2f} MAD (revenus encaissés - dépenses payées)

=== TENDANCE MENSUELLE (revenus encaissés vs dépenses payées, 6 derniers mois) ===
{tendance_txt or "Pas encore assez de données pour une tendance mensuelle."}

Réponds UNIQUEMENT avec un objet JSON valide (aucun texte avant/après, pas de balises ```json), avec exactement cette structure :
{{
  "score_sante_financiere": <entier de 0 à 100>,
  "synthese": "<2-3 phrases résumant la situation globale (revenus vs charges, trésorerie)>",
  "points_forts": ["<point fort 1>", "<point fort 2>"],
  "points_attention": ["<point de vigilance 1>", "<point de vigilance 2>"],
  "recommandations": [
    {{"titre": "<titre court et concret>", "detail": "<explication actionnable, chiffrée si pertinent>", "priorite": "haute|moyenne|basse"}}
  ],
  "cycle_a_surveiller": "<nom du cycle le plus problématique en termes d'encaissement, ou null si aucun>",
  "idees_innovantes": ["<idée originale et concrète pour améliorer les finances de l'école>", "<autre idée>"]
}}
Sois concret et chiffré. Adapte tes recommandations au contexte d'une école privée marocaine : relances de frais de
scolarité, échéanciers/paiement échelonné, réduction des impayés par cycle, optimisation des charges (négociation
fournisseurs, énergie, transport), maîtrise de la masse salariale, et pistes de diversification des revenus
(activités périscolaires, partenariats, etc.)."""


def _recuperer_impayes_detail(conn, hub_mois_debut='', hub_mois_fin='', hub_cycle_eleve=''):
    """🆕 Va chercher directement en base, ÉLÈVE PAR ÉLÈVE, le détail complet des impayés :
    combien il doit, combien il a payé, ce qu'il reste à payer, et depuis combien de jours
    il est en retard (si une échéance est dépassée). Sert à donner au robot IA (page Paiements)
    un accès réel aux données individuelles, pour qu'il puisse répondre correctement à des
    questions comme « combien de personnes n'ont pas payé ? », « qui a la facture la plus
    lourde ? » ou « qui paie en retard ? », et pas seulement aux totaux globaux."""
    where = ["(p.montant_total - p.montant_paye) > 0.01"]
    params = []
    if hub_cycle_eleve:
        where.append("(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))")
        params.extend([hub_cycle_eleve, hub_cycle_eleve])
    if hub_mois_debut:
        where.append("strftime('%Y-%m', p.date_echeance) >= ?")
        params.append(hub_mois_debut)
    if hub_mois_fin:
        where.append("strftime('%Y-%m', p.date_echeance) <= ?")
        params.append(hub_mois_fin)
    where_sql = "WHERE " + " AND ".join(where)

    try:
        rows = conn.execute(f"""
            SELECT e.id as eleve_id, e.nom, e.prenom, e.numero_matricule,
                   c.nom as classe_nom, COALESCE(c.cycle, 'Primaire') as cycle,
                   SUM(p.montant_total) as total_du,
                   SUM(p.montant_paye) as total_paye,
                   SUM(p.montant_total - p.montant_paye) as reste,
                   MIN(CASE WHEN (p.montant_total - p.montant_paye) > 0.01
                             AND p.date_echeance < date('now')
                        THEN p.date_echeance END) as echeance_plus_ancienne_en_retard
            FROM paiements p
            JOIN eleves e ON p.eleve_id = e.id
            LEFT JOIN classes c ON e.classe_id = c.id
            {where_sql}
            GROUP BY e.id
            HAVING SUM(p.montant_total - p.montant_paye) > 0.01
            ORDER BY reste DESC
        """, params).fetchall()
    except Exception:
        return None

    aujourd_hui = datetime.date.today()
    eleves_impayes = []
    for r in rows:
        jours_retard = None
        if r['echeance_plus_ancienne_en_retard']:
            try:
                d = datetime.datetime.strptime(r['echeance_plus_ancienne_en_retard'][:10], '%Y-%m-%d').date()
                jours_retard = (aujourd_hui - d).days
            except Exception:
                jours_retard = None
        eleves_impayes.append({
            'nom_complet': f"{r['prenom']} {r['nom']}",
            'matricule': r['numero_matricule'] or 'N/A',
            'classe': r['classe_nom'] or '',
            'cycle': r['cycle'],
            'total_du': r['total_du'] or 0,
            'total_paye': r['total_paye'] or 0,
            'reste': r['reste'] or 0,
            'jours_retard': jours_retard,
        })

    # eleves_impayes est déjà trié par "reste" décroissant (donc = classement des factures les plus lourdes)
    en_retard = sorted(
        [e for e in eleves_impayes if e['jours_retard'] and e['jours_retard'] > 0],
        key=lambda e: e['jours_retard'], reverse=True
    )

    return {
        'nb_total_eleves_impayes': len(eleves_impayes),
        'nb_total_eleves_en_retard': len(en_retard),
        'montant_total_impaye': sum(e['reste'] for e in eleves_impayes),
        # On limite les listes détaillées transmises à l'IA pour rester léger/rapide,
        # mais les COMPTEURS ci-dessus, eux, portent toujours sur la totalité des élèves.
        'top_plus_lourds': eleves_impayes[:25],
        'top_en_retard': en_retard[:25],
    }


def _construire_texte_impayes_detail(detail):
    """Formate le détail des impayés par élève en texte lisible pour le prompt de l'IA."""
    if not detail:
        return ""

    def _ligne_eleve(e, avec_retard=True):
        base = (f"- {e['nom_complet']} (classe {e['classe'] or e['cycle']}, matricule {e['matricule']}) : "
                f"reste à payer {e['reste']:.2f} MAD (total dû {e['total_du']:.2f} MAD, "
                f"déjà payé {e['total_paye']:.2f} MAD)")
        if avec_retard and e['jours_retard']:
            base += f" — EN RETARD de {e['jours_retard']} jour(s)"
        return base

    lignes_lourds = "\n".join(_ligne_eleve(e) for e in detail['top_plus_lourds']) or "Aucun impayé."
    lignes_retard = "\n".join(_ligne_eleve(e) for e in detail['top_en_retard']) or "Aucun élève en retard de paiement."

    return f"""

=== DÉTAIL DES IMPAYÉS ÉLÈVE PAR ÉLÈVE (accès direct à la base de données) ===
Nombre TOTAL d'élèves ayant au moins un impayé : {detail['nb_total_eleves_impayes']}
Nombre TOTAL d'élèves en retard de paiement (échéance dépassée) : {detail['nb_total_eleves_en_retard']}
Montant TOTAL restant à percevoir sur l'ensemble des impayés : {detail['montant_total_impaye']:.2f} MAD

Liste des factures les plus lourdes, triées de la plus élevée à la plus faible
(jusqu'à 25 élèves affichés — les compteurs ci-dessus, eux, portent sur la totalité) :
{lignes_lourds}

Liste des élèves en retard de paiement, triés du retard le plus long au plus court
(jusqu'à 25 élèves affichés — le compteur ci-dessus porte sur la totalité) :
{lignes_retard}

Consigne : utilise ces données individuelles pour répondre précisément (nombre exact, noms, montants,
jours de retard) aux questions sur les impayés. Si une liste est tronquée à 25 et que la question porte
sur un élève qui n'y figure pas, dis-le clairement et invite à consulter la liste complète sur la page
Paiements plutôt que d'inventer un chiffre."""


def _erreur_groq_http(resp):
    """Construit un message d'erreur clair à partir d'une réponse HTTP Gemini en échec, avec un
    traitement spécial pour le code 429 (quota gratuit de tokens/minute dépassé) qui indique
    combien de temps attendre avant de réessayer, plutôt qu'un message technique brut."""
    detail = ''
    try:
        detail = resp.json().get('error', {}).get('message', '') if resp is not None else ''
    except Exception:
        pass
    if resp is not None and resp.status_code == 429:
        retry_after = resp.headers.get('Retry-After') or resp.headers.get('retry-after')
        attente = None
        if retry_after:
            try:
                secs = int(float(retry_after))
                attente = f"{secs}s" if secs < 60 else f"{secs // 60}min{secs % 60:02d}s"
            except ValueError:
                attente = retry_after
        if attente:
            return (f"⏳ Quota gratuit Gemini atteint (trop de messages envoyés en peu de temps). "
                     f"Réessayez dans environ {attente}.")
        return ("⏳ Quota gratuit Gemini atteint (trop de messages envoyés en peu de temps). "
                 "Patientez quelques dizaines de secondes puis réessayez.")
    return f"L'API Gemini a renvoyé une erreur ({resp.status_code if resp is not None else '?'}). {detail}"


def appeler_robot_ia_analyse_financiere(analyse):
    """Envoie les données financières à l'IA (API Gemini) et retourne
    un dict {'rapport': {...}} en cas de succès, ou {'erreur': "..."} sinon."""
    if not GEMINI_API_KEY or GEMINI_API_KEY == 'VOTRE_CLE_API_ICI':
        return {'erreur': "Clé API Gemini non configurée. Définissez la variable d'environnement "
                           "GEMINI_API_KEY (ou éditez GEMINI_API_KEY dans le code) pour activer le robot IA."}

    prompt = _construire_prompt_analyse_financiere(analyse)
    texte = ""
    resp = None
    try:
        resp = requests.post(
            "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
            headers={
                "Authorization": f"Bearer {GEMINI_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "model": GEMINI_MODEL_IA,
                "messages": [
                    {"role": "system", "content": "Tu réponds UNIQUEMENT avec un objet JSON valide, sans texte ni balises autour."},
                    {"role": "user", "content": prompt}
                ],
                "temperature": 0.3,
                "max_tokens": 1800,
            },
            timeout=45,
        )
        resp.raise_for_status()
        data = resp.json()
        texte = data["choices"][0]["message"]["content"].strip()
        # Nettoyage de sécurité si le modèle encadre malgré tout la réponse avec ```json ... ```
        texte_nettoye = re.sub(r'^```(?:json)?|```$', '', texte, flags=re.MULTILINE).strip()
        rapport = json.loads(texte_nettoye)
        return {'rapport': rapport}
    except requests.exceptions.HTTPError:
        return {'erreur': _erreur_groq_http(resp)}
    except requests.exceptions.RequestException as e:
        return {'erreur': f"Erreur de connexion à l'API Gemini : {e}"}
    except (json.JSONDecodeError, ValueError, KeyError, IndexError):
        return {'erreur': "L'IA a renvoyé une réponse dans un format inattendu. Merci de réessayer."}
    except Exception as e:
        return {'erreur': f"Erreur inattendue lors de l'analyse IA : {e}"}


def repondre_question_ia_finance(analyse, question, historique=None, impayes_detail=None):
    """Répond à une question libre posée par l'utilisateur sur les finances de l'école
    (API Gemini), en se basant sur le contexte financier actuel (revenus 3 cycles, charges,
    trésorerie) ET sur le détail élève par élève des impayés/retards (impayes_detail),
    pour pouvoir répondre précisément à des questions individuelles."""
    if not GEMINI_API_KEY or GEMINI_API_KEY == 'VOTRE_CLE_API_ICI':
        return {'erreur': "Clé API Gemini non configurée. Définissez la variable d'environnement "
                           "GEMINI_API_KEY (ou éditez GEMINI_API_KEY dans le code) pour activer le robot IA."}

    contexte = _construire_prompt_analyse_financiere(analyse)
    contexte_data = contexte.split("Réponds UNIQUEMENT")[0].strip()  # on retire la consigne JSON, inutile ici
    contexte_data += _construire_texte_impayes_detail(impayes_detail)

    system_msg = (
        "Tu es un conseiller financier IA intégré à la plateforme de gestion de Bright Kidz Private. "
        "Tu réponds en français, de façon claire, concise et actionnable, aux questions de la direction "
        "sur la situation financière de l'école (revenus par cycle, charges, trésorerie, et détail des "
        "impayés élève par élève : qui n'a pas payé, qui a la facture la plus lourde, qui est en retard). "
        "Base-toi UNIQUEMENT sur les données fournies ci-dessous ; si une information manque, dis-le "
        "clairement plutôt que d'inventer des chiffres. Réponds en texte simple (pas de JSON), avec des "
        "puces si utile.\n\n"
        f"=== DONNÉES FINANCIÈRES ACTUELLES ===\n{contexte_data}"
    )

    messages = [{"role": "system", "content": system_msg}]
    for m in (historique or [])[-4:]:  # 🆕 historique réduit (4 échanges) pour économiser des tokens/minute
        role = m.get('role')
        content = (m.get('content') or '').strip()
        if role in ('user', 'assistant') and content:
            messages.append({"role": role, "content": content[:600]})
    messages.append({"role": "user", "content": question[:800]})

    resp = None
    try:
        resp = requests.post(
            "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
            headers={
                "Authorization": f"Bearer {GEMINI_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "model": GEMINI_MODEL_IA,
                "messages": messages,
                "temperature": 0.4,
                "max_tokens": 650,  # 🆕 réduit (900 -> 650) pour économiser le quota gratuit Gemini
            },
            timeout=45,
        )
        resp.raise_for_status()
        data = resp.json()
        reponse = data["choices"][0]["message"]["content"].strip()
        return {'reponse': reponse}
    except requests.exceptions.HTTPError:
        return {'erreur': _erreur_groq_http(resp)}
    except requests.exceptions.RequestException as e:
        return {'erreur': f"Erreur de connexion à l'API Gemini : {e}"}
    except (KeyError, IndexError):
        return {'erreur': "Réponse IA invalide. Merci de réessayer."}
    except Exception as e:
        return {'erreur': f"Erreur inattendue : {e}"}


# ═══════════════════════════════════════════════════════════════
# 🤖 ASSISTANT IA DU TABLEAU DE BORD — accès complet aux données
# (élèves, enseignants, classes, notes/résultats, absences, paiements),
# adapté au rôle de la personne connectée.
# ═══════════════════════════════════════════════════════════════
def _construire_contexte_ia_dashboard(conn, role, user_id):
    """Construit le contexte texte envoyé à l'IA du tableau de bord. Le contenu est
    adapté au rôle connecté : l'admin/agent_admin voit une synthèse de TOUTE l'école
    (effectifs, moyennes par classe/matière, enseignants, meilleurs/plus faibles élèves,
    absences, finances, alertes) ; l'enseignant voit ses classes et ses élèves ; le parent
    voit uniquement ses propres enfants (notes, absences, paiements)."""
    lignes = []

    if role in ('admin', 'agent_admin'):
        nb_eleves = conn.execute("SELECT COUNT(*) FROM eleves").fetchone()[0]
        nb_classes = conn.execute("SELECT COUNT(*) FROM classes").fetchone()[0]
        nb_enseignants = conn.execute("SELECT COUNT(*) FROM users WHERE role='enseignant'").fetchone()[0]
        nb_parents = conn.execute("SELECT COUNT(*) FROM users WHERE role='parent'").fetchone()[0]
        # 🆕 Moyenne pondérée (sous-matière puis matière), même formule que partout ailleurs.
        moy_par_eleve_global = _eleves_moyennes_ponderees(conn)
        moy_gen = round(sum(moy_par_eleve_global.values()) / len(moy_par_eleve_global), 2) if moy_par_eleve_global else 0
        nb_absences = conn.execute("SELECT COUNT(*) FROM absences").fetchone()[0]
        pay = conn.execute("SELECT SUM(montant_total) as t, SUM(montant_paye) as p FROM paiements").fetchone()
        total_du = pay['t'] or 0
        total_paye = pay['p'] or 0
        taux_paiement = round((total_paye / total_du * 100) if total_du else 0, 1)
        impaye_count = conn.execute("SELECT COUNT(*) FROM paiements WHERE statut!='paye'").fetchone()[0]

        lignes.append("=== VUE D'ENSEMBLE DE  ===")
        lignes.append(f"Élèves inscrits : {nb_eleves} | Classes : {nb_classes} | "
                       f"Enseignants : {nb_enseignants} | Comptes parents : {nb_parents}")
        lignes.append(f"Moyenne générale de l'établissement (toutes matières/classes) : {moy_gen}/20")
        lignes.append(f"Absences enregistrées (total, tous élèves) : {nb_absences}")
        lignes.append(f"Situation financière globale : {total_du:.0f} MAD facturés, {total_paye:.0f} MAD "
                       f"encaissés (taux de paiement {taux_paiement}%), {impaye_count} paiement(s) non "
                       f"soldé(s) (partiel ou non payé)")

        cycles = conn.execute("""
            SELECT COALESCE(NULLIF(c.cycle,''),'Primaire') as cycle,
                   COUNT(DISTINCT c.id) as nb_classes, COUNT(e.id) as nb_eleves
            FROM classes c LEFT JOIN eleves e ON e.classe_id = c.id
            GROUP BY COALESCE(NULLIF(c.cycle,''),'Primaire')
        """).fetchall()
        if cycles:
            lignes.append("\n=== RÉPARTITION PAR CYCLE ===")
            for c in cycles:
                lignes.append(f"- {c['cycle']} : {c['nb_classes']} classe(s), {c['nb_eleves']} élève(s)")

        classes_moy = conn.execute("""
            SELECT c.id, c.nom, c.niveau, COALESCE(NULLIF(c.cycle,''),'Primaire') as cycle,
                   COUNT(DISTINCT e.id) as nb_eleves
            FROM classes c
            LEFT JOIN eleves e ON e.classe_id = c.id
            GROUP BY c.id ORDER BY c.nom
        """).fetchall()
        classes_moy = [dict(r) for r in classes_moy]
        # 🆕 Moyenne de classe = moyenne des moyennes pondérées des élèves de la classe
        classe_of_eleve = {r['id']: r['classe_id'] for r in conn.execute("SELECT id, classe_id FROM eleves").fetchall()}
        moys_par_classe = {}
        for eid, moy in moy_par_eleve_global.items():
            cid = classe_of_eleve.get(eid)
            if cid:
                moys_par_classe.setdefault(cid, []).append(moy)
        for c in classes_moy:
            vals = moys_par_classe.get(c['id'])
            c['moyenne'] = round(sum(vals) / len(vals), 2) if vals else None
        if classes_moy:
            lignes.append("\n=== EFFECTIF ET MOYENNE PAR CLASSE ===")
            for c in classes_moy:
                m = f"{c['moyenne']:.2f}/20" if c['moyenne'] is not None else "aucune note saisie"
                lignes.append(f"- {c['nom']} (ID_CLASSE:{c['id']}) [{c['cycle']}, {c['niveau']}] : "
                               f"{c['nb_eleves']} élève(s), moyenne {m}")

        matieres_moy = _matieres_moyennes_ponderees(conn)
        if matieres_moy:
            lignes.append("\n=== MOYENNE PAR MATIÈRE (toutes classes confondues) ===")
            for m in matieres_moy:
                lignes.append(f"- {m['matiere']} : {m['moyenne']:.2f}/20 ({m['nb_notes']} note(s) saisie(s))")

        enseignants = conn.execute("""
            SELECT u.id, u.prenom||' '||u.nom as nom, u.matiere_specialite,
                   GROUP_CONCAT(DISTINCT c.nom) as classes
            FROM users u
            LEFT JOIN classe_profs cp ON cp.enseignant_id = u.id
            LEFT JOIN classes c ON c.id = cp.classe_id
            WHERE u.role = 'enseignant'
            GROUP BY u.id ORDER BY u.nom
        """).fetchall()
        if enseignants:
            lignes.append("\n=== ENSEIGNANTS ET LEURS CLASSES ===")
            for e in enseignants:
                spe = e['matiere_specialite'] or 'matière non précisée'
                lignes.append(f"- {e['nom']} (ID_ENSEIGNANT:{e['id']}) ({spe}) : "
                               f"classes = {e['classes'] or 'aucune classe assignée'}")

        # 🆕 Classement complet (moyenne pondérée sous-matière puis matière) pour Top / Bas 15
        eleves_info_rows = conn.execute("""
            SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe,
                   (SELECT COUNT(*) FROM notes n2 WHERE n2.eleve_id = e.id) as nb_notes
            FROM eleves e LEFT JOIN classes c ON c.id = e.classe_id
        """).fetchall()
        eleves_info_map = {r['id']: r for r in eleves_info_rows}
        classement_complet = [
            {'id': eid, 'nom': eleves_info_map[eid]['nom'], 'classe': eleves_info_map[eid]['classe'],
             'moyenne': moy, 'nb_notes': eleves_info_map[eid]['nb_notes']}
            for eid, moy in moy_par_eleve_global.items()
            if eid in eleves_info_map and eleves_info_map[eid]['nb_notes'] > 0
        ]
        top_eleves = sorted(classement_complet, key=lambda x: x['moyenne'], reverse=True)[:15]
        if top_eleves:
            lignes.append("\n=== TOP 15 DES MEILLEURS ÉLÈVES (toutes classes) ===")
            for e in top_eleves:
                lignes.append(f"- {e['nom']} (ID_ELEVE:{e['id']}) ({e['classe']}) : {e['moyenne']:.2f}/20")

        bas_eleves = sorted(classement_complet, key=lambda x: x['moyenne'])[:15]
        if bas_eleves:
            lignes.append("\n=== 15 ÉLÈVES EN DIFFICULTÉ (moyenne la plus basse) ===")
            for e in bas_eleves:
                lignes.append(f"- {e['nom']} (ID_ELEVE:{e['id']}) ({e['classe']}) : {e['moyenne']:.2f}/20")

        abs_freq = conn.execute("""
            SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe, COUNT(a.id) as nb
            FROM absences a JOIN eleves e ON a.eleve_id = e.id
            LEFT JOIN classes c ON c.id = e.classe_id
            GROUP BY a.eleve_id ORDER BY nb DESC LIMIT 10
        """).fetchall()
        if abs_freq:
            lignes.append("\n=== ÉLÈVES AVEC LE PLUS D'ABSENCES ===")
            for a in abs_freq:
                lignes.append(f"- {a['nom']} (ID_ELEVE:{a['id']}) ({a['classe']}) : {a['nb']} absence(s)")

        classes_sans_prof = conn.execute("""
            SELECT c.nom FROM classes c
            WHERE NOT EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id)
            ORDER BY c.nom
        """).fetchall()
        parents_sans_tel = conn.execute(
            "SELECT COUNT(*) FROM users WHERE role='parent' AND (telephone IS NULL OR telephone='')"
        ).fetchone()[0]
        lignes.append("\n=== ALERTES ===")
        if classes_sans_prof:
            lignes.append("- Classes sans enseignant assigné : " + ", ".join(c['nom'] for c in classes_sans_prof))
        else:
            lignes.append("- Toutes les classes ont au moins un enseignant assigné.")
        lignes.append(f"- {parents_sans_tel} parent(s) sans numéro de téléphone renseigné.")

        # 🆕 Fiche complète de CHAQUE élève : notes détaillées par matière + situation de
        # paiement précise. Permet à l'IA de répondre sur un élève nommé précis (ex: "Yazan"),
        # pas seulement sur les 15 meilleurs/plus faibles.
        notes_par_matiere = conn.execute("""
            SELECT y.eleve_id as eleve_id, y.matiere as matiere,
                   SUM(y.note * y.coef_sm) * 1.0 / NULLIF(SUM(y.coef_sm), 0) as moyenne, COUNT(*) as nb
            FROM (
                SELECT n.eleve_id, m.nom as matiere, n.note, COALESCE(sm.coefficient, 1) AS coef_sm
                FROM notes n JOIN matieres m ON m.id = n.matiere_id
                LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
            ) y GROUP BY y.eleve_id, y.matiere
        """).fetchall()
        notes_par_eleve = {}
        for n in notes_par_matiere:
            notes_par_eleve.setdefault(n['eleve_id'], []).append(
                f"{n['matiere']}: {n['moyenne']:.1f}/20 ({n['nb']} note(s))")

        paiements_par_eleve = {}
        for p in conn.execute("""
            SELECT eleve_id, SUM(montant_total) as t, SUM(montant_paye) as p,
                   GROUP_CONCAT(DISTINCT statut) as statuts
            FROM paiements GROUP BY eleve_id
        """).fetchall():
            paiements_par_eleve[p['eleve_id']] = p

        tous_eleves = conn.execute("""
            SELECT e.id, e.prenom||' '||e.nom as nom, e.numero_matricule,
                   c.nom as classe, COALESCE(NULLIF(c.cycle,''),'Primaire') as cycle
            FROM eleves e LEFT JOIN classes c ON c.id = e.classe_id
            ORDER BY c.nom, e.nom
        """).fetchall()

        if tous_eleves:
            lignes.append(f"\n=== FICHE DÉTAILLÉE DE TOUS LES ÉLÈVES ({len(tous_eleves)}) : "
                           "notes par matière + paiements ===")
            lignes.append("(Base-toi sur cette liste pour toute question portant sur un élève précis, "
                           "même s'il n'apparaît pas dans les classements ci-dessus.)")
            for e in tous_eleves:
                notes_txt = ", ".join(notes_par_eleve.get(e['id'], [])) or "aucune note saisie"
                pay = paiements_par_eleve.get(e['id'])
                if pay and (pay['t'] or pay['p']):
                    du = pay['t'] or 0
                    paye_m = pay['p'] or 0
                    pay_txt = f"{paye_m:.0f}/{du:.0f} MAD payés (statut: {pay['statuts']})"
                else:
                    pay_txt = "aucun paiement enregistré"
                lignes.append(f"- {e['nom']} (ID_ELEVE:{e['id']}) | matricule {e['numero_matricule'] or '—'} | "
                               f"classe {e['classe'] or '—'} ({e['cycle']}) | Notes: {notes_txt} | "
                               f"Paiements: {pay_txt}")

        lignes.append("\nNote : la fiche détaillée ci-dessus couvre TOUS les élèves de l'école ; utilise-la "
                       "en priorité pour toute question nominative (un élève précis) plutôt que d'inventer "
                       "une réponse. Les classements top/bottom 15 servent juste à repérer rapidement les cas "
                       "extrêmes.")

    elif role == 'enseignant':
        eid = user_id
        classes = conn.execute("""
            SELECT c.nom, c.niveau, COUNT(e.id) as nb_eleves
            FROM classes c LEFT JOIN eleves e ON e.classe_id = c.id
            WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
            GROUP BY c.id
        """, (eid,)).fetchall()
        lignes.append("=== MES CLASSES ===")
        for c in classes:
            lignes.append(f"- {c['nom']} ({c['niveau']}) : {c['nb_eleves']} élève(s)")

        # 🆕 Moyenne pondérée (sous-matière puis matière) des notes que CE prof a lui-même saisies
        eleves = conn.execute("""
            SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe,
                   y.moyenne as moyenne, COALESCE(y.nb_notes,0) as nb_notes
            FROM eleves e JOIN classes c ON c.id = e.classe_id
            LEFT JOIN (
                SELECT eleve_id,
                       SUM(matiere_moy*coef_matiere)*1.0/NULLIF(SUM(coef_matiere),0) as moyenne,
                       SUM(nb_notes) as nb_notes
                FROM (
                    SELECT eleve_id, matiere_id, coef_matiere,
                           SUM(note*coef_sm)*1.0/NULLIF(SUM(coef_sm),0) as matiere_moy,
                           COUNT(*) as nb_notes
                    FROM (
                        SELECT n.eleve_id, n.matiere_id, m.coefficient as coef_matiere, n.note,
                               COALESCE(sm.coefficient,1) as coef_sm
                        FROM notes n JOIN matieres m ON m.id=n.matiere_id
                        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                        WHERE n.enseignant_id=?
                    ) raw GROUP BY eleve_id, matiere_id, coef_matiere
                ) y2 GROUP BY eleve_id
            ) y ON y.eleve_id = e.id
            WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
            ORDER BY c.nom, e.nom
        """, (eid, eid)).fetchall()
        if eleves:
            lignes.append("\n=== MES ÉLÈVES ET LEUR MOYENNE (dans ma/mes matière(s)) ===")
            for e in eleves:
                m = f"{e['moyenne']:.2f}/20 ({e['nb_notes']} note(s))" if e['nb_notes'] else "aucune note saisie"
                lignes.append(f"- {e['nom']} (ID_ELEVE:{e['id']}) ({e['classe']}) : {m}")

        nb_abs = conn.execute("SELECT COUNT(*) FROM absences WHERE signale_par=?", (eid,)).fetchone()[0]
        lignes.append(f"\nAbsences que j'ai signalées personnellement : {nb_abs}")
        lignes.append("\nNote : je n'ai accès qu'à mes propres classes et aux notes que j'ai saisies ; "
                       "pour des données sur d'autres classes ou enseignants, dis clairement que ce n'est "
                       "pas accessible depuis cet espace.")

    elif role == 'parent':
        pid = user_id
        enfants = conn.execute("""
            SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe
            FROM eleves e LEFT JOIN classes c ON c.id = e.classe_id
            WHERE e.parent_id = ?
        """, (pid,)).fetchall()
        lignes.append("=== MES ENFANTS ===")
        for enf in enfants:
            moy = conn.execute("SELECT AVG(note) FROM notes WHERE eleve_id=?", (enf['id'],)).fetchone()[0]
            moy_txt = f"{moy:.2f}/20" if moy else "aucune note"
            nb_abs = conn.execute("SELECT COUNT(*) FROM absences WHERE eleve_id=?", (enf['id'],)).fetchone()[0]
            pay = conn.execute(
                "SELECT SUM(montant_total) as t, SUM(montant_paye) as p FROM paiements WHERE eleve_id=?",
                (enf['id'],)).fetchone()
            du = pay['t'] or 0
            paye_m = pay['p'] or 0
            lignes.append(f"- {enf['nom']} (ID_ELEVE:{enf['id']}) ({enf['classe']}) : moyenne générale {moy_txt}, {nb_abs} "
                           f"absence(s), paiements {paye_m:.0f}/{du:.0f} MAD")

            notes_detail = conn.execute("""
                SELECT m.nom as matiere, n.note, n.trimestre, n.commentaire
                FROM notes n JOIN matieres m ON m.id = n.matiere_id
                WHERE n.eleve_id = ? ORDER BY n.id DESC LIMIT 12
            """, (enf['id'],)).fetchall()
            if notes_detail:
                lignes.append(f"  Dernières notes de {enf['nom']} :")
                for n in notes_detail:
                    com = f" — {n['commentaire']}" if n['commentaire'] else ""
                    lignes.append(f"    · {n['matiere']} (T{n['trimestre']}) : {n['note']}/20{com}")

        lignes.append("\nNote : je n'ai accès qu'aux données de mes propres enfants ; pour toute question "
                       "sur d'autres élèves, dis clairement que ce n'est pas accessible depuis cet espace.")

    lignes.append("\n=== LÉGENDE DES IDENTIFIANTS (pour générer des boutons d'action) ===")
    lignes.append("Chaque nom ci-dessus peut être suivi d'un tag (ID_ELEVE:x / ID_CLASSE:x / "
                   "ID_ENSEIGNANT:x). Utilise UNIQUEMENT ces identifiants, jamais inventés, pour "
                   "construire des actions cliquables : profil élève -> /eleves/x ; liste des élèves "
                   "d'une classe -> /eleves?classe_id=x ; profil enseignant -> /enseignants/x. N'affiche "
                   "PAS ces tags '(ID_...)' dans le texte de ta réponse, ils sont réservés à la "
                   "construction des URLs d'action.")

    return "\n".join(lignes)


def repondre_question_ia_dashboard(contexte, question, historique, role):
    """Répond à une question libre posée depuis le tableau de bord (API Gemini), en se basant
    sur le contexte de la base de données (élèves, enseignants, classes, notes/résultats,
    absences, paiements) adapté au rôle de la personne connectée. Retourne une réponse
    STRUCTURÉE (texte + graphique optionnel + boutons d'action optionnels vers les pages
    du site) afin que l'interface puisse afficher des courbes et des liens cliquables."""
    if not GEMINI_API_KEY or GEMINI_API_KEY == 'VOTRE_CLE_API_ICI':
        return {'erreur': "Clé API Gemini non configurée. Définissez la variable d'environnement "
                           "GEMINI_API_KEY (ou éditez GEMINI_API_KEY dans le code) pour activer le robot IA."}

    role_label = {
        'admin': "l'administration de l'école (accès à toutes les données de l'établissement)",
        'agent_admin': "l'administration de l'école (accès à toutes les données de l'établissement)",
        'enseignant': "un enseignant (accès limité à ses classes et à ses notes)",
        'parent': "un parent d'élève (accès limité à ses propres enfants)",
    }.get(role, "un utilisateur de la plateforme")

    system_msg = (
        "Tu es l'assistant IA intégré au tableau de bord de la plateforme de gestion de ecole "
        f"test. La personne qui te parle est {role_label}. Tu réponds en français, de façon claire, "
        "concise, professionnelle et utile, à des questions sur les élèves, les enseignants, les "
        "classes, les notes/résultats, les absences et les paiements. Base-toi UNIQUEMENT sur les "
        "données fournies ci-dessous ; si une information manque ou dépasse le périmètre de la "
        "personne connectée, dis-le clairement plutôt que d'inventer des chiffres ou des noms. Tu peux "
        "proposer une analyse (tendances, points faibles/forts, recommandations) en t'appuyant sur ces "
        "données.\n\n"
        "RÉPONDS UNIQUEMENT AVEC UN OBJET JSON VALIDE (sans texte ni balises markdown autour), avec "
        "exactement cette structure :\n"
        "{\n"
        '  "texte": "ta réponse en français, avec des puces (\\n- ...) si utile, SANS jamais afficher '
        'les tags (ID_...)",\n'
        '  "graphique": null OU {"type": "bar"|"line"|"pie", "titre": "...", "labels": ["..."], '
        '"valeurs": [nombre, ...]},\n'
        '  "actions": [] OU [{"label": "Voir le profil de ...", "url": "/eleves/12"}, ...]\n'
        "}\n\n"
        "Règles pour \"graphique\" : inclue-le UNIQUEMENT si la question porte sur une comparaison, une "
        "répartition ou une évolution chiffrée (ex: moyennes par classe/matière, effectifs par cycle, "
        "évolution) où un graphique apporte une vraie valeur ; sinon mets null. Les valeurs doivent "
        "venir strictement des données fournies, jamais inventées. Limite à 12 labels maximum.\n"
        "Règles pour \"actions\" : propose 1 à 4 boutons UNIQUEMENT quand un élève, une classe ou un "
        "enseignant précis et nommé dans les données est concerné par la réponse. Construis l'URL "
        "SEULEMENT à partir d'un identifiant explicitement fourni dans les données (ID_ELEVE:x -> "
        "/eleves/x, ID_CLASSE:x -> /eleves?classe_id=x, ID_ENSEIGNANT:x -> /enseignants/x). N'invente "
        "jamais un identifiant. Si aucun élément précis n'est concerné, renvoie une liste vide.\n\n"
        f"=== DONNÉES ACTUELLES DE LA PLATEFORME ===\n{contexte}"
    )

    messages = [{"role": "system", "content": system_msg}]
    for m in (historique or [])[-4:]:  # 🆕 historique réduit (4 échanges) pour économiser des tokens/minute
        r = m.get('role')
        content = (m.get('content') or '').strip()
        if r in ('user', 'assistant') and content:
            messages.append({"role": r, "content": content[:600]})
    messages.append({"role": "user", "content": question[:800]})

    resp = None
    try:
        resp = requests.post(
            "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions",
            headers={
                "Authorization": f"Bearer {GEMINI_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "model": GEMINI_MODEL_IA,
                "messages": messages,
                "temperature": 0.4,
                "max_tokens": 700,  # 🆕 réduit (1100 -> 700) pour économiser le quota gratuit Gemini
                "response_format": {"type": "json_object"},
            },
            timeout=45,
        )
        resp.raise_for_status()
        data = resp.json()
        brut = data["choices"][0]["message"]["content"].strip()
        nettoye = re.sub(r'^```(?:json)?|```$', '', brut, flags=re.MULTILINE).strip()
        try:
            structure = json.loads(nettoye)
        except (json.JSONDecodeError, ValueError):
            # Filet de sécurité : si l'IA n'a malgré tout pas renvoyé du JSON valide,
            # on affiche quand même sa réponse en texte brut plutôt que d'échouer.
            return {'reponse': {'texte': brut, 'graphique': None, 'actions': []}}

        texte = (structure.get('texte') or "Je n'ai pas pu formuler de réponse.").strip()
        graphique = structure.get('graphique') or None
        if graphique and not (graphique.get('labels') and graphique.get('valeurs')):
            graphique = None
        actions_brutes = structure.get('actions') or []
        actions = []
        # 🔒 On ne fait confiance qu'aux URLs internes attendues (profil élève/classe/enseignant),
        # pour éviter qu'une réponse IA ne génère un lien externe ou mal formé.
        motif_url = re.compile(r'^/(eleves(/\d+)?(\?classe_id=\d+)?|enseignants/\d+)$')
        for a in actions_brutes[:4]:
            label = (a.get('label') or '').strip()
            url = (a.get('url') or '').strip()
            if label and url and motif_url.match(url):
                actions.append({'label': label[:60], 'url': url})

        return {'reponse': {'texte': texte, 'graphique': graphique, 'actions': actions}}
    except requests.exceptions.HTTPError:
        return {'erreur': _erreur_groq_http(resp)}
    except requests.exceptions.RequestException as e:
        return {'erreur': f"Erreur de connexion à l'API Gemini : {e}"}
    except (KeyError, IndexError):
        return {'erreur': "Réponse IA invalide. Merci de réessayer."}
    except Exception as e:
        return {'erreur': f"Erreur inattendue : {e}"}


def calculer_analyse_globale(conn, hub_mois_debut='', hub_mois_fin='', hub_cycle_eleve='', hub_type_ecole=''):
    """Calcule le tableau de bord financier global de l'école (Charge Élève vs Charge École) :
    revenus de scolarité (globaux + détail des 3 cycles Maternelle/Primaire/Collège), charges
    (salaires enseignants, personnel hors-prof, charges diverses par catégorie) et trésorerie nette.
    Fonction centrale réutilisée par la page Hub des paiements ET par le robot IA d'analyse."""
    # 1. CHARGE ÉLÈVE (Revenus scolarité) — filtrable par période et par cycle
    where_eleve = []
    params_eleve = []
    if hub_cycle_eleve:
        where_eleve.append("(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))")
        params_eleve.extend([hub_cycle_eleve, hub_cycle_eleve])
    if hub_mois_debut:
        where_eleve.append("strftime('%Y-%m', p.date_echeance) >= ?")
        params_eleve.append(hub_mois_debut)
    if hub_mois_fin:
        where_eleve.append("strftime('%Y-%m', p.date_echeance) <= ?")
        params_eleve.append(hub_mois_fin)
    where_sql_eleve = ("WHERE " + " AND ".join(where_eleve)) if where_eleve else ""

    rev_data = conn.execute(
        f"""SELECT SUM(p.montant_total) as total, SUM(p.montant_paye) as paye
            FROM paiements p
            JOIN eleves e ON p.eleve_id = e.id
            LEFT JOIN classes c ON e.classe_id = c.id
            {where_sql_eleve}""", params_eleve).fetchone()
    rev_total = rev_data['total'] if rev_data['total'] else 0
    rev_paye = rev_data['paye'] if rev_data['paye'] else 0
    rev_reste = rev_total - rev_paye

    # 🆕 Répartition des revenus SUR LES 3 CYCLES (indépendamment du filtre hub_cycle_eleve),
    # pour que l'analyse (et le robot IA) puisse comparer Maternelle / Primaire / Collège.
    revenue_par_cycle = {}
    for cyc in get_all_cycle_names():
        where_cyc = ["(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))"]
        params_cyc = [cyc, cyc]
        if hub_mois_debut:
            where_cyc.append("strftime('%Y-%m', p.date_echeance) >= ?")
            params_cyc.append(hub_mois_debut)
        if hub_mois_fin:
            where_cyc.append("strftime('%Y-%m', p.date_echeance) <= ?")
            params_cyc.append(hub_mois_fin)
        d = conn.execute(
            f"""SELECT SUM(p.montant_total) as total, SUM(p.montant_paye) as paye
                FROM paiements p
                JOIN eleves e ON p.eleve_id = e.id
                LEFT JOIN classes c ON e.classe_id = c.id
                WHERE {" AND ".join(where_cyc)}""", params_cyc).fetchone()
        t = d['total'] if d['total'] else 0
        pa = d['paye'] if d['paye'] else 0
        revenue_par_cycle[cyc] = {
            'total_attendu': t,
            'total_encaisse': pa,
            'reste': t - pa,
            'taux': round((pa / t * 100) if t else 0, 1)
        }

    # 2. CHARGE ÉCOLE (Dépenses : Salaires + Charges diverses)
    inclure_enseignants = (not hub_type_ecole) or hub_type_ecole == 'enseignants'
    inclure_personnel = (not hub_type_ecole) or hub_type_ecole == 'personnel'
    inclure_charges = (not hub_type_ecole) or hub_type_ecole == 'charges'

    # a) Salaires enseignants
    prof_total = prof_paye = 0
    if inclure_enseignants:
        where_prof = []
        params_prof = []
        if hub_mois_debut:
            where_prof.append("mois >= ?")
            params_prof.append(hub_mois_debut)
        if hub_mois_fin:
            where_prof.append("mois <= ?")
            params_prof.append(hub_mois_fin)
        where_sql_prof = ("WHERE " + " AND ".join(where_prof)) if where_prof else ""
        prof_data = conn.execute(
            f"SELECT SUM(montant_total) as total, SUM(montant_paye) as paye FROM paiements_enseignants {where_sql_prof}",
            params_prof).fetchone()
        prof_total = prof_data['total'] if prof_data['total'] else 0
        prof_paye = prof_data['paye'] if prof_data['paye'] else 0

    # b) Salaires du personnel hors prof (chauffeurs, femmes de ménage, sécurité, divers)
    staff_total = staff_paye = 0
    if inclure_personnel:
        try:
            where_staff = []
            params_staff = []
            if hub_mois_debut:
                where_staff.append("mois >= ?")
                params_staff.append(hub_mois_debut)
            if hub_mois_fin:
                where_staff.append("mois <= ?")
                params_staff.append(hub_mois_fin)
            where_sql_staff = ("WHERE " + " AND ".join(where_staff)) if where_staff else ""
            staff_data = conn.execute(
                f"SELECT SUM(montant_total) as total, SUM(montant_paye) as paye FROM paiements_personnel_hors_prof {where_sql_staff}",
                params_staff).fetchone()
            staff_total = staff_data['total'] if staff_data['total'] else 0
            staff_paye = staff_data['paye'] if staff_data['paye'] else 0
        except Exception:
            staff_total = 0
            staff_paye = 0

    # c) Charges diverses de l'école (+ détail par catégorie pour l'analyse IA)
    charge_payee = charge_non_payee = 0
    charges_par_categorie = []
    if inclure_charges:
        try:
            where_charge = []
            if hub_mois_debut:
                where_charge.append("strftime('%Y-%m', date_facture) >= ?")
            if hub_mois_fin:
                where_charge.append("strftime('%Y-%m', date_facture) <= ?")
            extra_charge_sql = (" AND " + " AND ".join(where_charge)) if where_charge else ""
            extra_params = ([hub_mois_debut] if hub_mois_debut else []) + ([hub_mois_fin] if hub_mois_fin else [])
            charge_p_data = conn.execute(
                f"SELECT SUM(montant) as total FROM charges WHERE statut='paye'{extra_charge_sql}",
                extra_params).fetchone()
            charge_np_data = conn.execute(
                f"SELECT SUM(montant) as total FROM charges WHERE statut!='paye'{extra_charge_sql}",
                extra_params).fetchone()
            charge_payee = charge_p_data['total'] if charge_p_data['total'] else 0
            charge_non_payee = charge_np_data['total'] if charge_np_data['total'] else 0

            rows_cat = conn.execute(
                f"""SELECT COALESCE(NULLIF(categorie,''),'Autre') as categorie,
                           SUM(montant) as total,
                           SUM(CASE WHEN statut='paye' THEN montant ELSE 0 END) as paye
                    FROM charges
                    WHERE 1=1{extra_charge_sql}
                    GROUP BY categorie ORDER BY total DESC""", extra_params).fetchall()
            charges_par_categorie = [
                {'categorie': r['categorie'], 'total': r['total'] or 0, 'paye': r['paye'] or 0}
                for r in rows_cat
            ]
        except Exception:
            charge_payee = 0
            charge_non_payee = 0
            charges_par_categorie = []

    charge_total = charge_payee + charge_non_payee

    ecole_total = prof_total + staff_total + charge_total
    ecole_paye = prof_paye + staff_paye + charge_payee
    ecole_reste = (prof_total - prof_paye) + (staff_total - staff_paye) + charge_non_payee

    # 🆕 Tendance mensuelle (courbe) : revenus encaissés vs dépenses payées, 6 derniers mois
    mois_data = {}
    for row in conn.execute(
            "SELECT strftime('%Y-%m', date_paiement) as m, SUM(montant_paye) as v FROM paiements "
            "WHERE date_paiement IS NOT NULL GROUP BY m"):
        if row['m']:
            mois_data.setdefault(row['m'], {'rev': 0, 'dep': 0})['rev'] += row['v'] or 0
    for row in conn.execute("SELECT mois as m, SUM(montant_paye) as v FROM paiements_enseignants GROUP BY mois"):
        if row['m']:
            mois_data.setdefault(row['m'], {'rev': 0, 'dep': 0})['dep'] += row['v'] or 0
    try:
        for row in conn.execute(
                "SELECT mois as m, SUM(montant_paye) as v FROM paiements_personnel_hors_prof GROUP BY mois"):
            if row['m']:
                mois_data.setdefault(row['m'], {'rev': 0, 'dep': 0})['dep'] += row['v'] or 0
    except Exception:
        pass
    try:
        for row in conn.execute(
                "SELECT strftime('%Y-%m', date_facture) as m, SUM(montant) as v FROM charges "
                "WHERE statut='paye' GROUP BY m"):
            if row['m']:
                mois_data.setdefault(row['m'], {'rev': 0, 'dep': 0})['dep'] += row['v'] or 0
    except Exception:
        pass
    mois_tries = sorted(mois_data.keys())[-6:]
    tendance_mensuelle = {
        'labels': mois_tries,
        'revenus': [round(mois_data[m]['rev'], 2) for m in mois_tries],
        'depenses': [round(mois_data[m]['dep'], 2) for m in mois_tries],
    }

    return {
        'charge_eleve': {
            'total_attendu': rev_total,
            'total_encaisse': rev_paye,
            'reste_a_percevoir': rev_reste
        },
        'charge_ecole': {
            'total_depenses': ecole_total,
            'total_paye': ecole_paye,
            'reste_a_payer': ecole_reste,
            'salaires_payes': prof_paye,
            'salaires_staff_payes': staff_paye,
            'charges_payees': charge_payee
        },
        'bilan_tresorerie': rev_paye - ecole_paye,
        'tendance_mensuelle': tendance_mensuelle,
        'revenue_par_cycle': revenue_par_cycle,
        'charges_par_categorie': charges_par_categorie,
    }


@app.route('/paiements/api/analyse-ia', methods=['POST'])
@login_required
@role_required('admin')
def api_analyse_ia_finance():
    """🤖 Déclenche le robot IA d'analyse financière sur la page principale des paiements.
    Recalcule les données (revenus des 3 cycles + charges) selon les filtres actifs du Hub,
    puis interroge l'IA pour produire un compte rendu et des recommandations d'amélioration."""
    # 🔒 AGENT ADMIN : ce robot IA révèle les totaux (revenus/charges/salaires) — interdit.
    if session.get('role') == 'agent_admin':
        return jsonify({'success': False, 'erreur': "Accès non autorisé."})
    f = request.get_json(silent=True) or {}
    hub_mois_debut = (f.get('hub_mois_debut') or '').strip()
    hub_mois_fin = (f.get('hub_mois_fin') or '').strip()
    hub_cycle_eleve = (f.get('hub_cycle_eleve') or '').strip()
    hub_type_ecole = (f.get('hub_type_ecole') or '').strip()

    conn = get_db()
    analyse = calculer_analyse_globale(conn, hub_mois_debut, hub_mois_fin, hub_cycle_eleve, hub_type_ecole)
    conn.close()

    resultat = appeler_robot_ia_analyse_financiere(analyse)
    if 'erreur' in resultat:
        return jsonify({'success': False, 'erreur': resultat['erreur']})
    return jsonify({'success': True, 'rapport': resultat['rapport']})

