@app.route('/paiements', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'parent')
def paiements():
    conn = get_db()

    if request.method == 'POST':
        # Récupération immédiate du cycle en cours pour la redirection
        cycle = request.form.get('cycle', 'Primaire')

        if session['role'] in ('admin', 'agent_admin'):
            f = request.form
            action = f.get('action')

            # 🆕 AGENT ADMIN : n'a pas accès à la rémunération des enseignants
            if session['role'] == 'agent_admin' and action in ('generer_enseignant', 'update_enseignant'):
                flash('Accès non autorisé.', 'error')
                return redirect(url_for('paiements', cycle=cycle))

            # --- ADAPTATION : Génération de la facture enseignant (Non payée) ---
            if action == 'generer_enseignant':
                enseignant_id = f.get('enseignant_id')
                mois = f.get('mois')
                unites = float(f.get('unites', 0) or 0)

                if not enseignant_id or not mois:
                    flash('Veuillez sélectionner un enseignant et un mois.', 'error')
                    return redirect(url_for('paiements', cycle=cycle))

                # Récupération du profil de l'enseignant
                ens = conn.execute("SELECT type_paiement, montant_paiement FROM users WHERE id=?",
                                   (enseignant_id,)).fetchone()

                type_p = ens['type_paiement'] if ens['type_paiement'] else 'Mensuel'
                taux = float(ens['montant_paiement'] or 0)

                if type_p.lower() in ['mensuel', 'mois']:
                    montant_total = taux
                    unites_validees = 1
                else:
                    montant_total = taux * unites
                    unites_validees = unites

                cur = conn.execute(
                    """INSERT INTO paiements_enseignants
                       (enseignant_id, mois, montant_total, montant_paye, type_paiement, unites_validees, statut)
                       VALUES (?, ?, ?, ?, ?, ?, 'non_paye')""",
                    (enseignant_id, mois, montant_total, 0, type_p, unites_validees)
                )
                nom_ens = conn.execute("SELECT prenom||' '||nom as nom FROM users WHERE id=?",
                                       (enseignant_id,)).fetchone()
                log_action(conn, 'creation', 'paiement_enseignant', cur.lastrowid,
                           f"Facture paie générée pour {nom_ens['nom'] if nom_ens else enseignant_id} — {mois} — {montant_total:.2f} MAD")
                conn.commit()
                flash('Facture enseignant générée avec succès (Non payée) !', 'success')

            # --- ADAPTATION : Mise à jour du paiement d'une facture enseignant existante ---
            elif action == 'update_enseignant':
                pid = f['paiement_id']
                mp = float(f.get('montant_paye', 0))

                mt_row = conn.execute("SELECT montant_total FROM paiements_enseignants WHERE id=?", (pid,)).fetchone()
                if mt_row:
                    mt = float(mt_row[0])
                    statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')

                    conn.execute(
                        "UPDATE paiements_enseignants SET montant_paye=?, statut=?, date_paiement=CURRENT_TIMESTAMP WHERE id=?",
                        (mp, statut, pid))
                    log_action(conn, 'modification', 'paiement_enseignant', pid,
                               f"Montant payé mis à jour : {mp:.2f} MAD (statut: {statut})")
                    conn.commit()
                    flash('Paiement enseignant mis à jour !', 'success')

            # --- Code d'origine pour les élèves ---
            elif action == 'add':
                categorie = f.get('categorie', 'Autre')
                note = f.get('note', '')
                description = f"[{categorie}] {note}".strip()

                montant_total_add = float(f['montant_total'] or 0)
                montant_paye_add = float(f.get('montant_paye', 0) or 0)
                # 🆕 Part transport de la facture (uniquement renseignée pour "Scolarité" quand
                # l'élève est abonné au transport — voir plus bas). Stockée à part dans la
                # colonne dédiée pour rester cohérente avec la génération automatique des
                # mensualités et permettre au reçu de séparer les deux postes.
                montant_transport_add = 0.0

                # 🆕 Réduction manuelle propre à la facture "Frais d'inscription" : saisie
                # directement sur ce formulaire (indépendante de la réduction scolarité de
                # l'élève, qui garde sa logique d'origine sur les mensualités).
                reduction_appliquee_add = 0.0
                if categorie == "Frais d'inscription":
                    try:
                        reduction_pct_add = float(f.get('reduction_inscription_pourcentage') or 0)
                    except ValueError:
                        reduction_pct_add = 0
                    reduction_pct_add = max(0, min(100, reduction_pct_add))
                    if reduction_pct_add > 0:
                        reduction_appliquee_add = round(montant_total_add * (reduction_pct_add / 100), 2)
                        montant_total_add = round(montant_total_add - reduction_appliquee_add, 2)
                        description += f" (Réduction {reduction_pct_add:g}% appliquée)"

                # 🆕 CORRECTIF : pour une facture "Scolarité" créée manuellement ici, on
                # applique automatiquement la réduction scolarité déjà configurée sur la
                # fiche de l'élève (reduction_pourcentage / reduction_validite, définies à
                # l'inscription ou modifiées ensuite) — exactement comme le fait la
                # génération automatique mensuelle (_generer_mensualites_cycle). Sans ce
                # correctif, la réduction de l'élève n'était appliquée que sur les
                # mensualités générées en masse, pas sur une facture "Scolarité" ajoutée
                # manuellement via ce formulaire.
                #
                # 🆕 Et si l'élève est abonné au transport, son frais de transport (avec sa
                # propre réduction transport indépendante) est automatiquement ajouté à cette
                # même facture "Scolarité" — exactement comme la mensualité auto-générée
                # combine les deux postes — au lieu de laisser l'élève facturé sans son
                # transport ou d'obliger à créer une 2ᵉ facture séparée.
                elif categorie == 'Scolarité':
                    eleve_reduc = conn.execute(
                        "SELECT reduction_pourcentage, reduction_validite, transport_abonne, "
                        "montant_transport, reduction_transport_pourcentage, reduction_transport_validite "
                        "FROM eleves WHERE id=?", (f['eleve_id'],)).fetchone()
                    mois_ref = (f.get('date_echeance') or datetime.datetime.now().strftime('%Y-%m-%d'))[:7]
                    scolarite_montant = montant_total_add
                    libelles_reduction_scol = []
                    if eleve_reduc:
                        reduction_pct_scol = float(eleve_reduc['reduction_pourcentage'] or 0)
                        if reduction_pct_scol > 0 and _reduction_est_valide(mois_ref):
                            reduction_appliquee_add = round(scolarite_montant * (reduction_pct_scol / 100), 2)
                            scolarite_montant = round(scolarite_montant - reduction_appliquee_add, 2)
                            libelles_reduction_scol.append(f"{reduction_pct_scol:g}% sur la mensualité")

                        if eleve_reduc['transport_abonne'] == 'oui':
                            montant_transport_add = float(eleve_reduc['montant_transport'] or 0)
                            reduction_pct_trans = float(eleve_reduc['reduction_transport_pourcentage'] or 0)
                            if montant_transport_add > 0 and reduction_pct_trans > 0 and \
                               _reduction_est_valide(mois_ref):
                                reduction_transport_add = round(montant_transport_add * (reduction_pct_trans / 100), 2)
                                montant_transport_add = round(montant_transport_add - reduction_transport_add, 2)
                                reduction_appliquee_add = round(reduction_appliquee_add + reduction_transport_add, 2)
                                libelles_reduction_scol.append(f"{reduction_pct_trans:g}% sur le transport")

                    montant_total_add = round(scolarite_montant + montant_transport_add, 2)
                    if montant_transport_add > 0:
                        description = description.replace('[Scolarité]', '[Scolarité + Transport]', 1)
                    if libelles_reduction_scol:
                        description += f" (Réduction {' + '.join(libelles_reduction_scol)})"

                # 🩹 FIX : le statut était pris tel quel du formulaire (souvent laissé sur
                # "Non payé" par défaut même quand un montant payé était saisi), ce qui faisait
                # apparaître le badge en rouge malgré un paiement complet — notamment pour les
                # "Frais d'inscription". On calcule désormais le statut à partir des montants
                # (une fois la réduction éventuelle déduite), exactement comme le fait l'action
                # "update" pour les mensualités générées.
                statut_add = 'paye' if montant_paye_add >= montant_total_add and montant_total_add > 0 \
                    else ('partiel' if montant_paye_add > 0 else 'non_paye')

                # 🆕 Si la facture est créée déjà partiellement ou totalement réglée, on
                # renseigne tout de suite la date de paiement (date du jour), sinon le reçu
                # affiche "—" en Date de paiement malgré un statut payé/partiel.
                date_paiement_add = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S') \
                    if statut_add in ('partiel', 'paye') else None

                cur = conn.execute(
                    "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut,reduction_appliquee,date_paiement,montant_transport) VALUES (?,?,?,?,?,?,?,?,?)",
                    (f['eleve_id'], montant_total_add, montant_paye_add, description, f.get('date_echeance'),
                     statut_add, reduction_appliquee_add, date_paiement_add, montant_transport_add))
                eleve_nom = conn.execute("SELECT prenom||' '||nom as nom FROM eleves WHERE id=?",
                                         (f['eleve_id'],)).fetchone()
                log_action(conn, 'creation', 'paiement', cur.lastrowid,
                           f"Facturation {eleve_nom['nom'] if eleve_nom else f['eleve_id']} — {description} — {montant_total_add:.2f} MAD")
                conn.commit()
                flash('Paiement mis à jour !', 'success')

            elif action == 'update':
                pid = f['paiement_id']
                mp = float(f.get('montant_paye', 0))
                mt = float(conn.execute("SELECT montant_total FROM paiements WHERE id=?", (pid,)).fetchone()[0])
                statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')
                conn.execute("UPDATE paiements SET montant_paye=?,statut=?,date_paiement=CURRENT_TIMESTAMP WHERE id=?",
                             (mp, statut, pid))
                if statut == 'paye':
                    eleve = conn.execute(
                        "SELECT e.parent_id, e.prenom||' '||e.nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
                        (pid,)).fetchone()
                    if eleve:
                        notif_to_parent(eleve['parent_id'], f"Paiement confirmé pour {eleve['nom']}. Merci!", conn)

                eleve_info = conn.execute(
                    "SELECT e.prenom||' '||e.nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
                    (pid,)).fetchone()
                log_action(conn, 'modification', 'paiement', pid,
                           f"Montant payé mis à jour : {mp:.2f} MAD (statut: {statut}) — {eleve_info['nom'] if eleve_info else ''}")

                conn.commit()
                flash('Paiement mis à jour !', 'success')

        if session['role'] == 'parent':
            return redirect(url_for('paiements'))
        else:
            return redirect(url_for('paiements', cycle=cycle))

    # --- CODE MÉTHODE GET ---
    cycle_filter = request.args.get('cycle')

    # 🆕 AGENT ADMIN : ne peut pas consulter l'onglet Enseignants (paiement enseignant)
    if session['role'] == 'agent_admin' and cycle_filter == 'Enseignants':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements'))

    if session['role'] in ('admin', 'agent_admin') and not cycle_filter:
        # =========================================================
        # ANALYSE GLOBALE : CHARGE ÉLÈVE vs CHARGE ÉCOLE
        # =========================================================

        # 🆕 FILTRAGE AVANCÉ DU HUB : période (mois début/fin), cycle (côté Charge Élève),
        # type de dépense (côté Charge École). Tout est optionnel (par défaut = aucun filtre = vue globale).
        hub_mois_debut = request.args.get('hub_mois_debut', '').strip()   # format YYYY-MM
        hub_mois_fin = request.args.get('hub_mois_fin', '').strip()      # format YYYY-MM
        hub_cycle_eleve = request.args.get('hub_cycle_eleve', '').strip()  # '', Maternelle, Primaire, College
        hub_type_ecole = request.args.get('hub_type_ecole', '').strip()   # '', enseignants, personnel, charges

        analyse_globale = calculer_analyse_globale(conn, hub_mois_debut, hub_mois_fin, hub_cycle_eleve, hub_type_ecole)

        conn.close()
        # On passe le dictionnaire 'analyse' + les filtres actifs au template
        return render_template_string(PAIEMENTS_HUB_HTML, analyse=analyse_globale, notif_count=get_notif_count(),
                                      hub_mois_debut=hub_mois_debut, hub_mois_fin=hub_mois_fin,
                                      hub_cycle_eleve=hub_cycle_eleve, hub_type_ecole=hub_type_ecole)

    status_filter = request.args.get('statut', '')
    mois_filter = request.args.get('mois', '')
    search_filter = request.args.get('q', '').strip()
    classe_filter = request.args.get('classe_id', '')
    categorie_filter = request.args.get('categorie_filter', '')
    date_debut = request.args.get('date_debut', '')
    date_fin = request.args.get('date_fin', '')
    tri = request.args.get('tri', 'recent')
    montant_min_raw = request.args.get('montant_min', '')
    montant_max_raw = request.args.get('montant_max', '')

    def _parse_montant(val):
        try:
            return float(val) if val not in (None, '') else None
        except ValueError:
            return None

    montant_min = _parse_montant(montant_min_raw)
    montant_max = _parse_montant(montant_max_raw)

    # 1. Préparation des requêtes pour les ÉLÈVES
    params_eleves = []
    where_clauses_eleves = []

    if session['role'] == 'parent':
        where_clauses_eleves.append("e.parent_id=?")
        params_eleves.append(session['user_id'])
    else:
        if cycle_filter != 'Global' and cycle_filter != 'Enseignants':
            where_clauses_eleves.append("(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))")
            params_eleves.extend([cycle_filter, cycle_filter])

    if status_filter:
        where_clauses_eleves.append("p.statut=?")
        params_eleves.append(status_filter)
    if mois_filter:
        where_clauses_eleves.append("strftime('%Y-%m', p.date_echeance) = ?")
        params_eleves.append(mois_filter)
    # --- FILTRAGE AVANCÉ : recherche, classe, catégorie, montant, période ---
    if search_filter:
        where_clauses_eleves.append("(e.nom LIKE ? OR e.prenom LIKE ? OR (e.prenom || ' ' || e.nom) LIKE ?)")
        like_term = f"%{search_filter}%"
        params_eleves.extend([like_term, like_term, like_term])
    if classe_filter:
        where_clauses_eleves.append("c.id=?")
        params_eleves.append(classe_filter)
    if categorie_filter:
        where_clauses_eleves.append("p.description LIKE ?")
        params_eleves.append(f"[{categorie_filter}]%")
    if montant_min is not None:
        where_clauses_eleves.append("p.montant_total >= ?")
        params_eleves.append(montant_min)
    if montant_max is not None:
        where_clauses_eleves.append("p.montant_total <= ?")
        params_eleves.append(montant_max)
    if date_debut:
        where_clauses_eleves.append("p.date_echeance >= ?")
        params_eleves.append(date_debut)
    if date_fin:
        where_clauses_eleves.append("p.date_echeance <= ?")
        params_eleves.append(date_fin)

    where_sql_eleves = "WHERE " + " AND ".join(where_clauses_eleves) if where_clauses_eleves else ""

    ORDER_MAP_ELEVES = {
        'recent': 'p.created_at DESC',
        'ancien': 'p.created_at ASC',
        'montant_desc': 'p.montant_total DESC',
        'montant_asc': 'p.montant_total ASC',
        'nom_asc': 'e.nom ASC, e.prenom ASC',
        'echeance': 'p.date_echeance ASC',
    }
    order_sql_eleves = ORDER_MAP_ELEVES.get(tri, 'p.created_at DESC')

    query_eleves = """
        SELECT p.*, e.prenom||' '||e.nom as eleve, c.nom as classe, e.parent_id as parent_id
        FROM paiements p 
        JOIN eleves e ON p.eleve_id=e.id 
        LEFT JOIN classes c ON e.classe_id=c.id 
    """ + where_sql_eleves + " ORDER BY " + order_sql_eleves

    paiements_list = conn.execute(query_eleves, params_eleves).fetchall()

    # 2. Préparation des requêtes pour les ENSEIGNANTS
    enseignants_list = []
    paiements_profs_list = []
    where_clauses_profs = []
    params_profs = []
    where_sql_profs = ""

    if session['role'] == 'admin':
        # 🆕 En plus des enseignants, on inclut ici le personnel administratif payé via ce même
        # système (agent_admin, secrétaire) : ils peuvent désormais aussi avoir un salaire
        # configuré sur leur fiche utilisateur (voir /utilisateurs) et être payés depuis cette page.
        enseignants_list = conn.execute(
            "SELECT id, prenom || ' ' || nom as nom, type_paiement, role FROM users "
            "WHERE role IN ('enseignant','agent_admin','secretaire') ORDER BY nom"
        ).fetchall()

        # Ajout des filtres spécifiques aux enseignants
        if status_filter:
            where_clauses_profs.append("p.statut=?")
            params_profs.append(status_filter)
        if mois_filter:
            where_clauses_profs.append("p.mois=?")
            params_profs.append(mois_filter)
        if search_filter:
            where_clauses_profs.append("(u.nom LIKE ? OR u.prenom LIKE ? OR (u.prenom || ' ' || u.nom) LIKE ?)")
            like_term = f"%{search_filter}%"
            params_profs.extend([like_term, like_term, like_term])
        if montant_min is not None:
            where_clauses_profs.append("p.montant_total >= ?")
            params_profs.append(montant_min)
        if montant_max is not None:
            where_clauses_profs.append("p.montant_total <= ?")
            params_profs.append(montant_max)
        if date_debut:
            where_clauses_profs.append("p.date_paiement >= ?")
            params_profs.append(date_debut)
        if date_fin:
            where_clauses_profs.append("p.date_paiement <= ?")
            params_profs.append(date_fin)

        where_sql_profs = "WHERE " + " AND ".join(where_clauses_profs) if where_clauses_profs else ""

        ORDER_MAP_PROFS = {
            'recent': 'p.id DESC',
            'ancien': 'p.id ASC',
            'montant_desc': 'p.montant_total DESC',
            'montant_asc': 'p.montant_total ASC',
            'nom_asc': 'u.nom ASC, u.prenom ASC',
            'echeance': 'p.date_paiement ASC',
        }
        order_sql_profs = ORDER_MAP_PROFS.get(tri, 'p.id DESC')

        query_profs = """
            SELECT p.*, u.prenom || ' ' || u.nom as enseignant 
            FROM paiements_enseignants p 
            JOIN users u ON p.enseignant_id = u.id 
        """ + where_sql_profs + " ORDER BY " + order_sql_profs

        paiements_profs_list = conn.execute(query_profs, params_profs).fetchall()

    # 3. Liste des élèves pour le formulaire (Admin uniquement)
    if session['role'] == 'parent' or cycle_filter == 'Global' or cycle_filter == 'Enseignants':
        eleves_list = []
    else:
        eleves_list = conn.execute("""
                                   SELECT e.id, e.prenom || ' ' || e.nom as nom, c.id as classe_id
                                   FROM eleves e
                                            JOIN classes c ON e.classe_id = c.id
                                   WHERE c.cycle = ?
                                      OR (c.cycle IS NULL AND ? = 'Primaire')
                                   ORDER BY e.nom
                                   """, (cycle_filter, cycle_filter)).fetchall()

    # 3bis. Liste des classes pour le menu déroulant du filtre avancé
    if cycle_filter == 'Enseignants':
        classes_cycle = []
    elif session['role'] == 'parent':
        classes_cycle = conn.execute("""
            SELECT DISTINCT c.id, c.nom
            FROM classes c
            JOIN eleves e ON e.classe_id = c.id
            WHERE e.parent_id=?
            ORDER BY c.nom
        """, (session['user_id'],)).fetchall()
    elif cycle_filter == 'Global':
        classes_cycle = conn.execute("SELECT id, nom, cycle FROM classes ORDER BY cycle, nom").fetchall()
    else:
        classes_cycle = conn.execute("""
            SELECT id, nom FROM classes
            WHERE cycle = ? OR (cycle IS NULL AND ? = 'Primaire')
            ORDER BY nom
        """, (cycle_filter, cycle_filter)).fetchall()

    # --- CORRECTION DES COMPTEURS : SÉPARATION INTELLIGENTE ---
    if cycle_filter == 'Enseignants':
        # On calcule les totaux en regardant la table paiements_enseignants
        query_totals = """
                       SELECT SUM(p.montant_total) as total, SUM(p.montant_paye) as paye
                       FROM paiements_enseignants p
                                JOIN users u ON p.enseignant_id = u.id
                       """ + where_sql_profs
        raw_totals = conn.execute(query_totals, params_profs).fetchone()
    else:
        # On calcule les totaux en regardant la table paiements (élèves)
        # 🆕 On ajoute au passage le total du transport facturé et le cumul des réductions appliquées
        query_totals = """
                       SELECT SUM(p.montant_total) as total, SUM(p.montant_paye) as paye,
                              SUM(p.montant_transport) as transport, SUM(p.reduction_appliquee) as reduction
                       FROM paiements p
                                JOIN eleves e ON p.eleve_id = e.id
                                LEFT JOIN classes c ON e.classe_id = c.id \
                       """ + where_sql_eleves
        raw_totals = conn.execute(query_totals, params_eleves).fetchone()

    # Sécurisation des valeurs
    total_du = raw_totals['total'] if raw_totals and raw_totals['total'] else 0
    total_paye = raw_totals['paye'] if raw_totals and raw_totals['paye'] else 0
    reste_a_verser = total_du - total_paye
    # 🆕 Le transport/réduction n'existent que côté élèves (pas pour l'onglet Enseignants)
    total_transport = 0
    total_reduction = 0
    if cycle_filter != 'Enseignants':
        try:
            total_transport = raw_totals['transport'] if raw_totals and raw_totals['transport'] else 0
            total_reduction = raw_totals['reduction'] if raw_totals and raw_totals['reduction'] else 0
        except (IndexError, KeyError):
            total_transport = 0
            total_reduction = 0

    totals_dict = {
        'total': total_du,
        'paye': total_paye,
        'reste': reste_a_verser,
        'transport': total_transport,
        'reduction': total_reduction
    }

    # 🆕 BADGE DE PONCTUALITÉ PAR PARENT — affiché directement dans le tableau des paiements
    # (colonne dédiée) et sur le profil du parent. Calculé une seule fois par parent unique
    # présent dans la liste affichée (pas de recalcul par ligne).
    parent_badges = {}
    if cycle_filter != 'Enseignants':
        seuil_bloque = get_seuil_compte_bloque(conn)
        parent_ids_uniques = {row['parent_id'] for row in paiements_list if row['parent_id']}
        for pid in parent_ids_uniques:
            indic_p = _indicateurs_paiement_parent(conn, pid)
            parent_badges[pid] = _badge_paiement_parent(indic_p, seuil_bloque)

    conn.close()

    # 🆕 TABLEAU REGROUPÉ PAR ÉLÈVE : au lieu d'une ligne par facture (l'élève apparaissait
    # donc plusieurs fois dans le tableau), on construit ici les lignes envoyées à la grille
    # (AG Grid) en Python : UNE seule ligne "élève" avec le montant cumulé de TOUTES ses
    # factures (scolarité, transport, frais d'inscription, etc.), et une flèche pour déplier
    # le détail facture par facture — même principe que le détail scolarité/transport déjà
    # existant sur chaque facture. Le côté "Enseignants" garde son ancien comportement
    # (une ligne par bulletin de paie, pas de regroupement).
    rows_data = []
    if cycle_filter == 'Enseignants':
        for p in paiements_profs_list:
            desc = (p['type_paiement'] or '').capitalize()
            if p['type_paiement'] and p['type_paiement'].lower() != 'mensuel' and p['unites_validees']:
                desc += f" (Unités : {p['unites_validees']})"
            solde = (p['montant_total'] or 0) - (p['montant_paye'] or 0)
            rows_data.append({
                'refId': p['id'], 'nom': p['enseignant'] or '', 'sub': p['mois'] or '',
                'categorie': (p['type_paiement'] or '').capitalize(), 'description': desc,
                'echeance': p['date_paiement'] or '', 'total': p['montant_total'] or 0,
                'paye': p['montant_paye'] or 0, 'solde': solde, 'transport': 0,
                'statut': p['statut'], 'badgeEmoji': '', 'badgeLabel': '', 'parentId': None,
                'canReceipt': False, 'canBulletin': (p['statut'] == 'paye'),
                'canUpdate': (session['role'] in ('admin', 'agent_admin') and p['statut'] != 'paye'),
            })
    else:
        groupes = {}
        ordre_eleves = []
        for p in paiements_list:
            cat = (p['description'].split(']')[0].lstrip('[')
                   if (p['description'] and ']' in p['description']) else 'Autre')
            desc = (p['description'].split('] ')[1]
                    if (p['description'] and ']' in p['description']) else (p['description'] or ''))
            solde = (p['montant_total'] or 0) - (p['montant_paye'] or 0)
            badge = parent_badges.get(p['parent_id']) if p['parent_id'] else None
            eleve_id = p['eleve_id']

            child = {
                'refId': p['id'], 'nom': p['eleve'] or '', 'sub': p['classe'] or 'Non assignée',
                'categorie': cat, 'description': desc, 'echeance': p['date_echeance'] or '',
                'total': p['montant_total'] or 0, 'paye': p['montant_paye'] or 0, 'solde': solde,
                'transport': p['montant_transport'] or 0, 'statut': p['statut'],
                'badgeEmoji': (badge['emoji'] if badge else ''), 'badgeLabel': (badge['label'] if badge else ''),
                'parentId': p['parent_id'], 'canReceipt': True, 'canBulletin': False,
                'canUpdate': (session['role'] in ('admin', 'agent_admin') and p['statut'] != 'paye'),
                'isChildRow': True, 'parentEleveId': eleve_id,
            }

            if eleve_id not in groupes:
                ordre_eleves.append(eleve_id)
                groupes[eleve_id] = {
                    'refId': f'grp-{eleve_id}', 'nom': p['eleve'] or '', 'sub': p['classe'] or 'Non assignée',
                    'categorie': '', 'description': '', 'echeance': '',
                    'total': 0, 'paye': 0, 'solde': 0, 'transport': 0,
                    'statut': 'paye', 'badgeEmoji': (badge['emoji'] if badge else ''),
                    'badgeLabel': (badge['label'] if badge else ''), 'parentId': p['parent_id'],
                    'canReceipt': False, 'canBulletin': False, 'canUpdate': False,
                    'isGroupRow': True, 'groupEleveId': eleve_id, 'nbFactures': 0,
                    '_children': [],
                }
            g = groupes[eleve_id]
            g['total'] += child['total']
            g['paye'] += child['paye']
            g['solde'] += child['solde']
            g['transport'] += child['transport']
            g['nbFactures'] += 1
            g['_children'].append(child)

        for eleve_id in ordre_eleves:
            g = groupes[eleve_id]
            statuts_enfants = {c['statut'] for c in g['_children']}
            if statuts_enfants == {'paye'}:
                g['statut'] = 'paye'
            elif statuts_enfants == {'non_paye'}:
                g['statut'] = 'non_paye'
            else:
                g['statut'] = 'partiel'
            children = g.pop('_children')
            rows_data.append(g)
            rows_data.extend(children)

    return render_template_string(PAIEMENTS_HTML,
                                  rows_data=rows_data,
                                  paiements=paiements_list,
                                  eleves=eleves_list,
                                  enseignants=enseignants_list,
                                  paiements_profs=paiements_profs_list,
                                  classes_cycle=classes_cycle,
                                  status_filter=status_filter,
                                  mois_filter=mois_filter,
                                  search_filter=search_filter,
                                  classe_filter=classe_filter,
                                  categorie_filter=categorie_filter,
                                  date_debut=date_debut,
                                  date_fin=date_fin,
                                  tri=tri,
                                  montant_min_raw=montant_min_raw,
                                  montant_max_raw=montant_max_raw,
                                  totals=totals_dict,
                                  cycle=cycle_filter,
                                  parent_badges=parent_badges,
                                  notif_count=get_notif_count())


@app.route('/paiements/charges', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def gestion_charges():
    conn = get_db()
    # 🆕 AGENT ADMIN : accès à la page des charges, mais restreint à ses propres charges
    # (ajoutées par lui) — voir plus bas pour le filtrage de la liste et le masquage des totaux.
    est_agent_admin = session.get('role') == 'agent_admin'

    if request.method == 'POST':
        action = request.form.get('action')

        # 🔒 Un agent-admin ne peut agir (supprimer / changer le statut) que sur une charge
        # qu'il a lui-même ajoutée.
        def _charge_accessible(charge_id):
            if not est_agent_admin:
                return True
            row = conn.execute("SELECT ajoute_par_id FROM charges WHERE id=?", (charge_id,)).fetchone()
            return bool(row) and row['ajoute_par_id'] == session['user_id']

        if action == 'add':
            date_facture = request.form.get('date_facture')
            categorie = request.form.get('categorie')

            # Gestion de la catégorie personnalisée
            if categorie == 'Autre':
                categorie = request.form.get('autre_categorie', 'Autre')

            responsable = request.form.get('responsable')
            montant = float(request.form.get('montant', 0))
            statut = request.form.get('statut', 'non_paye')
            # 🆕 Précision du sous-type de la charge (ex: pour "Fournitures de bureau" :
            # "Stylos", "Feuilles A4"...) — champ libre, facultatif.
            sous_categorie = request.form.get('sous_categorie', '').strip()

            # 🆕 Si la charge concerne le gasoil, on la rattache au chauffeur concerné
            # (pour pouvoir afficher son historique de gasoil sur sa fiche).
            chauffeur_id = request.form.get('chauffeur_id') or None
            if categorie != 'Gasoil (Transport)':
                chauffeur_id = None

            conn.execute("""
                         INSERT INTO charges (date_facture, categorie, sous_categorie, responsable, montant, statut, chauffeur_id, ajoute_par_id)
                         VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                         """, (date_facture, categorie, sous_categorie, responsable, montant, statut, chauffeur_id, session['user_id']))
            conn.commit()
            flash('Nouvelle charge ajoutée avec succès !', 'success')

        elif action == 'delete':
            charge_id = request.form.get('charge_id')
            if not _charge_accessible(charge_id):
                flash('Accès non autorisé.', 'error')
            else:
                conn.execute("DELETE FROM charges WHERE id=?", (charge_id,))
                conn.commit()
                flash('Charge supprimée !', 'success')

        elif action == 'update_statut':
            charge_id = request.form.get('charge_id')
            statut = request.form.get('statut')
            if not _charge_accessible(charge_id):
                flash('Accès non autorisé.', 'error')
            else:
                conn.execute("UPDATE charges SET statut=? WHERE id=?", (statut, charge_id))
                conn.commit()
                flash('Statut de la charge mis à jour !', 'success')

        return redirect(url_for('gestion_charges'))

    # Pour la méthode GET : récupérer les charges avec filtrage avancé
    search_filter = request.args.get('q', '').strip()
    categorie_filter = request.args.get('categorie_filter', '')
    statut_filter = request.args.get('statut_filter', '')
    date_debut = request.args.get('date_debut', '')
    date_fin = request.args.get('date_fin', '')
    tri = request.args.get('tri', 'recent')
    montant_min_raw = request.args.get('montant_min', '')
    montant_max_raw = request.args.get('montant_max', '')

    def _parse_montant(val):
        try:
            return float(val) if val not in (None, '') else None
        except ValueError:
            return None

    montant_min = _parse_montant(montant_min_raw)
    montant_max = _parse_montant(montant_max_raw)

    where_clauses = []
    params = []

    # 🆕 AGENT ADMIN : ne voit que les charges qu'il a lui-même ajoutées (l'admin voit tout).
    if est_agent_admin:
        where_clauses.append("ajoute_par_id = ?")
        params.append(session['user_id'])

    if search_filter:
        like_term = f"%{search_filter}%"
        where_clauses.append("(responsable LIKE ? OR categorie LIKE ?)")
        params.extend([like_term, like_term])
    if categorie_filter:
        where_clauses.append("categorie = ?")
        params.append(categorie_filter)
    if statut_filter:
        where_clauses.append("statut = ?")
        params.append(statut_filter)
    if date_debut:
        where_clauses.append("date_facture >= ?")
        params.append(date_debut)
    if date_fin:
        where_clauses.append("date_facture <= ?")
        params.append(date_fin)
    if montant_min is not None:
        where_clauses.append("montant >= ?")
        params.append(montant_min)
    if montant_max is not None:
        where_clauses.append("montant <= ?")
        params.append(montant_max)

    where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

    ORDER_MAP_CHARGES = {
        'recent': 'date_facture DESC, id DESC',
        'ancien': 'date_facture ASC, id ASC',
        'montant_desc': 'montant DESC',
        'montant_asc': 'montant ASC',
        'categorie': 'categorie ASC, date_facture DESC',
    }
    order_sql = ORDER_MAP_CHARGES.get(tri, 'date_facture DESC, id DESC')

    charges = conn.execute(
        f"SELECT * FROM charges {where_sql} ORDER BY {order_sql}", params
    ).fetchall()

    # Catégories réellement présentes en base (pour le menu déroulant du filtre)
    categories_existantes = conn.execute(
        "SELECT DISTINCT categorie FROM charges ORDER BY categorie"
    ).fetchall()

    # 🆕 AGENT ADMIN : ne doit connaître aucun total/somme sur cette page (même sur ses
    # propres charges) — seul l'admin voit les totaux agrégés.
    if est_agent_admin:
        total_charges = None
        total_filtre = None
        paye_filtre = None
        reste_filtre = None
    else:
        # Calcul du total global des charges payées (statistique générale, non filtrée)
        total_row = conn.execute("SELECT SUM(montant) as total FROM charges WHERE statut='paye'").fetchone()
        total_charges = total_row['total'] if total_row and total_row['total'] else 0

        # Statistiques sur les résultats actuellement filtrés
        filtres_stats = conn.execute(
            f"""SELECT SUM(montant) as total,
                       SUM(CASE WHEN statut='paye' THEN montant ELSE 0 END) as paye
                FROM charges {where_sql}""", params
        ).fetchone()
        total_filtre = filtres_stats['total'] if filtres_stats and filtres_stats['total'] else 0
        paye_filtre = filtres_stats['paye'] if filtres_stats and filtres_stats['paye'] else 0
        reste_filtre = total_filtre - paye_filtre

    # 🆕 Liste des chauffeurs, pour le sélecteur affiché quand la catégorie = "Gasoil (Transport)"
    chauffeurs_dispo = conn.execute(
        "SELECT id, nom, prenom FROM personnel_hors_prof WHERE mission='Chauffeur' ORDER BY nom, prenom"
    ).fetchall()

    conn.close()

    return render_template_string(CHARGES_HTML,
                                  charges=charges,
                                  total_charges=total_charges,
                                  total_filtre=total_filtre,
                                  paye_filtre=paye_filtre,
                                  reste_filtre=reste_filtre,
                                  masquer_totaux=est_agent_admin,
                                  categories_existantes=categories_existantes,
                                  chauffeurs_dispo=chauffeurs_dispo,
                                  search_filter=search_filter,
                                  categorie_filter=categorie_filter,
                                  statut_filter=statut_filter,
                                  date_debut=date_debut,
                                  date_fin=date_fin,
                                  tri=tri,
                                  montant_min_raw=montant_min_raw,
                                  montant_max_raw=montant_max_raw,
                                  notif_count=get_notif_count())


@app.route('/paiements/enseignants', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def paiements_enseignants():
    # 🆕 AGENT ADMIN : pas d'accès aux paiements des enseignants
    if session.get('role') == 'agent_admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements'))

    conn = get_db()

    if request.method == 'POST':
        action = request.form.get('action')

        # GÉNÉRATION AUTOMATIQUE DU SALAIRE
        if action == 'generer':
            enseignant_id = request.form.get('enseignant_id')
            mois = request.form.get('mois')
            unites = request.form.get('unites', 0)  # Représente le nombre d'heures ou de séances saisies

            if not enseignant_id or not mois:
                flash('Veuillez sélectionner un enseignant et un mois.', 'error')
                return redirect(url_for('paiements_enseignants'))

            # Récupération du profil de l'enseignant
            ens = conn.execute("SELECT type_paiement, montant_paiement FROM users WHERE id=?",
                               (enseignant_id,)).fetchone()

            type_p = ens['type_paiement'] or 'Mensuel'
            taux = ens['montant_paiement'] or 0

            # Calcul automatique selon le type
            if type_p.lower() == 'mensuel':
                montant_total = taux
                unites_val = 1
            else:  # Pour 'Heure' ou 'Séance'
                unites_val = float(unites) if unites else 0
                montant_total = taux * unites_val

            # Création de la facture avec statut 'non_paye' par défaut
            conn.execute("""
                         INSERT INTO paiements_enseignants
                         (enseignant_id, mois, montant_total, montant_paye, type_paiement, unites_validees, statut)
                         VALUES (?, ?, ?, 0, ?, ?, 'non_paye')
                         """, (enseignant_id, mois, montant_total, type_p, unites_val))
            conn.commit()
            flash('Fiche de paie générée avec succès ! (Statut: Non payé)', 'success')

        # MARQUER COMME PAYÉ
        elif action == 'payer':
            paiement_id = request.form.get('paiement_id')
            conn.execute("""
                         UPDATE paiements_enseignants
                         SET statut='paye',
                             montant_paye=montant_total,
                             date_paiement=CURRENT_DATE
                         WHERE id = ?
                         """, (paiement_id,))
            conn.commit()
            flash('Paiement validé !', 'success')

        # SUPPRIMER UNE FACTURE
        elif action == 'delete':
            paiement_id = request.form.get('paiement_id')
            conn.execute("DELETE FROM paiements_enseignants WHERE id=?", (paiement_id,))
            conn.commit()
            flash('Fiche de paie supprimée.', 'success')

        conn.close()
        return redirect(url_for('paiements_enseignants'))

    # MÉTHODE GET : Affichage de la page
    # 🆕 En plus des enseignants, on inclut ici le personnel administratif payé via ce même
    # système (agent_admin, secrétaire) : voir aussi /utilisateurs pour la saisie de leur salaire.
    enseignants = conn.execute(
        "SELECT id, nom, prenom, type_paiement, montant_paiement, role FROM users "
        "WHERE role IN ('enseignant','agent_admin','secretaire') ORDER BY nom").fetchall()

    paiements = conn.execute("""
                             SELECT p.*, u.nom, u.prenom
                             FROM paiements_enseignants p
                                      JOIN users u ON p.enseignant_id = u.id
                             ORDER BY p.id DESC
                             """).fetchall()

    # --- AJOUT POUR LES COMPTEURS ---
    raw_totals = conn.execute(
        "SELECT SUM(montant_total) as total, SUM(montant_paye) as paye FROM paiements_enseignants").fetchone()

    total_du = raw_totals['total'] if raw_totals and raw_totals['total'] else 0
    total_paye = raw_totals['paye'] if raw_totals and raw_totals['paye'] else 0
    reste_a_verser = total_du - total_paye

    totals_dict = {
        'total': total_du,
        'paye': total_paye,
        'reste': reste_a_verser
    }
    # --------------------------------

    conn.close()

    # --- ADAPTATION DU TEMPLATE ---
    return render_template_string(PAIEMENTS_HTML,
                                  enseignants=enseignants,
                                  paiements_profs=paiements,  # Modifié pour correspondre à votre HTML
                                  cycle='Enseignants',  # Modifié pour correspondre à votre HTML
                                  totals=totals_dict,  # Ajout du dictionnaire des compteurs
                                  parent_badges={},
                                  notif_count=get_notif_count())


JOUR_ECHEANCE_MAX = 1  # 🆕 Règle de l'école : la facture doit être réglée le 1er du mois (référence pour le calcul des jours de retard)


def _reduction_est_valide(mois):
    """🆕 Logique automatique : une réduction (scolarité ou transport) suit l'année scolaire —
    elle s'applique de septembre (mois 09) à juillet de l'année suivante (mois 07) inclus,
    et ne s'applique jamais au mois d'août (vacances, hors année scolaire). Plus besoin de
    saisir manuellement une date de fin de validité : dès qu'un pourcentage de réduction est
    configuré sur la fiche élève, il est reconduit automatiquement chaque année scolaire."""
    try:
        m = int(str(mois)[5:7])
    except (TypeError, ValueError, IndexError):
        return True
    return m != 8


def _generer_mensualites_cycle(conn, cycle, mois, montant_base=800):
    """Génère les factures (mensualités) du mois donné pour tous les élèves d'un cycle.
    Réutilisée par la génération manuelle (route /paiements/generer) ET par la génération
    automatique programmée en début de mois. Idempotente : ne recrée pas une facture déjà
    existante pour le même élève / le même mois."""
    query = """
            SELECT e.id, e.montant_mensualite, e.transport_abonne, e.montant_transport,
                   e.reduction_pourcentage, e.reduction_validite,
                   e.reduction_transport_pourcentage, e.reduction_transport_validite
            FROM eleves e
                     JOIN classes c ON e.classe_id = c.id
            WHERE (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
            """
    eleves = conn.execute(query, (cycle, cycle)).fetchall()

    count = 0
    for e in eleves:
        # 1. Calcul de la Scolarité
        scolarite = float(e['montant_mensualite']) if e['montant_mensualite'] is not None else montant_base

        # 2. Calcul du Transport (Sécurisé avec `or 0` pour éviter les erreurs)
        transport = float(e['montant_transport'] or 0) if e['transport_abonne'] == 'oui' else 0.0

        # 3. 🆕 Application de la réduction sur la mensualité (scolarité)
        reduction_pct = float(e['reduction_pourcentage'] or 0)
        reduction_appliquee = 0.0
        if reduction_pct > 0 and _reduction_est_valide(mois):
            reduction_appliquee = round(scolarite * (reduction_pct / 100), 2)
            scolarite = round(scolarite - reduction_appliquee, 2)

        # 4. 🆕 Application d'une réduction indépendante sur le transport
        reduction_transport_pct = float(e['reduction_transport_pourcentage'] or 0)
        reduction_transport_appliquee = 0.0
        if transport > 0 and reduction_transport_pct > 0 and _reduction_est_valide(mois):
            reduction_transport_appliquee = round(transport * (reduction_transport_pct / 100), 2)
            transport = round(transport - reduction_transport_appliquee, 2)

        # 5. Addition pour la facture finale (après réductions)
        montant_final = round(scolarite + transport, 2)
        reduction_totale = round(reduction_appliquee + reduction_transport_appliquee, 2)

        # 6. Titre dynamique pour plus de clarté
        if transport > 0 or e['transport_abonne'] == 'oui':
            desc = f"[Scolarité + Transport] Mensualité - {mois}"
        else:
            desc = f"[Scolarité] Mensualité - {mois}"
        libelles_reduction = []
        if reduction_appliquee > 0:
            libelles_reduction.append(f"{reduction_pct:g}% sur la mensualité")
        if reduction_transport_appliquee > 0:
            libelles_reduction.append(f"{reduction_transport_pct:g}% sur le transport")
        if libelles_reduction:
            desc += f" (Réduction {' + '.join(libelles_reduction)})"

        # 6. Vérification (On utilise LIKE "%Mensualité - {mois}" pour bloquer les doublons peu importe le titre généré)
        exists = conn.execute("SELECT id FROM paiements WHERE eleve_id=? AND description LIKE ?",
                              (e['id'], f"%Mensualité - {mois}")).fetchone()

        if not exists:
            # 🆕 Échéance fixée au {JOUR_ECHEANCE_MAX} du mois (règle : réglement dû le 1er du mois)
            date_echeance = f"{mois}-{JOUR_ECHEANCE_MAX:02d}"
            conn.execute(
                "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut,montant_transport,reduction_appliquee,mois) VALUES (?,?,?,?,?,?,?,?,?)",
                (e['id'], montant_final, 0, desc, date_echeance, 'non_paye', transport, reduction_totale, mois))
            count += 1

    conn.commit()
    return count


# 🆕 GÉNÉRATION AUTOMATIQUE DES FACTURES EN DÉBUT DE MOIS + RAPPELS DE RETARD
# ===================================================================
def tache_generation_factures_mensuelles():
    """Génère automatiquement, le 1er de chaque mois, les factures du mois courant pour les
    3 cycles (Maternelle, Primaire, Collège). Échéance fixée au 7 du mois. Idempotente :
    ne recrée jamais de facture en double pour un élève/mois déjà généré."""
    conn = get_db()
    try:
        mois = datetime.date.today().strftime('%Y-%m')
        total = 0
        for cycle in get_all_cycle_names(conn):
            total += _generer_mensualites_cycle(conn, cycle, mois)
        conn.execute(
            "INSERT INTO historique_actions (user_id,user_nom,user_role,action,cible_type,cible_id,details) "
            "VALUES (NULL,'Système','system','creation','paiements_generation_auto',NULL,?)",
            (f"Génération automatique mensuelle — mois {mois} — {total} facture(s) créée(s)",))
        conn.commit()
        print(f"  🧾  Génération automatique des factures {mois} : {total} facture(s) créée(s).")
    except Exception as e:
        conn.rollback()
        print(f"  ⚠️  Erreur génération automatique des factures : {e}")
    finally:
        conn.close()


def tache_rappels_retard_paiements():
    """Tous les jours : envoie une notification in-app à chaque parent ayant au moins une
    facture en retard (échéance dépassée, le 1er du mois, et toujours non payée intégralement),
    une seule fois par facture grâce au flag notif_retard_envoyee."""
    conn = get_db()
    try:
        today = datetime.date.today().isoformat()
        rows = conn.execute("""
            SELECT p.id, p.montant_total, p.montant_paye, p.description, p.date_echeance,
                   e.parent_id, e.prenom||' '||e.nom as eleve_nom
            FROM paiements p
            JOIN eleves e ON p.eleve_id = e.id
            WHERE p.statut IN ('non_paye','partiel')
              AND p.date_echeance IS NOT NULL AND p.date_echeance != ''
              AND p.date_echeance < ?
              AND (p.notif_retard_envoyee IS NULL OR p.notif_retard_envoyee = 0)
              AND e.parent_id IS NOT NULL
        """, (today,)).fetchall()

        nb_envoyes = 0
        for r in rows:
            reste = (r['montant_total'] or 0) - (r['montant_paye'] or 0)
            desc = r['description'] or 'Mensualité'
            msg = (f"⏰ Paiement en retard pour {r['eleve_nom']} — {desc}. "
                   f"Montant restant : {reste:.2f} MAD (échéance dépassée : {r['date_echeance']}). "
                   f"Merci de régulariser votre situation rapidement.")
            notif_to_parent(r['parent_id'], msg, conn)
            conn.execute("UPDATE paiements SET notif_retard_envoyee=1 WHERE id=?", (r['id'],))
            nb_envoyes += 1

        conn.commit()
        if nb_envoyes:
            print(f"  🔔  Rappels de retard de paiement envoyés : {nb_envoyes} notification(s).")
    except Exception as e:
        conn.rollback()
        print(f"  ⚠️  Erreur envoi rappels de retard de paiement : {e}")
    finally:
        conn.close()


# Enregistrement différé de ces 2 tâches : elles utilisent _generer_mensualites_cycle,
# défini juste au-dessus, donc on les ajoute au planificateur ici (déjà démarré plus haut
# dans le fichier), une fois que tout est disponible — plutôt que dans
# demarrer_planificateur_sauvegardes(), appelée trop tôt dans le fichier pour ces tâches.
if _CE_WORKER_GERE_LE_PLANIFICATEUR:
    try:
        if not scheduler.get_job('generation_factures_mensuelles'):
            scheduler.add_job(tache_generation_factures_mensuelles, trigger='cron',
                               day=1, hour=1, minute=0, id='generation_factures_mensuelles')
        if not scheduler.get_job('rappels_retard_paiements'):
            scheduler.add_job(tache_rappels_retard_paiements, trigger='cron',
                               hour=8, minute=30, id='rappels_retard_paiements')
        if not scheduler.running:
            scheduler.start()
        print("  🧾  Facturation automatique activée : génération mensuelle (le 1er, 01h00) "
              "+ rappels de retard quotidiens (08h30).")
    except Exception as _e:
        print(f"  ⚠️  Échec de l'activation de la facturation automatique : {_e}")


@app.route('/paiements/valider_ajax', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def paiement_valider_ajax():
    """🆕 Validation d'un paiement (élève ou enseignant) en AJAX : ne redirige jamais, ne
    recharge jamais la page. Utilisé par le bouton ✓ du tableau des paiements pour que la
    page reste exactement où l'admin se trouvait (scroll, pagination, filtres inchangés)."""
    is_enseignant = request.form.get('is_enseignant') == '1'

    if is_enseignant and session['role'] == 'agent_admin':
        return jsonify({'success': False, 'error': "Accès non autorisé."}), 403

    try:
        pid = int(request.form.get('paiement_id'))
        mp = float(request.form.get('montant_paye', 0))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400

    if mp < 0:
        return jsonify({'success': False, 'error': 'Le montant payé ne peut pas être négatif.'}), 400

    conn = get_db()
    try:
        table = 'paiements_enseignants' if is_enseignant else 'paiements'
        row = conn.execute(f"SELECT montant_total FROM {table} WHERE id=?", (pid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'error': 'Paiement introuvable.'}), 404

        mt = float(row['montant_total'] or 0)
        if mp > mt:
            return jsonify({'success': False, 'error': 'Le montant payé ne peut pas dépasser le montant total.'}), 400

        statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')
        conn.execute(f"UPDATE {table} SET montant_paye=?,statut=?,date_paiement=CURRENT_TIMESTAMP WHERE id=?",
                     (mp, statut, pid))

        badge_emoji, badge_label = None, None

        if is_enseignant:
            nom_row = conn.execute(
                "SELECT prenom||' '||nom as nom FROM users u JOIN paiements_enseignants pe ON pe.enseignant_id=u.id WHERE pe.id=?",
                (pid,)).fetchone()
            log_action(conn, 'modification', 'paiement_enseignant', pid,
                       f"Montant payé mis à jour (AJAX) : {mp:.2f} MAD (statut: {statut})"
                       f" — {nom_row['nom'] if nom_row else ''}")
            can_bulletin = (statut == 'paye')
            can_update = True  # un paiement enseignant peut toujours être réajusté
        else:
            eleve = conn.execute(
                "SELECT e.parent_id, e.prenom||' '||e.nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
                (pid,)).fetchone()
            if statut == 'paye' and eleve:
                notif_to_parent(eleve['parent_id'], f"Paiement confirmé pour {eleve['nom']}. Merci!", conn)
            log_action(conn, 'modification', 'paiement', pid,
                       f"Montant payé mis à jour (AJAX) : {mp:.2f} MAD (statut: {statut})"
                       f" — {eleve['nom'] if eleve else ''}")
            can_bulletin = False
            can_update = (statut != 'paye')

            # 🆕 Badge du parent recalculé après paiement, pour rafraîchir la colonne "Badge parent"
            if eleve and eleve['parent_id']:
                seuil_bloque = get_seuil_compte_bloque(conn)
                indic_p = _indicateurs_paiement_parent(conn, eleve['parent_id'])
                badge = _badge_paiement_parent(indic_p, seuil_bloque)
                badge_emoji, badge_label = badge['emoji'], badge['label']

        conn.commit()

        return jsonify({
            'success': True,
            'paiement': {
                'paye': mp,
                'solde': round(mt - mp, 2),
                'statut': statut,
                'canUpdate': can_update,
                'canBulletin': can_bulletin,
                'badgeEmoji': badge_emoji,
                'badgeLabel': badge_label,
            }
        })
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


