@app.route('/api/messages/supprimer_rapide/<int:msg_id>', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def message_supprimer_rapide(msg_id):
    """🆕 Suppression rapide d'un message depuis le widget "Derniers messages" du tableau de
    bord admin (bouton 🗑️ sur la ligne). Contrairement à l'action "supprimer" de la page
    /messages (qui ne fait qu'archiver la conversation côté utilisateur), ici le message est
    réellement supprimé — ce widget n'est visible que par l'admin/agent admin, qui a besoin
    de pouvoir nettoyer un message affiché par erreur ou indésirable directement depuis la
    liste, sans ouvrir la conversation."""
    conn = get_db()
    try:
        conn.execute("DELETE FROM msg_messages WHERE id=?", (msg_id,))
        conn.commit()
        return jsonify({'success': True})
    except Exception as ex:
        conn.rollback()
        return jsonify({'success': False, 'error': str(ex)}), 500
    finally:
        conn.close()


@app.route('/paiements/supprimer_ajax', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def paiement_supprimer_ajax():
    """Supprime un ou plusieurs paiements (élèves ou enseignants) en AJAX, sans recharger la
    page. Utilisé par le bouton 🗑️ individuel de chaque ligne ET par le bouton "Supprimer la
    sélection" (cases à cocher) du tableau des paiements."""
    # 🆕 SÉCURITÉ : un agent_admin peut facturer/valider/exporter, mais ne peut supprimer
    # aucun paiement (ni élève, ni enseignant) — seul un admin strict le peut.
    if session.get('role') != 'admin':
        return jsonify({'success': False, 'error': "Accès non autorisé."}), 403

    is_enseignant = request.form.get('is_enseignant') == '1'

    ids_raw = request.form.get('paiement_ids', '')
    try:
        ids = [int(x) for x in ids_raw.split(',') if x.strip()]
    except ValueError:
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400

    if not ids:
        return jsonify({'success': False, 'error': 'Aucun paiement sélectionné.'}), 400

    conn = get_db()
    try:
        table = 'paiements_enseignants' if is_enseignant else 'paiements'
        supprimes = []
        for pid in ids:
            if is_enseignant:
                info = conn.execute(
                    "SELECT prenom||' '||nom as nom FROM users u JOIN paiements_enseignants pe ON pe.enseignant_id=u.id WHERE pe.id=?",
                    (pid,)).fetchone()
                libelle = info['nom'] if info else str(pid)
            else:
                info = conn.execute(
                    "SELECT prenom||' '||nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
                    (pid,)).fetchone()
                libelle = info['nom'] if info else str(pid)

            cur = conn.execute(f"DELETE FROM {table} WHERE id=?", (pid,))
            if cur.rowcount:
                supprimes.append(pid)
                log_action(conn, 'suppression', 'paiement_enseignant' if is_enseignant else 'paiement', pid,
                           f"Paiement supprimé — {libelle}")

        conn.commit()

        if not supprimes:
            return jsonify({'success': False, 'error': 'Aucun paiement trouvé à supprimer.'}), 404

        return jsonify({'success': True, 'supprimes': supprimes})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


@app.route('/paiements/generer', methods=['POST'])
@login_required
@role_required('admin')
def generer_mensualites():
    mois = request.form.get('mois_generation')
    montant_base = float(request.form.get('montant_base', 800))  # Gardé comme filet de sécurité
    cycle = request.form.get('cycle', 'Primaire')

    if not mois:
        flash('Veuillez sélectionner un mois.', 'error')
        return redirect(url_for('paiements', cycle=cycle))

    # 🔧 CORRECTIF "disk I/O error" : ce type d'erreur SQLite (différent de "database is
    # locked") signale un vrai problème d'écriture sur le disque — le plus souvent un
    # disque persistant Render plein, ou un souci passager du volume réseau. On retente
    # quelques fois avec une courte pause avant d'abandonner proprement, et on referme
    # systématiquement la connexion pour ne pas laisser un fichier -wal/-shm à moitié écrit.
    import time as _time
    tentatives = 3
    for essai in range(tentatives):
        conn = get_db()
        try:
            count = _generer_mensualites_cycle(conn, cycle, mois, montant_base)
            log_action(conn, 'creation', 'paiements_generation', None,
                       f"Génération mensualités — cycle {cycle} — mois {mois} — {count} facture(s) créée(s)")
            conn.commit()
            flash(f"{count} facture(s) générée(s) avec succès pour {mois}.", 'success')
            break
        except sqlite3.OperationalError as e:
            conn.rollback()
            if 'disk i/o error' in str(e).lower() and essai < tentatives - 1:
                _time.sleep(0.5)
                continue
            flash(
                "Erreur disque lors de la génération des factures : "
                f"{e}. Si le problème persiste, vérifiez l'espace disponible sur le disque "
                "persistant Render (Dashboard → votre service → Disks).",
                'error')
            break
        finally:
            conn.close()

    return redirect(url_for('paiements', cycle=cycle))


@app.route('/paiements/reset', methods=['POST'])
@login_required
@role_required('admin')
def reset_paiements():
    # 🆕 SÉCURITÉ : le reset (suppression définitive des factures impayées du mois) reste
    # réservé à l'admin strict, même si role_required('admin') autorise techniquement
    # agent_admin par ailleurs — cette action est trop destructrice pour être partagée.
    if session.get('role') != 'admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements'))

    conn = get_db()
    mois = request.form.get('mois_reset')  # Format: YYYY-MM
    # Récupération du cycle envoyé par le formulaire caché de la page actuelle
    cycle = request.form.get('cycle', 'Primaire')

    if not mois:
        flash('Veuillez spécifier un mois.', 'error')
        return redirect(url_for('paiements'))

    # 1. Préparation de la sauvegarde (Filtrée par mois ET par cycle)
    paiements_mois = conn.execute("""
                                  SELECT p.id,
                                         e.nom,
                                         e.prenom,
                                         p.description,
                                         p.montant_total,
                                         p.montant_paye,
                                         p.statut,
                                         p.date_echeance
                                  FROM paiements p
                                           JOIN eleves e ON p.eleve_id = e.id
                                           LEFT JOIN classes c ON e.classe_id = c.id
                                  WHERE strftime('%Y-%m', p.date_echeance) = ?
                                    AND (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
                                  """, (mois, cycle, cycle)).fetchall()

    import csv, io
    si = io.StringIO()
    cw = csv.writer(si, delimiter=';')  # Séparateur point-virgule pour Excel
    cw.writerow(['ID Paiement', 'Nom', 'Prénom', 'Description', 'Total (MAD)', 'Payé (MAD)', 'Statut', 'Échéance'])

    for p in paiements_mois:
        cw.writerow([
            p['id'], p['nom'], p['prenom'], p['description'],
            p['montant_total'], p['montant_paye'], p['statut'], p['date_echeance']
        ])

    output = io.BytesIO()
    # Encodage utf-8-sig pour la bonne lecture des caractères spéciaux sur Excel
    output.write(si.getvalue().encode('utf-8-sig'))
    output.seek(0)

    # 2. Reset CIBLÉ : Suppression uniquement des factures du mois ET du cycle sélectionné
    nb_supprimees = len(paiements_mois)
    conn.execute("""
                 DELETE
                 FROM paiements
                 WHERE strftime('%Y-%m', date_echeance) = ?
                   AND eleve_id IN (SELECT e.id
                                    FROM eleves e
                                             LEFT JOIN classes c ON e.classe_id = c.id
                                    WHERE c.cycle = ?
                                       OR (c.cycle IS NULL AND ? = 'Primaire'))
                 """, (mois, cycle, cycle))

    log_action(conn, 'suppression', 'paiements_reset', None,
               f"Reset mensuel — cycle {cycle} — mois {mois} — {nb_supprimees} facture(s) sauvegardée(s) puis supprimée(s)")
    conn.commit()
    conn.close()

    # 3. Déclenchement du téléchargement avec un nom de fichier contenant le cycle
    return send_file(output, mimetype='text/csv', as_attachment=True,
                     download_name=f'sauvegarde_{cycle}_reset_{mois}.csv')


