ALLOWED_MSG_EXTENSIONS = EXT_PDF | EXT_WORD | EXT_IMAGE | EXT_EXCEL
PRIORITES_MSG = ['normal', 'important', 'urgent']
LABELS_PRIORITE_MSG = {'normal': '🟢 Normal', 'important': '🟠 Important', 'urgent': '🔴 Urgent'}
COULEURS_PRIORITE_MSG = {'normal': '#8E8E93', 'important': '#FF9F0A', 'urgent': '#FF453A'}


def upgrade_db_messagerie():
    """Crée le schéma de la nouvelle messagerie (conversations 1-à-1, éventuellement liées à un
    élève) et migre une seule fois les anciens messages de la table historique `messages` pour ne
    perdre aucune donnée existante."""
    if not os.path.exists(DB_PATH):
        return
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS msg_conversations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_a_id INTEGER NOT NULL REFERENCES users(id),
            user_b_id INTEGER NOT NULL REFERENCES users(id),
            eleve_id INTEGER REFERENCES eleves(id),
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(user_a_id, user_b_id, eleve_id)
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS msg_participant_etat (
            conversation_id INTEGER NOT NULL REFERENCES msg_conversations(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            epingle INTEGER DEFAULT 0,
            important INTEGER DEFAULT 0,
            archive INTEGER DEFAULT 0,
            non_lu_force INTEGER DEFAULT 0,
            dernier_lu_msg_id INTEGER DEFAULT 0,
            PRIMARY KEY(conversation_id, user_id)
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS msg_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            conversation_id INTEGER NOT NULL REFERENCES msg_conversations(id) ON DELETE CASCADE,
            expediteur_id INTEGER NOT NULL REFERENCES users(id),
            contenu TEXT NOT NULL,
            priorite TEXT DEFAULT 'normal',
            transfere_de INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS msg_fichiers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            message_id INTEGER NOT NULL REFERENCES msg_messages(id) ON DELETE CASCADE,
            nom_original TEXT,
            nom_fichier TEXT,
            type_fichier TEXT,
            taille INTEGER
        )
    """)
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_msgconv_a ON msg_conversations(user_a_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_msgconv_b ON msg_conversations(user_b_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_msgmsg_conv ON msg_messages(conversation_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_msgfichiers_msg ON msg_fichiers(message_id)")
    except sqlite3.OperationalError:
        pass

    # ── Migration ponctuelle des anciens messages (table `messages`) vers le nouveau schéma ──
    # Ne s'exécute qu'une seule fois : si msg_messages est déjà alimentée, on ne retouche rien.
    try:
        deja_migre = conn.execute("SELECT COUNT(*) FROM msg_messages").fetchone()[0]
        anciens = conn.execute("SELECT COUNT(*) FROM messages").fetchone()[0]
        if deja_migre == 0 and anciens > 0:
            print(f"  ♻️  Migration de {anciens} ancien(s) message(s) vers la nouvelle messagerie...")
            for m in conn.execute("SELECT * FROM messages ORDER BY id ASC").fetchall():
                exp_id, dest_id = m['expediteur_id'], m['destinataire_id']
                if not exp_id or not dest_id:
                    continue
                a, b = (exp_id, dest_id) if exp_id < dest_id else (dest_id, exp_id)
                conv = conn.execute(
                    "SELECT id FROM msg_conversations WHERE user_a_id=? AND user_b_id=? AND eleve_id IS NULL",
                    (a, b)).fetchone()
                if conv:
                    conv_id = conv['id']
                else:
                    cur = conn.execute(
                        "INSERT INTO msg_conversations (user_a_id, user_b_id, eleve_id, created_at) VALUES (?,?,NULL,?)",
                        (a, b, m['date_envoi']))
                    conv_id = cur.lastrowid
                contenu = m['contenu'] if not m['sujet'] or m['sujet'] == '(sans sujet)' else f"{m['sujet']}\n\n{m['contenu']}"
                conn.execute("""INSERT INTO msg_messages (conversation_id, expediteur_id, contenu, priorite, created_at)
                                 VALUES (?,?,?,'normal',?)""",
                             (conv_id, exp_id, contenu, m['date_envoi']))
                if m['lu']:
                    dernier_id = conn.execute("SELECT MAX(id) FROM msg_messages WHERE conversation_id=?",
                                               (conv_id,)).fetchone()[0]
                    conn.execute("""INSERT INTO msg_participant_etat (conversation_id, user_id, dernier_lu_msg_id)
                                     VALUES (?,?,?)
                                     ON CONFLICT(conversation_id, user_id) DO UPDATE SET dernier_lu_msg_id=MAX(dernier_lu_msg_id, excluded.dernier_lu_msg_id)""",
                                 (conv_id, dest_id, dernier_id))
            print("  ✅  Migration de l'ancienne messagerie terminée.")
    except Exception as e:
        print(f"  ⚠️  Migration messagerie ignorée : {e}")

    conn.commit()
    conn.close()


upgrade_db_messagerie()


def _msg_normalise(user_a, user_b):
    return (user_a, user_b) if int(user_a) < int(user_b) else (user_b, user_a)


def _msg_get_or_create_conversation(conn, user_a, user_b, eleve_id=None):
    a, b = _msg_normalise(user_a, user_b)
    row = conn.execute(
        "SELECT id FROM msg_conversations WHERE user_a_id=? AND user_b_id=? AND eleve_id IS ?",
        (a, b, eleve_id)).fetchone()
    if row:
        return row['id']
    cur = conn.execute("INSERT INTO msg_conversations (user_a_id, user_b_id, eleve_id) VALUES (?,?,?)",
                        (a, b, eleve_id))
    return cur.lastrowid


def _msg_classes_enseignant(conn, enseignant_id):
    """Classes accessibles à un enseignant (professeur principal, classe_profs ou matières enseignées)."""
    rows = conn.execute("""
        SELECT DISTINCT c.id FROM classes c
        WHERE c.enseignant_id=?
           OR EXISTS(SELECT 1 FROM classe_profs cp WHERE cp.classe_id=c.id AND cp.enseignant_id=?)
           OR EXISTS(SELECT 1 FROM matieres m WHERE m.classe_id=c.id AND m.enseignant_id=?)
    """, (enseignant_id, enseignant_id, enseignant_id)).fetchall()
    return [r['id'] for r in rows]


def _msg_contacts_autorises(conn, user_id, role):
    """🔐 Détermine la liste des destinataires qu'un utilisateur a le droit de contacter en
    messagerie privée, selon les règles de permissions (section 13 du cahier des charges)."""
    if role in ('admin', 'agent_admin'):
        rows = conn.execute(
            "SELECT id, prenom, nom, role FROM users WHERE id!=? ORDER BY role, nom",
            (user_id,)).fetchall()
    elif role == 'enseignant':
        classes_ids = _msg_classes_enseignant(conn, user_id)
        contacts = {r['id']: r for r in conn.execute(
            "SELECT id, prenom, nom, role FROM users WHERE role IN ('admin','agent_admin') AND id!=?",
            (user_id,)).fetchall()}
        if classes_ids:
            ph = ','.join('?' * len(classes_ids))
            for r in conn.execute(f"""
                SELECT DISTINCT u.id, u.prenom, u.nom, u.role FROM users u
                JOIN eleves e ON e.parent_id=u.id
                WHERE e.classe_id IN ({ph})
            """, classes_ids).fetchall():
                contacts[r['id']] = r
        rows = sorted(contacts.values(), key=lambda r: (r['role'], r['nom'] or ''))
    else:  # parent
        contacts = {r['id']: r for r in conn.execute(
            "SELECT id, prenom, nom, role FROM users WHERE role IN ('admin','agent_admin')").fetchall()}
        mes_classes = [r['classe_id'] for r in conn.execute(
            "SELECT DISTINCT classe_id FROM eleves WHERE parent_id=? AND classe_id IS NOT NULL",
            (user_id,)).fetchall()]
        if mes_classes:
            ph = ','.join('?' * len(mes_classes))
            for r in conn.execute(f"""
                SELECT DISTINCT u.id, u.prenom, u.nom, u.role FROM users u
                WHERE u.role='enseignant' AND (
                    u.id IN (SELECT enseignant_id FROM classes WHERE id IN ({ph}) AND enseignant_id IS NOT NULL)
                    OR u.id IN (SELECT enseignant_id FROM classe_profs WHERE classe_id IN ({ph}))
                    OR u.id IN (SELECT enseignant_id FROM matieres WHERE classe_id IN ({ph}) AND enseignant_id IS NOT NULL)
                )
            """, mes_classes * 3).fetchall():
                contacts[r['id']] = r
        rows = sorted(contacts.values(), key=lambda r: (r['role'], r['nom'] or ''))
    return [{'id': r['id'], 'nom': f"{r['prenom']} {r['nom']}", 'role': r['role']} for r in rows]


def _msg_peut_contacter(conn, user_id, role, contact_id):
    if role in ('admin', 'agent_admin'):
        return conn.execute("SELECT 1 FROM users WHERE id=?", (contact_id,)).fetchone() is not None
    return any(c['id'] == int(contact_id) for c in _msg_contacts_autorises(conn, user_id, role))


def _msg_eleves_communs(conn, user_id, role, contact_id, contact_role):
    """Élève(s) qui peuvent raisonnablement être « concernés » par la conversation entre ces deux
    personnes, pour affichage du sélecteur « Élève concerné »."""
    parent_id = user_id if role == 'parent' else (contact_id if contact_role == 'parent' else None)
    if parent_id is None:
        return []
    autre_id = contact_id if role == 'parent' else user_id
    autre_role = contact_role if role == 'parent' else role
    rows = conn.execute(
        "SELECT e.id, e.nom, e.prenom, e.classe_id, c.nom as classe_nom FROM eleves e "
        "LEFT JOIN classes c ON c.id=e.classe_id WHERE e.parent_id=?", (parent_id,)).fetchall()
    if autre_role in ('admin', 'agent_admin'):
        return [dict(r) for r in rows]
    if autre_role == 'enseignant':
        classes_prof = set(_msg_classes_enseignant(conn, autre_id))
        return [dict(r) for r in rows if r['classe_id'] in classes_prof]
    return [dict(r) for r in rows]


def _msg_marque_camera(conn, conversation_id, user_id, dernier_msg_id):
    conn.execute("""INSERT INTO msg_participant_etat (conversation_id, user_id, dernier_lu_msg_id)
                     VALUES (?,?,?)
                     ON CONFLICT(conversation_id, user_id) DO UPDATE SET dernier_lu_msg_id=?, non_lu_force=0""",
                 (conversation_id, user_id, dernier_msg_id, dernier_msg_id))


def _msg_etat(conn, conversation_id, user_id):
    row = conn.execute("SELECT * FROM msg_participant_etat WHERE conversation_id=? AND user_id=?",
                        (conversation_id, user_id)).fetchone()
    if row:
        return dict(row)
    return {'conversation_id': conversation_id, 'user_id': user_id, 'epingle': 0, 'important': 0,
            'archive': 0, 'non_lu_force': 0, 'dernier_lu_msg_id': 0}


def _msg_maj_etat(conn, conversation_id, user_id, **champs):
    existe = conn.execute("SELECT 1 FROM msg_participant_etat WHERE conversation_id=? AND user_id=?",
                          (conversation_id, user_id)).fetchone()
    if not existe:
        conn.execute("INSERT INTO msg_participant_etat (conversation_id, user_id) VALUES (?,?)",
                     (conversation_id, user_id))
    sets = ', '.join(f"{k}=?" for k in champs)
    conn.execute(f"UPDATE msg_participant_etat SET {sets} WHERE conversation_id=? AND user_id=?",
                (*champs.values(), conversation_id, user_id))


def _msg_autre_participant(conv_row, user_id):
    return conv_row['user_b_id'] if conv_row['user_a_id'] == user_id else conv_row['user_a_id']


def _msg_liste_conversations(conn, user_id):
    """Retourne toutes les conversations de l'utilisateur, enrichies : contact, élève lié,
    dernier message, compteur de non-lus, et l'état personnel (épinglé/important/archivé)."""
    convs = conn.execute(
        "SELECT * FROM msg_conversations WHERE user_a_id=? OR user_b_id=?",
        (user_id, user_id)).fetchall()
    if not convs:
        return []
    conv_ids = [c['id'] for c in convs]
    ph = ','.join('?' * len(conv_ids))

    derniers = {}
    for row in conn.execute(f"""
        SELECT mm.* FROM msg_messages mm
        WHERE mm.id IN (SELECT MAX(id) FROM msg_messages WHERE conversation_id IN ({ph}) GROUP BY conversation_id)
    """, conv_ids).fetchall():
        derniers[row['conversation_id']] = dict(row)

    non_lus = {}
    for row in conn.execute(f"""
        SELECT mm.conversation_id, COUNT(*) as nb FROM msg_messages mm
        WHERE mm.conversation_id IN ({ph}) AND mm.expediteur_id != ?
          AND mm.id > COALESCE((SELECT dernier_lu_msg_id FROM msg_participant_etat pe
                                 WHERE pe.conversation_id=mm.conversation_id AND pe.user_id=?), 0)
        GROUP BY mm.conversation_id
    """, conv_ids + [user_id, user_id]).fetchall():
        non_lus[row['conversation_id']] = row['nb']

    etats = {}
    for row in conn.execute(f"""
        SELECT * FROM msg_participant_etat WHERE conversation_id IN ({ph}) AND user_id=?
    """, conv_ids + [user_id]).fetchall():
        etats[row['conversation_id']] = dict(row)

    resultat = []
    for c in convs:
        autre_id = _msg_autre_participant(c, user_id)
        contact = conn.execute("SELECT id, prenom, nom, role FROM users WHERE id=?", (autre_id,)).fetchone()
        if not contact:
            continue
        eleve = None
        if c['eleve_id']:
            eleve = conn.execute(
                "SELECT e.id, e.nom, e.prenom, c2.nom as classe_nom FROM eleves e "
                "LEFT JOIN classes c2 ON c2.id=e.classe_id WHERE e.id=?", (c['eleve_id'],)).fetchone()
        etat = etats.get(c['id'], {'epingle': 0, 'important': 0, 'archive': 0, 'non_lu_force': 0,
                                    'dernier_lu_msg_id': 0})
        dernier = derniers.get(c['id'])
        nb_non_lus = non_lus.get(c['id'], 0)
        resultat.append({
            'id': c['id'], 'contact': dict(contact), 'eleve': dict(eleve) if eleve else None,
            'dernier_message': dernier, 'nb_non_lus': nb_non_lus,
            'non_lu': nb_non_lus > 0 or bool(etat.get('non_lu_force')),
            'epingle': bool(etat.get('epingle')), 'important': bool(etat.get('important')),
            'archive': bool(etat.get('archive')),
            'date_tri': (dernier['created_at'] if dernier else c['created_at']),
        })
    resultat.sort(key=lambda r: r['date_tri'] or '', reverse=True)
    resultat.sort(key=lambda r: r['epingle'], reverse=True)
    return resultat


@app.route('/messages', methods=['GET', 'POST'])
@login_required
def messages():
    conn = get_db()
    user_id = session['user_id']
    role = session['role']

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'nouveau':
            dest_ids = request.form.getlist('destinataire_id')
            contenu = request.form.get('contenu', '').strip()
            priorite = request.form.get('priorite', 'normal')
            if priorite not in PRIORITES_MSG:
                priorite = 'normal'
            eleve_id = request.form.get('eleve_id') or None
            if not dest_ids or not contenu:
                flash("Veuillez choisir au moins un destinataire et écrire un message.", "error")
                conn.close()
                return redirect(url_for('messages'))

            dest_valides = [d for d in dest_ids if _msg_peut_contacter(conn, user_id, role, d)]
            if not dest_valides:
                flash("Vous n'êtes pas autorisé à contacter ce(s) destinataire(s).", "error")
                conn.close()
                return redirect(url_for('messages'))

            dernier_conv_id = None
            for did in dest_valides:
                conv_id = _msg_get_or_create_conversation(conn, user_id, did, eleve_id)
                cur = conn.execute("""INSERT INTO msg_messages (conversation_id, expediteur_id, contenu, priorite)
                                       VALUES (?,?,?,?)""", (conv_id, user_id, contenu, priorite))
                msg_id = cur.lastrowid
                for fchier in request.files.getlist('fichiers'):
                    if fchier and fchier.filename:
                        ext = fchier.filename.rsplit('.', 1)[-1].lower() if '.' in fchier.filename else ''
                        if ext in ALLOWED_MSG_EXTENSIONS:
                            original = secure_filename(fchier.filename)
                            ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
                            nom_fichier = f"msg_{ts}_{original}"
                            _sauvegarder_image_compressee(fchier, os.path.join(UPLOAD_FOLDER_MESSAGES, nom_fichier), max_dimension=1800, qualite=84)
                            conn.execute("""INSERT INTO msg_fichiers (message_id, nom_original, nom_fichier, type_fichier, taille)
                                             VALUES (?,?,?,?,?)""",
                                         (msg_id, original, nom_fichier, type_fichier_depuis_extension(original),
                                          os.path.getsize(os.path.join(UPLOAD_FOLDER_MESSAGES, nom_fichier))))
                        else:
                            flash(f"Fichier « {fchier.filename} » ignoré : extension .{ext} non autorisée.", "error")
                _msg_marque_camera(conn, conv_id, user_id, msg_id)
                notif_to_parent(did, f"💬 Nouveau message de {session.get('nom_complet','Un utilisateur')}", conn)
                dernier_conv_id = conv_id
            conn.commit()
            flash(f"Message envoyé à {len(dest_valides)} destinataire(s).", "success")
            conn.close()
            if len(dest_valides) == 1:
                return redirect(url_for('messages', conv=dernier_conv_id))
            return redirect(url_for('messages'))

        # Pour toutes les autres actions, l'utilisateur doit être participant de la conversation
        conv_id = request.form.get('conversation_id', type=int)
        conv = conn.execute("SELECT * FROM msg_conversations WHERE id=?", (conv_id,)).fetchone() if conv_id else None
        if not conv or user_id not in (conv['user_a_id'], conv['user_b_id']):
            flash("Conversation introuvable.", "error")
            conn.close()
            return redirect(url_for('messages'))

        if action == 'repondre':
            contenu = request.form.get('contenu', '').strip()
            priorite = request.form.get('priorite', 'normal')
            if priorite not in PRIORITES_MSG:
                priorite = 'normal'
            fichiers_recus = request.files.getlist('fichiers')
            if not contenu and not any(f and f.filename for f in fichiers_recus):
                conn.close()
                return redirect(url_for('messages', conv=conv_id))
            cur = conn.execute("""INSERT INTO msg_messages (conversation_id, expediteur_id, contenu, priorite)
                                   VALUES (?,?,?,?)""", (conv_id, user_id, contenu or '📎 Pièce jointe', priorite))
            msg_id = cur.lastrowid
            for fchier in fichiers_recus:
                if fchier and fchier.filename:
                    ext = fchier.filename.rsplit('.', 1)[-1].lower() if '.' in fchier.filename else ''
                    if ext in ALLOWED_MSG_EXTENSIONS:
                        original = secure_filename(fchier.filename)
                        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
                        nom_fichier = f"msg_{ts}_{original}"
                        _sauvegarder_image_compressee(fchier, os.path.join(UPLOAD_FOLDER_MESSAGES, nom_fichier), max_dimension=1800, qualite=84)
                        conn.execute("""INSERT INTO msg_fichiers (message_id, nom_original, nom_fichier, type_fichier, taille)
                                         VALUES (?,?,?,?,?)""",
                                     (msg_id, original, nom_fichier, type_fichier_depuis_extension(original),
                                      os.path.getsize(os.path.join(UPLOAD_FOLDER_MESSAGES, nom_fichier))))
                    else:
                        flash(f"Fichier « {fchier.filename} » ignoré : extension .{ext} non autorisée.", "error")
            _msg_marque_camera(conn, conv_id, user_id, msg_id)
            autre_id = _msg_autre_participant(conv, user_id)
            notif_to_parent(autre_id, f"💬 Nouveau message de {session.get('nom_complet','Un utilisateur')}", conn)
            conn.commit()
            conn.close()
            return redirect(url_for('messages', conv=conv_id))

        elif action == 'toggle_epingle':
            etat = _msg_etat(conn, conv_id, user_id)
            _msg_maj_etat(conn, conv_id, user_id, epingle=0 if etat['epingle'] else 1)
        elif action == 'toggle_important':
            etat = _msg_etat(conn, conv_id, user_id)
            _msg_maj_etat(conn, conv_id, user_id, important=0 if etat['important'] else 1)
        elif action == 'archiver':
            _msg_maj_etat(conn, conv_id, user_id, archive=1)
            flash("Conversation archivée.", "success")
        elif action == 'desarchiver':
            _msg_maj_etat(conn, conv_id, user_id, archive=0)
        elif action == 'marquer_non_lu':
            _msg_maj_etat(conn, conv_id, user_id, non_lu_force=1)
        elif action == 'supprimer':
            # ⚠️ Les messages sont conservés (règles de conservation des données) : on archive
            # simplement la conversation côté utilisateur plutôt que de supprimer les données.
            _msg_maj_etat(conn, conv_id, user_id, archive=1)
            flash("Conversation retirée de votre boîte de réception (les messages restent conservés).", "success")
        elif action == 'transferer':
            message_id = request.form.get('message_id', type=int)
            dest_ids = request.form.getlist('destinataire_id')
            src = conn.execute("SELECT * FROM msg_messages WHERE id=? AND conversation_id=?",
                               (message_id, conv_id)).fetchone()
            if src:
                dest_valides = [d for d in dest_ids if _msg_peut_contacter(conn, user_id, role, d)]
                for did in dest_valides:
                    conv2_id = _msg_get_or_create_conversation(conn, user_id, did, conv['eleve_id'])
                    cur = conn.execute("""INSERT INTO msg_messages (conversation_id, expediteur_id, contenu, priorite, transfere_de)
                                           VALUES (?,?,?,?,?)""",
                                       (conv2_id, user_id, f"🔁 Transféré : {src['contenu']}", src['priorite'], message_id))
                    _msg_marque_camera(conn, conv2_id, user_id, cur.lastrowid)
                    notif_to_parent(did, f"💬 Message transféré par {session.get('nom_complet','Un utilisateur')}", conn)
                flash(f"Message transféré à {len(dest_valides)} destinataire(s).", "success")

        conn.commit()
        conn.close()
        return redirect(url_for('messages', conv=conv_id))

    # ═══ MÉTHODE GET ═══
    filtre = request.args.get('filtre', 'tous')
    q = request.args.get('q', '').strip()
    conv_id = request.args.get('conv', type=int)

    # 🔁 Compatibilité avec les anciens liens « ?chat_with=<user_id> » utilisés ailleurs dans
    # l'application (fiche parent, etc.) : on résout/crée la conversation puis on redirige.
    chat_with = request.args.get('chat_with', type=int)
    if chat_with and _msg_peut_contacter(conn, user_id, role, chat_with):
        conv_id_resolu = _msg_get_or_create_conversation(conn, user_id, chat_with)
        conn.commit()
        conn.close()
        return redirect(url_for('messages', conv=conv_id_resolu))

    toutes_conversations = _msg_liste_conversations(conn, user_id)

    if filtre == 'archives':
        conversations = [c for c in toutes_conversations if c['archive']]
    else:
        conversations = [c for c in toutes_conversations if not c['archive']]
        if filtre == 'non_lus':
            conversations = [c for c in conversations if c['non_lu']]
        elif filtre == 'importants':
            conversations = [c for c in conversations if c['important']]
        elif filtre == 'epingles':
            conversations = [c for c in conversations if c['epingle']]

    if q:
        ql = q.lower()
        def _correspond(c):
            if ql in c['contact']['nom'].lower():
                return True
            if c['eleve'] and (ql in c['eleve']['nom'].lower() or ql in c['eleve']['prenom'].lower()
                                or ql in (c['eleve']['classe_nom'] or '').lower()):
                return True
            if c['dernier_message'] and ql in c['dernier_message']['contenu'].lower():
                return True
            return False
        conversations = [c for c in conversations if _correspond(c)]

    stats_conv = {
        'total': len([c for c in toutes_conversations if not c['archive']]),
        'non_lus': len([c for c in toutes_conversations if not c['archive'] and c['non_lu']]),
        'importants': len([c for c in toutes_conversations if not c['archive'] and c['important']]),
    }

    active_conv = None
    active_contact = None
    active_eleve = None
    fil_messages = []
    autres_eleves_possibles = []
    if conv_id:
        conv_row = conn.execute("SELECT * FROM msg_conversations WHERE id=?", (conv_id,)).fetchone()
        if conv_row and user_id in (conv_row['user_a_id'], conv_row['user_b_id']):
            active_conv = dict(conv_row)
            autre_id = _msg_autre_participant(conv_row, user_id)
            active_contact = conn.execute("SELECT id, prenom, nom, role, telephone FROM users WHERE id=?",
                                          (autre_id,)).fetchone()
            if conv_row['eleve_id']:
                active_eleve = conn.execute(
                    "SELECT e.*, c2.nom as classe_nom FROM eleves e LEFT JOIN classes c2 ON c2.id=e.classe_id WHERE e.id=?",
                    (conv_row['eleve_id'],)).fetchone()
            msgs = conn.execute("""
                SELECT mm.*, u.prenom || ' ' || u.nom as exp_nom, u.role as exp_role
                FROM msg_messages mm JOIN users u ON u.id = mm.expediteur_id
                WHERE mm.conversation_id=? ORDER BY mm.id ASC
            """, (conv_id,)).fetchall()
            etat_autre = _msg_etat(conn, conv_id, autre_id)
            for m in msgs:
                item = dict(m)
                item['fichiers'] = [dict(x) for x in conn.execute(
                    "SELECT * FROM msg_fichiers WHERE message_id=?", (m['id'],)).fetchall()]
                if m['expediteur_id'] == user_id:
                    item['statut'] = 'lu' if etat_autre['dernier_lu_msg_id'] >= m['id'] else 'envoye'
                fil_messages.append(item)
            if msgs:
                _msg_marque_camera(conn, conv_id, user_id, msgs[-1]['id'])
                conn.commit()
            if active_contact:
                autres_eleves_possibles = _msg_eleves_communs(conn, user_id, role, autre_id, active_contact['role'])

    contacts_autorises = _msg_contacts_autorises(conn, user_id, role)
    eleves_par_contact = {}
    for c in contacts_autorises:
        el = _msg_eleves_communs(conn, user_id, role, c['id'], c['role'])
        if el:
            eleves_par_contact[c['id']] = [{'id': e['id'], 'label': f"{e['prenom']} {e['nom']} ({e['classe_nom'] or '—'})"}
                                            for e in el]

    # 🆕 VUE PARENT : page d'accueil "Communication" (hub) façon tableau de bord, affichée
    # par défaut pour les parents tant qu'aucune conversation n'est ouverte et qu'aucune
    # action de filtrage/recherche spécifique à la boîte de réception n'est demandée.
    # ?vue=inbox permet de forcer l'ancienne boîte de réception classique.
    # 🆕 Vue par défaut selon le rôle : les admins ont un tableau de bord "Business",
    # parents/enseignants ont une page d'accueil façon réseau social. ?vue=inbox force
    # à tout moment l'ancienne boîte de réception classique, pour tous les rôles.
    vue = request.args.get('vue', 'hub' if role in ('parent', 'enseignant', 'admin', 'agent_admin') else 'inbox')

    # 🆕 VUE ADMIN / AGENT ADMIN : tableau de bord "Communication" façon Meta Business Suite
    if role in ('admin', 'agent_admin') and vue == 'hub' and not conv_id and filtre == 'tous' and not q:
        def _safe_count(sql, params=()):
            try:
                return conn.execute(sql, params).fetchone()['n'] or 0
            except Exception:
                return 0

        nb_messages_mois = _safe_count(
            "SELECT COUNT(*) as n FROM msg_messages WHERE created_at >= date('now','start of month')")
        nb_annonces_mois = _safe_count(
            "SELECT COUNT(*) as n FROM communications WHERE statut='publie' AND date_publication >= date('now','start of month')")
        # 🩹 CORRECTIF : la colonne "archive" n'existe pas sur msg_conversations (elle est
        # propre à chaque participant, dans msg_participant_etat) — la requête précédente
        # provoquait une erreur SQL "no such column: archive" qui faisait planter toute la
        # page (page blanche / erreur 500) pour les admins et agents admin. On compte ici
        # simplement les conversations qui contiennent au moins un message.
        nb_conversations_actives = _safe_count(
            "SELECT COUNT(DISTINCT mc.id) as n FROM msg_conversations mc JOIN msg_messages mm ON mm.conversation_id=mc.id")
        nb_familles_total = _safe_count("SELECT COUNT(*) as n FROM users WHERE role='parent'")
        nb_familles_actives = _safe_count("""
            SELECT COUNT(DISTINCT u.id) as n FROM users u
            JOIN msg_conversations mc ON u.id IN (mc.user_a_id, mc.user_b_id)
            JOIN msg_messages mm ON mm.conversation_id = mc.id
            WHERE u.role='parent' AND mm.created_at >= date('now','start of month')
        """)
        taux_participation = round((nb_familles_actives / nb_familles_total * 100)) if nb_familles_total else 0

        jours_labels = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim']
        activite_semaine = []
        aujourdhui = datetime.date.today()
        for i in range(6, -1, -1):
            d = aujourdhui - datetime.timedelta(days=i)
            n = _safe_count("SELECT COUNT(*) as n FROM msg_messages WHERE date(created_at)=?", (d.strftime('%Y-%m-%d'),))
            activite_semaine.append({'label': jours_labels[d.weekday()], 'date': d.strftime('%d/%m'), 'n': n})
        max_activite = max([j['n'] for j in activite_semaine]) or 1
        for j in activite_semaine:
            j['pct'] = max(6, round(j['n'] / max_activite * 100))

        dernieres_annonces = conn.execute(
            "SELECT * FROM communications WHERE statut='publie' ORDER BY date_publication DESC LIMIT 5").fetchall()
        # 🩹 CORRECTIF : même bug que ci-dessus (mc.archive n'existe pas) — cette requête
        # non protégée par _safe_count faisait planter la page avec une erreur 500 dès
        # qu'un admin/agent admin ouvrait /messages.
        top_conversations = conn.execute("""
            SELECT mc.id, MAX(mm.created_at) as dernier, COUNT(mm.id) as nb
            FROM msg_conversations mc JOIN msg_messages mm ON mm.conversation_id = mc.id
            GROUP BY mc.id ORDER BY dernier DESC LIMIT 6
        """).fetchall()
        notif_count_hub = get_notif_count()
        conn.close()
        return render_template_string(
            ADMIN_COMM_HUB_HTML, stats_conv=stats_conv, nb_messages_mois=nb_messages_mois,
            nb_annonces_mois=nb_annonces_mois, nb_conversations_actives=nb_conversations_actives,
            nb_familles_actives=nb_familles_actives, nb_familles_total=nb_familles_total,
            taux_participation=taux_participation, activite_semaine=activite_semaine,
            dernieres_annonces=dernieres_annonces, top_conversations=top_conversations,
            conversations=conversations[:6], notif_count=notif_count_hub,
            LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION,
            COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        )

    # 🆕 VUE PARENT / ENSEIGNANT : page d'accueil "Communication" façon Instagram
    if role in ('parent', 'enseignant') and vue == 'hub' and not conv_id and filtre == 'tous' and not q:
        enfant = None
        classe_ens = None
        if role == 'parent':
            enfant = conn.execute(
                "SELECT e.id, e.nom, e.prenom, e.classe_id, c2.nom as classe_nom FROM eleves e "
                "LEFT JOIN classes c2 ON c2.id = e.classe_id WHERE e.parent_id=? ORDER BY e.id LIMIT 1",
                (user_id,)).fetchone()
            classe_ids = [r['classe_id'] for r in conn.execute(
                "SELECT classe_id FROM eleves WHERE parent_id=? AND classe_id IS NOT NULL", (user_id,)).fetchall()]
        else:
            try:
                classe_ens = conn.execute(
                    "SELECT c2.id, c2.nom FROM classe_profs cp JOIN classes c2 ON c2.id=cp.classe_id "
                    "WHERE cp.enseignant_id=? ORDER BY c2.nom LIMIT 1", (user_id,)).fetchone()
            except Exception:
                classe_ens = None
            classe_ids = [r['id'] for r in conn.execute(
                "SELECT DISTINCT classe_id as id FROM classe_profs WHERE enseignant_id=?", (user_id,)).fetchall()] \
                if role == 'enseignant' else []
        if classe_ids:
            placeholders = ','.join('?' * len(classe_ids))
            prochaines_annonces = conn.execute(f"""
                SELECT DISTINCT c.* FROM communications c
                LEFT JOIN communication_classes cc ON cc.communication_id = c.id
                WHERE c.statut='publie' AND (c.toutes_classes=1 OR cc.classe_id IN ({placeholders}))
                ORDER BY c.date_publication DESC LIMIT 3
            """, classe_ids).fetchall()
        else:
            prochaines_annonces = conn.execute("""
                SELECT * FROM communications WHERE statut='publie' AND toutes_classes=1
                ORDER BY date_publication DESC LIMIT 3
            """).fetchall()
        try:
            nb_annonces_mois = conn.execute("""
                SELECT COUNT(*) as n FROM communications
                WHERE statut='publie' AND date_publication >= date('now','start of month')
            """).fetchone()['n']
        except Exception:
            nb_annonces_mois = 0
        try:
            nb_messages_mois = conn.execute("""
                SELECT COUNT(*) as n FROM msg_messages mm
                JOIN msg_conversations mc ON mc.id = mm.conversation_id
                WHERE (mc.user_a_id=? OR mc.user_b_id=?) AND mm.created_at >= date('now','start of month')
            """, (user_id, user_id)).fetchone()['n']
        except Exception:
            nb_messages_mois = 0
        notif_count_hub = get_notif_count()
        conn.close()
        return render_template_string(
            COMMUNICATION_HUB_HTML, conversations=conversations[:5], stats_conv=stats_conv,
            contacts_autorises=contacts_autorises, eleves_par_contact=eleves_par_contact,
            enfant=dict(enfant) if enfant else None, classe_ens=dict(classe_ens) if classe_ens else None,
            role=role, prochaines_annonces=prochaines_annonces,
            nb_annonces_mois=nb_annonces_mois, nb_messages_mois=nb_messages_mois,
            notif_count=notif_count_hub, LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION,
            COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        )

    conn.close()

    return render_template_string(
        MESSAGES_HTML, conversations=conversations, filtre=filtre, q=q, stats_conv=stats_conv,
        active_conv=active_conv, active_contact=active_contact, active_eleve=active_eleve,
        fil_messages=fil_messages, autres_eleves_possibles=autres_eleves_possibles,
        contacts_autorises=contacts_autorises, eleves_par_contact=eleves_par_contact, notif_count=get_notif_count(),
        PRIORITES_MSG=PRIORITES_MSG, LABELS_PRIORITE_MSG=LABELS_PRIORITE_MSG,
        COULEURS_PRIORITE_MSG=COULEURS_PRIORITE_MSG, ICONES_TYPE_FICHIER=ICONES_TYPE_FICHIER,
    )


@app.route('/messages/fichier/<int:fichier_id>')
@login_required
def message_fichier(fichier_id):
    conn = get_db()
    fl = conn.execute("SELECT * FROM msg_fichiers WHERE id=?", (fichier_id,)).fetchone()
    if not fl:
        conn.close()
        flash("Fichier introuvable.", "error")
        return redirect(url_for('messages'))
    msg = conn.execute("SELECT * FROM msg_messages WHERE id=?", (fl['message_id'],)).fetchone()
    conv = conn.execute("SELECT * FROM msg_conversations WHERE id=?", (msg['conversation_id'],)).fetchone() if msg else None
    conn.close()
    if not conv or session['user_id'] not in (conv['user_a_id'], conv['user_b_id']):
        flash("Accès refusé.", "error")
        return redirect(url_for('messages'))
    path = os.path.join(UPLOAD_FOLDER_MESSAGES, fl['nom_fichier'])
    if not os.path.exists(path):
        flash("Fichier introuvable sur le serveur.", "error")
        return redirect(url_for('messages'))
    return send_file(path, as_attachment=False, download_name=fl['nom_original'] or fl['nom_fichier'])


