@app.route('/admin/reset-financier', methods=['POST'])
@login_required
@role_required('admin')
def reset_financier():
    # Sécurité supplémentaire : seul le rôle 'admin' strict peut faire cette action
    # (même un agent_admin, qui passe role_required('admin'), ne doit pas pouvoir tout effacer).
    if session.get('role') != 'admin':
        flash("Accès non autorisé : seul un administrateur principal peut réinitialiser les données financières.", 'error')
        return redirect(url_for('utilisateurs'))

    confirmation = request.form.get('confirmation', '').strip().upper()
    if confirmation != 'RESET':
        flash("Réinitialisation annulée : le mot de confirmation ne correspond pas.", 'error')
        return redirect(url_for('utilisateurs'))

    conn = get_db()
    tables = ['paiements', 'paiements_enseignants', 'paiements_personnel_hors_prof', 'charges']
    total = 0
    for t in tables:
        try:
            n = conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
            conn.execute(f"DELETE FROM {t}")
            conn.execute("DELETE FROM sqlite_sequence WHERE name=?", (t,))
            total += n
        except sqlite3.OperationalError:
            pass  # table absente sur cette base
    conn.commit()
    conn.close()
    flash(f"Réinitialisation effectuée : {total} enregistrement(s) supprimé(s) (paiements élèves, salaires enseignants, salaires personnel, charges).", 'success')
    return redirect(url_for('utilisateurs'))


@app.route('/utilisateurs', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def utilisateurs():
    # 🆕 AGENT ADMIN : accès total à cette page, à l'exception des comptes admin
    # (jamais affichés, jamais modifiables/supprimables, et impossible d'attribuer
    # le rôle 'admin' à un compte depuis cette page).
    role_courant = session.get('role')
    est_agent_admin_utilisateurs = (role_courant == 'agent_admin')

    conn = get_db()

    if request.method == 'POST':
        f = request.form
        action = f.get('action')

        # 🆕 SÉCURITÉ : un agent_admin ne peut ni créer/modifier un compte en rôle 'admin',
        # ni agir sur un compte admin existant (même en devinant son id).
        if est_agent_admin_utilisateurs:
            if (f.get('role') == 'admin'):
                flash('Accès non autorisé : vous ne pouvez pas attribuer le rôle Administrateur.', 'error')
                conn.close()
                return redirect(url_for('utilisateurs'))
            if action in ('edit', 'delete'):
                cible = conn.execute("SELECT role FROM users WHERE id=?", (f.get('user_id'),)).fetchone()
                if cible and cible['role'] == 'admin':
                    flash('Accès non autorisé : ce compte est un compte Administrateur.', 'error')
                    conn.close()
                    return redirect(url_for('utilisateurs'))

        # Récupération des champs existants
        tel = f.get('telephone', '')
        cnss = f.get('cnss', '')
        date_embauche = f.get('date_embauche')
        duree_contrat = f.get('duree_contrat', '')
        date_naissance = f.get('date_naissance')
        cin = f.get('cin', '')
        adresse = f.get('adresse', '')
        matiere_specialite = f.get('matiere_specialite', '')
        heures = f.get('heures_par_mois', 0)

        # --- NOUVEAUTÉ : Champs de paiement ---
        # 🆕 Un agent admin ne doit jamais définir ni voir la rémunération d'un enseignant
        # (donnée réservée à l'administrateur) : on ignore ce qu'il aurait pu soumettre pour
        # ces 2 champs dès la création d'un compte, pas seulement à la modification.
        if est_agent_admin_utilisateurs:
            type_paiement = ''
            montant_paiement = 0
        else:
            type_paiement = f.get('type_paiement', '')
            montant_paiement = f.get('montant_paiement', 0)

        # --- NOUVEAUTÉ : Champs pour les parents ---
        nom_pere = f.get('nom_pere', '')
        profession_pere = f.get('profession_pere', '')
        nom_mere = f.get('nom_mere', '')
        profession_mere = f.get('profession_mere', '')

        if action == 'edit':
            user_id = f.get('user_id')
            try:
                # 🆕 Un agent admin ne voit jamais la rémunération des enseignants (masquée
                # côté template) : le formulaire lui arrive donc avec ces champs vides/à 0.
                # Pour ne pas écraser par erreur le salaire réel enregistré en base à chaque
                # modification faite par un agent admin, on ignore purement et simplement ce
                # qu'il a soumis pour ces 2 champs et on conserve la valeur déjà en base.
                if est_agent_admin_utilisateurs:
                    _actuel_paie = conn.execute(
                        "SELECT type_paiement, montant_paiement FROM users WHERE id=?", (user_id,)).fetchone()
                    if _actuel_paie:
                        type_paiement = _actuel_paie['type_paiement']
                        montant_paiement = _actuel_paie['montant_paiement']

                # Mise à jour avec les colonnes de paiement et parents
                conn.execute("""
                             UPDATE users
                             SET nom=?,
                                 prenom=?,
                                 email=?,
                                 role=?,
                                 telephone=?,
                                 cnss=?,
                                 date_embauche=?,
                                 duree_contrat=?,
                                 date_naissance=?,
                                 cin=?,
                                 adresse=?,
                                 matiere_specialite=?,
                                 heures_par_mois=?,
                                 type_paiement=?,
                                 montant_paiement=?,
                                 nom_pere=?,
                                 profession_pere=?,
                                 nom_mere=?,
                                 profession_mere=?
                             WHERE id = ?
                             """, (f['nom'], f['prenom'], f['email'], f['role'], tel, cnss,
                                   date_embauche, duree_contrat, date_naissance, cin, adresse,
                                   matiere_specialite, heures, type_paiement, montant_paiement,
                                   nom_pere, profession_pere, nom_mere, profession_mere, user_id))

                if f.get('password') and f['password'].strip() != '':
                    conn.execute("UPDATE users SET password=? WHERE id=?",
                                 (hash_pw(f['password']), user_id))

                if f['role'] == 'enseignant':
                    conn.execute("UPDATE matieres SET enseignant_id=NULL WHERE enseignant_id=?", (user_id,))
                    matieres_ids = f.getlist('matieres_ids')
                    for mid in matieres_ids:
                        conn.execute("UPDATE matieres SET enseignant_id=? WHERE id=?", (user_id, mid))

                    # 🔄 MODIFIÉ : Mise à jour des classes via la table de liaison classe_profs
                    conn.execute("DELETE FROM classe_profs WHERE enseignant_id=?", (user_id,))
                    classes_ids = f.getlist('classes_ids')
                    for cid in classes_ids:
                        if cid:  # Sécurité si l'ID n'est pas vide
                            conn.execute(
                                "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                (cid, user_id, matiere_specialite))

                    # 🆕 FIX : chaque matière cochée est déjà rattachée à une classe précise (matieres.classe_id).
                    # On synchronise donc aussi classe_profs pour CETTE classe+matière, afin que l'assignation
                    # se reflète bien dans la classe (et pas seulement dans le profil de l'enseignant).
                    for mid in matieres_ids:
                        m = conn.execute("SELECT classe_id, nom FROM matieres WHERE id=?", (mid,)).fetchone()
                        if m and m['classe_id']:
                            conn.execute(
                                "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                (m['classe_id'], user_id, m['nom']))

                # 🆕 SECRÉTAIRE : classes assignées via classe_secretaires (accès restreint à ces classes)
                if f['role'] == 'secretaire':
                    conn.execute("DELETE FROM classe_secretaires WHERE secretaire_id=?", (user_id,))
                    for cid in f.getlist('classes_ids'):
                        if cid:
                            conn.execute(
                                "INSERT OR IGNORE INTO classe_secretaires (classe_id, secretaire_id) VALUES (?, ?)",
                                (cid, user_id))

                conn.commit()
                flash('Utilisateur mis à jour avec succès.', 'success')
            except sqlite3.IntegrityError:
                flash('Erreur : Cet email est déjà utilisé.', 'error')

            # ✅ ADAPTATION : Fermeture de la connexion avant la redirection
            conn.close()
            return redirect(url_for('utilisateurs'))

        elif action == 'delete':
            user_id = f.get('user_id')
            if str(user_id) == str(session.get('user_id')):
                flash('Action impossible : vous ne pouvez pas supprimer votre propre compte.', 'error')
            else:
                # 🔄 MODIFIÉ : Suppression du professeur dans la table classe_profs
                conn.execute("DELETE FROM classe_profs WHERE enseignant_id=?", (user_id,))
                conn.execute("UPDATE matieres SET enseignant_id=NULL WHERE enseignant_id=?", (user_id,))
                conn.execute("DELETE FROM users WHERE id=?", (user_id,))
                conn.commit()
                flash('Utilisateur supprimé.', 'success')

            # ✅ ADAPTATION : Fermeture de la connexion avant la redirection
            conn.close()
            return redirect(url_for('utilisateurs'))

        else:
            existing = conn.execute("SELECT id FROM users WHERE email=?", (f['email'],)).fetchone()
            if existing:
                flash('Email déjà utilisé!', 'error')
            else:
                cursor = conn.cursor()
                cursor.execute("""
                               INSERT INTO users (nom, prenom, email, password, role, telephone, cnss,
                                                  date_embauche, duree_contrat, date_naissance, cin, adresse,
                                                  matiere_specialite,
                                                  heures_par_mois, type_paiement, montant_paiement,
                                                  nom_pere, profession_pere, nom_mere, profession_mere)
                               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                               """, (f['nom'], f['prenom'], f['email'], hash_pw(f['password']), f['role'],
                                     tel, cnss, date_embauche, duree_contrat, date_naissance, cin, adresse,
                                     matiere_specialite, heures, type_paiement, montant_paiement,
                                     nom_pere, profession_pere, nom_mere, profession_mere))
                new_user_id = cursor.lastrowid

                if f['role'] == 'enseignant':
                    matieres_ids = f.getlist('matieres_ids')
                    for mid in matieres_ids:
                        conn.execute("UPDATE matieres SET enseignant_id=? WHERE id=?", (new_user_id, mid))

                    # 🔄 MODIFIÉ : Ajout des classes via la table de liaison classe_profs
                    classes_ids = f.getlist('classes_ids')
                    for cid in classes_ids:
                        if cid:
                            conn.execute(
                                "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                (cid, new_user_id, matiere_specialite))

                    # 🆕 FIX : on synchronise aussi classe_profs pour chaque matière cochée, avec SA classe
                    # (matieres.classe_id), afin que l'assignation soit correcte dès la création.
                    for mid in matieres_ids:
                        m = conn.execute("SELECT classe_id, nom FROM matieres WHERE id=?", (mid,)).fetchone()
                        if m and m['classe_id']:
                            conn.execute(
                                "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                (m['classe_id'], new_user_id, m['nom']))

                # 🆕 SECRÉTAIRE : classes assignées via classe_secretaires (accès restreint à ces classes)
                if f['role'] == 'secretaire':
                    for cid in f.getlist('classes_ids'):
                        if cid:
                            conn.execute(
                                "INSERT OR IGNORE INTO classe_secretaires (classe_id, secretaire_id) VALUES (?, ?)",
                                (cid, new_user_id))

                conn.commit()
                flash('Utilisateur créé avec succès!', 'success')

            # ✅ ADAPTATION : Fermeture de la connexion avant la redirection
            conn.close()
            return redirect(url_for('utilisateurs'))

    search_query = request.args.get('q', '').strip()

    if search_query:
        like_query = f"%{search_query}%"
        if est_agent_admin_utilisateurs:
            users_raw = conn.execute("""
                                 SELECT *
                                 FROM users
                                 WHERE role != 'admin'
                                    AND (nom LIKE ?
                                    OR prenom LIKE ?
                                    OR email LIKE ?)
                                 ORDER BY role, nom, prenom
                                 """, (like_query, like_query, like_query)).fetchall()
        else:
            users_raw = conn.execute("""
                                 SELECT *
                                 FROM users
                                 WHERE nom LIKE ?
                                    OR prenom LIKE ?
                                    OR email LIKE ?
                                 ORDER BY role, nom, prenom
                                 """, (like_query, like_query, like_query)).fetchall()
    else:
        if est_agent_admin_utilisateurs:
            users_raw = conn.execute("SELECT * FROM users WHERE role != 'admin' ORDER BY role,nom,prenom").fetchall()
        else:
            users_raw = conn.execute("SELECT * FROM users ORDER BY role,nom,prenom").fetchall()

    # ✅ NOUVEAU : On enrichit les utilisateurs pour récupérer leurs classes associées
    users_list = []
    for u in users_raw:
        u_dict = dict(u)
        if u_dict['role'] == 'enseignant':
            # On récupère les classes assignées depuis la nouvelle table
            classes_assignees = conn.execute("""
                SELECT c.id, c.nom, c.niveau 
                FROM classes c
                JOIN classe_profs cp ON c.id = cp.classe_id
                WHERE cp.enseignant_id = ?
            """, (u['id'],)).fetchall()

            # Chaîne formatée pour l'affichage dans le tableau HTML (ex: "CP A, CE1 B")
            u_dict['classes_liste'] = ", ".join([f"{c['niveau']} {c['nom']}" for c in classes_assignees])

            # Liste d'IDs pour pré-cocher/sélectionner les classes dans le modal de modification
            u_dict['classes_ids_assignees'] = [c['id'] for c in classes_assignees]

            # 🆕 FIX : Liste d'IDs de matières déjà assignées, pour pré-cocher le modal de modification
            # (sans ça, ré-enregistrer la fiche sans tout recocher effaçait les assignations existantes)
            matieres_assignees = conn.execute(
                "SELECT id FROM matieres WHERE enseignant_id = ?", (u['id'],)).fetchall()
            u_dict['matieres_ids_assignees'] = [m['id'] for m in matieres_assignees]

            # 🆕 Un agent admin ne doit jamais voir la rémunération d'un enseignant (donnée
            # sensible réservée à l'administrateur) : on masque le montant et le type de
            # paiement AVANT l'envoi au template, quel que soit l'endroit où ils sont affichés
            # (carte utilisateur, modal de modification, script de pré-remplissage). Le reste
            # de la logique (droits d'accès, édition des autres champs) reste inchangé.
            if est_agent_admin_utilisateurs:
                u_dict['montant_paiement'] = None
                u_dict['type_paiement'] = None
        elif u_dict['role'] == 'secretaire':
            # 🆕 Classes assignées à la secrétaire (accès restreint)
            classes_assignees = conn.execute("""
                SELECT c.id, c.nom, c.niveau
                FROM classes c
                JOIN classe_secretaires cs ON c.id = cs.classe_id
                WHERE cs.secretaire_id = ?
            """, (u['id'],)).fetchall()
            u_dict['classes_liste'] = ", ".join([f"{c['niveau']} {c['nom']}" for c in classes_assignees])
            u_dict['classes_ids_assignees'] = [c['id'] for c in classes_assignees]
            u_dict['matieres_ids_assignees'] = []
        else:
            u_dict['classes_liste'] = ""
            u_dict['classes_ids_assignees'] = []
            u_dict['matieres_ids_assignees'] = []

        users_list.append(u_dict)

    matieres_dispo = conn.execute(
        "SELECT m.id, m.nom, c.nom as classe_nom FROM matieres m JOIN classes c ON m.classe_id=c.id ORDER BY c.nom, m.nom").fetchall()
    classes_dispo = conn.execute("SELECT id, nom, niveau FROM classes ORDER BY niveau, nom").fetchall()

    # Ce close() s'occupe de la requête GET initiale
    conn.close()

    # 🔄 MODIFIÉ : On passe `users=users_list` (les données enrichies) au template
    return render_template_string(USERS_HTML, users=users_list, matieres_dispo=matieres_dispo,
                                  classes_dispo=classes_dispo,
                                  search_query=search_query,
                                  est_agent_admin=est_agent_admin_utilisateurs,
                                  notif_count=get_notif_count())


# ─────────────────────────────────────────────
# 🆕 PAIEMENTS — SALARIÉS HORS PROF (chauffeurs, femmes de ménage, sécurité, divers)
# ─────────────────────────────────────────────
@app.route('/paiements/personnel-hors-prof', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def paiements_personnel_hors_prof():
    # 🆕 AGENT ADMIN : pas d'accès aux paiements du personnel hors prof
    if session.get('role') == 'agent_admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements'))

    conn = get_db()

    if request.method == 'POST':
        action = request.form.get('action')

        # GÉNÉRATION D'UNE FICHE DE PAIE
        if action == 'generer':
            personnel_id = request.form.get('personnel_id')
            mois = request.form.get('mois')

            if not personnel_id or not mois:
                flash('Veuillez sélectionner un salarié et un mois.', 'error')
                conn.close()
                return redirect(url_for('paiements_personnel_hors_prof'))

            pers = conn.execute("SELECT salaire, mode_paiement FROM personnel_hors_prof WHERE id=?",
                                 (personnel_id,)).fetchone()
            montant_total = pers['salaire'] if pers and pers['salaire'] else 0
            mode_p = pers['mode_paiement'] if pers else ''

            conn.execute("""
                         INSERT INTO paiements_personnel_hors_prof
                         (personnel_id, mois, montant_total, montant_paye, statut, mode_paiement)
                         VALUES (?, ?, ?, 0, 'non_paye', ?)
                         """, (personnel_id, mois, montant_total, mode_p))
            conn.commit()
            log_action(conn, 'creation', 'paiement_personnel_hors_prof', None, f'Fiche de paie {mois}')
            flash('Fiche de paie générée avec succès ! (Statut : Non payé)', 'success')

        # MARQUER COMME PAYÉ
        elif action == 'payer':
            paiement_id = request.form.get('paiement_id')
            conn.execute("""
                         UPDATE paiements_personnel_hors_prof
                         SET statut='paye', montant_paye=montant_total, date_paiement=CURRENT_DATE
                         WHERE id=?
                         """, (paiement_id,))
            conn.commit()
            log_action(conn, 'modification', 'paiement_personnel_hors_prof', paiement_id, 'Paiement validé')
            flash('Paiement validé !', 'success')

        # SUPPRIMER UNE FICHE
        elif action == 'delete':
            paiement_id = request.form.get('paiement_id')
            conn.execute("DELETE FROM paiements_personnel_hors_prof WHERE id=?", (paiement_id,))
            conn.commit()
            log_action(conn, 'suppression', 'paiement_personnel_hors_prof', paiement_id, 'Fiche de paie supprimée')
            flash('Fiche de paie supprimée.', 'success')

        conn.close()
        return redirect(url_for('paiements_personnel_hors_prof'))

    # MÉTHODE GET : Affichage de la page
    personnel = conn.execute(
        "SELECT id, nom, prenom, mission, salaire, mode_paiement FROM personnel_hors_prof ORDER BY mission, nom").fetchall()

    paiements = conn.execute("""
                             SELECT p.*, pe.nom, pe.prenom, pe.mission
                             FROM paiements_personnel_hors_prof p
                                      JOIN personnel_hors_prof pe ON p.personnel_id = pe.id
                             ORDER BY p.id DESC
                             """).fetchall()

    raw_totals = conn.execute(
        "SELECT SUM(montant_total) as total, SUM(montant_paye) as paye FROM paiements_personnel_hors_prof").fetchone()

    total_du = raw_totals['total'] if raw_totals and raw_totals['total'] else 0
    total_paye = raw_totals['paye'] if raw_totals and raw_totals['paye'] else 0

    totals_dict = {
        'total': total_du,
        'paye': total_paye,
        'reste': total_du - total_paye
    }

    conn.close()

    return render_template_string(PAIEMENTS_PERSONNEL_HORS_PROF_HTML,
                                  personnel=personnel,
                                  paiements=paiements,
                                  totals=totals_dict,
                                  notif_count=get_notif_count())


# ─────────────────────────────────────────────
# 🆕 PATRIMOINE (inventaire des équipements de l'école)
# ─────────────────────────────────────────────
@app.route('/patrimoine', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin')
def gestion_patrimoine():
    conn = get_db()

    if request.method == 'POST':
        f = request.form
        action = f.get('action', 'add')

        if action == 'delete':
            pid = f.get('patrimoine_id')
            item = conn.execute("SELECT nom FROM patrimoine WHERE id=?", (pid,)).fetchone()
            conn.execute("DELETE FROM patrimoine WHERE id=?", (pid,))
            conn.commit()
            if item:
                log_action(conn, 'suppression', 'patrimoine', pid, f"Suppression de l'article \"{item['nom']}\"")
            flash('Article supprimé de l\'inventaire.', 'success')
            conn.close()
            return redirect(url_for('gestion_patrimoine'))

        nom = f.get('nom', '').strip()
        categorie = f.get('categorie', '').strip() or 'Autre'
        try:
            quantite = int(f.get('quantite') or 1)
        except ValueError:
            quantite = 1
        etat = f.get('etat', '').strip() or 'Bon'
        emplacement = f.get('emplacement', '').strip()
        numero_serie = f.get('numero_serie', '').strip()
        date_acquisition = f.get('date_acquisition') or None
        try:
            valeur_achat = float(f.get('valeur_achat') or 0)
        except ValueError:
            valeur_achat = 0
        fournisseur = f.get('fournisseur', '').strip()
        notes = f.get('notes', '').strip()

        if not nom:
            flash("Le nom de l'article est obligatoire.", 'error')
            conn.close()
            return redirect(url_for('gestion_patrimoine'))

        # 🆕 Photo de l'article (optionnelle)
        photo_nom = None
        photo = request.files.get('photo')
        if photo and photo.filename:
            ext = photo.filename.rsplit('.', 1)[-1].lower() if '.' in photo.filename else ''
            if ext in ALLOWED_PHOTO_EXTENSIONS:
                ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
                photo_nom = f"patrimoine_{ts}.{ext}"
                _sauvegarder_image_compressee(photo, os.path.join(UPLOAD_FOLDER_PATRIMOINE, photo_nom), max_dimension=1400, qualite=82)
            else:
                flash(f"Format d'image non autorisé. Formats acceptés : "
                      f"{', '.join(sorted(ALLOWED_PHOTO_EXTENSIONS))}.", 'error')
                conn.close()
                return redirect(url_for('gestion_patrimoine'))

        if action == 'edit':
            pid = f.get('patrimoine_id')
            if photo_nom:
                # Supprime l'ancienne photo pour ne pas accumuler de fichiers orphelins
                ancienne = conn.execute("SELECT photo FROM patrimoine WHERE id=?", (pid,)).fetchone()
                if ancienne and ancienne['photo']:
                    ancien_path = os.path.join(UPLOAD_FOLDER_PATRIMOINE, ancienne['photo'])
                    if os.path.exists(ancien_path):
                        try:
                            os.remove(ancien_path)
                        except OSError:
                            pass
                conn.execute("""
                    UPDATE patrimoine
                    SET nom=?, categorie=?, quantite=?, etat=?, emplacement=?, numero_serie=?,
                        date_acquisition=?, valeur_achat=?, fournisseur=?, notes=?, photo=?
                    WHERE id=?
                """, (nom, categorie, quantite, etat, emplacement, numero_serie,
                      date_acquisition, valeur_achat, fournisseur, notes, photo_nom, pid))
            else:
                conn.execute("""
                    UPDATE patrimoine
                    SET nom=?, categorie=?, quantite=?, etat=?, emplacement=?, numero_serie=?,
                        date_acquisition=?, valeur_achat=?, fournisseur=?, notes=?
                    WHERE id=?
                """, (nom, categorie, quantite, etat, emplacement, numero_serie,
                      date_acquisition, valeur_achat, fournisseur, notes, pid))
            conn.commit()
            log_action(conn, 'modification', 'patrimoine', pid, f'Modification de "{nom}"')
            flash('Article mis à jour avec succès.', 'success')
        else:
            cursor = conn.cursor()
            cursor.execute("""
                INSERT INTO patrimoine (nom, categorie, quantite, etat, emplacement, numero_serie,
                                        date_acquisition, valeur_achat, fournisseur, notes, photo)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (nom, categorie, quantite, etat, emplacement, numero_serie,
                  date_acquisition, valeur_achat, fournisseur, notes, photo_nom))
            conn.commit()
            log_action(conn, 'creation', 'patrimoine', cursor.lastrowid, f'Ajout de "{nom}" ({categorie})')
            flash('Article ajouté à l\'inventaire avec succès.', 'success')

        conn.close()
        return redirect(url_for('gestion_patrimoine'))

    # --- GET : liste + filtres ---
    categorie_filter = request.args.get('categorie', '')
    etat_filter = request.args.get('etat', '')
    q = request.args.get('q', '').strip()

    where = "1=1"
    params = []
    if categorie_filter:
        where += " AND categorie = ?"
        params.append(categorie_filter)
    if etat_filter:
        where += " AND etat = ?"
        params.append(etat_filter)
    if q:
        where += " AND (nom LIKE ? OR emplacement LIKE ? OR numero_serie LIKE ?)"
        params.extend([f'%{q}%', f'%{q}%', f'%{q}%'])

    items = conn.execute(f"SELECT * FROM patrimoine WHERE {where} ORDER BY categorie, nom", params).fetchall()

    stats = {
        'total_articles': conn.execute("SELECT COUNT(*) FROM patrimoine").fetchone()[0],
        'total_quantite': conn.execute("SELECT COALESCE(SUM(quantite),0) FROM patrimoine").fetchone()[0],
        'valeur_totale': conn.execute("SELECT COALESCE(SUM(valeur_achat*quantite),0) FROM patrimoine").fetchone()[0],
        'hors_service': conn.execute("SELECT COUNT(*) FROM patrimoine WHERE etat='Hors service'").fetchone()[0],
    }

    conn.close()
    return render_template_string(PATRIMOINE_HTML, items=items, stats=stats,
                                  categories=CATEGORIES_PATRIMOINE, etats=ETATS_PATRIMOINE,
                                  categorie_filter=categorie_filter, etat_filter=etat_filter, q=q,
                                  notif_count=get_notif_count())


@app.route('/patrimoine/photo/<path:filename>')
@login_required
def patrimoine_photo_afficher(filename):
    safe_name = secure_filename(filename)
    path = os.path.join(UPLOAD_FOLDER_PATRIMOINE, safe_name)
    if not os.path.exists(path):
        return "Photo introuvable", 404
    return send_file(path, as_attachment=False)


# ─────────────────────────────────────────────
# 🆕 CONGÉS (demandes de congé des enseignants)
# ─────────────────────────────────────────────
@app.route('/conges', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant')
def gestion_conges():
    conn = get_db()
    role = session['role']
    uid = session['user_id']

    if request.method == 'POST':
        action = request.form.get('action')

        if action == 'demander':
            if role != 'enseignant':
                flash("Seuls les enseignants peuvent faire une demande de congé.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))

            date_debut = request.form.get('date_debut', '')
            date_fin = request.form.get('date_fin', '')
            motif = request.form.get('motif', '').strip()

            if not date_debut or not date_fin:
                flash("Les dates de début et de fin sont obligatoires.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))
            if date_fin < date_debut:
                flash("La date de fin ne peut pas être avant la date de début.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))

            conn.execute("""
                INSERT INTO conges (enseignant_id, date_debut, date_fin, motif, statut)
                VALUES (?, ?, ?, ?, 'en_attente')
            """, (uid, date_debut, date_fin, motif))
            conn.commit()

            ens = conn.execute("SELECT nom, prenom FROM users WHERE id=?", (uid,)).fetchone()
            admins = conn.execute("SELECT id FROM users WHERE role IN ('admin','agent_admin')").fetchall()
            msg_conge = (f"🌴 Nouvelle demande de congé de {ens['prenom']} {ens['nom']} "
                         f"(du {date_debut} au {date_fin})")
            for a in admins:
                conn.execute(
                    "INSERT INTO notifications (user_id, message, type) VALUES (?, ?, 'info')",
                    (a['id'], msg_conge))
                envoyer_push_utilisateur_async(a['id'], "Bright Kidz Private", msg_conge)
            conn.commit()
            flash("Votre demande de congé a été envoyée à l'administration.", "success")

        elif action == 'annuler':
            if role != 'enseignant':
                flash("Action non autorisée.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))
            conge_id = request.form.get('conge_id')
            c = conn.execute("SELECT * FROM conges WHERE id=? AND enseignant_id=?", (conge_id, uid)).fetchone()
            if not c:
                flash("Demande introuvable.", "error")
            elif c['statut'] != 'en_attente':
                flash("Impossible d'annuler une demande déjà traitée.", "error")
            else:
                conn.execute("DELETE FROM conges WHERE id=?", (conge_id,))
                conn.commit()
                flash("Demande de congé annulée.", "success")

        elif action == 'traiter':
            if role not in ('admin', 'agent_admin'):
                flash("Action non autorisée.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))

            conge_id = request.form.get('conge_id')
            decision = request.form.get('decision')  # 'approuve' ou 'refuse'
            nouvelle_date_debut = request.form.get('date_debut', '')
            nouvelle_date_fin = request.form.get('date_fin', '')
            commentaire = request.form.get('commentaire_admin', '').strip()

            if decision not in ('approuve', 'refuse'):
                flash("Décision invalide.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))

            c = conn.execute("SELECT * FROM conges WHERE id=?", (conge_id,)).fetchone()
            if not c:
                flash("Demande introuvable.", "error")
                conn.close()
                return redirect(url_for('gestion_conges'))

            date_debut_finale = nouvelle_date_debut or c['date_debut']
            date_fin_finale = nouvelle_date_fin or c['date_fin']
            dates_modifiees = (date_debut_finale != c['date_debut']) or (date_fin_finale != c['date_fin'])

            conn.execute("""
                UPDATE conges
                SET statut=?, date_debut=?, date_fin=?, commentaire_admin=?,
                    traite_par=?, date_traitement=CURRENT_TIMESTAMP,
                    date_debut_originale=?, date_fin_originale=?
                WHERE id=?
            """, (decision, date_debut_finale, date_fin_finale, commentaire, uid,
                  c['date_debut'] if dates_modifiees else c['date_debut_originale'],
                  c['date_fin'] if dates_modifiees else c['date_fin_originale'],
                  conge_id))
            conn.commit()

            libelle = 'approuvée ✅' if decision == 'approuve' else 'refusée ❌'
            msg = f"Votre demande de congé du {c['date_debut']} au {c['date_fin']} a été {libelle}"
            if dates_modifiees:
                msg += f" (dates ajustées par l'administration : du {date_debut_finale} au {date_fin_finale})"
            conn.execute("INSERT INTO notifications (user_id, message, type) VALUES (?, ?, 'info')",
                         (c['enseignant_id'], msg))
            envoyer_push_utilisateur_async(c['enseignant_id'], "Bright Kidz Private", msg)
            conn.commit()
            flash(f"Demande {libelle}.", "success")

        conn.close()
        return redirect(url_for('gestion_conges'))

    # --- GET ---
    if role == 'enseignant':
        mes_demandes = conn.execute("""
            SELECT c.*, u.nom as traite_par_nom, u.prenom as traite_par_prenom
            FROM conges c LEFT JOIN users u ON c.traite_par = u.id
            WHERE c.enseignant_id=? ORDER BY c.date_demande DESC
        """, (uid,)).fetchall()
        conn.close()
        return render_template_string(CONGES_HTML, role=role, mes_demandes=mes_demandes,
                                      demandes_attente=[], historique=[],
                                      notif_count=get_notif_count())
    else:
        demandes_attente = conn.execute("""
            SELECT c.*, u.nom as ens_nom, u.prenom as ens_prenom
            FROM conges c JOIN users u ON c.enseignant_id = u.id
            WHERE c.statut='en_attente' ORDER BY c.date_demande ASC
        """).fetchall()
        historique = conn.execute("""
            SELECT c.*, u.nom as ens_nom, u.prenom as ens_prenom,
                   t.nom as traite_par_nom, t.prenom as traite_par_prenom
            FROM conges c JOIN users u ON c.enseignant_id = u.id
            LEFT JOIN users t ON c.traite_par = t.id
            WHERE c.statut != 'en_attente' ORDER BY c.date_traitement DESC
        """).fetchall()
        conn.close()
        return render_template_string(CONGES_HTML, role=role, mes_demandes=[],
                                      demandes_attente=demandes_attente, historique=historique,
                                      notif_count=get_notif_count())


# ─────────────────────────────────────────────
# 🆕 PERSONNEL HORS PROF (chauffeurs, femmes de ménage, sécurité, divers)
# ─────────────────────────────────────────────
MISSIONS_HORS_PROF = ['Chauffeur', 'Femme de ménage', 'Sécurité', 'Accompagnatrice', 'Divers']


@app.route('/personnel-hors-prof', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def personnel_hors_prof():
    conn = get_db()

    if request.method == 'POST':
        f = request.form
        action = f.get('action', 'add')

        if action == 'delete':
            pid = f.get('personnel_id')
            conn.execute("DELETE FROM personnel_hors_prof WHERE id=?", (pid,))
            conn.commit()
            log_action(conn, 'suppression', 'personnel_hors_prof', pid, 'Suppression salarié hors prof')
            flash('Salarié supprimé avec succès.', 'success')
            conn.close()
            return redirect(url_for('personnel_hors_prof'))

        # Champs communs à l'ajout et à la modification
        mission = f.get('mission', '').strip()
        nom = f.get('nom', '').strip()
        prenom = f.get('prenom', '').strip()
        cin = f.get('cin', '').strip()
        date_naissance = f.get('date_naissance') or None
        date_embauche = f.get('date_embauche') or None
        cnss = f.get('cnss', '').strip()
        adresse = f.get('adresse', '').strip()
        # 🆕 SÉCURITÉ : agent_admin voit toutes les infos du personnel hors prof SAUF le salaire —
        # il ne peut donc jamais le fixer ni le modifier depuis ce formulaire.
        if session.get('role') == 'agent_admin':
            if f.get('action') == 'edit':
                pid_salaire = f.get('personnel_id')
                existant = conn.execute("SELECT salaire, mode_paiement FROM personnel_hors_prof WHERE id=?", (pid_salaire,)).fetchone()
                salaire = existant['salaire'] if existant and existant['salaire'] else 0
                mode_paiement = existant['mode_paiement'] if existant and existant['mode_paiement'] else ''
            else:
                salaire = 0
                mode_paiement = ''
        else:
            salaire = f.get('salaire') or 0
            mode_paiement = f.get('mode_paiement', '').strip()
        sexe = f.get('sexe', '').strip()
        note = f.get('note', '').strip()

        # 🆕 Champs spécifiques au transport scolaire — uniquement significatifs pour un
        # chauffeur, mais on les enregistre tels que saisis (vide si non renseigné, jamais
        # de valeur inventée) pour éviter de perdre l'info si l'admin change la mission plus tard.
        permis_numero = f.get('permis_numero', '').strip()
        permis_categorie = f.get('permis_categorie', '').strip()
        permis_expiration = f.get('permis_expiration') or None
        vehicule_immatriculation = f.get('vehicule_immatriculation', '').strip()
        vehicule_modele = f.get('vehicule_modele', '').strip()
        try:
            vehicule_capacite = int(f.get('vehicule_capacite')) if f.get('vehicule_capacite') else None
        except ValueError:
            vehicule_capacite = None
        statut_chauffeur = f.get('statut_chauffeur', 'Actif').strip() or 'Actif'

        if not mission or not nom or not prenom:
            flash('Merci de renseigner au minimum la mission, le nom et le prénom.', 'error')
            conn.close()
            return redirect(url_for('personnel_hors_prof'))

        if action == 'edit':
            pid = f.get('personnel_id')
            conn.execute("""
                         UPDATE personnel_hors_prof
                         SET mission=?, nom=?, prenom=?, cin=?, date_naissance=?, date_embauche=?,
                             cnss=?, adresse=?, salaire=?, sexe=?, mode_paiement=?, note=?,
                             permis_numero=?, permis_categorie=?, permis_expiration=?,
                             vehicule_immatriculation=?, vehicule_modele=?, vehicule_capacite=?,
                             statut_chauffeur=?
                         WHERE id=?
                         """, (mission, nom, prenom, cin, date_naissance, date_embauche,
                               cnss, adresse, salaire, sexe, mode_paiement, note,
                               permis_numero, permis_categorie, permis_expiration,
                               vehicule_immatriculation, vehicule_modele, vehicule_capacite,
                               statut_chauffeur, pid))
            conn.commit()
            log_action(conn, 'modification', 'personnel_hors_prof', pid, f'Modification {prenom} {nom}')
            flash('Fiche du salarié mise à jour avec succès.', 'success')
        else:
            cursor = conn.cursor()
            cursor.execute("""
                           INSERT INTO personnel_hors_prof
                               (mission, nom, prenom, cin, date_naissance, date_embauche,
                                cnss, adresse, salaire, sexe, mode_paiement, note,
                                permis_numero, permis_categorie, permis_expiration,
                                vehicule_immatriculation, vehicule_modele, vehicule_capacite,
                                statut_chauffeur)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                           """, (mission, nom, prenom, cin, date_naissance, date_embauche,
                                 cnss, adresse, salaire, sexe, mode_paiement, note,
                                 permis_numero, permis_categorie, permis_expiration,
                                 vehicule_immatriculation, vehicule_modele, vehicule_capacite,
                                 statut_chauffeur))
            conn.commit()
            log_action(conn, 'creation', 'personnel_hors_prof', cursor.lastrowid, f'Ajout {prenom} {nom} ({mission})')
            flash('Salarié ajouté avec succès à l\'annuaire.', 'success')

        conn.close()
        return redirect(url_for('personnel_hors_prof'))

    personnel_raw = conn.execute(
        "SELECT * FROM personnel_hors_prof ORDER BY mission, nom, prenom").fetchall()
    conn.close()

    personnel_list = [dict(p) for p in personnel_raw]
    # 🆕 SÉCURITÉ : agent_admin voit toutes les infos du personnel hors prof SAUF le salaire —
    # on retire ces champs des données envoyées au navigateur (y compris du JSON utilisé par
    # le modal de modification), pas seulement de l'affichage du tableau.
    if session.get('role') == 'agent_admin':
        for p in personnel_list:
            p['salaire'] = None
            p['mode_paiement'] = None
    compteurs = {m: 0 for m in MISSIONS_HORS_PROF}
    for p in personnel_list:
        if p['mission'] in compteurs:
            compteurs[p['mission']] += 1

    aujourdhui = datetime.date.today()
    return render_template_string(
        PERSONNEL_HORS_PROF_HTML,
        personnel=personnel_list,
        missions=MISSIONS_HORS_PROF,
        compteurs=compteurs,
        notif_count=get_notif_count(),
        today_str=aujourdhui.isoformat(),
        permis_alerte_str=(aujourdhui + datetime.timedelta(days=30)).isoformat(),
    )


@app.route('/personnel-hors-prof/<int:personnel_id>')
@login_required
@role_required('admin')
def personnel_hors_prof_detail(personnel_id):
    conn = get_db()
    p = conn.execute("SELECT * FROM personnel_hors_prof WHERE id=?", (personnel_id,)).fetchone()

    if not p:
        conn.close()
        flash("Ce salarié n'existe pas ou a été supprimé.", 'error')
        return redirect(url_for('personnel_hors_prof'))

    eleves_assignes = []
    eleves_disponibles = []
    historique_gasoil = []
    total_gasoil = 0
    total_km_parcourus = 0
    montant_par_km = None
    if p['mission'] == 'Chauffeur':
        eleves_assignes = conn.execute("""
                                        SELECT e.id, e.nom, e.prenom, e.transport_abonne, e.adresse as eleve_adresse,
                                               e.latitude, e.longitude,
                                               c.nom as classe_nom, c.niveau as classe_niveau,
                                               u.adresse as parent_adresse, u.telephone as parent_telephone,
                                               u.prenom || ' ' || u.nom as parent_nom
                                        FROM transport_eleves t
                                                 JOIN eleves e ON t.eleve_id = e.id
                                                 LEFT JOIN classes c ON e.classe_id = c.id
                                                 LEFT JOIN users u ON e.parent_id = u.id
                                        WHERE t.chauffeur_id = ?
                                        ORDER BY c.niveau, c.nom, e.nom
                                        """, (personnel_id,)).fetchall()
        eleves_disponibles = conn.execute("""
                                           SELECT e.id, e.nom, e.prenom, c.nom as classe_nom, c.niveau as classe_niveau
                                           FROM eleves e
                                                    LEFT JOIN classes c ON e.classe_id = c.id
                                           WHERE e.transport_abonne = 'oui'
                                             AND e.id NOT IN (SELECT eleve_id FROM transport_eleves)
                                           ORDER BY c.niveau, c.nom, e.nom
                                           """).fetchall()

        # 🆕 Historique du gasoil : charges de catégorie "Gasoil (Transport)" rattachées à ce
        # chauffeur (voir page Paiements > Charges), + coût au km calculé à partir du kilométrage
        # réellement parcouru (table chauffeur_trajets, alimentée par le suivi GPS).
        historique_gasoil = conn.execute(
            "SELECT * FROM charges WHERE categorie='Gasoil (Transport)' AND chauffeur_id=? "
            "ORDER BY date_facture DESC, id DESC", (personnel_id,)
        ).fetchall()
        total_gasoil = sum(c['montant'] or 0 for c in historique_gasoil)

        km_row = conn.execute(
            "SELECT COALESCE(SUM(distance_km), 0) as total FROM chauffeur_trajets WHERE chauffeur_id=?",
            (personnel_id,)
        ).fetchone()
        total_km_parcourus = round(km_row['total'] or 0, 2)
        if total_km_parcourus > 0:
            montant_par_km = round(total_gasoil / total_km_parcourus, 2)

    # 🆕 Score de performance (données réelles uniquement) + historique récent des trajets,
    # utilisés par le bloc "Performance" de la fiche chauffeur.
    score_chauffeur = None
    trajets_recents = []
    if p['mission'] == 'Chauffeur':
        score_chauffeur = calculer_score_chauffeur(personnel_id, conn)
        trajets_recents = conn.execute(
            "SELECT * FROM chauffeur_trajets WHERE chauffeur_id=? "
            "ORDER BY date_trajet DESC, id DESC LIMIT 15", (personnel_id,)
        ).fetchall()

    ecole = get_ecole_coords(conn)
    conn.close()

    # 🗺️ Liste des élèves localisés (adresse géocodée) pour la carte OpenStreetMap du trajet
    eleves_localises = [
        {
            'id': e['id'],
            'nom': f"{e['prenom']} {e['nom']}",
            'adresse': e['eleve_adresse'] or e['parent_adresse'] or '',
            'lat': e['latitude'],
            'lon': e['longitude'],
            # 🆕 Champs complémentaires (classe, contact parent) pour l'affichage de la liste
            # ordonnée (élève le plus éloigné en premier), utilisés à la fois par la fiche
            # admin du chauffeur et par l'espace personnel du chauffeur.
            'classe_nom': e['classe_nom'],
            'classe_niveau': e['classe_niveau'],
            'parent_nom': e['parent_nom'],
            'parent_telephone': e['parent_telephone'],
        }
        for e in eleves_assignes if e['latitude'] is not None and e['longitude'] is not None
    ]

    # 🚐 Ordre de ramassage : on part de l'élève le plus éloigné de l'école, puis on
    # enchaîne toujours vers l'élève non visité le plus proche du point courant.
    ecole_localisee = ecole['lat'] is not None and ecole['lon'] is not None
    if ecole_localisee:
        eleves_carte = ordonner_trajet_ramassage(ecole['lat'], ecole['lon'], eleves_localises)
    else:
        eleves_carte = eleves_localises

    # 📏 Distance RÉELLE totale du trajet complet (à vol d'oiseau) :
    # École ➝ élève le plus éloigné ➝ ... ➝ élève le plus proche ➝ retour à l'École.
    distance_totale_trajet = None
    if ecole_localisee and eleves_carte:
        distance_totale_trajet = distance_totale_trajet_km(ecole['lat'], ecole['lon'], eleves_carte)

    p_dict = dict(p)
    # 🆕 SÉCURITÉ : agent_admin voit toutes les infos du salarié SAUF le salaire.
    if session.get('role') == 'agent_admin':
        p_dict['salaire'] = None
        p_dict['mode_paiement'] = None

    return render_template_string(
        PERSONNEL_HORS_PROF_DETAIL_HTML,
        p=p_dict,
        eleves_assignes=eleves_assignes,
        eleves_carte=eleves_carte,
        ecole=ecole,
        ecole_localisee=ecole_localisee,
        eleves_disponibles=eleves_disponibles,
        distance_totale_trajet=distance_totale_trajet,
        historique_gasoil=historique_gasoil,
        total_gasoil=total_gasoil,
        total_km_parcourus=total_km_parcourus,
        montant_par_km=montant_par_km,
        score_chauffeur=score_chauffeur,
        trajets_recents=trajets_recents,
        permis_alerte_str=(datetime.date.today() + datetime.timedelta(days=30)).isoformat(),
        today_str=datetime.date.today().isoformat(),
        notif_count=get_notif_count()
    )


# 🆕 Photo de profil du personnel hors prof (chauffeurs notamment) — même mécanique que
# la photo des élèves : upload, remplacement de l'ancienne photo, affichage sécurisé.
@app.route('/personnel-hors-prof/<int:personnel_id>/photo', methods=['POST'])
@login_required
@role_required('admin')
def personnel_hors_prof_photo_upload(personnel_id):
    conn = get_db()
    try:
        photo = request.files.get('photo')
        if not photo or photo.filename == '':
            flash('Veuillez sélectionner une image.', 'error')
            return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))

        ext = photo.filename.rsplit('.', 1)[-1].lower() if '.' in photo.filename else ''
        if ext not in ALLOWED_PHOTO_EXTENSIONS:
            flash(f"Format d'image non autorisé. Formats acceptés : "
                  f"{', '.join(sorted(ALLOWED_PHOTO_EXTENSIONS))}.", 'error')
            return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))

        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
        nom_fichier = f"staff_{personnel_id}_{ts}.{ext}"

        ancien = conn.execute("SELECT photo FROM personnel_hors_prof WHERE id=?", (personnel_id,)).fetchone()
        if ancien and ancien['photo']:
            ancien_path = os.path.join(UPLOAD_FOLDER_PHOTOS, ancien['photo'])
            if os.path.exists(ancien_path):
                try:
                    os.remove(ancien_path)
                except OSError:
                    pass

        _sauvegarder_image_compressee(photo, os.path.join(UPLOAD_FOLDER_PHOTOS, nom_fichier), max_dimension=1000, qualite=82)
        conn.execute("UPDATE personnel_hors_prof SET photo=? WHERE id=?", (nom_fichier, personnel_id))
        conn.commit()
        log_action(conn, 'modification', 'personnel_hors_prof', personnel_id, 'Photo de profil mise à jour')
        flash('Photo de profil mise à jour !', 'success')
    finally:
        conn.close()
    return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))


