# ─── TRANSPORT SCOLAIRE : assignation des élèves à un chauffeur ───

@app.route('/parametres/ecole/adresse', methods=['POST'])
@login_required
@role_required('admin')
def parametres_ecole_adresse():
    """Enregistre l'adresse principale de l'école (point de départ commun à tous les chauffeurs)."""
    adresse = request.form.get('adresse_ecole', '').strip()
    chauffeur_id = request.form.get('chauffeur_id')

    lat, lon = geocoder_adresse(adresse) if adresse else (None, None)

    conn = get_db()
    conn.execute("UPDATE parametres_ecole SET adresse=?, latitude=?, longitude=? WHERE id=1", (adresse, lat, lon))
    conn.commit()
    conn.close()

    if not adresse:
        flash("Adresse de l'école effacée.", 'success')
    elif lat is not None:
        flash("📍 Adresse de l'école enregistrée et localisée avec succès.", 'success')
    else:
        flash("Adresse enregistrée, mais elle n'a pas pu être localisée. Vérifiez l'adresse ou utilisez des coordonnées GPS / un lien OpenStreetMap.", 'error')

    if chauffeur_id:
        return redirect(url_for('personnel_hors_prof_detail', personnel_id=chauffeur_id))
    return redirect(url_for('personnel_hors_prof'))


@app.route('/transport/<int:chauffeur_id>/geocoder', methods=['POST'])
@login_required
@role_required('admin')
def transport_geocoder(chauffeur_id):
    """
    Géocode (via OpenStreetMap / Nominatim) les adresses des élèves assignés à ce chauffeur
    qui n'ont pas encore de coordonnées GPS enregistrées, pour alimenter la carte du trajet.
    """
    conn = get_db()
    a_geocoder = conn.execute("""
                               SELECT e.id, COALESCE(NULLIF(e.adresse, ''), u.adresse) as adresse
                               FROM transport_eleves t
                                        JOIN eleves e ON t.eleve_id = e.id
                                        LEFT JOIN users u ON e.parent_id = u.id
                               WHERE t.chauffeur_id = ?
                                 AND (e.latitude IS NULL OR e.longitude IS NULL)
                                 AND COALESCE(NULLIF(e.adresse, ''), u.adresse) IS NOT NULL
                               """, (chauffeur_id,)).fetchall()

    nb_ok = 0
    premier_appel_reseau = True
    for e in a_geocoder:
        # Si l'utilisateur a saisi des coordonnées GPS / un lien OSM directement,
        # aucun appel réseau n'est nécessaire : pas besoin de délai dans ce cas.
        lat, lon = parser_coordonnees_ou_lien(e['adresse'])
        if lat is None:
            if not premier_appel_reseau:
                time.sleep(1)  # ⚠️ Politique d'usage Nominatim : 1 requête/seconde maximum
            premier_appel_reseau = False
            lat, lon = geocoder_adresse(e['adresse'])
        if lat is not None and lon is not None:
            conn.execute("UPDATE eleves SET latitude=?, longitude=? WHERE id=?", (lat, lon, e['id']))
            nb_ok += 1
    conn.commit()
    conn.close()

    if not a_geocoder:
        flash("Toutes les adresses disponibles sont déjà localisées (ou aucune adresse n'est renseignée).", 'success')
    elif nb_ok == len(a_geocoder):
        flash(f"{nb_ok} adresse(s) localisée(s) avec succès sur la carte !", 'success')
    else:
        flash(f"{nb_ok} adresse(s) localisée(s) sur {len(a_geocoder)}. Vérifiez l'orthographe des adresses non trouvées.",
              'success' if nb_ok else 'error')

    return redirect(url_for('personnel_hors_prof_detail', personnel_id=chauffeur_id))


@app.route('/transport/assigner', methods=['POST'])
@login_required
@role_required('admin')
def transport_assigner():
    chauffeur_id = request.form.get('chauffeur_id')
    eleve_id = request.form.get('eleve_id')
    conn = get_db()
    if chauffeur_id and eleve_id:
        eleve = conn.execute("SELECT nom, prenom, transport_abonne FROM eleves WHERE id=?", (eleve_id,)).fetchone()
        if not eleve:
            flash("Cet élève n'existe pas ou a été supprimé.", 'error')
        elif eleve['transport_abonne'] != 'oui':
            flash(f"{eleve['prenom']} {eleve['nom']} n'est pas abonné au transport : modifiez sa fiche élève pour l'abonner avant de l'assigner.", 'error')
        else:
            # INSERT OR REPLACE : si l'élève avait déjà un chauffeur, il est simplement réassigné.
            conn.execute("INSERT OR REPLACE INTO transport_eleves (eleve_id, chauffeur_id) VALUES (?, ?)",
                         (eleve_id, chauffeur_id))
            conn.commit()
            log_action(conn, 'modification', 'personnel_hors_prof', chauffeur_id,
                       f"Élève assigné au transport : {eleve['prenom']} {eleve['nom']}")
