@app.route('/api/chauffeur/position', methods=['POST'])
@login_required
@role_required('chauffeur')
def api_chauffeur_position():
    """Reçoit la position GPS envoyée régulièrement par le téléphone du chauffeur (JS geolocation)."""
    data = request.get_json(silent=True) or {}
    lat, lon = data.get('lat'), data.get('lon')
    if lat is None or lon is None:
        return jsonify({'erreur': 'Coordonnées manquantes.'}), 400
    try:
        lat, lon = float(lat), float(lon)
    except (TypeError, ValueError):
        return jsonify({'erreur': 'Coordonnées invalides.'}), 400

    conn = get_db()
    conn.execute(
        "UPDATE personnel_hors_prof SET position_lat=?, position_lon=?, position_maj_le=CURRENT_TIMESTAMP WHERE id=?",
        (lat, lon, session['user_id'])
    )

    # 🆕 Si un trajet (aller/retour) est en cours pour ce chauffeur, on accumule la distance
    # réellement parcourue depuis la dernière position connue. On ignore les sauts aberrants
    # (> 2 km entre deux envois, ~ toutes les quelques secondes) qui trahissent un problème GPS
    # plutôt qu'un vrai déplacement, pour ne pas fausser le kilométrage.
    trajet = conn.execute(
        "SELECT id, distance_km, dernier_lat, dernier_lon FROM chauffeur_trajets "
        "WHERE chauffeur_id=? AND actif=1 ORDER BY id DESC LIMIT 1",
        (session['user_id'],)
    ).fetchone()
    if trajet:
        nouvelle_distance = trajet['distance_km']
        if trajet['dernier_lat'] is not None and trajet['dernier_lon'] is not None:
            saut = distance_km(trajet['dernier_lat'], trajet['dernier_lon'], lat, lon)
            if saut <= 2.0:
                nouvelle_distance += saut
        conn.execute(
            "UPDATE chauffeur_trajets SET distance_km=?, dernier_lat=?, dernier_lon=?, fin_le=CURRENT_TIMESTAMP WHERE id=?",
            (round(nouvelle_distance, 3), lat, lon, trajet['id'])
        )
        # 🆕 On enregistre également ce point dans l'historique GPS du trajet (déjà limité à
        # 1 envoi/15s côté téléphone du chauffeur, donc pas de risque de saturer la base), afin
        # de pouvoir retracer le chemin exact parcouru sur la carte de suivi admin.
        conn.execute(
            "INSERT INTO transport_positions_trajet (trajet_id, lat, lon) VALUES (?,?,?)",
            (trajet['id'], lat, lon)
        )

    conn.commit()
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/chauffeur/trajet-debut', methods=['POST'])
@login_required
@role_required('chauffeur')
def api_chauffeur_trajet_debut():
    """Démarre le suivi d'un trajet (aller ou retour) pour le chauffeur connecté, déclenché
    quand il active le partage de position. S'il avait laissé un trajet actif (ex : partage
    coupé sans repasser par le bouton), on le clôture d'abord proprement."""
    data = request.get_json(silent=True) or {}
    type_trajet = data.get('type_trajet') if data.get('type_trajet') in ('aller', 'retour') else 'aller'

    conn = get_db()
    conn.execute(
        "UPDATE chauffeur_trajets SET actif=0, fin_le=CURRENT_TIMESTAMP WHERE chauffeur_id=? AND actif=1",
        (session['user_id'],)
    )
    chauffeur = conn.execute(
        "SELECT position_lat, position_lon FROM personnel_hors_prof WHERE id=?", (session['user_id'],)
    ).fetchone()
    cur = conn.execute(
        "INSERT INTO chauffeur_trajets (chauffeur_id, type_trajet, date_trajet, distance_km, dernier_lat, dernier_lon, actif) "
        "VALUES (?, ?, date('now'), 0, ?, ?, 1)",
        (session['user_id'], type_trajet,
         chauffeur['position_lat'] if chauffeur else None,
         chauffeur['position_lon'] if chauffeur else None)
    )
    conn.commit()
    trajet_id = cur.lastrowid
    conn.close()
    return jsonify({'ok': True, 'trajet_id': trajet_id})


