@app.route('/api/admin/historique-trajets')
@login_required
@role_required('admin')
def api_admin_historique_trajets():
    """Historique des trajets chauffeurs pour l'admin, filtrable par chauffeur, par jour et
    par sens de trajet (aller/retour). Utilisé par le panneau 'Historique trajet' de la page
    de suivi des chauffeurs."""
    chauffeur_id = request.args.get('chauffeur_id', type=int)
    date_filtre = request.args.get('date', '').strip()
    type_filtre = request.args.get('type_trajet', '').strip()

    sql = """
        SELECT t.id, t.chauffeur_id, t.type_trajet, t.date_trajet, t.distance_km,
               t.actif, t.debut_le, t.fin_le,
               p.nom AS chauffeur_nom, p.prenom AS chauffeur_prenom
        FROM chauffeur_trajets t
        JOIN personnel_hors_prof p ON p.id = t.chauffeur_id
        WHERE 1=1
    """
    params = []
    if chauffeur_id:
        sql += " AND t.chauffeur_id=?"
        params.append(chauffeur_id)
    if date_filtre:
        sql += " AND t.date_trajet=?"
        params.append(date_filtre)
    if type_filtre in ('aller', 'retour'):
        sql += " AND t.type_trajet=?"
        params.append(type_filtre)
    sql += " ORDER BY t.date_trajet DESC, t.debut_le DESC LIMIT 300"

    conn = get_db()
    rows = conn.execute(sql, params).fetchall()
    conn.close()

    trajets = [{
        'id': r['id'],
        'chauffeur_id': r['chauffeur_id'],
        'chauffeur_nom': f"{r['chauffeur_prenom']} {r['chauffeur_nom']}",
        'type_trajet': r['type_trajet'],
        'date_trajet': r['date_trajet'],
        'distance_km': round(r['distance_km'] or 0, 2),
        'actif': bool(r['actif']),
        'debut_le': r['debut_le'],
        'fin_le': r['fin_le'],
    } for r in rows]
    return jsonify({'trajets': trajets})


@app.route('/api/admin/trajet-trace/<int:trajet_id>')
@login_required
@role_required('admin')
def api_admin_trajet_trace(trajet_id):
    """🆕 Renvoie la trace GPS (liste de points [lat, lon]) d'un trajet donné, pour l'afficher
    sur la carte de /suivi-chauffeurs. Si le trajet a déjà été archivé (nuit précédente,
    voir tache_archiver_historique_trajets_24h), on lit directement la trace compactée
    (trace_json) ; sinon (trajet du jour, pas encore archivé) on reconstitue le tracé en
    direct à partir des points bruts déjà reçus."""
    conn = get_db()
    trajet = conn.execute("""
        SELECT t.id, t.type_trajet, t.date_trajet, t.distance_km, t.trace_json,
               p.nom AS chauffeur_nom, p.prenom AS chauffeur_prenom
        FROM chauffeur_trajets t
        JOIN personnel_hors_prof p ON p.id = t.chauffeur_id
        WHERE t.id=?
    """, (trajet_id,)).fetchone()
    if not trajet:
        conn.close()
        return jsonify({'erreur': 'Trajet introuvable.'}), 404

    if trajet['trace_json'] is not None:
        points = json.loads(trajet['trace_json'])
    else:
        rows = conn.execute(
            "SELECT lat, lon FROM transport_positions_trajet WHERE trajet_id=? ORDER BY horodatage ASC",
            (trajet_id,)
        ).fetchall()
        points = [[r['lat'], r['lon']] for r in rows]
    conn.close()

    return jsonify({
        'trajet_id': trajet['id'],
        'chauffeur_nom': f"{trajet['chauffeur_prenom']} {trajet['chauffeur_nom']}",
        'type_trajet': trajet['type_trajet'],
        'date_trajet': trajet['date_trajet'],
        'distance_km': round(trajet['distance_km'] or 0, 2),
        'points': points,
    })


@app.route('/api/admin/chauffeurs-position')
@login_required
@role_required('admin')
def api_admin_chauffeurs_position():
    """Renvoie la dernière position connue de chaque chauffeur, pour la carte de suivi en direct,
    ainsi que les élèves qui lui sont assignés (avec leur emplacement) et une détection en direct
    de l'arrivée du chauffeur chez chaque élève (distance chauffeur ↔ élève < ARRIVEE_ELEVE_SEUIL_KM)."""
    conn = get_db()
    rows = conn.execute("""
                         SELECT id, nom, prenom, email, position_lat, position_lon, position_maj_le,
                                statut_chauffeur, vehicule_immatriculation, vehicule_modele,
                                vehicule_capacite, permis_expiration, photo
                         FROM personnel_hors_prof
                         WHERE mission = 'Chauffeur'
                         ORDER BY nom, prenom
                         """).fetchall()
    ecole = get_ecole_coords(conn)

    maintenant = datetime.datetime.now()
    aujourdhui_str = maintenant.date().isoformat()
    permis_alerte_str = (maintenant.date() + datetime.timedelta(days=30)).isoformat()
    chauffeurs = []
    evenements_jour = []  # 🆕 timeline du jour, construite à partir de données réelles (chauffeur_trajets)

    for r in rows:
        en_ligne = False
        if r['position_maj_le']:
            try:
                maj = datetime.datetime.strptime(r['position_maj_le'], '%Y-%m-%d %H:%M:%S.%f')
            except ValueError:
                try:
                    maj = datetime.datetime.strptime(r['position_maj_le'], '%Y-%m-%d %H:%M:%S')
                except ValueError:
                    maj = None
            if maj:
                en_ligne = (maintenant - maj).total_seconds() < 180  # "en ligne" si maj il y a < 3 min

        # 🆕 Élèves assignés à ce chauffeur, avec leur emplacement, pour les afficher sur la carte
        # de suivi admin, et détecter en direct si le chauffeur vient d'arriver chez l'un d'eux.
        donnees_trajet = construire_donnees_trajet_chauffeur(r['id'], conn)
        eleves_suivi = []
        nb_eleves_a_bord = 0
        for e in donnees_trajet['eleves_carte']:
            arrive = False
            distance_actuelle_km = None
            if r['position_lat'] is not None and r['position_lon'] is not None:
                distance_actuelle_km = round(
                    distance_km(r['position_lat'], r['position_lon'], e['lat'], e['lon']), 3)
                arrive = distance_actuelle_km <= ARRIVEE_ELEVE_SEUIL_KM
                if arrive:
                    nb_eleves_a_bord += 1
            eleves_suivi.append({
                'id': e['id'],
                'nom': e['nom'],
                'adresse': e['adresse'],
                'lat': e['lat'],
                'lon': e['lon'],
                'arrive': arrive,
                'distance_actuelle_km': distance_actuelle_km,
            })

        # 🆕 Distance parcourue aujourd'hui par ce chauffeur (somme de ses trajets aller/retour du jour).
        distance_jour = conn.execute(
            "SELECT COALESCE(SUM(distance_km), 0) AS total FROM chauffeur_trajets "
            "WHERE chauffeur_id=? AND date_trajet=date('now')",
            (r['id'],)
        ).fetchone()['total']

        # 🆕 Trajet en cours (aller/retour), s'il y en a un actif — pour le panneau détail
        trajet_actif = conn.execute(
            "SELECT type_trajet, debut_le FROM chauffeur_trajets WHERE chauffeur_id=? AND actif=1 "
            "ORDER BY id DESC LIMIT 1", (r['id'],)
        ).fetchone()

        # 🆕 Alerte permis, calculée uniquement si une date d'expiration a été saisie (donnée réelle)
        alerte_permis = None
        if r['permis_expiration']:
            if r['permis_expiration'] < aujourdhui_str:
                alerte_permis = 'expire'
            elif r['permis_expiration'] <= permis_alerte_str:
                alerte_permis = 'bientot'

        # 🆕 Statut visuel de supervision, dérivé uniquement de faits réels et vérifiables :
        # compte suspendu/indisponible (saisie admin), permis expiré, hors ligne, ou normal.
        if r['statut_chauffeur'] == 'Suspendu':
            statut_visuel = 'suspendu'
        elif alerte_permis == 'expire':
            statut_visuel = 'alerte'
        elif r['statut_chauffeur'] == 'Indisponible':
            statut_visuel = 'indisponible'
        elif not en_ligne:
            statut_visuel = 'hors_ligne'
        else:
            statut_visuel = 'normal'

        chauffeurs.append({
            'id': r['id'],
            'nom': f"{r['prenom']} {r['nom']}",
            'lat': r['position_lat'],
            'lon': r['position_lon'],
            'maj_le': r['position_maj_le'],
            'en_ligne': en_ligne,
            'compte_actif': bool(r['email']),
            'eleves': eleves_suivi,
            'nb_eleves_a_bord': nb_eleves_a_bord,
            'distance_jour_km': round(distance_jour, 2),
            'statut_chauffeur': r['statut_chauffeur'] or 'Actif',
            'statut_visuel': statut_visuel,
            'vehicule_immatriculation': r['vehicule_immatriculation'],
            'vehicule_modele': r['vehicule_modele'],
            'vehicule_capacite': r['vehicule_capacite'],
            'alerte_permis': alerte_permis,
            'permis_expiration': r['permis_expiration'],
            'photo': r['photo'],
            'trajet_en_cours': dict(trajet_actif) if trajet_actif else None,
        })

        # Événements de la timeline du jour, à partir des trajets réellement démarrés/terminés
        trajets_du_jour = conn.execute(
            "SELECT type_trajet, debut_le, fin_le FROM chauffeur_trajets "
            "WHERE chauffeur_id=? AND date_trajet=date('now') ORDER BY id",
            (r['id'],)
        ).fetchall()
        nom_chauffeur = f"{r['prenom']} {r['nom']}"
        for t in trajets_du_jour:
            libelle_sens = 'aller' if t['type_trajet'] == 'aller' else 'retour'
            if t['debut_le']:
                evenements_jour.append({
                    'heure': t['debut_le'][-8:] if len(t['debut_le']) >= 8 else t['debut_le'],
                    'horodatage': t['debut_le'],
                    'texte': f"{nom_chauffeur} a démarré le trajet {libelle_sens}"
                              + (f" ({r['vehicule_immatriculation']})" if r['vehicule_immatriculation'] else ''),
                })
            if t['fin_le']:
                evenements_jour.append({
                    'heure': t['fin_le'][-8:] if len(t['fin_le']) >= 8 else t['fin_le'],
                    'horodatage': t['fin_le'],
                    'texte': f"{nom_chauffeur} a terminé le trajet {libelle_sens}",
                })

    evenements_jour.sort(key=lambda ev: ev['horodatage'] or '', reverse=True)

    # 🆕 Distance totale (tous chauffeurs confondus) effectuée aujourd'hui — affichée dans
    # le carré récapitulatif en haut de la page de suivi.
    distance_totale_jour = conn.execute(
        "SELECT COALESCE(SUM(distance_km), 0) AS total FROM chauffeur_trajets WHERE date_trajet=date('now')"
    ).fetchone()['total']

    conn.close()
    return jsonify({
        'chauffeurs': chauffeurs,
        'ecole': dict(ecole) if ecole else None,
        'distance_totale_jour_km': round(distance_totale_jour, 2),
        'evenements_jour': evenements_jour[:20],
    })


@app.route('/suivi-chauffeurs')
@login_required
@role_required('admin')
def suivi_chauffeurs():
    """Dashboard de suivi en temps réel : localisation de tous les chauffeurs, statistiques
    globales du transport scolaire (élèves abonnés, distances, revenu), vue admin uniquement."""
    conn = get_db()
    chauffeurs = conn.execute(
        "SELECT * FROM personnel_hors_prof WHERE mission='Chauffeur' ORDER BY nom, prenom"
    ).fetchall()
    ecole = get_ecole_coords(conn)

    # 🆕 Indicateurs du tableau de bord ────────────────────────────────
    nb_eleves_abonnes = conn.execute(
        "SELECT COUNT(*) FROM eleves WHERE transport_abonne='oui'"
    ).fetchone()[0]
    nb_eleves_assignes = conn.execute(
        "SELECT COUNT(DISTINCT eleve_id) FROM transport_eleves"
    ).fetchone()[0]
    revenu_transport_mensuel = conn.execute(
        "SELECT COALESCE(SUM(montant_transport),0) FROM eleves WHERE transport_abonne='oui'"
    ).fetchone()[0]
    distance_totale_jour = conn.execute(
        "SELECT COALESCE(SUM(distance_km),0) FROM chauffeur_trajets WHERE date_trajet=date('now')"
    ).fetchone()[0]

    # Distance totale estimée (somme des trajets complets École ↔ élèves, tous chauffeurs)
    # et nombre de chauffeurs actuellement en ligne (position reçue il y a moins de 3 min).
    distance_totale_estimee = 0.0
    nb_chauffeurs_en_ligne = 0
    maintenant = datetime.datetime.now()
    for c in chauffeurs:
        donnees_trajet = construire_donnees_trajet_chauffeur(c['id'], conn)
        if donnees_trajet['distance_totale_trajet']:
            distance_totale_estimee += donnees_trajet['distance_totale_trajet']
        if c['position_maj_le']:
            try:
                maj = datetime.datetime.strptime(c['position_maj_le'], '%Y-%m-%d %H:%M:%S.%f')
            except ValueError:
                try:
                    maj = datetime.datetime.strptime(c['position_maj_le'], '%Y-%m-%d %H:%M:%S')
                except ValueError:
                    maj = None
            if maj and (maintenant - maj).total_seconds() < 180:
                nb_chauffeurs_en_ligne += 1

    conn.close()
    return render_template_string(
        SUIVI_CHAUFFEURS_HTML,
        chauffeurs=chauffeurs,
        ecole=ecole,
        notif_count=get_notif_count(),
        nb_eleves_abonnes=nb_eleves_abonnes,
        nb_eleves_assignes=nb_eleves_assignes,
        revenu_transport_mensuel=revenu_transport_mensuel,
        distance_totale_jour=round(distance_totale_jour, 2),
        distance_totale_estimee=round(distance_totale_estimee, 1),
        nb_chauffeurs_en_ligne=nb_chauffeurs_en_ligne,
    )


# ─────────────────────────────────────────────
# 🆕 HISTORIQUE / JOURNAL D'AUDIT (admin uniquement)
# ─────────────────────────────────────────────
# Traduction technique -> libellé lisible pour la colonne "Page / Section"
HISTORIQUE_PAGES = {
    'note': 'Notes',
    'paiement': 'Paiements (Élèves)',
    'paiement_enseignant': 'Paiements (Enseignants)',
    'paiements_generation': 'Paiements (Génération auto)',
    'paiements_reset': 'Paiements (Reset mensuel)',
    'paiement_personnel_hors_prof': 'Paiements (Personnel hors-prof)',
    'personnel_hors_prof': 'Personnel hors-prof',
    'eleve': 'Élèves',
    'absence': 'Absences',
    'charge': 'Charges (École)',
    'classe': 'Classes',
    'matiere': 'Matières',
    'utilisateur': 'Utilisateurs',
}
HISTORIQUE_ACTIONS_LABELS = {
    'creation': 'Création',
    'modification': 'Modification',
    'suppression': 'Suppression',
}


@app.route('/historique', methods=['GET'])
@login_required
@role_required('admin')
def historique():
    """🆕 Journal d'audit centralisé : qui a fait quoi, sur quelle page, et quand.
    Couvre les notes, paiements (élèves + enseignants), fiches élèves, absences, charges,
    classes, matières et comptes utilisateurs."""
    # 🆕 AGENT ADMIN : n'a pas accès à l'historique / traçabilité (réservé à l'admin)
    if session.get('role') == 'agent_admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))

    conn = get_db()

    page_filter = request.args.get('page', '').strip()
    action_filter = request.args.get('type_action', '').strip()
    user_filter = request.args.get('utilisateur', '').strip()
    q = request.args.get('q', '').strip()
    date_debut = request.args.get('date_debut', '').strip()
    date_fin = request.args.get('date_fin', '').strip()

    where_clauses = []
    params = []

    if page_filter:
        where_clauses.append("cible_type = ?")
        params.append(page_filter)
    if action_filter:
        where_clauses.append("action = ?")
        params.append(action_filter)
    if user_filter:
        where_clauses.append("user_nom LIKE ?")
        params.append(f"%{user_filter}%")
    if q:
        where_clauses.append("(details LIKE ? OR user_nom LIKE ?)")
        params.append(f"%{q}%")
        params.append(f"%{q}%")
    if date_debut:
        where_clauses.append("date(date_action) >= date(?)")
        params.append(date_debut)
    if date_fin:
        where_clauses.append("date(date_action) <= date(?)")
        params.append(date_fin)

    where_sql = ("WHERE " + " AND ".join(where_clauses)) if where_clauses else ""

    # Pagination simple (les 200 dernières actions par défaut, un journal peut vite devenir long)
    try:
        limite = min(int(request.args.get('limite', 200)), 1000)
    except ValueError:
        limite = 200

    try:
        lignes = conn.execute(
            f"SELECT * FROM historique_actions {where_sql} ORDER BY date_action DESC LIMIT ?",
            params + [limite]
        ).fetchall()
        total_count = conn.execute(f"SELECT COUNT(*) FROM historique_actions {where_sql}", params).fetchone()[0]
    except sqlite3.OperationalError:
        lignes = []
        total_count = 0

    # Liste des utilisateurs distincts ayant une action tracée (pour le filtre déroulant)
    try:
        utilisateurs_distincts = [r['user_nom'] for r in
                                   conn.execute("SELECT DISTINCT user_nom FROM historique_actions "
                                                "WHERE user_nom IS NOT NULL AND user_nom != '' ORDER BY user_nom").fetchall()]
    except sqlite3.OperationalError:
        utilisateurs_distincts = []

    conn.close()

    historique_data = []
    for l in lignes:
        d = dict(l)
        d['page_libelle'] = HISTORIQUE_PAGES.get(d['cible_type'], d['cible_type'] or 'Autre')
        d['action_libelle'] = HISTORIQUE_ACTIONS_LABELS.get(d['action'], d['action'] or '—')
        historique_data.append(d)

    return render_template_string(
        HISTORIQUE_HTML,
        historique=historique_data,
        total_count=total_count,
        limite=limite,
        pages_dispo=HISTORIQUE_PAGES,
        actions_dispo=HISTORIQUE_ACTIONS_LABELS,
        utilisateurs_distincts=utilisateurs_distincts,
        filtres={
            'page': page_filter, 'type_action': action_filter, 'utilisateur': user_filter,
            'q': q, 'date_debut': date_debut, 'date_fin': date_fin,
        },
        notif_count=get_notif_count()
    )


