# WHATSAPP — RAPPELS PAIEMENT
# ─────────────────────────────────────────────
@app.route('/whatsapp/rappels', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def whatsapp_rappels():
    """Page admin : envoyer manuellement les rappels WhatsApp aux parents impayés."""
    conn = get_db()

    if request.method == 'POST':
        action = request.form.get('action')

        # Mise à jour du numéro de téléphone d'un parent
        if action == 'update_tel':
            user_id = request.form.get('user_id')
            tel = request.form.get('telephone', '').strip()
            conn.execute("UPDATE users SET telephone=? WHERE id=?", (tel, user_id))
            conn.commit()
            flash('Numéro mis à jour.', 'success')
            conn.close()
            return redirect(url_for('whatsapp_rappels'))

        # Les envois (rappels, message libre, fichier) ne passent plus par ici :
        # ils sont préparés par les endpoints JSON /whatsapp/api/... ci-dessous,
        # puis envoyés via WhatsApp Web (wa.me) directement dans le navigateur,
        # un contact à la fois, avec validation manuelle de l'utilisateur.

    # GET : liste des parents avec statut paiement
    parents_impayes = conn.execute("""
                                   SELECT u.id,
                                          u.nom,
                                          u.prenom,
                                          u.telephone,
                                          e.prenom || ' ' || e.nom              AS eleve_nom,
                                          SUM(p.montant_total - p.montant_paye) AS reste_total,
                                          COUNT(p.id)                           AS nb_impayes
                                   FROM paiements p
                                            JOIN eleves e ON p.eleve_id = e.id
                                            JOIN users u ON e.parent_id = u.id
                                   WHERE p.statut IN ('non_paye', 'partiel')
                                   GROUP BY u.id
                                   ORDER BY reste_total DESC
                                   """).fetchall()

    tous_parents = conn.execute(
        "SELECT id, nom, prenom, telephone FROM users WHERE role='parent' ORDER BY nom"
    ).fetchall()

    # NOUVEAU — Filtres Cycle / Classe pour les onglets "Message" et "Fichier"
    cycle_sel = request.args.get('cycle', '')
    classe_sel = request.args.get('classe_id', '')
    tab_actif = request.args.get('tab', 'rappels')

    cycles_dispo = [r['cycle'] for r in conn.execute(
        "SELECT DISTINCT cycle FROM classes WHERE cycle IS NOT NULL AND cycle != '' ORDER BY cycle"
    ).fetchall()]

    if cycle_sel:
        classes_dispo = conn.execute(
            "SELECT id, nom, niveau, cycle FROM classes WHERE cycle=? ORDER BY niveau, nom", (cycle_sel,)
        ).fetchall()
    else:
        classes_dispo = conn.execute(
            "SELECT id, nom, niveau, cycle FROM classes ORDER BY cycle, niveau, nom"
        ).fetchall()

    # Liste des parents (un parent = une ligne, même s'il a plusieurs enfants dans le filtre)
    query_parents = """
        SELECT u.id, u.nom, u.prenom, u.telephone,
               GROUP_CONCAT(DISTINCT e.prenom || ' ' || e.nom) AS enfants,
               GROUP_CONCAT(DISTINCT c.nom)                    AS classes_noms
        FROM users u
                 JOIN eleves e ON e.parent_id = u.id
                 JOIN classes c ON e.classe_id = c.id
        WHERE u.role = 'parent'
    """
    params_parents = []
    if classe_sel:
        query_parents += " AND c.id = ?"
        params_parents.append(classe_sel)
    elif cycle_sel:
        query_parents += " AND c.cycle = ?"
        params_parents.append(cycle_sel)
    query_parents += " GROUP BY u.id ORDER BY u.nom, u.prenom"
    parents_filtres = conn.execute(query_parents, params_parents).fetchall()

    conn.close()
    return render_template_string(WHATSAPP_HTML,
                                  parents_impayes=parents_impayes,
                                  tous_parents=tous_parents,
                                  parents_filtres=parents_filtres,
                                  cycles_dispo=cycles_dispo,
                                  classes_dispo=classes_dispo,
                                  cycle_sel=cycle_sel,
                                  classe_sel=classe_sel,
                                  tab_actif=tab_actif,
                                  notif_count=get_notif_count())


# ─────────────────────────────────────────────
# WHATSAPP WEB AUTOMATISÉ (Playwright) — endpoints JSON pour l'envoi
# Ces routes pilotent directement la session WhatsApp Web côté serveur
# (voir wa_bot / WhatsAppWebBot plus haut) : les messages et fichiers sont
# envoyés automatiquement, contact par contact, sans aucune action manuelle
# de l'administrateur (aucun onglet à ouvrir, aucun clic "Envoyer" à faire).
# ─────────────────────────────────────────────

def _envoyer_queue_messages(queue):
    """Envoie automatiquement, un par un, chaque message de la file via WhatsApp Web."""
    resultats = []
    for c in queue:
        ok, erreur = wa_bot.envoyer_message(c['telephone'], c['message'])
        resultats.append({
            'nom': c['nom'],
            'telephone': c['telephone'],
            'statut': 'ok' if ok else 'erreur',
            'erreur': '' if ok else erreur
        })
    return resultats


