# ABSENCES
# ─────────────────────────────────────────────
@app.route('/absences', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'enseignant', 'secretaire')
def absences():
    # 🆕 L'admin passe désormais par le hub (Enseignant / Élève / Salarié hors prof) plutôt
    # que par l'ancien formulaire à choix de cycle, réservé maintenant à l'enseignant.
    if session['role'] == 'admin' and request.method == 'GET':
        return redirect(url_for('absences_hub'))

    conn = get_db()

    # 🆕 NOUVEAU PARCOURS ENSEIGNANT / SECRÉTAIRE : au lieu de l'ancien formulaire manuel
    # (choisir un élève dans une liste déroulante + date + case "justifiée"), on voit
    # uniquement SES classes assignées sous forme de cartes. On clique sur une classe →
    # tableau des élèves → clique sur un élève pour le marquer absent (voir
    # /absences/classe/<id> et /api/absences/toggle ci-dessous, qui gèrent tout
    # automatiquement sans bouton "enregistrer"). La secrétaire est scopée via
    # classe_secretaires plutôt que classe_profs (voir _classes_assignees_role).
    if session['role'] in ('enseignant', 'secretaire') and request.method == 'GET':
        classes_prof = _classes_assignees_role(conn, session['role'], session['user_id'])
        conn.close()
        return render_template_string(ABSENCES_PROF_CLASSES_HTML, classes=classes_prof,
                                      notif_count=get_notif_count())

    # Récupération du cycle actif (par défaut 'Primaire' si aucun n'est spécifié)
    cycle = request.form.get('cycle') or request.args.get('cycle', 'Primaire')

    if request.method == 'POST':
        f = request.form
        conn.execute("INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                     (f['eleve_id'], f['date_absence'], 1 if f.get('justifiee') else 0, f.get('motif', ''),
                      session['user_id']))
        eleve = conn.execute("SELECT parent_id, prenom||' '||nom as nom FROM eleves WHERE id=?",
                             (f['eleve_id'],)).fetchone()
        if eleve and eleve['parent_id']:
            just = "justifiée" if f.get('justifiee') else "non justifiée"
            notif_to_parent(eleve['parent_id'], f"Absence {just} signalée pour {eleve['nom']} le {f['date_absence']}.",
                            conn)
        conn.commit()
        flash('Absence enregistrée!', 'success')

    if session['role'] in ('enseignant', 'secretaire'):
        # Filtrage des élèves et absences de l'enseignant/secrétaire selon le cycle actif
        table, col = ('classe_profs', 'enseignant_id') if session['role'] == 'enseignant' else ('classe_secretaires', 'secretaire_id')
        eleves_list = conn.execute(
            f"SELECT e.*, c.nom as classe FROM eleves e JOIN classes c ON e.classe_id=c.id WHERE EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?) AND (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) ORDER BY e.nom",
            (session['user_id'], cycle, cycle)).fetchall()
        absences_list = conn.execute(
            f"SELECT a.*, e.prenom||' '||e.nom as eleve FROM absences a JOIN eleves e ON a.eleve_id=e.id JOIN classes c ON e.classe_id=c.id WHERE EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?) AND (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) ORDER BY a.date_absence DESC",
            (session['user_id'], cycle, cycle)).fetchall()
    else:
        # Filtrage global (Admin) selon le cycle actif
        eleves_list = conn.execute(
            "SELECT e.*, c.nom as classe FROM eleves e JOIN classes c ON e.classe_id=c.id WHERE c.cycle=? OR (c.cycle IS NULL AND ?='Primaire') ORDER BY e.nom",
            (cycle, cycle)).fetchall()
        absences_list = conn.execute(
            "SELECT a.*, e.prenom||' '||e.nom as eleve FROM absences a JOIN eleves e ON a.eleve_id=e.id JOIN classes c ON e.classe_id=c.id WHERE c.cycle=? OR (c.cycle IS NULL AND ?='Primaire') ORDER BY a.date_absence DESC",
            (cycle, cycle)).fetchall()

    conn.close()
    return render_template_string(ABSENCES_HTML, eleves=eleves_list, absences=absences_list,
                                  notif_count=get_notif_count(), cycle=cycle)


# 🆕 ─────────────────────────────────────────────
# ABSENCES — PARCOURS ENSEIGNANT (classe → tableau élèves cliquable, tout automatique)
# ─────────────────────────────────────────────
@app.route('/absences/classe/<int:classe_id>')
@login_required
@role_required('enseignant', 'secretaire')
def absences_classe_prof(classe_id):
    """🆕 Tableau élégant des élèves d'UNE classe assignée à l'enseignant (ou à la secrétaire).
    Cliquer sur une ligne marque/annule l'absence du JOUR pour cet élève, automatiquement
    (AJAX), sans bouton "enregistrer" — voir /api/absences/toggle."""
    conn = get_db()
    table, col = ('classe_profs', 'enseignant_id') if session['role'] == 'enseignant' else ('classe_secretaires', 'secretaire_id')
    autorise = conn.execute(
        f"SELECT 1 FROM {table} WHERE classe_id=? AND {col}=?",
        (classe_id, session['user_id'])).fetchone()
    if not autorise:
        conn.close()
        flash("Vous n'êtes pas assigné à cette classe.", 'error')
        return redirect(url_for('absences'))
    classe = conn.execute("SELECT * FROM classes WHERE id=?", (classe_id,)).fetchone()
    if not classe:
        conn.close()
        abort(404)
    aujourdhui = datetime.date.today().isoformat()
    eleves_list = conn.execute(
        "SELECT * FROM eleves WHERE classe_id=? ORDER BY nom, prenom", (classe_id,)).fetchall()
    absents_ids = {r['eleve_id'] for r in conn.execute(
        "SELECT eleve_id FROM absences WHERE date_absence=? AND eleve_id IN (SELECT id FROM eleves WHERE classe_id=?)",
        (aujourdhui, classe_id)).fetchall()}
    conn.close()
    return render_template_string(ABSENCES_PROF_TABLE_HTML, classe=classe, eleves=eleves_list,
                                  absents_ids=absents_ids, aujourdhui=aujourdhui,
                                  notif_count=get_notif_count())


@app.route('/api/absences/toggle', methods=['POST'])
@login_required
@role_required('enseignant', 'secretaire')
def api_absences_toggle():
    """🆕 Marque/annule automatiquement l'absence du JOUR d'un élève, en un clic (pas de
    formulaire, pas de bouton "enregistrer"). Vérifie que l'élève appartient bien à une classe
    assignée à l'enseignant (ou à la secrétaire) connecté avant toute écriture (sécurité)."""
    data = request.get_json(silent=True) or {}
    try:
        eleve_id = int(data.get('eleve_id'))
    except (TypeError, ValueError):
        return jsonify({'error': "eleve_id manquant ou invalide"}), 400

    conn = get_db()
    table, col = ('classe_profs', 'enseignant_id') if session['role'] == 'enseignant' else ('classe_secretaires', 'secretaire_id')
    eleve = conn.execute(
        f"SELECT e.id, e.prenom, e.nom, e.parent_id FROM eleves e JOIN classes c ON e.classe_id=c.id "
        f"WHERE e.id=? AND EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?)",
        (eleve_id, session['user_id'])).fetchone()
    if not eleve:
        conn.close()
        return jsonify({'error': "Élève introuvable ou non autorisé pour cet enseignant."}), 403

    aujourdhui = datetime.date.today().isoformat()
    existante = conn.execute(
        "SELECT id FROM absences WHERE eleve_id=? AND date_absence=?",
        (eleve_id, aujourdhui)).fetchone()

    if existante:
        # 2e clic → on annule l'absence marquée précédemment aujourd'hui.
        conn.execute("DELETE FROM absences WHERE id=?", (existante['id'],))
        conn.commit()
        conn.close()
        return jsonify({'absent': False, 'eleve_id': eleve_id})
    else:
        # 1er clic → on marque l'élève absent aujourd'hui (non justifiée par défaut ; l'admin ou
        # l'enseignant peut la justifier plus tard depuis la fiche élève si besoin).
        conn.execute(
            "INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,0,?,?)",
            (eleve_id, aujourdhui, '', session['user_id']))
        conn.commit()
        if eleve['parent_id']:
            notif_to_parent(eleve['parent_id'],
                            f"Absence signalée pour {eleve['prenom']} {eleve['nom']} le {aujourdhui}.", conn)
            conn.commit()
        conn.close()
        return jsonify({'absent': True, 'eleve_id': eleve_id})


