@app.route('/absences/dashboard/<type_hub>')
@login_required
@role_required('admin')
def absences_dashboard(type_hub):
    """🆕 Dashboard d'un type d'absence : stats rapides + analyse (courbe d'évolution par
    période + camembert de répartition) + 2 boutons (Marquer un absent / Historique complet)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    conn = get_db()

    # 🆕 Courbe d'évolution des absences sur les 6 derniers mois (commune aux 3 types).
    table_par_type = {'eleve': 'absences', 'enseignant': 'absences_enseignants', 'personnel': 'absences_personnel'}
    table = table_par_type[type_hub]
    mois_labels, mois_valeurs = [], []
    for i in range(5, -1, -1):
        d = datetime.date.today().replace(day=1) - datetime.timedelta(days=i * 30)
        cle_mois = d.strftime('%Y-%m')
        nb = conn.execute(
            f"SELECT COUNT(*) FROM {table} WHERE strftime('%Y-%m', date_absence)=?", (cle_mois,)).fetchone()[0]
        mois_labels.append(d.strftime('%b %Y'))
        mois_valeurs.append(nb)

    if type_hub == 'eleve':
        total = conn.execute("SELECT COUNT(*) FROM absences").fetchone()[0]
        justifiees = conn.execute("SELECT COUNT(*) FROM absences WHERE justifiee=1").fetchone()[0]
        top = conn.execute("""
            SELECT e.prenom||' '||e.nom as nom, c.nom as sous_titre, COUNT(a.id) as nb
            FROM absences a JOIN eleves e ON a.eleve_id=e.id
            LEFT JOIN classes c ON e.classe_id=c.id
            GROUP BY a.eleve_id ORDER BY nb DESC LIMIT 5
        """).fetchall()
        ce_mois = conn.execute(
            "SELECT COUNT(*) FROM absences WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
        # 🆕 Camembert : répartition des absences PAR CLASSE
        repartition = conn.execute("""
            SELECT COALESCE(c.niveau || ' ' || c.nom, 'Sans classe') as label, COUNT(a.id) as nb
            FROM absences a JOIN eleves e ON a.eleve_id=e.id
            LEFT JOIN classes c ON e.classe_id=c.id
            GROUP BY c.id ORDER BY nb DESC
        """).fetchall()
        repartition_titre = "Répartition des absences par classe"
    elif type_hub == 'enseignant':
        total = conn.execute("SELECT COUNT(*) FROM absences_enseignants").fetchone()[0]
        justifiees = conn.execute("SELECT COUNT(*) FROM absences_enseignants WHERE justifiee=1").fetchone()[0]
        top = conn.execute("""
            SELECT u.prenom||' '||u.nom as nom, 'Enseignant' as sous_titre, COUNT(a.id) as nb
            FROM absences_enseignants a JOIN users u ON a.enseignant_id=u.id
            GROUP BY a.enseignant_id ORDER BY nb DESC LIMIT 5
        """).fetchall()
        ce_mois = conn.execute(
            "SELECT COUNT(*) FROM absences_enseignants WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
        # 🆕 Camembert : répartition PAR CLASSE prise en charge par l'enseignant absent
        # (un enseignant peut avoir plusieurs classes → chaque classe qu'il enseigne est comptée).
        repartition = conn.execute("""
            SELECT COALESCE(c.niveau || ' ' || c.nom, 'Classe non assignée') as label, COUNT(*) as nb
            FROM absences_enseignants a
            JOIN classe_profs cp ON cp.enseignant_id = a.enseignant_id
            LEFT JOIN classes c ON cp.classe_id = c.id
            GROUP BY c.id ORDER BY nb DESC
        """).fetchall()
        repartition_titre = "Répartition des absences par classe impactée"
    else:
        total = conn.execute("SELECT COUNT(*) FROM absences_personnel").fetchone()[0]
        justifiees = conn.execute("SELECT COUNT(*) FROM absences_personnel WHERE justifiee=1").fetchone()[0]
        top = conn.execute("""
            SELECT p.prenom||' '||p.nom as nom, p.mission as sous_titre, COUNT(a.id) as nb
            FROM absences_personnel a JOIN personnel_hors_prof p ON a.personnel_id=p.id
            GROUP BY a.personnel_id ORDER BY nb DESC LIMIT 5
        """).fetchall()
        ce_mois = conn.execute(
            "SELECT COUNT(*) FROM absences_personnel WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
        # 🆕 Camembert : répartition PAR MISSION (le personnel hors prof n'appartient pas à une classe)
        repartition = conn.execute("""
            SELECT COALESCE(p.mission, 'Non précisé') as label, COUNT(a.id) as nb
            FROM absences_personnel a JOIN personnel_hors_prof p ON a.personnel_id=p.id
            GROUP BY p.mission ORDER BY nb DESC
        """).fetchall()
        repartition_titre = "Répartition des absences par mission"
    conn.close()

    infos = ABSENCES_HUB_TYPES[type_hub]
    evolution_json = json.dumps({'labels': mois_labels, 'valeurs': mois_valeurs})
    repartition_json = json.dumps({
        'labels': [r['label'] for r in repartition],
        'valeurs': [r['nb'] for r in repartition],
    }, ensure_ascii=False)
    return render_template_string(ABSENCES_DASHBOARD_HTML, type_hub=type_hub, infos=infos,
                                  total=total, justifiees=justifiees, non_justifiees=total - justifiees,
                                  ce_mois=ce_mois, top=top, repartition_titre=repartition_titre,
                                  evolution_json=evolution_json, repartition_json=repartition_json,
                                  notif_count=get_notif_count())


@app.route('/absences/marquer/<type_hub>', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def absences_marquer(type_hub):
    """🆕 Formulaire de saisie d'une absence. La date est TOUJOURS celle du jour (calculée
    côté serveur, jamais reprise d'un éventuel champ envoyé par le client)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    conn = get_db()
    aujourdhui = datetime.date.today().isoformat()

    if request.method == 'POST':
        f = request.form
        entite_id = f.get('entite_id')
        if not entite_id:
            flash("Veuillez sélectionner une personne avant d'enregistrer.", 'error')
            conn.close()
            return redirect(url_for('absences_marquer', type_hub=type_hub))
        justifiee = 1 if f.get('justifiee') else 0
        motif = f.get('motif', '')
        if type_hub == 'eleve':
            conn.execute("INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                         (entite_id, aujourdhui, justifiee, motif, session['user_id']))
            eleve = conn.execute("SELECT parent_id, prenom||' '||nom as nom FROM eleves WHERE id=?",
                                 (entite_id,)).fetchone()
            if eleve and eleve['parent_id']:
                just = "justifiée" if justifiee else "non justifiée"
                notif_to_parent(eleve['parent_id'], f"Absence {just} signalée pour {eleve['nom']} le {aujourdhui}.", conn)
        elif type_hub == 'enseignant':
            conn.execute("INSERT INTO absences_enseignants (enseignant_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                         (entite_id, aujourdhui, justifiee, motif, session['user_id']))
        else:
            conn.execute("INSERT INTO absences_personnel (personnel_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                         (entite_id, aujourdhui, justifiee, motif, session['user_id']))
        conn.commit()
        conn.close()
        flash('Absence enregistrée !', 'success')
        return redirect(url_for('absences_marquer', type_hub=type_hub))

    classe_id = request.args.get('classe_id', type=int)
    q = (request.args.get('q') or '').strip()
    classes = []
    entites = []
    if type_hub == 'eleve':
        classes = conn.execute("SELECT * FROM classes ORDER BY niveau, nom").fetchall()
        if q:
            entites = conn.execute(
                "SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as sous_titre FROM eleves e "
                "LEFT JOIN classes c ON e.classe_id=c.id "
                "WHERE e.nom LIKE ? OR e.prenom LIKE ? ORDER BY e.nom",
                (f'%{q}%', f'%{q}%')).fetchall()
        elif classe_id:
            entites = conn.execute(
                "SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as sous_titre FROM eleves e "
                "LEFT JOIN classes c ON e.classe_id=c.id WHERE e.classe_id=? ORDER BY e.nom",
                (classe_id,)).fetchall()
    elif type_hub == 'enseignant':
        entites = conn.execute(
            "SELECT id, prenom||' '||nom as nom, 'Enseignant' as sous_titre FROM users WHERE role='enseignant' ORDER BY nom"
        ).fetchall()
    else:
        entites = conn.execute(
            "SELECT id, prenom||' '||nom as nom, mission as sous_titre FROM personnel_hors_prof ORDER BY nom"
        ).fetchall()
    conn.close()
    infos = ABSENCES_HUB_TYPES[type_hub]
    return render_template_string(ABSENCES_MARQUER_HTML, type_hub=type_hub, infos=infos,
                                  classes=classes, classe_id=classe_id, q=q, entites=entites,
                                  aujourdhui=aujourdhui, notif_count=get_notif_count())


