# ═══════════════════════════════════════════════════════════════
# 🆕 NOTIFICATIONS PUSH — service worker + abonnement/désabonnement
# ═══════════════════════════════════════════════════════════════
@app.route('/sw.js')
def service_worker_push():
    """Le fichier doit être servi à la racine du site (pas dans /static) pour que son
    scope couvre toute l'application."""
    js = """
self.addEventListener('install', function(event) { self.skipWaiting(); });
self.addEventListener('activate', function(event) { event.waitUntil(self.clients.claim()); });

self.addEventListener('push', function(event) {
  var data = {};
  try { data = event.data ? event.data.json() : {}; } catch (e) {}
  var titre = data.titre || 'Bright Kidz Private';
  var options = {
    body: data.corps || '',
    tag: 'ecole-test-notif',
    renotify: true,
    data: { url: data.url || '/notifications' }
  };
  event.waitUntil(self.registration.showNotification(titre, options));
});

self.addEventListener('notificationclick', function(event) {
  event.notification.close();
  var url = (event.notification.data && event.notification.data.url) || '/notifications';
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(clientList) {
      for (var i = 0; i < clientList.length; i++) {
        var client = clientList[i];
        if ('focus' in client) {
          client.navigate(url);
          return client.focus();
        }
      }
      if (clients.openWindow) return clients.openWindow(url);
    })
  );
});
"""
    return app.response_class(js, mimetype='application/javascript')


