@app.route('/api/push/subscribe', methods=['POST'])
@login_required
def api_push_subscribe():
    data = request.get_json(silent=True) or {}
    endpoint = data.get('endpoint')
    keys = data.get('keys') or {}
    p256dh = keys.get('p256dh')
    auth = keys.get('auth')
    if not endpoint or not p256dh or not auth:
        return jsonify({'ok': False, 'error': "Données d'abonnement incomplètes."}), 400
    conn = get_db()
    conn.execute("""
        INSERT INTO push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(endpoint) DO UPDATE SET
            user_id=excluded.user_id, p256dh=excluded.p256dh, auth=excluded.auth
    """, (session['user_id'], endpoint, p256dh, auth, request.headers.get('User-Agent', '')[:255]))
    conn.commit()
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/push/unsubscribe', methods=['POST'])
@login_required
def api_push_unsubscribe():
    data = request.get_json(silent=True) or {}
    endpoint = data.get('endpoint')
    conn = get_db()
    if endpoint:
        conn.execute("DELETE FROM push_subscriptions WHERE endpoint=? AND user_id=?",
                     (endpoint, session['user_id']))
        conn.commit()
    conn.close()
    return jsonify({'ok': True})


