# PAGE PARENT (dédiée)
# ─────────────────────────────────────────────
@app.route('/espace-parent', methods=['GET', 'POST'])
@login_required
def espace_parent():
    # 1. Vérification de sécurité : Autoriser admin, agent_admin et parent
    #    (🆕 agent_admin gère l'espace parent comme un admin, sauf les options avancées
    #    de rôle/suppression de compte qui restent réservées à l'admin strict)
    if session.get('role') not in ['parent', 'admin', 'agent_admin']:
        return "Accès non autorisé", 403

    conn = get_db()

    # --- Actions d'administration : modification des infos du parent / reset mot de passe ---
    if request.method == 'POST':
        if session.get('role') not in ('admin', 'agent_admin'):
            conn.close()
            flash("Action non autorisée.", "error")
            return redirect(url_for('espace_parent'))

        target_id = request.form.get('parent_id')
        action = request.form.get('action')

        # 🆕 Création d'un nouveau compte parent (accessible à admin ET agent_admin)
        if action == 'add_parent':
            nom = request.form.get('nom', '').strip()
            prenom = request.form.get('prenom', '').strip()
            email = request.form.get('email', '').strip()
            password = request.form.get('password', '').strip()
            telephone = request.form.get('telephone', '').strip()
            adresse = request.form.get('adresse', '').strip()

            if not nom or not prenom or not email or len(password) < 4:
                flash("Nom, prénom, email et mot de passe (4 caractères min.) sont requis.", "error")
            else:
                try:
                    conn.execute("""
                        INSERT INTO users (nom, prenom, email, password, role, telephone, adresse)
                        VALUES (?, ?, ?, ?, 'parent', ?, ?)
                    """, (nom, prenom, email, hash_pw(password), telephone, adresse))
                    conn.commit()
                    flash(f"Compte parent créé avec succès pour {prenom} {nom}.", 'success')
                except sqlite3.IntegrityError:
                    flash("Erreur : cet email est déjà utilisé par un autre compte.", 'error')
            conn.close()
            return redirect(url_for('espace_parent'))

        if action == 'update_parent_info':
            nom = request.form.get('nom', '').strip()
            prenom = request.form.get('prenom', '').strip()
            email = request.form.get('email', '').strip()
            telephone = request.form.get('telephone', '').strip()
            adresse = request.form.get('adresse', '').strip()
            nom_pere = request.form.get('nom_pere', '').strip()
            profession_pere = request.form.get('profession_pere', '').strip()
            nom_mere = request.form.get('nom_mere', '').strip()
            profession_mere = request.form.get('profession_mere', '').strip()
            try:
                conn.execute("""
                    UPDATE users SET nom=?, prenom=?, email=?, telephone=?, adresse=?,
                                     nom_pere=?, profession_pere=?, nom_mere=?, profession_mere=?
                    WHERE id=? AND role='parent'
                """, (nom, prenom, email, telephone, adresse, nom_pere, profession_pere,
                      nom_mere, profession_mere, target_id))
                conn.commit()
                flash('Informations du parent mises à jour avec succès.', 'success')
            except sqlite3.IntegrityError:
                flash('Erreur : cet email est déjà utilisé par un autre compte.', 'error')

        elif action == 'reset_password':
            new_pw = request.form.get('new_password', '').strip()
            if len(new_pw) < 4:
                flash('Le mot de passe doit contenir au moins 4 caractères.', 'error')
            else:
                conn.execute("UPDATE users SET password=? WHERE id=? AND role='parent'",
                             (hash_pw(new_pw), target_id))
                conn.commit()
                flash('Mot de passe réinitialisé avec succès.', 'success')

        conn.close()
        return redirect(url_for('espace_parent', parent_id=target_id))

    # --- DEBUT DE LA MODIFICATION : GESTION DE L'ANNUAIRE POUR L'ADMIN ---

    # On regarde si un ID de parent a été passé dans l'URL (ex: /espace-parent?parent_id=5)
    url_parent_id = request.args.get('parent_id')

    # Si c'est l'admin/agent_admin et qu'il n'a cliqué sur aucun parent précis -> On lui montre l'annuaire
    if session.get('role') in ('admin', 'agent_admin') and not url_parent_id:
        search_q = request.args.get('q', '').strip()
        tri = request.args.get('tri', 'nom')

        where_sql = ""
        params = []
        if search_q:
            like_term = f"%{search_q}%"
            where_sql = "AND (nom LIKE ? OR prenom LIKE ? OR email LIKE ? OR telephone LIKE ?)"
            params = [like_term, like_term, like_term, like_term]

        parents = conn.execute(f"""
            SELECT * FROM users WHERE role='parent' {where_sql} ORDER BY nom, prenom
        """, params).fetchall()

        parents_data = []
        nb_enfants_total = 0
        nb_parents_impayes = 0
        montant_total_attente = 0

        for p in parents:
            enfants_parent = conn.execute("""
                SELECT e.id, e.nom, e.prenom, c.nom as classe
                FROM eleves e LEFT JOIN classes c ON e.classe_id=c.id
                WHERE e.parent_id=? ORDER BY e.nom
            """, (p['id'],)).fetchall()

            stats_row = conn.execute("""
                SELECT SUM(pa.montant_total) as total, SUM(pa.montant_paye) as paye,
                       SUM(CASE WHEN pa.statut != 'paye' THEN 1 ELSE 0 END) as nb_impayes
                FROM paiements pa JOIN eleves e2 ON pa.eleve_id = e2.id
                WHERE e2.parent_id=?
            """, (p['id'],)).fetchone()

            total = stats_row['total'] or 0
            paye = stats_row['paye'] or 0
            reste = total - paye
            nb_impayes = stats_row['nb_impayes'] or 0

            nb_enfants_total += len(enfants_parent)
            if reste > 0:
                nb_parents_impayes += 1
                montant_total_attente += reste

            parents_data.append({
                'info': dict(p),
                'enfants': [dict(e) for e in enfants_parent],
                'nb_enfants': len(enfants_parent),
                'total_du': total,
                'total_paye': paye,
                'reste': reste,
                'nb_impayes': nb_impayes,
            })

        # Tri en mémoire selon le critère choisi
        if tri == 'nb_enfants_desc':
            parents_data.sort(key=lambda x: x['nb_enfants'], reverse=True)
        elif tri == 'reste_desc':
            parents_data.sort(key=lambda x: x['reste'], reverse=True)
        else:
            parents_data.sort(key=lambda x: ((x['info'].get('nom') or ''), (x['info'].get('prenom') or '')))

        stats_globales = {
            'nb_parents': len(parents_data),
            'nb_enfants': nb_enfants_total,
            'nb_impayes': nb_parents_impayes,
            'montant_attente': montant_total_attente,
        }

        conn.close()

        return render_template_string(PARENTS_ANNUAIRE_HTML, parents_data=parents_data,
                                      stats=stats_globales, search_q=search_q, tri=tri,
                                      notif_count=get_notif_count())

    # Définition du "pid" (ID du parent ciblé)
    if session.get('role') in ('admin', 'agent_admin'):
        try:
            pid = int(url_parent_id)
        except (TypeError, ValueError):
            conn.close()
            flash('Identifiant de parent invalide.', 'error')
            return redirect(url_for('espace_parent'))
    else:
        pid = session['user_id']  # Si c'est un parent, il regarde ses propres données

    # --- FIN DE LA MODIFICATION STRUCTURELLE (Le reste de votre code récupère les données du "pid" ciblé) ---

    parent_info_row = conn.execute("SELECT * FROM users WHERE id=? AND role='parent'", (pid,)).fetchone()
    if not parent_info_row:
        conn.close()
        flash('Parent introuvable.', 'error')
        return redirect(url_for('dashboard'))
    parent_info = dict(parent_info_row)

    enfants = conn.execute(
        "SELECT e.*, c.nom as classe, c.niveau FROM eleves e LEFT JOIN classes c ON e.classe_id=c.id WHERE e.parent_id=?",
        (pid,)
    ).fetchall()

    data_enfants = []
    for enf in enfants:
        eid = enf['id']
        notes_t = {}
        for t in [1, 2]:
            notes = conn.execute(
                "SELECT n.*, m.nom as matiere, m.coefficient, sm.coefficient as sm_coefficient "
                "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
                "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
                "WHERE n.eleve_id=? AND n.trimestre=?",
                (eid, t)).fetchall()
            if notes:
                avg, _ = _moyenne_ponderee_matieres(notes)
            else:
                avg = 0
            notes_t[t] = {'notes': notes, 'moyenne': avg}

        absences = conn.execute(
            "SELECT * FROM absences WHERE eleve_id=? ORDER BY date_absence DESC", (eid,)).fetchall()
        paiements = conn.execute(
            "SELECT * FROM paiements WHERE eleve_id=? ORDER BY created_at DESC", (eid,)).fetchall()

        # 🆕 Emploi du temps de la classe de l'enfant (lecture seule, consultable par le parent)
        emploi_temps_enf = {jour: [] for jour in JOURS_SEMAINE}
        if enf['classe_id']:
            creneaux_enf = conn.execute("""
                SELECT et.*, m.nom as matiere_nom, u.prenom || ' ' || u.nom as enseignant_nom
                FROM emploi_temps et
                LEFT JOIN matieres m ON et.matiere_id = m.id
                LEFT JOIN users u ON m.enseignant_id = u.id
                WHERE et.classe_id = ?
                ORDER BY et.heure_debut
            """, (enf['classe_id'],)).fetchall()
            for c in creneaux_enf:
                if c['jour'] in emploi_temps_enf:
                    emploi_temps_enf[c['jour']].append(dict(c))

        nb_abs_inj = sum(1 for a in absences if not a['justifiee'])
        # 🆕 Moyenne générale rapide (même formule pondérée que le bulletin détaillé plus bas)
        _moys_rapides = [notes_t[t]['moyenne'] for t in [1, 2] if notes_t[t]['notes']]
        avg_gen = round(sum(_moys_rapides) / len(_moys_rapides), 2) if _moys_rapides else None

        # 🆕 BULLETIN DÉTAILLÉ (onglet "Notes et Bulletin" — Espace Parent) :
        # notes par matière, moyenne générale pondérée, classement, évolution, comparaison trimestre/semestre,
        # et matière où l'enfant a obtenu sa meilleure moyenne.
        # La moyenne de chaque matière tient compte du coefficient de ses sous-matières (si définies),
        # puis la moyenne générale tient compte du coefficient de chaque matière.
        toutes_notes_enfant = notes_t[1]['notes'] + notes_t[2]['notes']
        _, moys_matiere_global = _moyenne_ponderee_matieres(toutes_notes_enfant) if toutes_notes_enfant else (0, {})
        _, moys_matiere_t1 = _moyenne_ponderee_matieres(notes_t[1]['notes']) if notes_t[1]['notes'] else (0, {})
        _, moys_matiere_t2 = _moyenne_ponderee_matieres(notes_t[2]['notes']) if notes_t[2]['notes'] else (0, {})
        coef_par_matiere = {}
        for n in toutes_notes_enfant:
            coef_par_matiere.setdefault(n['matiere'], n['coefficient'] or 1)

        notes_par_matiere = []
        for matiere, moyenne_matiere in moys_matiere_global.items():
            notes_par_matiere.append({
                'matiere': matiere,
                'coefficient': coef_par_matiere.get(matiere, 1),
                'moyenne': round(moyenne_matiere, 2),
                't1': round(moys_matiere_t1[matiere], 2) if matiere in moys_matiere_t1 else None,
                't2': round(moys_matiere_t2[matiere], 2) if matiere in moys_matiere_t2 else None,
            })
        notes_par_matiere.sort(key=lambda x: x['matiere'])

        # Moyenne générale pondérée sur l'ensemble des notes (tous trimestres confondus)
        moyennes_valides = [notes_t[t]['moyenne'] for t in [1, 2] if notes_t[t]['notes']]
        moyenne_generale_bulletin = round(sum(moyennes_valides) / len(moyennes_valides), 2) if moyennes_valides else None

        # Matière spéciale : celle où l'enfant a la meilleure moyenne
        matiere_forte = None
        matieres_valides = [m for m in notes_par_matiere if m['moyenne'] is not None]
        if matieres_valides:
            matiere_forte = max(matieres_valides, key=lambda x: x['moyenne'])

        # Classement dans la classe (même logique que la fiche élève, pondérée sous-matière + matière)
        rang_classe, total_classe_eff = None, None
        if enf['classe_id']:
            classement = conn.execute(SQL_CLASSEMENT_PONDERE, (enf['classe_id'],)).fetchall()
            total_classe_eff = len(classement)
            for i, row in enumerate(classement, start=1):
                if row['id'] == eid:
                    rang_classe = i
                    break

        data_enfants.append({
            'eleve': dict(enf),
            'notes_t': notes_t,
            'absences': [dict(a) for a in absences],
            'paiements': [dict(p) for p in paiements],
            'nb_abs_total': len(absences),
            'nb_abs_inj': nb_abs_inj,
            'avg_gen': round(avg_gen, 2) if avg_gen else 'N/A',
            # 🆕 Emploi du temps
            'emploi_temps': emploi_temps_enf,
            # 🆕 Données bulletin
            'notes_par_matiere': notes_par_matiere,
            'moyenne_generale_bulletin': moyenne_generale_bulletin,
            'matiere_forte': matiere_forte,
            'rang_classe': rang_classe,
            'total_classe': total_classe_eff,
        })

    # --- Résumé financier consolidé (tous les enfants du parent) ---
    total_du_g = sum(p['montant_total'] for d in data_enfants for p in d['paiements'])
    total_paye_g = sum(p['montant_paye'] for d in data_enfants for p in d['paiements'])
    nb_retard_g = sum(1 for d in data_enfants for p in d['paiements'] if p['statut'] != 'paye')
    totals_globaux = {
        'total_du': total_du_g,
        'total_paye': total_paye_g,
        'reste': total_du_g - total_paye_g,
        'nb_retard': nb_retard_g,
        'nb_enfants': len(data_enfants),
    }

    conn.close()

    # Assurez-vous que PARENT_HTML et get_notif_count() existent bien dans la suite de votre fichier
    return render_template_string(PARENT_HTML, data_enfants=data_enfants, parent_info=parent_info,
                                  totals_globaux=totals_globaux, jours_semaine=JOURS_SEMAINE,
                                  notif_count=get_notif_count())


# ─────────────────────────────────────────────
# PAGE ENSEIGNANT (dédiée)
# ─────────────────────────────────────────────
@app.route('/espace-enseignant', methods=['GET', 'POST'])
@login_required
@role_required('enseignant', 'admin')
def espace_enseignant():
    conn = get_db()

    # Gestion des actions de modification et suppression par l'admin / agent-admin
    # 🆕 AGENT ADMIN : accès complet à cette page comme l'admin, SAUF pour tout ce qui
    # concerne la rémunération de l'enseignant (voir plus bas : ses valeurs saisies pour
    # type_paiement / montant_paiement sont ignorées et on garde celles déjà en base).
    if request.method == 'POST' and session['role'] in ('admin', 'agent_admin'):
        action = request.form.get('action')
        ens_id_form = request.form.get('enseignant_id')
        cycle = request.form.get('cycle', 'Primaire')  # Conserve le cycle actif après validation

        if action == 'edit':
            nom = request.form.get('nom')
            prenom = request.form.get('prenom')
            email = request.form.get('email')

            # --- NOUVEAUTÉ : Récupération des nouveaux champs ---
            tel = request.form.get('telephone', '')
            cnss = request.form.get('cnss', '')
            date_embauche = request.form.get('date_embauche')
            duree_contrat = request.form.get('duree_contrat', '')
            date_naissance = request.form.get('date_naissance')
            cin = request.form.get('cin', '')
            adresse = request.form.get('adresse', '')
            matiere_specialite = request.form.get('matiere_specialite', '')
            heures = request.form.get('heures_par_mois', 0)

            # --- ADAPTATION : Récupération des champs de paiement ---
            # 🔒 AGENT ADMIN : n'a pas le droit de voir/modifier la rémunération. Même si un
            # champ était forgé côté client, on ignore la saisie et on relit les valeurs déjà
            # enregistrées en base pour les réécrire telles quelles (aucun changement réel).
            if session['role'] == 'agent_admin':
                _ens_actuel = conn.execute(
                    "SELECT type_paiement, montant_paiement FROM users WHERE id=?", (ens_id_form,)).fetchone()
                type_paiement = _ens_actuel['type_paiement'] if _ens_actuel else ''
                montant_paiement = _ens_actuel['montant_paiement'] if _ens_actuel else 0
            else:
                type_paiement = request.form.get('type_paiement', '')
                montant_paiement = request.form.get('montant_paiement', 0)

            matieres_ids = request.form.getlist('matieres_ids')  # Liste des matières cochées
            classes_ids = request.form.getlist('classes_ids')  # --- NOUVEAUTÉ : Liste des classes cochées ---

            try:
                # --- ADAPTATION : Mise à jour incluant type_paiement et montant_paiement ---
                conn.execute("""
                             UPDATE users
                             SET nom=?,
                                 prenom=?,
                                 email=?,
                                 telephone=?,
                                 cnss=?,
                                 date_embauche=?,
                                 duree_contrat=?,
                                 date_naissance=?,
                                 cin=?,
                                 adresse=?,
                                 matiere_specialite=?,
                                 heures_par_mois=?,
                                 type_paiement=?,
                                 montant_paiement=?
                             WHERE id = ?
                               AND role = 'enseignant'
                             """,
                             (nom, prenom, email, tel, cnss, date_embauche, duree_contrat, date_naissance, cin, adresse,
                              matiere_specialite, heures, type_paiement, montant_paiement, ens_id_form))

                # Réinitialiser puis assigner les matières sélectionnées
                conn.execute("UPDATE matieres SET enseignant_id=NULL WHERE enseignant_id=?", (ens_id_form,))
                for mid in matieres_ids:
                    conn.execute("UPDATE matieres SET enseignant_id=? WHERE id=?", (ens_id_form, mid))

                # 🆕 FIX : on utilise désormais classe_profs (table de liaison) au lieu de l'ancienne
                # colonne classes.enseignant_id, pour rester cohérent avec le reste de l'application
                # (page /utilisateurs, dossier élève, etc.) et éviter les désynchronisations.
                conn.execute("DELETE FROM classe_profs WHERE enseignant_id=?", (ens_id_form,))
                for cid in classes_ids:
                    if cid:
                        conn.execute(
                            "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                            (cid, ens_id_form, matiere_specialite))
                # Chaque matière cochée est rattachée à une classe précise : on synchronise classe_profs
                # avec cette classe+matière pour que l'assignation soit correcte aussi côté classe.
                for mid in matieres_ids:
                    m = conn.execute("SELECT classe_id, nom FROM matieres WHERE id=?", (mid,)).fetchone()
                    if m and m['classe_id']:
                        conn.execute(
                            "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                            (m['classe_id'], ens_id_form, m['nom']))

                conn.commit()
                flash('Dossier enseignant, matières, classes et informations de paiement mis à jour avec succès !',
                      'success')
            except sqlite3.IntegrityError:
                flash('Erreur : Cet email est déjà utilisé.', 'error')

            conn.close()
            return redirect(url_for('espace_enseignant', ens_id=ens_id_form, cycle=cycle))

        elif action == 'delete':
            # Optionnel : Dissocier les classes rattachées à cet enseignant avant suppression
            conn.execute("DELETE FROM classe_profs WHERE enseignant_id=?", (ens_id_form,))
            conn.execute("UPDATE matieres SET enseignant_id=NULL WHERE enseignant_id=?", (ens_id_form,))
            # Supprimer l'utilisateur
            conn.execute("DELETE FROM users WHERE id=? AND role='enseignant'", (ens_id_form,))
            conn.commit()
            conn.close()
            flash('Enseignant supprimé avec succès !', 'success')
            return redirect(url_for('espace_enseignant', cycle=cycle))

        elif action == 'add_aide':
            # 🆕 Ajout d'une "Aide maîtresse" — réservé au cycle Maternelle.
            nom = request.form.get('nom', '').strip()
            prenom = request.form.get('prenom', '').strip()
            email = request.form.get('email', '').strip()
            password = request.form.get('password', '').strip()
            tel = request.form.get('telephone', '').strip()
            classe_id_aide = request.form.get('classe_id', '').strip()

            if not nom or not prenom or not email or not password:
                flash('Nom, prénom, email et mot de passe sont obligatoires pour ajouter une aide maîtresse.', 'error')
                conn.close()
                return redirect(url_for('espace_enseignant', cycle='Maternelle'))

            existing = conn.execute("SELECT id FROM users WHERE email=?", (email,)).fetchone()
            if existing:
                flash('Erreur : cet email est déjà utilisé.', 'error')
                conn.close()
                return redirect(url_for('espace_enseignant', cycle='Maternelle'))

            try:
                cur = conn.execute(
                    """INSERT INTO users (nom, prenom, email, password, role, telephone, fonction)
                       VALUES (?, ?, ?, ?, 'enseignant', ?, 'Aide maîtresse')""",
                    (nom, prenom, email, hash_pw(password), tel)
                )
                nouvelle_aide_id = cur.lastrowid
                if classe_id_aide:
                    conn.execute(
                        "INSERT OR REPLACE INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                        (classe_id_aide, nouvelle_aide_id, 'Aide maîtresse'))
                conn.commit()
                flash(f'Aide maîtresse "{prenom} {nom}" ajoutée avec succès !', 'success')
            except sqlite3.IntegrityError:
                flash('Erreur : Cet email est déjà utilisé.', 'error')

            conn.close()
            return redirect(url_for('espace_enseignant', cycle='Maternelle'))

    # --- MÉTHODE GET ---
    # 🆕 SUPPRESSION DU HUB : on ne demande plus à l'admin de cliquer sur une page intermédiaire.
    # On affiche directement la liste des enseignants, avec des onglets de cycle en haut de page.
    cycle_filter = request.args.get('cycle', 'Primaire')
    search_query = request.args.get('q', '').strip()  # Nouvelle variable pour la recherche
    # 🆕 HUB Enseignants / Personnel Admin : permet à l'admin/agent-admin de basculer entre
    # la liste des enseignants (logique existante inchangée) et la liste des agents admin
    # + secrétaires (nouveau). Sans effet pour un enseignant (toujours redirigé vers sa
    # propre fiche via ens_id ci-dessous).
    vue = request.args.get('vue', 'enseignants')
    # 🆕 NOUVEAU : tri, filtre par matière et filtre par statut de paiement de l'enseignant
    sort_by = request.args.get('sort', '')
    matiere_filter = request.args.get('matiere', '').strip()
    statut_paiement_filter = request.args.get('statut_paiement', '').strip()

    ens_id = request.args.get('ens_id', session['user_id'] if session['role'] == 'enseignant' else None)

    # Étape 2 : Si admin/agent-admin et aucun enseignant sélectionné, on affiche la liste de
    # choix d'enseignants filtrée (🆕 agent-admin y a accès aussi, mais sans les infos de paiement)
    if session['role'] in ('admin', 'agent_admin') and not ens_id:
        # REQUÊTE ADAPTÉE : Filtre les profs rattachés au cycle via la table de liaison classe_profs
        # 🆕 On ajoute : nb de classes, nb d'élèves couverts, et l'agrégat de paiement (total dû / payé)
        # pour afficher un statut de paiement et des indicateurs directement dans la liste.
        query = """
                SELECT DISTINCT u.*, \
                       COALESCE( \
                           NULLIF(u.matiere_specialite, ''), \
                           (SELECT GROUP_CONCAT(DISTINCT cp2.matiere) FROM classe_profs cp2 \
                             WHERE cp2.enseignant_id = u.id AND cp2.matiere IS NOT NULL AND cp2.matiere != '' AND cp2.matiere != 'Non défini'), \
                           (SELECT GROUP_CONCAT(DISTINCT m2.nom) FROM matieres m2 WHERE m2.enseignant_id = u.id) \
                       ) as matiere_affichee, \
                       (SELECT COUNT(DISTINCT cp3.classe_id) FROM classe_profs cp3 WHERE cp3.enseignant_id = u.id) as nb_classes, \
                       (SELECT COUNT(DISTINCT e2.id) FROM classe_profs cp4 JOIN eleves e2 ON e2.classe_id = cp4.classe_id WHERE cp4.enseignant_id = u.id) as nb_eleves, \
                       pay.total_du, pay.total_paye \
                FROM users u \
                         LEFT JOIN classe_profs cp ON cp.enseignant_id = u.id \
                         LEFT JOIN classes c1 ON cp.classe_id = c1.id \
                         LEFT JOIN ( \
                            SELECT enseignant_id, SUM(montant_total) as total_du, SUM(montant_paye) as total_paye \
                            FROM paiements_enseignants GROUP BY enseignant_id \
                         ) pay ON pay.enseignant_id = u.id \
                WHERE u.role = 'enseignant'
                  AND (c1.cycle = ? OR (c1.cycle IS NULL AND ? = 'Primaire'))
                """
        params = [cycle_filter, cycle_filter]

        # 🆕 Recherche élargie : nom, prénom, email, téléphone, matière (au lieu de nom/prénom seuls)
        if search_query:
            query += " AND (u.nom LIKE ? OR u.prenom LIKE ? OR u.email LIKE ? OR u.telephone LIKE ? OR u.matiere_specialite LIKE ?)"
            params.extend([f"%{search_query}%"] * 5)

        # 🆕 Filtre par matière
        if matiere_filter:
            query += " AND u.matiere_specialite = ?"
            params.append(matiere_filter)

        # 🆕 Tri configurable
        if sort_by == 'nom_desc':
            query += " ORDER BY u.nom DESC, u.prenom DESC"
        elif sort_by == 'anciennete':
            query += " ORDER BY u.date_embauche ASC"
        else:
            query += " ORDER BY u.nom"

        enseignants_tous_raw = conn.execute(query, params).fetchall()

        # 🆕 Calcul du statut de paiement + statut de congé en cours, en Python (comme pour les élèves)
        today_str = datetime.date.today().isoformat()
        conges_en_cours_ids = {r['enseignant_id'] for r in conn.execute(
            "SELECT enseignant_id FROM conges WHERE statut='approuve' AND date_debut<=? AND date_fin>=?",
            (today_str, today_str)).fetchall()}

        enseignants_tous = []
        for row in enseignants_tous_raw:
            e = dict(row)
            total_du = e.get('total_du') or 0
            total_paye = e.get('total_paye') or 0
            if not e.get('total_du'):
                e['statut_paiement'] = 'aucun'
            else:
                reste = total_du - total_paye
                if reste <= 0:
                    e['statut_paiement'] = 'paye'
                elif total_paye > 0:
                    e['statut_paiement'] = 'partiel'
                else:
                    e['statut_paiement'] = 'non_paye'
            e['en_conge'] = e['id'] in conges_en_cours_ids
            enseignants_tous.append(e)

        # 🆕 Filtre par statut de paiement (appliqué après calcul) — réservé à l'admin, jamais
        # à l'agent-admin, même si le paramètre est forgé directement dans l'URL.
        if session['role'] == 'admin' and statut_paiement_filter in ('paye', 'partiel', 'non_paye', 'aucun'):
            enseignants_tous = [e for e in enseignants_tous if e['statut_paiement'] == statut_paiement_filter]

        # 🔒 AGENT ADMIN : ne doit recevoir aucune info de paiement, même dans les données
        # brutes envoyées au template (au cas où un futur affichage y accéderait directement).
        if session['role'] == 'agent_admin':
            for e in enseignants_tous:
                e['total_du'] = None
                e['total_paye'] = None
                e['statut_paiement'] = None
            statut_paiement_filter = ''

        # 🆕 On sépare les "Aide maîtresse" (fonction dédiée) des enseignants classiques,
        # pour les afficher dans deux sections distinctes côté template — sans rien
        # changer à la requête ni au reste de la logique existante.
        enseignants = [e for e in enseignants_tous if (e['fonction'] or 'Enseignant(e)') != 'Aide maîtresse']
        aides_maternelle = [e for e in enseignants_tous if (e['fonction'] or '') == 'Aide maîtresse']

        # Classes du cycle Maternelle, pour le sélecteur du formulaire d'ajout d'une aide
        classes_maternelle = conn.execute(
            "SELECT id, nom, niveau FROM classes WHERE cycle = 'Maternelle' ORDER BY nom").fetchall()

        # 🆕 Liste des matières distinctes (pour le filtre) et stats globales pour les cartes du haut
        matieres_distinctes = sorted({e['matiere_affichee'] for e in enseignants_tous if e.get('matiere_affichee')})
        nb_classes_couvertes = conn.execute("""
            SELECT COUNT(DISTINCT cp.classe_id) FROM classe_profs cp
            JOIN classes c ON c.id = cp.classe_id
            WHERE c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire')
        """, (cycle_filter, cycle_filter)).fetchone()[0]
        stats_enseignants = {
            'total': len(enseignants) + len(aides_maternelle),
            'nb_matieres': len(matieres_distinctes),
            'nb_classes_couvertes': nb_classes_couvertes,
            'en_conge': sum(1 for e in enseignants_tous if e['en_conge']),
            'impayes': sum(1 for e in enseignants_tous if e['statut_paiement'] in ('non_paye', 'partiel')),
        }

        # 🆕 Vue "Personnel Admin" du hub : liste des agents admin + secrétaires. Un
        # agent-admin ne voit jamais les comptes 'admin' (déjà exclus de cette requête,
        # comme partout ailleurs dans l'app), donc aucune donnée admin ne fuite ici.
        personnel_admin = []
        if vue == 'admin':
            personnel_admin_raw = conn.execute(
                "SELECT * FROM users WHERE role IN ('agent_admin','secretaire') ORDER BY role, nom, prenom"
            ).fetchall()
            personnel_admin = [dict(p) for p in personnel_admin_raw]

        conn.close()
        return render_template_string(ENSEIGNANT_CHOOSE_HTML, enseignants=enseignants,
                                      aides_maternelle=aides_maternelle, classes_maternelle=classes_maternelle,
                                      matieres_distinctes=matieres_distinctes, stats_enseignants=stats_enseignants,
                                      sort_by=sort_by, matiere_filter=matiere_filter,
                                      statut_paiement_filter=statut_paiement_filter,
                                      cycle=cycle_filter, vue=vue, personnel_admin=personnel_admin,
                                      search_query=search_query, notif_count=get_notif_count())

    enseignant = conn.execute("SELECT * FROM users WHERE id=?", (ens_id,)).fetchone()
    if not enseignant:
        conn.close()
        flash('Enseignant introuvable.', 'error')
        return redirect(url_for('espace_enseignant', cycle=cycle_filter))

    # Étape 3 : On filtre les classes de l'enseignant selon le cycle choisi
    classes = conn.execute("""
                           SELECT c.*, COUNT(e.id) as nb_eleves
                           FROM classes c
                                    JOIN classe_profs cp ON cp.classe_id = c.id
                                    LEFT JOIN eleves e ON e.classe_id = c.id
                           WHERE cp.enseignant_id = ?
                             AND (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
                           GROUP BY c.id
                           """, (ens_id, cycle_filter, cycle_filter)).fetchall()

    data_classes = []
    for cl in classes:
        eleves = conn.execute(
            "SELECT e.* FROM eleves e WHERE e.classe_id=? ORDER BY e.nom", (cl['id'],)).fetchall()
        eleves_data = []
        for elv in eleves:
            nb_abs = conn.execute("SELECT COUNT(*) FROM absences WHERE eleve_id=?", (elv['id'],)).fetchone()[0]
            notes_par_t = {}
            for t in [1, 2]:
                notes = conn.execute(
                    "SELECT n.*, m.nom as matiere, m.coefficient, sm.coefficient as sm_coefficient "
                    "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
                    "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
                    "WHERE n.eleve_id=? AND n.trimestre=?",
                    (elv['id'], t)).fetchall()
                if notes:
                    moy_t, _ = _moyenne_ponderee_matieres(notes)
                    notes_par_t[t] = round(moy_t, 2)
                else:
                    notes_par_t[t] = None
            # 🆕 Moyenne générale = moyenne des trimestres réellement notés (même formule que la fiche élève)
            moys_t_valides = [v for v in notes_par_t.values() if v is not None]
            avg = round(sum(moys_t_valides) / len(moys_t_valides), 2) if moys_t_valides else None
            eleves_data.append({
                'eleve': elv,
                'avg': avg if avg is not None else 'N/A',
                'nb_abs': nb_abs,
                'notes_par_t': notes_par_t
            })

        # Taux de réussite (moyenne >= 10)
        reussite = sum(1 for e in eleves_data if e['avg'] != 'N/A' and e['avg'] >= 10)
        taux = round(reussite / len(eleves_data) * 100, 1) if eleves_data else 0

        # 🆕 Moyenne de la classe = moyenne des moyennes pondérées des élèves (cohérent avec 'avg' ci-dessus)
        avgs_num = [e['avg'] for e in eleves_data if e['avg'] != 'N/A']
        avg_classe = round(sum(avgs_num) / len(avgs_num), 2) if avgs_num else None

        data_classes.append({
            'classe': cl,
            'eleves': eleves_data,
            'taux_reussite': taux,
            'avg_classe': avg_classe if avg_classe is not None else 'N/A',
            'nb_reussite': reussite
        })

    # Récupérer les matières globales pour l'édition filtrées par cycle
    all_matieres = conn.execute("""
                                SELECT m.id, m.nom, c.nom as classe_nom
                                FROM matieres m
                                         JOIN classes c ON m.classe_id = c.id
                                WHERE (c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))
                                ORDER BY c.nom, m.nom
                                """, (cycle_filter, cycle_filter)).fetchall()

    # Récupérer les matières actuelles de l'enseignant pour les cocher
    enseignant_matieres = conn.execute("SELECT id FROM matieres WHERE enseignant_id=?", (ens_id,)).fetchall()
    enseignant_matieres_ids = [r['id'] for r in enseignant_matieres]

    # --- NOUVEAUTÉ : Récupérer toutes les classes du cycle pour l'assignation ---
    toutes_les_classes = conn.execute("""
                                      SELECT id, nom, niveau
                                      FROM classes
                                      WHERE (cycle = ? OR (cycle IS NULL AND ? = 'Primaire'))
                                      ORDER BY niveau, nom
                                      """, (cycle_filter, cycle_filter)).fetchall()

    # --- NOUVEAUTÉ : Récupérer les classes actuelles de l'enseignant pour les cocher ---
    classes_assignees = conn.execute("SELECT id FROM classes WHERE enseignant_id=?", (ens_id,)).fetchall()
    classes_assignees_ids = [r['id'] for r in classes_assignees]

    total_notes = conn.execute("SELECT COUNT(*) FROM notes WHERE enseignant_id=?", (ens_id,)).fetchone()[0]
    total_abs = conn.execute("SELECT COUNT(*) FROM absences WHERE signale_par=?", (ens_id,)).fetchone()[0]
    conn.close()

    # --- NOUVEAUTÉ : Ajout des variables des classes dans le rendu du template ---
    return render_template_string(ENSEIGNANT_HTML,
                                  enseignant=enseignant,
                                  data_classes=data_classes,
                                  total_notes=total_notes,
                                  total_abs=total_abs,
                                  all_matieres=all_matieres,
                                  enseignant_matieres_ids=enseignant_matieres_ids,
                                  toutes_les_classes=toutes_les_classes,
                                  classes_assignees_ids=classes_assignees_ids,
                                  cycle=cycle_filter,
                                  notif_count=get_notif_count())


