# API analyse — v3 : toutes filtrées par cycle + filtres avancés (trimestre/classe/matière/enseignant/année)
# ✅ FIX: dans la v2 ces API ignoraient totalement le cycle sélectionné, les graphiques
# affichaient donc toujours TOUTES les classes (Maternelle+Primaire+Collège) quel que soit l'onglet actif.
def _api_filters():
    return (
        request.args.get('cycle', 'Primaire'),
        request.args.get('trimestre', ''),
        request.args.get('gf_classe_id', ''),
        request.args.get('gf_matiere_nom', ''),
        request.args.get('gf_ens_id', ''),
        request.args.get('gf_annee', ''),
    )


@app.route('/api/analyse/enseignants')
@login_required
@role_required('admin')
def api_analyse_enseignants():
    conn = get_db()
    cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee = _api_filters()
    where_sql, params = _build_where(cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee)
    data = conn.execute(
        f"SELECT y.id as id, y.nom as nom, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, "
        f"SUM(CASE WHEN y.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux "
        f"FROM ( "
        f"    SELECT u.id as id, u.prenom||' '||u.nom as nom, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN users u ON n.enseignant_id=u.id "
        f"    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_sql} "
        f") y GROUP BY y.id ORDER BY avg DESC", params
    ).fetchall()
    conn.close()
    return jsonify(
        [{'enseignant': r['nom'], 'avg': round(r['avg'], 2), 'taux': round(r['taux'] or 0, 1)} for r in data])


@app.route('/api/analyse/matieres')
@login_required
@role_required('admin')
def api_analyse_matieres():
    conn = get_db()
    cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee = _api_filters()
