@app.route('/export/paiements/excel')
@login_required
@role_required('admin')
def export_paiements_excel():
    try:
        import openpyxl
        conn = get_db()

        # --- Reprise des mêmes filtres avancés que la page /paiements ---
        # pour exporter exactement ce que l'admin est en train de consulter.
        cycle_filter = request.args.get('cycle', 'Global')

        # 🔒 AGENT ADMIN : ne doit pas pouvoir contourner l'interface (qui bloque déjà l'onglet
        # "Enseignants") en forgeant directement l'URL d'export Excel.
        if session.get('role') == 'agent_admin' and cycle_filter == 'Enseignants':
            flash('Accès non autorisé.', 'error')
            return redirect(url_for('paiements'))

        status_filter = request.args.get('statut', '')
        mois_filter = request.args.get('mois', '')
        search_filter = request.args.get('q', '').strip()
        classe_filter = request.args.get('classe_id', '')
        categorie_filter = request.args.get('categorie_filter', '')
        date_debut = request.args.get('date_debut', '')
        date_fin = request.args.get('date_fin', '')

        def _parse_montant(val):
            try:
                return float(val) if val not in (None, '') else None
            except ValueError:
                return None

        montant_min = _parse_montant(request.args.get('montant_min', ''))
        montant_max = _parse_montant(request.args.get('montant_max', ''))

        wb = openpyxl.Workbook()
        ws = wb.active

        if cycle_filter == 'Enseignants':
            ws.title = "Paiements Enseignants"
            where_clauses = []
            params = []
            if status_filter:
                where_clauses.append("p.statut=?")
                params.append(status_filter)
            if mois_filter:
                where_clauses.append("p.mois=?")
                params.append(mois_filter)
            if search_filter:
                like_term = f"%{search_filter}%"
                where_clauses.append("(u.nom LIKE ? OR u.prenom LIKE ?)")
                params.extend([like_term, like_term])
            if montant_min is not None:
                where_clauses.append("p.montant_total >= ?")
                params.append(montant_min)
            if montant_max is not None:
                where_clauses.append("p.montant_total <= ?")
                params.append(montant_max)
            if date_debut:
                where_clauses.append("p.date_paiement >= ?")
                params.append(date_debut)
            if date_fin:
                where_clauses.append("p.date_paiement <= ?")
                params.append(date_fin)
            where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

            data = conn.execute(f"""
                SELECT u.prenom||' '||u.nom, p.mois, p.type_paiement, p.montant_total,
                       p.montant_paye, p.montant_total-p.montant_paye, p.statut, p.date_paiement
                FROM paiements_enseignants p
                JOIN users u ON p.enseignant_id = u.id
                {where_sql}
                ORDER BY p.statut, u.nom
            """, params).fetchall()

            headers = ['Enseignant', 'Mois', 'Type de paiement', 'Montant Total', 'Montant Payé', 'Reste', 'Statut',
                       'Date paiement']
        else:
            ws.title = "Paiements"
            where_clauses = []
            params = []
            if cycle_filter not in ('Global', ''):
                where_clauses.append("(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))")
                params.extend([cycle_filter, cycle_filter])
            if status_filter:
                where_clauses.append("p.statut=?")
                params.append(status_filter)
            if mois_filter:
                where_clauses.append("strftime('%Y-%m', p.date_echeance) = ?")
                params.append(mois_filter)
            if search_filter:
                like_term = f"%{search_filter}%"
                where_clauses.append("(e.nom LIKE ? OR e.prenom LIKE ?)")
                params.extend([like_term, like_term])
            if classe_filter:
                where_clauses.append("c.id=?")
                params.append(classe_filter)
            if categorie_filter:
                where_clauses.append("p.description LIKE ?")
                params.append(f"[{categorie_filter}]%")
            if montant_min is not None:
                where_clauses.append("p.montant_total >= ?")
                params.append(montant_min)
            if montant_max is not None:
                where_clauses.append("p.montant_total <= ?")
                params.append(montant_max)
            if date_debut:
                where_clauses.append("p.date_echeance >= ?")
                params.append(date_debut)
            if date_fin:
                where_clauses.append("p.date_echeance <= ?")
                params.append(date_fin)
            where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

            data = conn.execute(f"""
                SELECT e.prenom||' '||e.nom, c.nom, p.description, p.montant_total,
                       p.montant_paye, p.montant_total-p.montant_paye, p.statut, p.date_echeance
                FROM paiements p
                JOIN eleves e ON p.eleve_id=e.id
                LEFT JOIN classes c ON e.classe_id=c.id
                {where_sql}
                ORDER BY p.statut, e.nom
            """, params).fetchall()

            headers = ['Élève', 'Classe', 'Description', 'Montant Total', 'Montant Payé', 'Reste', 'Statut', 'Échéance']

        conn.close()
        for col, h in enumerate(headers, 1): ws.cell(1, col, h)
        for row, d in enumerate(data, 2):
            d = list(d)
            # 🆕 Dernière colonne = date (Échéance élèves / Date paiement enseignants) :
            # mois + année uniquement, sauf saison scolaire pour les frais d'inscription.
            if cycle_filter == 'Enseignants':
                d[-1] = _formater_mois_annee(d[-1]) or ''
            else:
                d[-1] = _formater_date_paiement(d[-1], d[2]) or ''
            for col, val in enumerate(d, 1): ws.cell(row, col, val or '')
        buf = io.BytesIO();
        wb.save(buf);
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name='paiements.xlsx',
                         mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    except Exception as ex:
        flash(f'Erreur export: {ex}', 'error');
        return redirect(url_for('paiements'))


# ═══════════════════════════════════════════════════════════════
# 🆕 BULLETIN SCOLAIRE — design "école de luxe" (bandeau bleu marine, sceau doré,
# photo de l'élève, tableau des moyennes, mini-graphique d'évolution, observations
# des enseignants). Dessiné entièrement avec reportlab (canvas), sans dépendance
# externe supplémentaire (aucun ajout à requirements.txt).
# ═══════════════════════════════════════════════════════════════
# 🩹 CORRECTIF : `cm` doit être importé au niveau du MODULE (pas seulement à l'intérieur de
# export_bulletin_pdf) car les fonctions _bulletin_* ci-dessous sont définies au niveau module
# et le résolvent donc dans les globals du module, pas dans les locals de la route appelante.
from reportlab.lib.units import cm

_BULLETIN_NAVY = '#152341'
_BULLETIN_NAVY_LIGHT = '#1F3358'
_BULLETIN_GOLD = '#C9A24B'
_BULLETIN_GOLD_LIGHT = '#E4C878'
_BULLETIN_CREAM = '#FBF8F1'
_BULLETIN_BORDER = '#E7DFC9'
_BULLETIN_TEXT_DARK = '#1E2430'
_BULLETIN_TEXT_MUTED = '#6B7280'
_BULLETIN_GREEN = '#1F9254'
_BULLETIN_AMBER = '#C08A1E'
_BULLETIN_RED = '#C0392B'

_MOIS_FR = ['', 'janvier', 'février', 'mars', 'avril', 'mai', 'juin',
            'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre']


def _bulletin_date_fr(date_str):
    """Formate une date ISO ('2015-03-12') en 'Mars 2015' à la française, sans dépendance
    à la locale du serveur (souvent absente sur Render)."""
    if not date_str:
        return None
    try:
        d = datetime.datetime.strptime(date_str[:10], '%Y-%m-%d').date()
        return f"{d.day} {_MOIS_FR[d.month].capitalize()} {d.year}"
    except (ValueError, TypeError, IndexError):
        return None


def _formater_mois_annee(date_str):
    """Formate une date ISO ('2026-01-12') en 'Janvier 2026' (mois + année, sans le jour),
    sans dépendance à la locale du serveur."""
    if not date_str:
        return None
    try:
        d = datetime.datetime.strptime(str(date_str)[:10], '%Y-%m-%d').date()
        return f"{_MOIS_FR[d.month].capitalize()} {d.year}"
    except (ValueError, TypeError, IndexError):
        return None


def _formater_date_paiement(date_str, description=None):
    """🆕 Formatage des dates sur la page Paiements et les factures :
    - Frais d'inscription -> saison scolaire (ex: '2026-2027'), année en cours + année suivante
    - Toutes les autres dates -> mois + année uniquement, sans le jour (ex: 'Janvier 2026')."""
    if not date_str:
        return None
    categorie = ''
    if description and ']' in str(description):
        categorie = str(description).split(']')[0].lstrip('[').strip()
    if categorie.lower() == "frais d'inscription":
        try:
            d = datetime.datetime.strptime(str(date_str)[:10], '%Y-%m-%d').date()
            return f"{d.year}-{d.year + 1}"
        except (ValueError, TypeError, IndexError):
            return None
    return _formater_mois_annee(date_str)


def _label_mois_paye(p):
    """🆕 Libellé "Mois payé" / "Saison payée" pour le reçu PDF : pour un "Frais
    d'inscription", on affiche toujours la saison scolaire (ex: '2026-2027') calculée à
    partir de la date d'échéance — quel que soit le contenu de la colonne `mois` (celle-ci
    est renseignée automatiquement par un trigger SQLite dès qu'une échéance existe, y
    compris pour les frais d'inscription, ce qui donnerait sinon un mois au lieu d'une saison).
    Pour tous les autres types de paiement (mensualités, Voyage, Achat...), on se base en
    priorité sur la colonne `mois` (fiable pour les mensualités générées automatiquement),
    et on retombe sur la date d'échéance formatée (mois/année) si `mois` est vide (cas des
    paiements ajoutés manuellement)."""
    categorie = ''
    if p['description'] and ']' in str(p['description']):
        categorie = str(p['description']).split(']')[0].lstrip('[').strip()

    if categorie.lower() == "frais d'inscription":
        return _formater_date_paiement(p['date_echeance'], p['description'])

    mois_col = None
    try:
        mois_col = p['mois']
    except (IndexError, KeyError):
        mois_col = None
    if mois_col:
        label = _formater_mois_annee(f"{mois_col}-01")
        if label:
            return label
    return _formater_date_paiement(p['date_echeance'], p['description'])


# 🆕 Filtres Jinja utilisables dans les templates : {{ p.date_echeance | date_paiement(p.description) }}
app.jinja_env.filters['date_paiement'] = lambda v, desc=None: _formater_date_paiement(v, desc) or '—'
app.jinja_env.filters['mois_annee'] = lambda v: _formater_mois_annee(v) or '—'


def _bulletin_annee_scolaire():
    """Année scolaire en cours ('2025-2026'), calculée à partir de la date du jour :
    à partir de septembre on est déjà dans la nouvelle année scolaire."""
    aujourdhui = datetime.date.today()
    if aujourdhui.month >= 9:
        return f"{aujourdhui.year}-{aujourdhui.year + 1}"
    return f"{aujourdhui.year - 1}-{aujourdhui.year}"


def _bulletin_appreciation(note):
    if note is None:
        return '—'
    if note >= 16: return 'Excellent'
    if note >= 14: return 'Très bien'
    if note >= 12: return 'Bien'
    if note >= 10: return 'Passable'
    return 'Insuffisant'


def _bulletin_note_color(v):
    from reportlab.lib import colors
    if v is None: return colors.HexColor(_BULLETIN_TEXT_MUTED)
    if v < 8: return colors.HexColor(_BULLETIN_RED)
    if v < 12: return colors.HexColor(_BULLETIN_AMBER)
    return colors.HexColor(_BULLETIN_GREEN)


def _bulletin_rounded_rect(c, x, y, w, h, r, fill=None, stroke=None, lw=1):
    c.saveState()
    if fill is not None:
        c.setFillColor(fill)
    if stroke is not None:
        c.setStrokeColor(stroke)
        c.setLineWidth(lw)
    c.roundRect(x, y, w, h, r, stroke=1 if stroke is not None else 0, fill=1 if fill is not None else 0)
    c.restoreState()


def _bulletin_star(c, cx, cy, r_out, r_in, color, points=5, rotation=-90):
    import math
    c.saveState()
    c.setFillColor(color)
    path = c.beginPath()
    ang_step = math.pi / points
    start = math.radians(rotation)
    for i in range(points * 2):
        r = r_out if i % 2 == 0 else r_in
        ang = start + i * ang_step
        x = cx + r * math.cos(ang)
        y = cy + r * math.sin(ang)
        if i == 0:
            path.moveTo(x, y)
        else:
            path.lineTo(x, y)
    path.close()
    c.drawPath(path, fill=1, stroke=0)
    c.restoreState()


def _bulletin_diamond(c, cx, cy, r, color):
    c.saveState()
    c.setFillColor(color)
    p = c.beginPath()
    p.moveTo(cx, cy + r); p.lineTo(cx + r, cy); p.lineTo(cx, cy - r); p.lineTo(cx - r, cy)
    p.close()
    c.drawPath(p, fill=1, stroke=0)
    c.restoreState()


def _bulletin_safe_image(path, max_px=900):
    """🩹 Charge une image pour le PDF en la redimensionnant/compressant si besoin.
    Évite les timeouts Gunicorn et les pics mémoire causés par des photos très
    lourdes (ex: photo de smartphone non compressée, plusieurs Mo / haute résolution)
    et convertit au passage les modes problématiques (CMYK, palette...) en RGB."""
    from reportlab.lib.utils import ImageReader
    try:
        from PIL import Image
        img = Image.open(path)
        img.load()
        if img.mode not in ('RGB', 'L'):
            img = img.convert('RGB')
        w, h = img.size
        if max(w, h) > max_px:
            scale = max_px / max(w, h)
            img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))), Image.LANCZOS)
        out = io.BytesIO()
        img.save(out, format='JPEG', quality=85)
        out.seek(0)
        return ImageReader(out)
    except Exception:
        # Dernier recours : laisser reportlab tenter de lire le fichier tel quel
        return ImageReader(path)


def _bulletin_fit_right_text(text, font_name, max_width, max_size=6.9, min_size=5.2, step=0.3):
    """🩹 Réduit progressivement la taille de police pour qu'un texte tienne dans
    max_width (ex: nom de matière à côté de son libellé 'Meilleure matière' /
    'Matière la plus faible', qui peuvent être longs). Si même à la taille
    minimale ça ne rentre toujours pas, tronque proprement avec des points de
    suspension au lieu de laisser le texte chevaucher le libellé."""
    from reportlab.pdfbase.pdfmetrics import stringWidth
    text = str(text)
    size = max_size
    while size >= min_size:
        if stringWidth(text, font_name, size) <= max_width:
            return text, size
        size = round(size - step, 2)
    size = min_size
    truncated = text
    while truncated and stringWidth(truncated + '…', font_name, size) > max_width:
        truncated = truncated[:-1]
    return (truncated + '…' if truncated != text else text), size


def _bulletin_draw_crest(c, cx, cy, size, logo_path=None):
    """Emblème gauche du bandeau : logo réel de l'école si disponible (uploadé depuis
    /parametres), sinon un blason dessiné (livre + étoile) dans le même esprit visuel."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    if logo_path and os.path.exists(logo_path):
        try:
            img = _bulletin_safe_image(logo_path)
            iw, ih = img.getSize()
            ratio = min(size / iw, size / ih)
            w, h = iw * ratio, ih * ratio
            c.drawImage(img, cx - w / 2, cy - h / 2, width=w, height=h,
                        preserveAspectRatio=True, mask='auto')
            return
        except Exception:
            pass
    r = size / 2
    c.saveState()
    c.setStrokeColor(GOLD)
    c.setLineWidth(1.4)
    c.circle(cx, cy, r, stroke=1, fill=0)
    c.circle(cx, cy, r - 0.09 * cm, stroke=1, fill=0)
    bw, bh = r * 0.95, r * 0.62
    c.setFillColor(GOLD)
    c.roundRect(cx - bw / 2, cy - bh / 2, bw, bh, 2, stroke=0, fill=1)
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.1)
    c.line(cx, cy - bh / 2 + 1, cx, cy + bh / 2 - 1)
    for dx in (-bw * 0.28, bw * 0.28):
        c.setLineWidth(0.6)
        c.line(cx + dx - bw * 0.14, cy - bh * 0.12, cx + dx + bw * 0.14, cy - bh * 0.12)
        c.line(cx + dx - bw * 0.14, cy + bh * 0.02, cx + dx + bw * 0.14, cy + bh * 0.02)
    _bulletin_star(c, cx, cy + r * 0.72, r * 0.16, r * 0.07, GOLD)
    c.restoreState()


def _bulletin_draw_medallion(c, cx, cy, r, lines, tail_bottom_y):
    """Sceau doré à droite du bandeau, avec deux rubans qui retombent sous l'en-tête."""
    import math
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
    c.saveState()
    tail_w = r * 0.62
    for dx in (-r * 0.55, r * 0.55):
        x0 = cx + dx - tail_w / 2
        c.setFillColor(GOLD)
        p = c.beginPath()
        p.moveTo(x0, cy)
        p.lineTo(x0 + tail_w, cy)
        p.lineTo(x0 + tail_w, tail_bottom_y + 0.35 * cm)
        p.lineTo(x0 + tail_w / 2, tail_bottom_y)
        p.lineTo(x0, tail_bottom_y + 0.35 * cm)
        p.close()
        c.drawPath(p, fill=1, stroke=0)
    c.setFillColor(GOLD_LIGHT)
    c.circle(cx, cy, r, stroke=0, fill=1)
    c.setStrokeColor(colors.white)
    c.setLineWidth(1.3)
    c.circle(cx, cy, r - 0.14 * cm, stroke=1, fill=0)
    c.setStrokeColor(GOLD)
    c.setLineWidth(0.8)
    c.circle(cx, cy, r - 0.28 * cm, stroke=1, fill=0)
    for i in range(8):
        ang = math.radians(i * 45 + 10)
        _bulletin_star(c, cx + (r - 0.05 * cm) * math.cos(ang), cy + (r - 0.05 * cm) * math.sin(ang),
                       0.045 * cm, 0.02 * cm, colors.white)
    c.setFillColor(NAVY)
    n = len(lines)
    fsz = 6.6
    total_h = n * (fsz + 1.4)
    ystart = cy + total_h / 2 - fsz
    for i, (txt, bold) in enumerate(lines):
        c.setFont('Helvetica-Bold' if bold else 'Helvetica', fsz if not bold else fsz + 0.6)
        c.drawCentredString(cx, ystart - i * (fsz + 1.4), txt)
    c.restoreState()


def _bulletin_draw_avatar(c, cx, cy, r, image_path=None, initials=''):
    from reportlab.lib import colors
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    c.saveState()
    c.setStrokeColor(GOLD)
    c.setLineWidth(2.2)
    c.setFillColor(colors.HexColor('#EDE6D3'))
    c.circle(cx, cy, r, stroke=1, fill=1)
    drew_image = False
    if image_path and os.path.exists(image_path):
        try:
            img = _bulletin_safe_image(image_path)
            c.saveState()
            p = c.beginPath()
            p.circle(cx, cy, r - 1.1)
            c.clipPath(p, stroke=0, fill=0)
            # 🩹 Mode "cover" (comme object-fit:cover en CSS) : la photo est agrandie pour
            # remplir tout le cercle sans bande vide, quel que soit son ratio d'origine —
            # avant, l'option preserveAspectRatio "contain" laissait parfois la photo plus
            # petite que le cercle, avec le fond crème visible autour ("photo coupée/petite").
            iw, ih = img.getSize()
            scale = max((2 * r) / iw, (2 * r) / ih)
            dw, dh = iw * scale, ih * scale
            c.drawImage(img, cx - dw / 2, cy - dh / 2, width=dw, height=dh,
                        preserveAspectRatio=True, mask='auto', anchor='c')
            c.restoreState()
            drew_image = True
        except Exception:
            drew_image = False
    if not drew_image:
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', r * 0.9)
        c.drawCentredString(cx, cy - r * 0.32, initials.upper())
    c.restoreState()


def _bulletin_mini_line_chart(c, x, y, w, h, labels, values, line_color, area_color):
    """Petit graphique d'évolution dessiné à la main (aucune dépendance externe type matplotlib)."""
    from reportlab.lib import colors
    c.saveState()
    pad_l, pad_b, pad_t = 0.75 * cm, 0.55 * cm, 0.15 * cm
    plot_x, plot_y = x + pad_l, y + pad_b
    plot_w, plot_h = w - pad_l - 0.25 * cm, h - pad_b - pad_t
    vmax = 20.0
    c.setFont('Helvetica', 6.2)
    c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
    for gv in (0, 5, 10, 15, 20):
        gy = plot_y + (gv / vmax) * plot_h
        c.setStrokeColor(colors.HexColor('#EDEBE3'))
        c.setLineWidth(0.5)
        c.line(plot_x, gy, plot_x + plot_w, gy)
        c.drawRightString(plot_x - 0.12 * cm, gy - 2, str(gv))
    pts_valid = [(i, v) for i, v in enumerate(values) if v is not None]
    n = len(values)
    if n >= 1:
        step = plot_w / max(1, n - 1)
        coords = [(plot_x + i * step, plot_y + (v / vmax) * plot_h) for i, v in pts_valid]
        if len(coords) >= 2:
            p = c.beginPath()
            p.moveTo(coords[0][0], plot_y)
            for cxp, cyp in coords:
                p.lineTo(cxp, cyp)
            p.lineTo(coords[-1][0], plot_y)
            p.close()
            c.setFillColor(area_color)
            c.drawPath(p, fill=1, stroke=0)
            c.setStrokeColor(line_color)
            c.setLineWidth(2.2)
            c.setLineJoin(1)
            p2 = c.beginPath()
            p2.moveTo(*coords[0])
            for pt in coords[1:]:
                p2.lineTo(*pt)
            c.drawPath(p2, fill=0, stroke=1)
        for (cxp, cyp), (_, v) in zip(coords, pts_valid):
            c.setFillColor(line_color)
            c.circle(cxp, cyp, 2.6, stroke=0, fill=1)
            c.setFillColor(colors.HexColor(_BULLETIN_TEXT_DARK))
            c.setFont('Helvetica-Bold', 7)
            c.drawCentredString(cxp, cyp + 6, f"{v:.2f}")
    c.setFont('Helvetica', 6.4)
    c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
    step = plot_w / max(1, n - 1) if n > 1 else 0
    for i, lab in enumerate(labels):
        lx = plot_x + i * step if n > 1 else plot_x + plot_w / 2
        c.drawCentredString(lx, y + 0.12 * cm, lab)
    c.restoreState()


# 🆕 Anneau/cercle de progression (« donut ») — utilisé pour l'analyse par matière du bulletin
# (page 2) : affiche la moyenne d'une matière sous forme de cercle rempli proportionnellement
# à la note/20, coloré selon le niveau (vert/orange/rouge), sans dépendance externe.
def _bulletin_donut_gauge(c, cx, cy, r, pct, color, track_hex='#EDE8D8'):
    """Dessine un cercle de progression centré en (cx, cy) de rayon r. `pct` est une fraction
    0..1 (ex: moyenne/20). Le remplissage part du haut (12h) et tourne dans le sens horaire."""
    from reportlab.lib import colors
    c.saveState()
    pct = max(0.0, min(1.0, pct or 0.0))
    c.setFillColor(colors.HexColor(track_hex))
    c.circle(cx, cy, r, stroke=0, fill=1)
    if pct > 0:
        c.setFillColor(color)
        extent = -360.0 * pct
        if pct >= 0.999:
            c.circle(cx, cy, r, stroke=0, fill=1)
        else:
            c.wedge(cx - r, cy - r, cx + r, cy + r, 90, extent, stroke=0, fill=1)
    c.setFillColor(colors.white)
    c.circle(cx, cy, r * 0.60, stroke=0, fill=1)
    c.restoreState()


# ═══════════════════════════════════════════════════════════════════════════
# 🆕 DESIGN SYSTEM PDF UNIFIÉ — les mêmes fonctions ci-dessous dessinent le
# bandeau navy/or, la carte d'identité, le tableau et le pied de page utilisés
# par le bulletin scolaire, et sont désormais réutilisées par TOUS les autres
# documents PDF officiels (reçus/factures de paiement, bulletins de paie du
# personnel enseignant et non-enseignant) afin qu'ils partagent exactement la
# même identité visuelle premium (même couleurs, même blason, même typographie).
# ═══════════════════════════════════════════════════════════════════════════

def _doc_premium_header(c, ML, CW, H, title_main, subtitle_label, badge_text, medallion_lines,
                         logo_path=None, banniere_path=None, header_h=3.9 * cm):
    """Bandeau d'en-tête premium générique — EXACTEMENT le même dessin que le bandeau du
    bulletin scolaire (blason/logo à gauche, titre + sous-titre + pastille dorée au centre,
    médaillon à droite ; ou bannière personnalisée de l'école si elle a été uploadée).
    Retourne header_bot (bas du bandeau) pour enchaîner avec la suite du document."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    NAVY_LIGHT = colors.HexColor(_BULLETIN_NAVY_LIGHT)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)

    header_top = H - ML
    header_bot = header_top - header_h
    if banniere_path:
        c.saveState()
        p = c.beginPath()
        p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
        c.clipPath(p, stroke=0, fill=0)
        try:
            img = _bulletin_safe_image(banniere_path)
            iw, ih = img.getSize()
            scale = max(CW / iw, header_h / ih)
            dw, dh = iw * scale, ih * scale
            dx = ML + (CW - dw) / 2
            dy = header_bot + (header_h - dh) / 2
            c.drawImage(img, dx, dy, width=dw, height=dh, preserveAspectRatio=True, mask='auto')
        except Exception:
            c.setFillColor(NAVY)
            c.rect(ML, header_bot, CW, header_h, stroke=0, fill=1)
        c.restoreState()
    else:
        _bulletin_rounded_rect(c, ML, header_bot, CW, header_h, 0.35 * cm, fill=NAVY)
        c.saveState()
        p = c.beginPath()
        p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
        c.clipPath(p, stroke=0, fill=0)
        c.setFillColor(NAVY_LIGHT)
        c.rect(ML, header_top - 0.06 * cm, CW, 0.06 * cm, stroke=0, fill=1)
        c.restoreState()

        crest_cx = ML + 2.0 * cm
        crest_cy = header_bot + header_h / 2 + 0.15 * cm
        _bulletin_draw_crest(c, crest_cx, crest_cy, 2.6 * cm, logo_path=logo_path)
        if not logo_path:
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 8.4)
            c.drawCentredString(crest_cx, crest_cy - 1.55 * cm, 'ÉCOLE')

        center_x = ML + CW / 2 + 0.3 * cm
        c.setFillColor(colors.white)
        c.setFont('Helvetica-Bold', 22)
        c.drawCentredString(center_x, header_top - 1.35 * cm, title_main)
        c.setFillColor(GOLD_LIGHT)
        c.setFont('Helvetica-Bold', 11)
        c.drawCentredString(center_x, header_top - 1.95 * cm, subtitle_label.upper())
        sep_y = header_top - 2.35 * cm
        c.setStrokeColor(GOLD)
        c.setLineWidth(0.7)
        c.line(center_x - 2.9 * cm, sep_y, center_x - 0.35 * cm, sep_y)
        c.line(center_x + 0.35 * cm, sep_y, center_x + 2.9 * cm, sep_y)
        _bulletin_diamond(c, center_x, sep_y, 0.09 * cm, GOLD)
        pill_w, pill_h = 7.2 * cm, 0.68 * cm
        badge_txt, badge_size = _bulletin_fit_right_text(badge_text, 'Helvetica-Bold', pill_w - 0.6 * cm,
                                                          max_size=9.2, min_size=6.8)
        _bulletin_rounded_rect(c, center_x - pill_w / 2, sep_y - 0.35 * cm - pill_h, pill_w, pill_h,
                               pill_h / 2, fill=GOLD)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', badge_size)
        c.drawCentredString(center_x, sep_y - 0.35 * cm - pill_h / 2 - 3, badge_txt)

        medal_cx = ML + CW - 2.05 * cm
        medal_cy = header_bot + header_h / 2 + 0.25 * cm
        _bulletin_draw_medallion(c, medal_cx, medal_cy, 1.55 * cm, medallion_lines,
                                 tail_bottom_y=header_bot - 1.0 * cm)
    return header_bot


def _doc_identity_card(c, ML, CW, card_top, card_h, initials, photo_path, nom_complet, info_lines,
                        stat_labels, note_title, note_body, note_footer=None):
    """Carte d'identité premium générique — même dessin que la carte d'identité élève du bulletin
    scolaire (avatar rond cerclé d'or, informations, indicateurs chiffrés, encart texte à droite).
    Retourne card_bot (bas de la carte)."""
    from reportlab.lib import colors
    from reportlab.platypus import Paragraph
    from reportlab.lib.styles import ParagraphStyle
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    CREAM = colors.HexColor(_BULLETIN_CREAM)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)

    card_bot = card_top - card_h
    _bulletin_rounded_rect(c, ML, card_bot, CW, card_h, 0.3 * cm, fill=CREAM, stroke=BORDER, lw=0.8)

    photo_r = 1.6 * cm
    photo_cx = ML + 0.5 * cm + photo_r
    photo_cy = card_bot + card_h / 2
    _bulletin_draw_avatar(c, photo_cx, photo_cy, photo_r, image_path=photo_path, initials=initials)

    info_x = photo_cx + photo_r + 0.5 * cm
    c.setFillColor(TEXT_DARK)
    c.setFont('Helvetica-Bold', 9.5)
    # 🔄 Nom en plus petit sur la facture/reçu et les bulletins de paie (demande explicite :
    # le nom ne doit pas dominer visuellement la carte d'identité sur ces documents).
    nom_txt, nom_size = _bulletin_fit_right_text(nom_complet.upper(), 'Helvetica-Bold',
                                                 10.0 * cm, max_size=9.5, min_size=7.0)
    c.setFont('Helvetica-Bold', nom_size)
    c.drawString(info_x, card_top - 0.8 * cm, nom_txt)
    # 🩹 FIX chevauchement (« nom du parent / montant croisés ») : la largeur disponible pour
    # la valeur (ex: nom du parent, description) était fixée à 7.3cm, ce qui débordait très
    # largement sur la colonne des montants (qui commence à ML+10.55cm) et sur l'encart de
    # droite. On borne désormais la largeur au véritable espace disponible avant cette colonne.
    stat_x = ML + 10.55 * cm
    val_max_w = (stat_x - 0.35 * cm) - (info_x + 2.55 * cm)
    ly = card_top - 1.5 * cm
    for label, val in info_lines:
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.9)
        c.drawString(info_x, ly, f'{label} :')
        c.setFillColor(TEXT_DARK)
        val_txt, val_size = _bulletin_fit_right_text(str(val), 'Helvetica-Bold', val_max_w,
                                                      max_size=8.1, min_size=6.0)
        c.setFont('Helvetica-Bold', val_size)
        c.drawString(info_x + 2.55 * cm, ly, val_txt)
        ly -= 0.48 * cm

    sy = card_top - 0.55 * cm
    for label, val, col in stat_labels:
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(stat_x, sy, label)
        c.setFillColor(col)
        c.setFont('Helvetica-Bold', 13.5)
        c.drawString(stat_x, sy - 0.6 * cm, val)
        sy -= 1.35 * cm

    app_x = ML + 13.85 * cm
    app_w = CW - 13.85 * cm - 0.3 * cm
    _bulletin_rounded_rect(c, app_x, card_bot + 0.3 * cm, app_w, card_h - 0.6 * cm, 0.22 * cm,
                           fill=colors.white, stroke=BORDER, lw=0.7)
    c.setFillColor(GOLD)
    c.setFont('Helvetica-Bold', 8.3)
    c.drawString(app_x + 0.3 * cm, card_top - 0.65 * cm, note_title)
    style_app = ParagraphStyle('appDoc', fontName='Helvetica', fontSize=8.0, leading=11.2, textColor=TEXT_DARK)
    para = Paragraph(note_body, style_app)
    pw, ph = para.wrap(app_w - 0.6 * cm, card_h)
    para.drawOn(c, app_x + 0.3 * cm, card_top - 0.95 * cm - ph)
    # 🩹 FIX « Cachet & signature de l'établissement » qui débordait de son cadre : ce libellé
    # est désormais centré, sur une police réduite et automatiquement réparti sur deux lignes
    # si besoin (au lieu d'une seule ligne qui dépassait la largeur de l'encart), tout en
    # restant entièrement contenu dans le cadre blanc.
    from xml.sax.saxutils import escape as _xml_escape_footer
    from reportlab.lib.enums import TA_CENTER
    footer_line_y = card_bot + 0.85 * cm
    c.setStrokeColor(colors.HexColor('#D8D2BE'))
    c.setLineWidth(0.6)
    c.line(app_x + 0.3 * cm, footer_line_y, app_x + app_w - 0.3 * cm, footer_line_y)
    footer_txt = _xml_escape_footer(note_footer or 'La Direction')
    style_footer = ParagraphStyle('footerDoc', fontName='Helvetica', fontSize=6.6, leading=7.6,
                                  textColor=TEXT_MUTED, alignment=TA_CENTER)
    para_footer = Paragraph(footer_txt, style_footer)
    footer_w = app_w - 0.6 * cm
    fw, fh = para_footer.wrap(footer_w, card_h)
    # Sécurité supplémentaire : si le texte est encore trop long pour tenir sur 2 lignes dans
    # l'espace restant (cas extrême), on réduit encore la police jusqu'à ce qu'il rentre.
    min_footer_size = 6.6
    while fh > (footer_line_y - (card_bot + 0.22 * cm)) and min_footer_size > 5.0:
        min_footer_size -= 0.3
        style_footer = ParagraphStyle('footerDoc', fontName='Helvetica', fontSize=min_footer_size,
                                      leading=min_footer_size + 1.0, textColor=TEXT_MUTED,
                                      alignment=TA_CENTER)
        para_footer = Paragraph(footer_txt, style_footer)
        fw, fh = para_footer.wrap(footer_w, card_h)
    para_footer.drawOn(c, app_x + 0.3 * cm, footer_line_y - 0.15 * cm - fh)
    return card_bot


def _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=None):
    """Tableau financier premium — même style visuel que le tableau des évaluations du bulletin
    scolaire (en-tête bleu marine, lignes zébrées crème, ligne TOTAL en marine).
    Retourne la hauteur totale dessinée (th)."""
    from reportlab.lib import colors
    from reportlab.platypus import Table, TableStyle
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    data = [headers] + rows + ([total_row] if total_row else [])
    t = Table(data, colWidths=col_w, repeatRows=1)
    last_body_row = len(data) - (2 if total_row else 1)
    style_cmds = [
        ('BACKGROUND', (0, 0), (-1, 0), NAVY),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 8.8),
        ('ROWBACKGROUNDS', (0, 1), (-1, last_body_row), [colors.white, colors.HexColor('#F6F2E7')]),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#E7E2D3')),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('FONTSIZE', (0, 1), (-1, -1), 8.6),
        ('TOPPADDING', (0, 0), (-1, -1), 7.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 7.5),
        ('ALIGN', (-1, 0), (-1, -1), 'RIGHT'),
    ]
    if total_row:
        style_cmds += [
            ('BACKGROUND', (0, -1), (-1, -1), NAVY),
            ('TEXTCOLOR', (0, -1), (-1, -1), colors.white),
            ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
            ('FONTSIZE', (0, -1), (-1, -1), 9.4),
        ]
    t.setStyle(TableStyle(style_cmds))
    tw, th = t.wrap(CW, 0)
    t.drawOn(c, ML, table_top - th)
    return th


def _doc_info_panel(c, ML, CW, panel_top, panel_h, title, lines):
    """Encart d'informations complémentaires premium — même style que le bloc "Observations des
    enseignants" du bulletin scolaire (carte blanche, titre marine centré, contenu en colonnes)."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    _bulletin_rounded_rect(c, ML, panel_top - panel_h, CW, panel_h, 0.25 * cm,
                           fill=colors.white, stroke=BORDER, lw=0.7)
    c.setFillColor(NAVY)
    c.setFont('Helvetica-Bold', 9.4)
    c.drawCentredString(ML + CW / 2, panel_top - 0.5 * cm, title)
    col_w = CW / max(1, len(lines))
    for idx, (label, val) in enumerate(lines):
        cx = ML + idx * col_w + 0.35 * cm
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(cx, panel_top - 1.05 * cm, label)
        c.setFillColor(TEXT_DARK)
        c.setFont('Helvetica-Bold', 8.6)
        c.drawString(cx, panel_top - 1.45 * cm, str(val)[:32])


def _doc_signature_block(c, ML, CW, y_top, labels):
    """Bloc(s) de signature premium — même présentation discrète que le bulletin scolaire
    (ligne fine + libellé), avec 1 à 3 signatures côte à côte selon le document."""
    from reportlab.lib import colors
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    n = len(labels)
    col_w = CW / n
    c.setStrokeColor(BORDER)
    c.setLineWidth(0.6)
    for i, label in enumerate(labels):
        x0 = ML + i * col_w + 0.4 * cm
        x1 = ML + (i + 1) * col_w - 0.4 * cm
        c.line(x0, y_top, x1, y_top)
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 8)
        c.drawCentredString((x0 + x1) / 2, y_top - 0.4 * cm, label)


def _doc_quote_bandeau(c, ML, CW, quote_text, quote_y=1.15 * cm):
    """Bandeau de citation + pied de page — EXACTEMENT le même bandeau marine/or que celui du
    bas du bulletin scolaire, réutilisé pour garder la cohérence visuelle jusqu'au bas de page.
    `quote_y` (bas du bandeau) est ajustable pour les documents plus courts que le bulletin, afin
    de ne pas laisser un grand vide entre le contenu et la citation — jamais en dessous de 1.15cm
    du bas de page, pour ne jamais chevaucher le pied de page."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    quote_h = 1.05 * cm
    quote_y = max(quote_y, 1.15 * cm)
    _bulletin_rounded_rect(c, ML, quote_y, CW, quote_h, 0.2 * cm, fill=NAVY)
    c.setFillColor(GOLD_LIGHT)
    c.setFont('Helvetica-Oblique', 8.6)
    c.drawCentredString(ML + CW / 2, quote_y + quote_h / 2 - 3, quote_text)
    c.setFillColor(TEXT_MUTED)
    c.setFont('Helvetica', 7)
    c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
    c.drawRightString(ML + CW, 0.55 * cm, "Page 1")


@app.route('/export/bulletin/<int:eleve_id>')
@login_required
def export_bulletin_pdf(eleve_id):
    # 🔒 Un enseignant ne doit voir que les notes de sa propre matière : le bulletin complet
    # contient TOUTES les matières (donc celles des autres enseignants), il lui est donc fermé.
    if session.get('role') == 'enseignant':
        flash("Accès non autorisé : le bulletin complet n'est pas accessible aux enseignants.", 'error')
        return redirect(url_for('gestion_notes'))
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.platypus import Table, TableStyle, Paragraph
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import cm
        from reportlab.pdfgen import canvas as pdfcanvas

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        NAVY_LIGHT = colors.HexColor(_BULLETIN_NAVY_LIGHT)
        GOLD = colors.HexColor(_BULLETIN_GOLD)
        GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
        CREAM = colors.HexColor(_BULLETIN_CREAM)
        BORDER = colors.HexColor(_BULLETIN_BORDER)
        TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
        TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
        GREEN = colors.HexColor(_BULLETIN_GREEN)

        conn = get_db()
        eleve = conn.execute(
            "SELECT e.*, c.nom as classe, c.niveau as niveau, c.cycle as cycle, c.id as classe_id "
            "FROM eleves e LEFT JOIN classes c ON e.classe_id=c.id WHERE e.id=?",
            (eleve_id,)).fetchone()
        if not eleve:
            conn.close()
            return "Élève non trouvé", 404
        if session['role'] == 'parent' and eleve['parent_id'] != session['user_id']:
            conn.close()
            return "Accès refusé", 403

        trimestre = request.args.get('t', '1')
        notes = conn.execute(
            "SELECT n.note, n.commentaire, m.id as matiere_id, m.nom as matiere, m.coefficient, "
            "sm.nom as sous_matiere, sm.coefficient as sm_coefficient "
            "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
            "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
            "WHERE n.eleve_id=? AND n.trimestre=? ORDER BY m.nom, sm.ordre, sm.nom",
            (eleve_id, trimestre)).fetchall()

        # 🆕 Classement dans la classe pour CE trimestre (cohérent avec les données affichées
        # sur le bulletin, plutôt que le classement cumulé toute l'année utilisé sur la fiche élève)
        rang, total_classe = None, None
        if eleve['classe_id']:
            classement = conn.execute("""
                SELECT e.id,
                       SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) AS moyenne
                FROM eleves e
                LEFT JOIN (
                    SELECT eleve_id, matiere_id, coef_matiere,
                           SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) AS matiere_moy
                    FROM (
                        SELECT n.eleve_id, n.matiere_id, m.coefficient AS coef_matiere, n.note,
                               COALESCE(sm.coefficient, 1) AS coef_sm
                        FROM notes n
                        JOIN matieres m ON m.id = n.matiere_id
                        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                        WHERE n.trimestre = ?
                    ) raw
                    GROUP BY eleve_id, matiere_id, coef_matiere
                ) y ON y.eleve_id = e.id
                WHERE e.classe_id = ?
                GROUP BY e.id
                HAVING moyenne IS NOT NULL
                ORDER BY moyenne DESC
            """, (trimestre, eleve['classe_id'])).fetchall()
            total_classe = conn.execute("SELECT COUNT(*) as n FROM eleves WHERE classe_id=?",
                                        (eleve['classe_id'],)).fetchone()['n']
            for i, row in enumerate(classement, start=1):
                if row['id'] == eleve_id:
                    rang = i
                    break

        # 🆕 Évolution T1 → T2 (mêmes formules que la fiche élève / le tableau de bord)
        evol_valeurs = []
        for t in (1, 2):
            notes_t = conn.execute(
                "SELECT n.*, m.nom as matiere, m.coefficient, sm.coefficient as sm_coefficient "
                "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
                "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
                "WHERE n.eleve_id=? AND n.trimestre=?", (eleve_id, t)).fetchall()
            if notes_t:
                moy_t, _ = _moyenne_ponderee_matieres(notes_t)
                evol_valeurs.append(round(moy_t, 2))
            else:
                evol_valeurs.append(None)

        # 🆕 Absences / retards (comptage factuel — aucun pourcentage inventé faute de nombre
        # de jours de classe suivi précisément dans l'app)
        nb_absences = conn.execute("SELECT COUNT(*) as n FROM absences WHERE eleve_id=?",
                                   (eleve_id,)).fetchone()['n']
        nb_retards = conn.execute("SELECT COUNT(*) as n FROM retards WHERE eleve_id=?",
                                  (eleve_id,)).fetchone()['n']

        photo_path = None
        if eleve['photo']:
            candidate = os.path.join(UPLOAD_FOLDER_PHOTOS, eleve['photo'])
            if os.path.exists(candidate):
                photo_path = candidate
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate

        # 🆕 Bannière personnalisée de l'école (remplace le bandeau bleu marine si uploadée)
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        # 🆕 Appréciation générale (admin/agent-admin) & observations des enseignants (enseignant)
        # saisies manuellement pour ce trimestre — utilisées à la place du texte auto-généré.
        appr_row = conn.execute(
            "SELECT appreciation_generale, observation_enseignant FROM bulletin_appreciations WHERE eleve_id=? AND trimestre=?",
            (eleve_id, trimestre)).fetchone()
        appreciation_manuelle = (appr_row['appreciation_generale'] or '').strip() if appr_row else ''
        observation_manuelle = (appr_row['observation_enseignant'] or '').strip() if appr_row else ''

        conn.close()

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # ═══ 1) BANDEAU D'EN-TÊTE ═══
        header_h = 3.9 * cm
        header_top = H - ML
        header_bot = header_top - header_h
        if banniere_path:
            # 🆕 Bannière personnalisée de l'école : remplace entièrement le bandeau bleu marine
            # par la photo/bannière uploadée depuis "Mon profil", en mode "cover" (remplit tout
            # le bandeau, sans bande vide, recadrée si nécessaire) et respecte les coins arrondis.
            c.saveState()
            p = c.beginPath()
            p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
            c.clipPath(p, stroke=0, fill=0)
            try:
                img = _bulletin_safe_image(banniere_path)
                iw, ih = img.getSize()
                scale = max(CW / iw, header_h / ih)
                dw, dh = iw * scale, ih * scale
                dx = ML + (CW - dw) / 2
                dy = header_bot + (header_h - dh) / 2
                c.drawImage(img, dx, dy, width=dw, height=dh, preserveAspectRatio=True, mask='auto')
            except Exception:
                c.setFillColor(NAVY)
                c.rect(ML, header_bot, CW, header_h, stroke=0, fill=1)
            c.restoreState()
        else:
            _bulletin_rounded_rect(c, ML, header_bot, CW, header_h, 0.35 * cm, fill=NAVY)
            c.saveState()
            p = c.beginPath()
            p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
            c.clipPath(p, stroke=0, fill=0)
            c.setFillColor(NAVY_LIGHT)
            c.rect(ML, header_top - 0.06 * cm, CW, 0.06 * cm, stroke=0, fill=1)
            c.restoreState()

            crest_cx = ML + 2.0 * cm
            crest_cy = header_bot + header_h / 2 + 0.15 * cm
            _bulletin_draw_crest(c, crest_cx, crest_cy, 2.6 * cm, logo_path=logo_path)
            if not logo_path:
                c.setFillColor(colors.white)
                c.setFont('Helvetica-Bold', 8.4)
                c.drawCentredString(crest_cx, crest_cy - 1.55 * cm, 'ÉCOLE')

            center_x = ML + CW / 2 + 0.3 * cm
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 25)
            c.drawCentredString(center_x, header_top - 1.35 * cm, 'BULLETIN SCOLAIRE')
            c.setFillColor(GOLD_LIGHT)
            c.setFont('Helvetica-Bold', 11.5)
            cycle_label = f"ENSEIGNEMENT {(eleve['cycle'] or 'SCOLAIRE').upper()}"
            c.drawCentredString(center_x, header_top - 1.95 * cm, cycle_label)
            sep_y = header_top - 2.35 * cm
            c.setStrokeColor(GOLD)
            c.setLineWidth(0.7)
            c.line(center_x - 2.6 * cm, sep_y, center_x - 0.35 * cm, sep_y)
            c.line(center_x + 0.35 * cm, sep_y, center_x + 2.6 * cm, sep_y)
            _bulletin_diamond(c, center_x, sep_y, 0.09 * cm, GOLD)
            pill_w, pill_h = 5.4 * cm, 0.68 * cm
            _bulletin_rounded_rect(c, center_x - pill_w / 2, sep_y - 0.35 * cm - pill_h, pill_w, pill_h,
                                   pill_h / 2, fill=GOLD)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.2)
            c.drawCentredString(center_x, sep_y - 0.35 * cm - pill_h / 2 - 3,
                                f'ANNÉE SCOLAIRE {_bulletin_annee_scolaire()}')

            medal_cx = ML + CW - 2.05 * cm
            medal_cy = header_bot + header_h / 2 + 0.25 * cm
            _bulletin_draw_medallion(c, medal_cx, medal_cy, 1.55 * cm,
                                     [('EXCELLENCE', True), ('&', False), ('BIENVEILLANCE', True)],
                                     tail_bottom_y=header_bot - 1.0 * cm)

        # ═══ 2) CARTE D'IDENTITÉ ═══
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = card_top - card_h
        _bulletin_rounded_rect(c, ML, card_bot, CW, card_h, 0.3 * cm, fill=CREAM, stroke=BORDER, lw=0.8)

        photo_r = 1.6 * cm
        photo_cx = ML + 0.5 * cm + photo_r
        photo_cy = card_bot + card_h / 2
        initials = (eleve['prenom'][:1] + eleve['nom'][:1]) if eleve['prenom'] else '?'
        _bulletin_draw_avatar(c, photo_cx, photo_cy, photo_r, image_path=photo_path, initials=initials)

        info_x = photo_cx + photo_r + 0.5 * cm
        c.setFillColor(TEXT_DARK)
        # 🩹 Nom/prénom de l'élève réduit (était 14.5 — trop grand, débordait sur certains
        # noms longs à côté de la photo)
        c.setFont('Helvetica-Bold', 11.5)
        c.drawString(info_x, card_top - 0.8 * cm, f"{eleve['prenom']} {eleve['nom']}".upper())
        info_lines = [
            ('Né(e) le', _bulletin_date_fr(eleve['date_naissance']) or '—'),
            ('Niveau', eleve['niveau'] or '—'),
            ('Classe', eleve['classe'] or '—'),
            ('Effectif classe', f"{total_classe} élèves" if total_classe else '—'),
        ]
        ly = card_top - 1.5 * cm
        for label, val in info_lines:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.9)
            c.drawString(info_x, ly, f'{label} :')
            c.setFillColor(TEXT_DARK)
            c.setFont('Helvetica-Bold', 8.1)
            c.drawString(info_x + 2.55 * cm, ly, str(val))
            ly -= 0.48 * cm

        moyenne_generale = evol_valeurs[int(trimestre) - 1] if trimestre in ('1', '2') else None
        assiduite_label = f"{nb_absences} absence{'s' if nb_absences > 1 else ''}"
        assiduite_color = GREEN if nb_absences == 0 else (colors.HexColor(_BULLETIN_AMBER) if nb_absences <= 5 else colors.HexColor(_BULLETIN_RED))

        stat_x = ML + 10.55 * cm
        stat_labels = [
            ('Moyenne générale', f"{moyenne_generale:.2f}/20" if moyenne_generale is not None else '—',
             _bulletin_note_color(moyenne_generale)),
            ('Rang', f"{rang}e/{total_classe}" if rang else '—', NAVY),
            ('Assiduité', assiduite_label, assiduite_color),
        ]
        sy = card_top - 0.55 * cm
        for label, val, col in stat_labels:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.6)
            c.drawString(stat_x, sy, label)
            c.setFillColor(col)
            c.setFont('Helvetica-Bold', 14)
            c.drawString(stat_x, sy - 0.6 * cm, val)
            sy -= 1.35 * cm

        app_x = ML + 13.85 * cm
        app_w = CW - 13.85 * cm - 0.3 * cm
        _bulletin_rounded_rect(c, app_x, card_bot + 0.3 * cm, app_w, card_h - 0.6 * cm, 0.22 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(GOLD)
        c.setFont('Helvetica-Bold', 8.3)
        c.drawString(app_x + 0.3 * cm, card_top - 0.65 * cm, 'APPRÉCIATION GÉNÉRALE')
        appr_generale = _bulletin_appreciation(moyenne_generale)
        if appreciation_manuelle:
            # 🆕 Priorité au texte saisi manuellement par l'admin/agent-admin (page Notes de la
            # fiche élève) sur le texte auto-généré à partir de la moyenne.
            from xml.sax.saxutils import escape as _xml_escape
            txt_appr = _xml_escape(appreciation_manuelle).replace('\n', '<br/>')
        elif moyenne_generale is None:
            txt_appr = "Aucune note enregistrée pour ce trimestre."
        elif moyenne_generale >= 14:
            txt_appr = f"{eleve['prenom']} obtient d'excellents résultats ce trimestre ({appr_generale.lower()}), avec sérieux et régularité. Continuez ainsi !"
        elif moyenne_generale >= 10:
            txt_appr = f"{eleve['prenom']} obtient des résultats {appr_generale.lower()} ce trimestre. Des efforts réguliers permettront de progresser encore."
        else:
            txt_appr = f"Ce trimestre reste difficile pour {eleve['prenom']}. Un accompagnement rapproché est recommandé pour consolider les bases."
        style_app = ParagraphStyle('app', fontName='Helvetica', fontSize=8.0, leading=10.8, textColor=TEXT_DARK)
        para = Paragraph(txt_appr, style_app)
        pw, ph = para.wrap(app_w - 0.6 * cm, card_h)
        para.drawOn(c, app_x + 0.3 * cm, card_top - 0.95 * cm - ph)
        c.setStrokeColor(colors.HexColor('#D8D2BE'))
        c.setLineWidth(0.6)
        c.line(app_x + 0.3 * cm, card_bot + 0.75 * cm, app_x + app_w - 0.3 * cm, card_bot + 0.75 * cm)
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(app_x + 0.3 * cm, card_bot + 0.55 * cm, 'La Direction')

        # ═══ 3) TABLEAU DES ÉVALUATIONS ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Matière', 'Moyenne /20', 'Coeff.', 'Moyenne pondérée', 'Appréciation']
        data = [headers]
        row_is_detail = []
        observations = []
        if observation_manuelle:
            # 🆕 Observation générale saisie manuellement (admin ou enseignant, page Notes de la
            # fiche élève) — affichée en premier dans le bloc "Observations des enseignants".
            from xml.sax.saxutils import escape as _xml_escape_obs
            observations.append({'matiere': 'Observation générale',
                                 'texte': _xml_escape_obs(observation_manuelle)})
        if notes:
            par_matiere = {}
            for n in notes:
                d = par_matiere.setdefault(n['matiere_id'], {
                    'nom': n['matiere'], 'coefficient': n['coefficient'] or 1, 'pts': 0.0,
                    'coef_sum': 0.0, 'details': [], 'commentaires': []
                })
                coef_sm = n['sm_coefficient'] if (n['sous_matiere'] and n['sm_coefficient']) else 1
                d['pts'] += n['note'] * coef_sm
                d['coef_sum'] += coef_sm
                d['details'].append(n)
                if n['commentaire']:
                    d['commentaires'].append(n['commentaire'])

            total_pts = total_coef = 0.0
            for mat_id, d in sorted(par_matiere.items(), key=lambda kv: kv[1]['nom']):
                moy_matiere = d['pts'] / d['coef_sum'] if d['coef_sum'] else 0
                data.append([d['nom'], f"{moy_matiere:.2f}", str(d['coefficient']),
                            f"{moy_matiere * d['coefficient']:.2f}", _bulletin_appreciation(moy_matiere)])
                if any(n['sous_matiere'] for n in d['details']):
                    for n in d['details']:
                        if n['sous_matiere']:
                            data.append([f"   · {n['sous_matiere']}", f"{n['note']:.2f}",
                                        f"(coef {n['sm_coefficient'] or 1:g})", '', n['commentaire'] or ''])
                            row_is_detail.append(len(data) - 1)
                total_pts += moy_matiere * d['coefficient']
                total_coef += d['coefficient']
                if d['commentaires']:
                    observations.append({'matiere': d['nom'], 'texte': '; '.join(d['commentaires'])})
            data.append(['TOTAL', '', f"{total_coef:g}", f"{total_pts:.2f}", ''])

            col_w = [5.5 * cm, 3.0 * cm, 2.3 * cm, 3.8 * cm, 4.0 * cm]
            t = Table(data, colWidths=col_w, repeatRows=1)
            style_cmds = [
                ('BACKGROUND', (0, 0), (-1, 0), NAVY),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, 0), 8.6),
                ('BACKGROUND', (0, -1), (-1, -1), NAVY),
                ('TEXTCOLOR', (0, -1), (-1, -1), colors.white),
                ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                ('ROWBACKGROUNDS', (0, 1), (-1, -2), [colors.white, colors.HexColor('#F6F2E7')]),
                ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#E7E2D3')),
                ('ALIGN', (1, 0), (3, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTSIZE', (0, 1), (-1, -1), 8.2),
                ('TOPPADDING', (0, 0), (-1, -1), 5.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 5.5),
            ]
            for ridx in row_is_detail:
                style_cmds.append(('FONTSIZE', (0, ridx), (-1, ridx), 7.3))
                style_cmds.append(('TEXTCOLOR', (0, ridx), (-1, ridx), TEXT_MUTED))
            t.setStyle(TableStyle(style_cmds))
            tw, th = t.wrap(CW, 0)
            t.drawOn(c, ML, table_top - th)
        else:
            th = 1.2 * cm
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica-Oblique', 9)
            c.drawString(ML, table_top - 0.7 * cm, "Aucune note disponible pour ce trimestre.")

        # ═══ 4) TROIS CARTES (résumé / évolution / appréciations) ═══
        row2_top = table_top - th - 0.4 * cm
        row2_h = 4.7 * cm
        gap = 0.35 * cm
        card_w3 = (CW - 2 * gap) / 3

        moys_matieres = {row[0]: float(row[1]) for row in data[1:-1] if row not in [data[i] for i in row_is_detail]} if notes else {}
        # (recalcul propre à partir de par_matiere pour éviter tout risque de parsing)
        meilleure_txt = plus_basse_txt = '—'
        if notes and par_matiere:
            moy_par_nom = {}
            for mat_id, d in par_matiere.items():
                moy_par_nom[d['nom']] = d['pts'] / d['coef_sum'] if d['coef_sum'] else 0
            if moy_par_nom:
                nom_max = max(moy_par_nom, key=lambda k: moy_par_nom[k])
                nom_min = min(moy_par_nom, key=lambda k: moy_par_nom[k])
                meilleure_txt = f"{nom_max} ({moy_par_nom[nom_max]:.2f})"
                plus_basse_txt = f"{nom_min} ({moy_par_nom[nom_min]:.2f})"

        x1 = ML
        _bulletin_rounded_rect(c, x1, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x1 + 0.35 * cm, row2_top - 0.55 * cm, 'RÉSUMÉ DES RÉSULTATS')
        resume_rows = [
            ('Moyenne générale', f"{moyenne_generale:.2f}/20" if moyenne_generale is not None else '—', False),
            ('Rang', f"{rang}/{total_classe}" if rang else '—', False),
            ('Meilleure matière', meilleure_txt, True),
            ('Matière la plus faible', plus_basse_txt, True),
            ('Absences / Retards', f"{nb_absences} / {nb_retards}", False),
        ]
        ry = row2_top - 1.15 * cm
        for label, val, matiere_petite in resume_rows:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.6)
            c.drawString(x1 + 0.35 * cm, ry, label)
            c.setFillColor(TEXT_DARK)
            if matiere_petite:
                # 🩹 Nom de matière : taille de police ajustée dynamiquement (et tronquée en
                # dernier recours avec "…") pour ne jamais chevaucher le libellé à gauche,
                # quelle que soit la longueur du nom de la matière.
                from reportlab.pdfbase.pdfmetrics import stringWidth
                label_w = stringWidth(label, 'Helvetica', 7.6)
                avail_w = (card_w3 - 0.7 * cm) - label_w - 0.15 * cm
                fitted_txt, fitted_size = _bulletin_fit_right_text(val, 'Helvetica-Bold', avail_w)
                c.setFont('Helvetica-Bold', fitted_size)
                c.drawRightString(x1 + card_w3 - 0.35 * cm, ry, fitted_txt)
            else:
                c.setFont('Helvetica-Bold', 8.4)
                c.drawRightString(x1 + card_w3 - 0.35 * cm, ry, str(val)[:26])
            ry -= 0.68 * cm

        x2 = x1 + card_w3 + gap
        _bulletin_rounded_rect(c, x2, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x2 + 0.35 * cm, row2_top - 0.55 * cm, 'ÉVOLUTION DE LA MOYENNE')
        _bulletin_mini_line_chart(c, x2 + 0.15 * cm, row2_top - row2_h + 0.15 * cm,
                                  card_w3 - 0.3 * cm, row2_h - 0.8 * cm,
                                  ['Trimestre 1', 'Trimestre 2'], evol_valeurs,
                                  line_color=GOLD, area_color=colors.HexColor('#F3E6C4'))

        x3 = x2 + card_w3 + gap
        _bulletin_rounded_rect(c, x3, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x3 + 0.35 * cm, row2_top - 0.55 * cm, 'APPRÉCIATION PAR TRIMESTRE')
        ay = row2_top - 1.25 * cm
        for i, val in enumerate(evol_valeurs, start=1):
            appr = _bulletin_appreciation(val) if val is not None else 'En attente'
            col = _bulletin_note_color(val) if val is not None else TEXT_MUTED
            c.setFillColor(TEXT_DARK)
            c.setFont('Helvetica', 8.4)
            c.drawString(x3 + 0.35 * cm, ay, f'Trimestre {i}')
            c.setFillColor(col)
            c.setFont('Helvetica-Bold', 8.4)
            c.drawRightString(x3 + card_w3 - 0.35 * cm, ay, appr)
            ay -= 0.85 * cm

        # ═══ 5) OBSERVATIONS DES ENSEIGNANTS ═══
        import math as _math
        obs_top = row2_top - row2_h - 0.4 * cm
        n_obs = len(observations)
        obs_rows_count = _math.ceil(n_obs / 3) if n_obs else 1
        obs_h = 0.55 * cm + obs_rows_count * 1.05 * cm + 0.3 * cm
        _bulletin_rounded_rect(c, ML, obs_top - obs_h, CW, obs_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9.4)
        c.drawCentredString(ML + CW / 2, obs_top - 0.5 * cm, 'OBSERVATIONS DES ENSEIGNANTS')
        if observations:
            col_w_obs = CW / 3
            for idx, obs in enumerate(observations):
                col_i = idx % 3
                row_i = idx // 3
                ox = ML + col_i * col_w_obs + 0.3 * cm
                oy = obs_top - 0.95 * cm - row_i * 1.05 * cm
                c.setFillColor(NAVY)
                c.setFont('Helvetica-Bold', 8.2)
                c.drawString(ox, oy, obs['matiere'])
                style_obs = ParagraphStyle('obs', fontName='Helvetica', fontSize=7.4, leading=9.4,
                                           textColor=TEXT_MUTED)
                p2 = Paragraph(obs['texte'], style_obs)
                pw2, ph2 = p2.wrap(col_w_obs - 0.6 * cm, 1 * cm)
                p2.drawOn(c, ox, oy - 0.15 * cm - ph2)
        else:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica-Oblique', 8.2)
            c.drawCentredString(ML + CW / 2, obs_top - 1.0 * cm,
                                "Aucune observation enregistrée pour ce trimestre.")

        # ═══ 6) BANDEAU DE CITATION ═══
        quote_h = 1.05 * cm
        quote_y = 1.15 * cm
        _bulletin_rounded_rect(c, ML, quote_y, CW, quote_h, 0.2 * cm, fill=NAVY)
        c.setFillColor(GOLD_LIGHT)
        c.setFont('Helvetica-Oblique', 8.6)
        c.drawCentredString(ML + CW / 2, quote_y + quote_h / 2 - 3,
                            "« L'éducation est l'arme la plus puissante pour changer le monde. » — Nelson Mandela")

        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7)
        c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
        c.drawRightString(ML + CW, 0.55 * cm, "Page 1")

        # ═══ 7) 🆕 PAGE 2 — ANALYSE GRAPHIQUE DES MATIÈRES (courbe + cercles) ═══
        # Uniquement si des notes existent pour ce trimestre (sinon rien à analyser).
        if notes and par_matiere:
            c.showPage()
            import math as _math2

            # -- 7a) Bandeau d'en-tête (même identité visuelle, format réduit) --
            head2_h = 2.3 * cm
            head2_top = H - ML
            head2_bot = head2_top - head2_h
            _bulletin_rounded_rect(c, ML, head2_bot, CW, head2_h, 0.3 * cm, fill=NAVY)
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 16.5)
            c.drawString(ML + 0.6 * cm, head2_top - 1.05 * cm, 'ANALYSE DES MATIÈRES')
            c.setFillColor(GOLD_LIGHT)
            c.setFont('Helvetica-Bold', 9.5)
            c.drawString(ML + 0.6 * cm, head2_top - 1.65 * cm,
                        f"{eleve['prenom']} {eleve['nom']}".upper() +
                        f"  ·  Trimestre {trimestre}  ·  {_bulletin_annee_scolaire()}")
            c.setFillColor(colors.white)
            c.setFont('Helvetica', 7.6)
            c.drawRightString(ML + CW - 0.6 * cm, head2_top - 1.65 * cm,
                              'Courbe des moyennes et vue circulaire par matière')

            # -- 7b) Courbe des moyennes par matière --
            labels_mat = list(moy_par_nom.keys())
            values_mat = [round(v, 2) for v in moy_par_nom.values()]
            courbe_top = head2_bot - 0.4 * cm
            courbe_h = 7.2 * cm
            _bulletin_rounded_rect(c, ML, courbe_top - courbe_h, CW, courbe_h, 0.3 * cm,
                                   fill=colors.white, stroke=BORDER, lw=0.7)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.6)
            c.drawString(ML + 0.4 * cm, courbe_top - 0.55 * cm, 'COURBE DES MOYENNES PAR MATIÈRE')
            _bulletin_mini_line_chart(c, ML + 0.25 * cm, courbe_top - courbe_h + 0.25 * cm,
                                      CW - 0.5 * cm, courbe_h - 1.1 * cm,
                                      labels_mat, values_mat,
                                      line_color=GOLD, area_color=colors.HexColor('#F3E6C4'))

            # -- 7c) Cercles (donuts) par matière --
            cercles_top = courbe_top - courbe_h - 0.4 * cm
            n_mat = len(labels_mat)
            n_cols = 5 if n_mat > 4 else max(1, n_mat)
            n_rows = _math2.ceil(n_mat / n_cols) if n_mat else 1
            row_h = 3.55 * cm
            cercles_h = 0.7 * cm + n_rows * row_h + 0.25 * cm
            _bulletin_rounded_rect(c, ML, cercles_top - cercles_h, CW, cercles_h, 0.3 * cm,
                                   fill=colors.white, stroke=BORDER, lw=0.7)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.6)
            c.drawCentredString(ML + CW / 2, cercles_top - 0.55 * cm,
                                'VUE CIRCULAIRE DES RÉSULTATS PAR MATIÈRE')
            col_w_cerc = CW / n_cols
            r_donut = 1.05 * cm
            for idx, nom_mat in enumerate(labels_mat):
                col_i = idx % n_cols
                row_i = idx // n_cols
                moy_mat = moy_par_nom[nom_mat]
                cx_d = ML + col_i * col_w_cerc + col_w_cerc / 2
                cy_d = cercles_top - 1.05 * cm - row_i * row_h - r_donut
                col_note = _bulletin_note_color(moy_mat)
                _bulletin_donut_gauge(c, cx_d, cy_d, r_donut, moy_mat / 20.0, col_note)
                c.setFillColor(TEXT_DARK)
                c.setFont('Helvetica-Bold', 10.5)
                c.drawCentredString(cx_d, cy_d - 3, f"{moy_mat:.1f}")
                c.setFillColor(TEXT_MUTED)
                c.setFont('Helvetica', 6.6)
                c.drawCentredString(cx_d, cy_d - r_donut - 0.32 * cm, '/20')
                nom_txt2, nom_size2 = _bulletin_fit_right_text(nom_mat, 'Helvetica-Bold',
                                                                col_w_cerc - 0.3 * cm,
                                                                max_size=7.6, min_size=5.6)
                c.setFillColor(NAVY)
                c.setFont('Helvetica-Bold', nom_size2)
                c.drawCentredString(cx_d, cy_d - r_donut - 0.72 * cm, nom_txt2)

            # -- 7d) Légende couleurs --
            leg_y = cercles_top - cercles_h - 0.55 * cm
            leg_items = [(GREEN, '≥ 12 : Bien / Excellent'),
                        (colors.HexColor(_BULLETIN_AMBER), '8 à 12 : Passable'),
                        (colors.HexColor(_BULLETIN_RED), '< 8 : Insuffisant')]
            lx0 = ML + CW / 2 - 6.6 * cm
            for col_leg, txt_leg in leg_items:
                c.setFillColor(col_leg)
                c.circle(lx0 + 0.15 * cm, leg_y + 0.1 * cm, 0.15 * cm, stroke=0, fill=1)
                c.setFillColor(TEXT_MUTED)
                c.setFont('Helvetica', 7.4)
                c.drawString(lx0 + 0.4 * cm, leg_y, txt_leg)
                lx0 += 4.4 * cm

            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7)
            c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
            c.drawRightString(ML + CW, 0.55 * cm, "Page 2")

        c.save()
        buf.seek(0)
        return send_file(buf, as_attachment=True,
                         download_name=f'bulletin_{eleve["nom"]}_{trimestre}.pdf',
                         mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))



@app.route('/export/recu/<int:paiement_id>')
@login_required
def export_recu_pdf(paiement_id):
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.pdfgen import canvas as pdfcanvas
        from reportlab.lib.units import cm
        from xml.sax.saxutils import escape as _xml_escape

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        GREEN = colors.HexColor(_BULLETIN_GREEN)
        RED = colors.HexColor(_BULLETIN_RED)
        AMBER = colors.HexColor(_BULLETIN_AMBER)

        conn = get_db()
        p = conn.execute(
            "SELECT p.*, e.prenom||' '||e.nom as eleve, e.prenom as eleve_prenom, e.nom as eleve_nom, "
            "e.photo as eleve_photo, c.nom as classe, u.prenom||' '||u.nom as parent, "
            "u.telephone as parent_telephone "
            "FROM paiements p JOIN eleves e ON p.eleve_id=e.id LEFT JOIN classes c ON e.classe_id=c.id "
            "LEFT JOIN users u ON e.parent_id=u.id WHERE p.id=?",
            (paiement_id,)).fetchone()
        conn.close()
        if not p:
            return "Non trouvé", 404

        # 🔄 Mêmes ressources (logo / bannière de l'école) que le bulletin scolaire, pour un
        # en-tête strictement identique sur les deux documents.
        photo_path = None
        if p['eleve_photo']:
            candidate = os.path.join(UPLOAD_FOLDER_PHOTOS, p['eleve_photo'])
            if os.path.exists(candidate):
                photo_path = candidate
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        reste = p['montant_total'] - p['montant_paye']
        statut = (p['statut'] or '').lower()
        if statut == 'paye':
            statut_label, statut_hex = 'PAYÉ INTÉGRALEMENT', _BULLETIN_GREEN
        elif p['montant_paye'] and p['montant_paye'] > 0:
            statut_label, statut_hex = 'PARTIELLEMENT PAYÉ', _BULLETIN_AMBER
        else:
            statut_label, statut_hex = 'NON PAYÉ', _BULLETIN_RED

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # 🆕 Hauteur du bandeau calculée à partir du ratio réel de la bannière uploadée : la
        # largeur du bandeau reste celle de la page (CW), la hauteur suit proportionnellement
        # pour afficher la bannière EN ENTIER sans la recadrer (auparavant, une hauteur fixe de
        # 3.9cm forçait un "zoom" façon cover qui coupait le haut/le bas de l'image quand son
        # ratio ne correspondait pas exactement au bandeau). L'image elle-même n'est jamais
        # modifiée, seule la taille d'affichage du bandeau s'adapte à sa proportion réelle.
        header_h_recu = 3.9 * cm
        if banniere_path:
            try:
                img_banniere = _bulletin_safe_image(banniere_path)
                iw_b, ih_b = img_banniere.getSize()
                header_h_recu = CW * (ih_b / iw_b)
            except Exception:
                header_h_recu = 3.9 * cm

        # ═══ 1) BANDEAU D'EN-TÊTE (identique au bulletin scolaire) ═══
        header_bot = _doc_premium_header(
            c, ML, CW, H,
            title_main='REÇU DE PAIEMENT',
            subtitle_label='FACTURE — ÉTABLISSEMENT SCOLAIRE',
            badge_text=f"REÇU N° {paiement_id:04d} — {datetime.datetime.now().strftime('%d/%m/%Y')}",
            medallion_lines=[('PAIEMENT', True), ('&', False), ('CONFIANCE', True)],
            logo_path=logo_path, banniere_path=banniere_path, header_h=header_h_recu)

        # ═══ 2) CARTE D'IDENTITÉ (identique au bulletin scolaire) ═══
        initials = (p['eleve_prenom'][:1] + p['eleve_nom'][:1]) if p['eleve_prenom'] else '?'
        info_lines = [
            ('Classe', p['classe'] or '—'),
            ('Parent', p['parent'] or '—'),
            ('Téléphone', p['parent_telephone'] or '—'),
            ('Description', p['description'] or '—'),
        ]
        stat_labels = [
            ('Montant total', f"{p['montant_total']:,.2f} MAD".replace(',', ' '), NAVY),
            ('Montant payé', f"{p['montant_paye']:,.2f} MAD".replace(',', ' '), GREEN),
            ('Reste à payer', f"{reste:,.2f} MAD".replace(',', ' '), RED if reste > 0 else GREEN),
        ]
        note_body = (f'<font color="{statut_hex}"><b>{_xml_escape(statut_label)}</b></font><br/>'
                     f'<font color="{_BULLETIN_TEXT_MUTED}" size="7.4">Merci pour votre confiance '
                     f'et la régularité de vos règlements.</font>')
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = _doc_identity_card(
            c, ML, CW, card_top, card_h, initials, photo_path, p['eleve'],
            info_lines, stat_labels, 'STATUT DU PAIEMENT', note_body,
            note_footer="")

        # ═══ 3) TABLEAU FINANCIER (même style que le tableau des évaluations) ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Désignation', 'Montant']
        # 🆕 Si une réduction a été appliquée sur ce paiement, on l'affiche en détail :
        # montant brut (avant réduction) -> ligne réduction -> net à payer (après réduction),
        # puis le montant déjà réglé comme avant. Sans réduction, on garde l'affichage d'origine.
        reduction_appliquee = 0.0
        try:
            reduction_appliquee = float(p['reduction_appliquee'] or 0)
        except (IndexError, KeyError, TypeError, ValueError):
            reduction_appliquee = 0.0
        montant_brut = round((p['montant_total'] or 0) + reduction_appliquee, 2)

        # 🆕 Montant transport déjà facturé sur cette ligne (net, après sa propre réduction
        # éventuelle) — permet de repérer une facture combinée « Scolarité + Transport »
        # (générée par la mensualisation automatique) et de détailler séparément les deux
        # postes sur le reçu, au lieu d'un seul bloc fusionné.
        montant_transport_p = 0.0
        try:
            montant_transport_p = float(p['montant_transport'] or 0)
        except (IndexError, KeyError, TypeError, ValueError):
            montant_transport_p = 0.0

        if montant_transport_p > 0:
            # Facture combinée Scolarité + Transport : on sépare les deux postes, chacun avec
            # son montant initial et sa propre réduction (les pourcentages de réduction sont
            # récupérés dans le libellé de la facture, où ils sont enregistrés indépendamment
            # l'un de l'autre lors de la génération — ex : "10% sur la mensualité + 5% sur le
            # transport").
            import re as _re_recu
            desc_txt = str(p['description'] or '')
            m_scol = _re_recu.search(r'([\d.,]+)\s*%\s*sur la mensualit', desc_txt)
            m_trans = _re_recu.search(r'([\d.,]+)\s*%\s*sur le transport', desc_txt)
            pct_scol = float(m_scol.group(1).replace(',', '.')) if m_scol else 0.0
            pct_trans = float(m_trans.group(1).replace(',', '.')) if m_trans else 0.0

            scolarite_net = round((p['montant_total'] or 0) - montant_transport_p, 2)
            transport_net = montant_transport_p

            scolarite_brut = round(scolarite_net / (1 - pct_scol / 100), 2) if pct_scol > 0 else scolarite_net
            reduction_scol_montant = round(scolarite_brut - scolarite_net, 2) if pct_scol > 0 else 0.0

            transport_brut = round(transport_net / (1 - pct_trans / 100), 2) if pct_trans > 0 else transport_net
            reduction_trans_montant = round(transport_brut - transport_net, 2) if pct_trans > 0 else 0.0

            rows = [['Frais de scolarité', f"{scolarite_brut:,.2f} MAD".replace(',', ' ')]]
            if reduction_scol_montant > 0:
                rows.append([f'Réduction scolarité ({pct_scol:g}%)', f"- {reduction_scol_montant:,.2f} MAD".replace(',', ' ')])
            rows.append(['Frais de transport', f"{transport_brut:,.2f} MAD".replace(',', ' ')])
            if reduction_trans_montant > 0:
                rows.append([f'Réduction transport ({pct_trans:g}%)', f"- {reduction_trans_montant:,.2f} MAD".replace(',', ' ')])
            rows.append(['Total à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')])
            rows.append(['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')])
        elif reduction_appliquee > 0:
            # 🆕 Taux de réduction toujours affiché à côté de la ligne "Réduction appliquée" :
            # on le récupère depuis le libellé de la facture (déjà enregistré lors de sa
            # création — ex : "10% sur la mensualité" ou "(Réduction 10% appliquée)" pour un
            # Frais d'inscription), avec un repli sur un calcul à partir des montants si le
            # libellé ne contient pas de pourcentage exploitable.
            import re as _re_recu2
            desc_txt2 = str(p['description'] or '')
            m_pct = (_re_recu2.search(r'([\d.,]+)\s*%\s*sur la mensualit', desc_txt2)
                     or _re_recu2.search(r'Réduction\s*([\d.,]+)\s*%\s*appliquée', desc_txt2)
                     or _re_recu2.search(r'([\d.,]+)\s*%', desc_txt2))
            if m_pct:
                pct_reduc = float(m_pct.group(1).replace(',', '.'))
            elif montant_brut > 0:
                pct_reduc = round(reduction_appliquee / montant_brut * 100, 2)
            else:
                pct_reduc = 0.0
            rows = [
                [p['description'] or 'Frais de scolarité', f"{montant_brut:,.2f} MAD".replace(',', ' ')],
                [f'Réduction appliquée ({pct_reduc:g}%)', f"- {reduction_appliquee:,.2f} MAD".replace(',', ' ')],
                ['Net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')],
                ['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')],
            ]
        else:
            rows = [
                [p['description'] or 'Frais de scolarité', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')],
                ['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')],
            ]
        total_row = ['SOLDE RESTANT DÛ', f"{reste:,.2f} MAD".replace(',', ' ')]
        col_w = [12.6 * cm, 6.0 * cm]
        th = _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=total_row)

        # ═══ 4) ENCART INFORMATIONS COMPLÉMENTAIRES ═══
        panel_top = table_top - th - 0.4 * cm
        panel_h = 1.9 * cm
        # 🆕 "Mois payé" (ou "Saison payée" pour un Frais d'inscription) remplace "Date
        # d'échéance" (peu utile sur un reçu déjà réglé), et "Date de paiement" affiche
        # désormais le jour complet (uniquement sur ce document).
        categorie_recu = ''
        if p['description'] and ']' in str(p['description']):
            categorie_recu = str(p['description']).split(']')[0].lstrip('[').strip()
        label_periode = 'Saison payée' if categorie_recu.lower() == "frais d'inscription" else 'Mois payé'
        mois_paye = _label_mois_paye(p) or '—'
        date_paie = _bulletin_date_fr(p['date_paiement']) or '—'
        _doc_info_panel(c, ML, CW, panel_top, panel_h, 'INFORMATIONS COMPLÉMENTAIRES', [
            (label_periode, mois_paye),
            ('Date de paiement', date_paie),
            ('Année scolaire', _bulletin_annee_scolaire()),
        ])

        # ═══ 5) SIGNATURE ═══
        sig_y = panel_top - panel_h - 1.6 * cm

        # 🆕 Mention "Fait à FES, le [date complète]" (convention factures), juste au-dessus de
        # la signature — seule date à apparaître en entier (jour + mois + année) sur le document.
        c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
        c.setFont('Helvetica', 8)
        c.drawRightString(ML + CW, sig_y + 0.5 * cm,
                          f"Fait à FES, le {_bulletin_date_fr(datetime.datetime.now().strftime('%Y-%m-%d'))}")

        _doc_signature_block(c, ML, CW, sig_y,
                             ["Cachet & signature de l'établissement"])

        # ═══ 6) BANDEAU DE CITATION + PIED DE PAGE (identique au bulletin scolaire) ═══
        _doc_quote_bandeau(c, ML, CW,
                           "« La confiance est la monnaie la plus précieuse d'un partenariat durable. »",
                           quote_y=sig_y - 1.9 * cm)

        c.save()
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name=f'recu_{paiement_id:04d}.pdf',
                         mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur: {ex}', 'error');
        return redirect(url_for('paiements'))


@app.route('/export/bulletin-paie/enseignant/<int:paiement_id>')
@login_required
@role_required('admin')
def export_bulletin_paie_enseignant(paiement_id):
    # 🆕 AGENT ADMIN : pas d'accès aux fiches de paie des enseignants
    if session.get('role') == 'agent_admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements_enseignants'))
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.pdfgen import canvas as pdfcanvas
        from reportlab.lib.units import cm
        from xml.sax.saxutils import escape as _xml_escape

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        GREEN = colors.HexColor(_BULLETIN_GREEN)

        conn = get_db()
        p = conn.execute("""
                         SELECT pe.*, u.nom, u.prenom, u.cin, u.cnss, u.adresse,
                                u.matiere_specialite, u.date_embauche, u.telephone
                         FROM paiements_enseignants pe
                                  JOIN users u ON pe.enseignant_id = u.id
                         WHERE pe.id = ?
                         """, (paiement_id,)).fetchone()
        conn.close()

        if not p:
            flash('Fiche de paie introuvable.', 'error')
            return redirect(url_for('paiements_enseignants'))
        if p['statut'] != 'paye':
            flash("Le bulletin de paie n'est disponible qu'après validation du paiement.", 'error')
            return redirect(url_for('paiements_enseignants'))

        # 🔄 Mêmes ressources (logo / bannière de l'école) que le bulletin scolaire.
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        type_p = (p['type_paiement'] or 'Mensuel')
        if type_p.lower() == 'mensuel':
            libelle_type = 'Salaire mensuel forfaitaire'
        else:
            libelle_type = f"{type_p} — {p['unites_validees'] or 0} unité(s) validée(s)"
        reste = (p['montant_total'] or 0) - (p['montant_paye'] or 0)

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # ═══ 1) BANDEAU D'EN-TÊTE (identique au bulletin scolaire) ═══
        header_bot = _doc_premium_header(
            c, ML, CW, H,
            title_main='BULLETIN DE PAIE',
            subtitle_label='PERSONNEL ENSEIGNANT',
            badge_text=f"PÉRIODE : {str(p['mois']).upper()}",
            medallion_lines=[('RIGUEUR', True), ('&', False), ('RECONNAISSANCE', True)],
            logo_path=logo_path, banniere_path=banniere_path)

        # ═══ 2) CARTE D'IDENTITÉ (identique au bulletin scolaire) ═══
        initials = (p['prenom'][:1] + p['nom'][:1]) if p['prenom'] else '?'
        info_lines = [
            ('Fonction', f"Enseignant — {p['matiere_specialite'] or 'Non spécifiée'}"),
            ('CIN', p['cin'] or 'N/A'),
            ('N° CNSS', p['cnss'] or 'N/A'),
            ('Téléphone', p['telephone'] or 'N/A'),
            ("Date d'embauche", p['date_embauche'] or 'N/A'),
        ]
        stat_labels = [
            ('Montant net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' '), NAVY),
            ('Montant versé', f"{p['montant_paye']:,.2f} MAD".replace(',', ' '), GREEN),
        ]
        note_body = (f'<font color="{_BULLETIN_GREEN}"><b>PAYÉ ✓</b></font><br/>'
                     f'<font color="{_BULLETIN_TEXT_MUTED}" size="7.4">Bulletin n° {paiement_id:04d} — '
                     f'{_xml_escape(libelle_type)}.</font>')
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = _doc_identity_card(
            c, ML, CW, card_top, card_h, initials, None, f"{p['prenom']} {p['nom']}",
            info_lines, stat_labels, 'STATUT DU PAIEMENT', note_body,
            note_footer='La Direction')

        # ═══ 3) TABLEAU FINANCIER (même style que le tableau des évaluations) ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Désignation', 'Montant']
        rows = [
            ['Type de rémunération', libelle_type],
            ['Montant brut / net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')],
        ]
        total_row = ['MONTANT RÉELLEMENT VERSÉ', f"{p['montant_paye']:,.2f} MAD".replace(',', ' ')]
        col_w = [12.6 * cm, 6.0 * cm]
        th = _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=total_row)

        # ═══ 4) ENCART INFORMATIONS COMPLÉMENTAIRES ═══
        panel_top = table_top - th - 0.4 * cm
        panel_h = 1.9 * cm
        date_p = _bulletin_date_fr(p['date_paiement']) or (p['date_paiement'] or '—')
        _doc_info_panel(c, ML, CW, panel_top, panel_h, 'INFORMATIONS COMPLÉMENTAIRES', [
            ('Adresse', p['adresse'] or '—'),
            ('Date de paiement', date_p),
            ('Année scolaire', _bulletin_annee_scolaire()),
        ])

        # ═══ 5) SIGNATURES ═══
        sig_y = panel_top - panel_h - 1.6 * cm
        _doc_signature_block(c, ML, CW, sig_y,
                             ['Signature Direction', 'Signature Employé'])

        # ═══ 6) BANDEAU DE CITATION + PIED DE PAGE (identique au bulletin scolaire) ═══
        _doc_quote_bandeau(c, ML, CW,
                           "« Le travail accompli avec cœur mérite une reconnaissance à sa mesure. »",
                           quote_y=sig_y - 1.9 * cm)

        c.save()
        buf.seek(0)
        nom_fichier = f'bulletin_paie_{p["nom"]}_{p["prenom"]}_{p["mois"]}.pdf'.replace(' ', '_')
        return send_file(buf, as_attachment=True, download_name=nom_fichier, mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération du bulletin de paie: {ex}', 'error')
        return redirect(url_for('paiements_enseignants'))


@app.route('/export/bulletin-paie/personnel/<int:paiement_id>')
@login_required
@role_required('admin')
def export_bulletin_paie_personnel(paiement_id):
    # 🆕 AGENT ADMIN : pas d'accès aux fiches de paie du personnel hors prof
    if session.get('role') == 'agent_admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements_personnel_hors_prof'))
