# Tri une seule fois du plus long au plus court + compilation regex (mots entiers)
_TRANSLATIONS_PATTERNS = [
    (_re_i18n.compile(r'\b' + _re_i18n.escape(fr) + r'\b'), ar)
    for fr, ar in sorted(TRANSLATIONS_AR.items(), key=lambda kv: -len(kv[0]))
]

_SCRIPT_SPLIT_RE = _re_i18n.compile(r'(<script\b[^>]*>.*?</script>)', _re_i18n.DOTALL | _re_i18n.IGNORECASE)

def translate_html(html, lang):
    """Traduit le texte visible d'une page déjà rendue (remplacement par mots entiers).
    Le contenu des balises <script> est préservé tel quel (jamais traduit), par sécurité
    pour ne jamais risquer de casser du code JavaScript."""
    if lang != 'ar' or not html:
        return html
    parts = _SCRIPT_SPLIT_RE.split(html)
    for i, part in enumerate(parts):
        if part.startswith('<script'):
            continue  # ne pas toucher au JavaScript
        for pattern, ar in _TRANSLATIONS_PATTERNS:
            part = pattern.sub(ar, part)
        parts[i] = part
    html = ''.join(parts)
    # Bascule la direction et la langue du document
    html = _re_i18n.sub(r'<html[^>]*>', '<html lang="ar" dir="rtl">', html, count=1)
    # Injecte la police arabe + les correctifs de mise en page RTL juste avant </head>
    if '</head>' in html:
        html = html.replace('</head>', RTL_CSS + '</head>', 1)
    return html

RTL_CSS = """<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style id="rtl-overrides">
html[dir="rtl"] body, html[dir="rtl"] input, html[dir="rtl"] select, html[dir="rtl"] textarea, html[dir="rtl"] button{
  font-family:'Cairo','Segoe UI',Tahoma,Arial,sans-serif !important;
}
html[dir="rtl"] body{ direction:rtl; }
/* Sidebar passe à droite */
html[dir="rtl"] .sidebar{ left:auto !important; right:0 !important; }
html[dir="rtl"] .sidebar-logo, html[dir="rtl"] .sidebar-role, html[dir="rtl"] .sidebar-footer{ text-align:right; }
html[dir="rtl"] .nav-link{ border-left:none !important; border-right:3px solid transparent; flex-direction:row-reverse; }
html[dir="rtl"] .nav-link:hover, html[dir="rtl"] .nav-link.active{ border-right-color:#60a5fa; border-left-color:transparent !important; }
html[dir="rtl"] .main{ margin-left:0 !important; margin-right:260px !important; }
html[dir="rtl"] .sidebar-toggle{ left:auto !important; right:12px !important; }
html[dir="rtl"] .topbar{ flex-direction:row-reverse; }
html[dir="rtl"] .topbar-actions{ flex-direction:row-reverse; }
html[dir="rtl"] .notif-badge{ right:auto !important; left:0 !important; }
/* Tableaux et texte alignés à droite */
html[dir="rtl"] table th, html[dir="rtl"] table td{ text-align:right; }
html[dir="rtl"] .content, html[dir="rtl"] .container{ text-align:right; }
html[dir="rtl"] .stat-card, html[dir="rtl"] .card-header, html[dir="rtl"] .lux-filter-head, html[dir="rtl"] .robot-reco-card{
  flex-direction:row-reverse;
}
html[dir="rtl"] .lang-toggle-btn{ direction:ltr; }
@media(max-width:960px){
  html[dir="rtl"] .sidebar{ transform:translateX(100%); }
  html[dir="rtl"] body.sidebar-open .sidebar{ transform:translateX(0); }
  html[dir="rtl"] .main{ margin-right:0 !important; }
}
</style>"""

