def nav_html(active_path='', notif_count=0, lang='fr'):
    role = session.get('role', 'admin')
    links = NAV_LINKS.get(role, [])
    role_labels = {'admin': 'Administrateur', 'agent_admin': 'Agent Admin', 'enseignant': 'Enseignant', 'parent': 'Parent', 'chauffeur': 'Chauffeur', 'secretaire': 'Secrétaire'}
    items = ''
    for label, icon, path in links:
        active = 'active' if active_path == path else ''
        badge = f' <span style="background:var(--danger);color:white;border-radius:99px;padding:1px 7px;font-size:.65rem;margin-left:auto;">{notif_count}</span>' if path == '/notifications' and notif_count else ''
        items += f'<a href="{path}" class="nav-link {active}"><span class="icon"><i data-lucide="{icon}"></i></span>{label}{badge}</a>'
    name = session.get('nom_complet', 'Utilisateur')
    initials = ''.join([w[0].upper() for w in name.split()[:2]])
    lang_target = 'fr' if lang == 'ar' else 'ar'
    lang_label = 'FR' if lang == 'ar' else 'AR'
    # 🆕 Logo personnalisé de l'école (uploadé par l'admin) à la place du texte, si présent
    logo_filename = get_logo_filename()
    if logo_filename:
        sidebar_logo_html = (
            '<div class="sidebar-logo sidebar-logo-custom">'
            '<img src="/logo-ecole" alt="Logo de l\'école" class="sidebar-logo-img">'
            '</div>'
        )
    else:
        sidebar_logo_html = (
            '<div class="sidebar-logo"><h1><i data-lucide="school" '
            'style="width:20px;height:20px;vertical-align:-4px;margin-right:6px;"></i>Bright Kidz Private</h1>'
            '<span>Plateforme Scolaire</span></div>'
        )
    return f"""
    {couleurs_personnalisees_style_html()}
    {luxe_3d_style_html()}
    <div class="sidebar-backdrop" onclick="closeSidebar()"></div>
    {'<div id="pushDiagBanner" class="push-banner" style="background:#7A1F1F;"><i data-lucide="alert-triangle" style="width:20px;height:20px;flex-shrink:0;"></i><div class="push-banner-text">Notifications push désactivées côté serveur : le paquet <code>pywebpush</code> est absent (ajoutez-le à requirements.txt puis redéployez).</div><button type="button" class="push-banner-close" onclick="this.closest(\'#pushDiagBanner\').style.display=\'none\'" aria-label="Fermer"><i data-lucide="x" style="width:16px;height:16px;"></i></button></div>' if (role == 'admin' and not VAPID_PUBLIC_KEY_B64) else ''}
    <div id="pushBanner" class="push-banner">
        <i data-lucide="bell-ring" style="width:20px;height:20px;flex-shrink:0;"></i>
        <div class="push-banner-text">Activez les notifications pour recevoir immédiatement les nouveaux messages, devoirs et communications sur votre téléphone.</div>
        <button type="button" class="push-banner-btn" onclick="window._activerNotifsPush && window._activerNotifsPush()">Activer</button>
        <button type="button" class="push-banner-close" onclick="fermerPushBanner()" aria-label="Fermer"><i data-lucide="x" style="width:16px;height:16px;"></i></button>
    </div>
    <button type="button" class="sidebar-toggle" onclick="toggleSidebar()" aria-label="Ouvrir le menu"><i data-lucide="menu"></i></button>
    <div class="sidebar">
        {sidebar_logo_html}
        <div class="sidebar-role">{role_labels.get(role, '')}</div>
        <nav class="sidebar-nav" onclick="closeSidebar()">{items}</nav>
        <div class="sidebar-footer">
            <div style="opacity:.7;font-size:.8rem">{name}</div>
            <a href="/logout" style="color:#1a1a1a;font-size:.8rem;display:inline-flex;align-items:center;gap:4px;font-weight:600;">🚪 Déconnexion</a>
        </div>
    </div>
    <div class="main">
        <div class="topbar">
            <button type="button" class="sidebar-toggle-inline" onclick="toggleSidebar()" aria-label="Ouvrir le menu"><i data-lucide="menu"></i></button>
            <span class="topbar-title" id="page-title">Bright Kidz Private</span>
            <div class="topbar-actions">
                <a href="/set-language/{lang_target}" class="lang-toggle-btn" title="Switch language / تبديل اللغة">{lang_label}</a>
                <div class="notif-bell-wrap">
                    <button type="button" class="notif-bell-btn" onclick="toggleNotifPanel(event)" aria-label="Notifications" aria-haspopup="true" aria-expanded="false" id="notifBellBtn">
                        <i data-lucide="bell" style="width:19px;height:19px;"></i><span class="notif-badge" id="notifBadge" style="{'' if notif_count else 'display:none;'}">{notif_count if notif_count else ''}</span>
                    </button>
                    <div class="notif-panel-backdrop" onclick="closeNotifPanel()"></div>
                    <div class="notif-panel" id="notifPanel" role="dialog" aria-label="Notifications">
                        <div class="notif-panel-header">
                            <span><i data-lucide="bell" style="width:16px;height:16px;vertical-align:-3px;margin-right:6px;"></i>Notifications</span>
                            <button type="button" class="notif-panel-close" onclick="closeNotifPanel()" aria-label="Fermer"><i data-lucide="x" style="width:16px;height:16px;"></i></button>
                        </div>
                        <div class="notif-panel-body" id="notifPanelBody">
                            <div class="notif-panel-loading">
                                <span class="notif-spinner"></span> Chargement…
                            </div>
                        </div>
                        <a href="/notifications" class="notif-panel-footer">Voir toutes les notifications</a>
                    </div>
                </div>
                <a href="/profile" class="user-avatar" title="Mon Profil">{initials}</a>
            </div>
        </div>
        <div class="content">
    <style>
    .notif-bell-wrap{{position:relative;display:inline-flex;align-items:center;}}
    .notif-bell-btn{{position:relative;display:inline-flex;align-items:center;justify-content:center;background:none;border:none;cursor:pointer;color:var(--text-soft);padding:6px;border-radius:10px;transition:background .15s ease;}}
    .notif-bell-btn:hover{{background:var(--gray-100, rgba(0,0,0,.05));}}
    .notif-bell-btn .notif-badge{{position:absolute;top:0;right:0;min-width:16px;height:16px;padding:0 3px;}}
    .notif-panel-backdrop{{position:fixed;inset:0;background:rgba(15,20,30,.35);backdrop-filter:blur(1px);z-index:1000;opacity:0;pointer-events:none;transition:opacity .18s ease;}}
    body.notif-open .notif-panel-backdrop{{opacity:1;pointer-events:auto;}}
    .notif-panel{{position:absolute;top:calc(100% + 12px);right:0;width:360px;max-width:92vw;max-height:70vh;background:var(--card-bg,#fff);border-radius:16px;box-shadow:0 20px 50px rgba(15,23,42,.18),0 2px 8px rgba(15,23,42,.08);border:1px solid var(--gray-200,#eee);z-index:1001;display:flex;flex-direction:column;overflow:hidden;opacity:0;transform:translateY(-8px) scale(.98);pointer-events:none;transition:opacity .16s ease,transform .16s ease;}}
    body.notif-open .notif-panel{{opacity:1;transform:translateY(0) scale(1);pointer-events:auto;}}
    .notif-panel-header{{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;font-weight:700;font-size:.92rem;border-bottom:1px solid var(--gray-100,#f1f1f1);}}
    .notif-panel-close{{background:none;border:none;cursor:pointer;color:var(--gray-500,#888);padding:4px;border-radius:8px;display:inline-flex;}}
    .notif-panel-close:hover{{background:var(--gray-100,#f1f1f1);}}
    .notif-panel-body{{overflow-y:auto;flex:1;}}
    .notif-panel-loading{{padding:28px 16px;text-align:center;color:var(--gray-500,#888);font-size:.85rem;display:flex;align-items:center;justify-content:center;gap:8px;}}
    .notif-spinner{{width:14px;height:14px;border:2px solid var(--gray-200,#ddd);border-top-color:var(--primary,#3b82f6);border-radius:50%;display:inline-block;animation:notifspin .7s linear infinite;}}
    @keyframes notifspin{{to{{transform:rotate(360deg);}}}}
    .notif-panel-item{{padding:12px 16px;border-bottom:1px solid var(--gray-100,#f4f4f4);display:flex;gap:10px;align-items:flex-start;}}
    .notif-panel-item:last-child{{border-bottom:none;}}
    .notif-panel-item.unread{{background:var(--blue-light,#eff6ff);}}
    .notif-panel-dot{{width:8px;height:8px;border-radius:50%;background:var(--primary,#3b82f6);margin-top:6px;flex-shrink:0;}}
    .notif-panel-item:not(.unread) .notif-panel-dot{{background:transparent;}}
    .notif-panel-content{{flex:1;min-width:0;}}
    .notif-panel-msg{{font-size:.85rem;color:var(--gray-900,#111);line-height:1.4;word-break:break-word;}}
    .notif-panel-date{{font-size:.7rem;color:var(--gray-500,#999);margin-top:4px;}}
    .notif-panel-empty{{padding:36px 16px;text-align:center;color:var(--gray-500,#999);font-size:.85rem;}}
    .notif-panel-footer{{display:block;text-align:center;padding:11px;font-size:.8rem;font-weight:600;color:var(--primary,#3b82f6);text-decoration:none;border-top:1px solid var(--gray-100,#f1f1f1);background:var(--gray-50,#fafafa);}}
    .notif-panel-footer:hover{{text-decoration:underline;}}
    .push-banner{{display:none;align-items:center;gap:12px;position:fixed;left:16px;right:16px;bottom:16px;max-width:460px;margin:0 auto;background:#111827;color:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 14px 34px rgba(15,23,42,.28);z-index:3000;}}
    .push-banner-text{{flex:1;font-size:.82rem;line-height:1.4;}}
    .push-banner-btn{{background:var(--primary,#3b82f6);color:#fff;border:none;padding:8px 14px;border-radius:8px;font-size:.8rem;font-weight:700;cursor:pointer;white-space:nowrap;flex-shrink:0;}}
    .push-banner-btn:hover{{filter:brightness(1.08);}}
    .push-banner-close{{background:none;border:none;color:rgba(255,255,255,.6);cursor:pointer;padding:4px;flex-shrink:0;display:inline-flex;}}
    .push-banner-close:hover{{color:#fff;}}
    @media(max-width:640px){{ .push-banner{{ left:10px;right:10px;bottom:10px;flex-wrap:wrap; }} }}
    @media(max-width:640px){{
        .notif-panel-backdrop{{z-index:2000;}}
        .notif-panel{{position:fixed;top:auto;bottom:0;left:0;right:0;width:100%;max-width:100%;max-height:80vh;border-radius:20px 20px 0 0;transform:translateY(100%);z-index:2001;box-shadow:0 -10px 40px rgba(15,23,42,.25);}}
        body.notif-open .notif-panel{{transform:translateY(0);}}
        .notif-panel-header{{padding:16px 18px;}}
    }}
    </style>
    <script>
    function toggleSidebar(){{ document.body.classList.toggle('sidebar-open'); }}
    function closeSidebar(){{ document.body.classList.remove('sidebar-open'); }}
    var _notifLoaded = false;
    function toggleNotifPanel(ev){{
        if(ev){{ ev.stopPropagation(); }}
        var isOpen = document.body.classList.contains('notif-open');
        if(isOpen){{ closeNotifPanel(); }} else {{ openNotifPanel(); }}
    }}
    function openNotifPanel(){{
        document.body.classList.add('notif-open');
        document.getElementById('notifBellBtn').setAttribute('aria-expanded','true');
        if(!_notifLoaded){{ loadNotifPanel(); }}
    }}
    function closeNotifPanel(){{
        document.body.classList.remove('notif-open');
        document.getElementById('notifBellBtn').setAttribute('aria-expanded','false');
    }}
    function loadNotifPanel(){{
        fetch('/api/notifications_panel').then(function(r){{ return r.json(); }}).then(function(data){{
            _notifLoaded = true;
            var body = document.getElementById('notifPanelBody');
            var notifs = data.notifs || [];
            if(notifs.length === 0){{
                body.innerHTML = '<div class="notif-panel-empty">Aucune notification.</div>';
            }} else {{
                var html = '';
                for(var i=0; i<notifs.length; i++){{
                    var n = notifs[i];
                    var date = (n.created_at || '').substring(0,16).replace('T',' ');
                    var msg = String(n.message || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
                    html += '<div class="notif-panel-item ' + (n.lu ? '' : 'unread') + '">' +
                            '<span class="notif-panel-dot"></span>' +
                            '<div class="notif-panel-content">' +
                            '<div class="notif-panel-msg">' + msg + '</div>' +
                            '<div class="notif-panel-date">' + date + '</div>' +
                            '</div></div>';
                }}
                body.innerHTML = html;
            }}
            // Le panneau vient d'être ouvert et marque les notifs comme lues côté serveur : on vide le badge.
            var badge = document.getElementById('notifBadge');
            if(badge){{ badge.style.display = 'none'; badge.textContent = ''; }}
        }}).catch(function(){{
            document.getElementById('notifPanelBody').innerHTML = '<div class="notif-panel-empty">Impossible de charger les notifications.</div>';
        }});
    }}
    document.addEventListener('keydown', function(e){{ if(e.key === 'Escape'){{ closeSidebar(); closeNotifPanel(); }} }});

    // 🆕 Notifications Push (navigateur / téléphone) ────────────────────────────
    function fermerPushBanner(){{
        var b = document.getElementById('pushBanner');
        if(b) b.style.display = 'none';
        try {{ localStorage.setItem('pushRefuse', '1'); }} catch(e) {{}}
    }}
    (function(){{
        var VAPID_PUBLIC_KEY = "{VAPID_PUBLIC_KEY_B64}";
        if(!VAPID_PUBLIC_KEY || !('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)){{ return; }}

        function urlB64ToUint8Array(base64String){{
            var padding = '='.repeat((4 - base64String.length % 4) % 4);
            var base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
            var rawData = window.atob(base64);
            var outputArray = new Uint8Array(rawData.length);
            for(var i = 0; i < rawData.length; ++i){{ outputArray[i] = rawData.charCodeAt(i); }}
            return outputArray;
        }}
        function envoyerAbonnementServeur(sub){{
            fetch('/api/push/subscribe', {{
                method: 'POST',
                headers: {{'Content-Type': 'application/json'}},
                body: JSON.stringify(sub)
            }}).catch(function(){{}});
        }}
        function sAbonner(){{
            navigator.serviceWorker.ready.then(function(reg){{
                return reg.pushManager.subscribe({{
                    userVisibleOnly: true,
                    applicationServerKey: urlB64ToUint8Array(VAPID_PUBLIC_KEY)
                }});
            }}).then(function(sub){{
                envoyerAbonnementServeur(sub.toJSON());
                fermerPushBanner();
            }}).catch(function(err){{
                console.warn('Abonnement notifications push impossible :', err);
            }});
        }}
        window._activerNotifsPush = function(){{
            Notification.requestPermission().then(function(permission){{
                if(permission === 'granted'){{ sAbonner(); }}
                else {{ fermerPushBanner(); }}
            }});
        }};

        navigator.serviceWorker.register('/sw.js').then(function(reg){{
            if(Notification.permission === 'granted'){{
                reg.pushManager.getSubscription().then(function(sub){{
                    if(!sub){{ sAbonner(); }} else {{ envoyerAbonnementServeur(sub.toJSON()); }}
                }});
            }} else if(Notification.permission === 'default'){{
                var refuse = false;
                try {{ refuse = localStorage.getItem('pushRefuse') === '1'; }} catch(e) {{}}
                if(!refuse){{
                    var banniere = document.getElementById('pushBanner');
                    if(banniere) banniere.style.display = 'flex';
                }}
            }}
        }}).catch(function(err){{ console.warn('Service worker non enregistré :', err); }});
    }})();

    if(window.lucide){{ lucide.createIcons(); }}
    </script>
    """


# Pages exclues de la traduction arabe (restent toujours en français, sur demande) :
# fiches/annuaires Élèves, Enseignants, Parents, Personnel hors-prof, Historique, Utilisateurs.
EXCLUDED_LANG_PREFIXES = (
    '/eleves', '/enseignants', '/espace-enseignant',
    '/parents', '/admin/parents', '/espace-parent',
    '/personnel-hors-prof', '/historique', '/utilisateurs',
)


def _is_lang_excluded(path):
    return any(path == p or path.startswith(p + '/') or path.startswith(p + '?') for p in EXCLUDED_LANG_PREFIXES)


# Override render_template_string to auto-inject nav + appliquer la traduction FR/AR
_orig_rts = render_template_string


def render_template_string(source, **context):
    from flask import get_flashed_messages
    nc = context.get('notif_count', 0)
    session_lang = get_lang()
    effective_lang = 'fr' if _is_lang_excluded(request.path) else session_lang
    nav = nav_html(request.path, nc, effective_lang)
    context['nav_html'] = nav
    context['lang'] = effective_lang
    html_out = _orig_rts(source, **context)
    html_out = translate_html(html_out, effective_lang)
    return html_out


@app.route('/set-language/<lang>')
def set_language(lang):
    if lang in ('fr', 'ar'):
        session['lang'] = lang
    dest = request.referrer or url_for('dashboard')
    return redirect(dest)



