# eleve hub
ELEVES_HUB_HTML = """<!DOCTYPE html><html><head><title>Choix du Cycle - Élèves</title>""" + BASE_CSS + MACOS_CSS + """</head><body class="page-cyclehub"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Gestion des Élèves';</script>
<div class="container" style="padding-top: 20px;">
  <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; margin-bottom:10px;">
    <div>
      <h2 style="font-size:1.6rem; font-weight:700; margin-bottom:6px; color:#000;">👥 Sélectionner un cycle pour les Éléves</h2>
      <p class="text-muted" style="margin:0;">Choisissez un cycle d'enseignement pour accéder aux listes d'élèves.</p>
    </div>
    {% if session.role in ('admin', 'agent_admin') %}
    <div style="display:flex; gap:10px; flex-wrap:wrap;">
      <a href="/eleves/add" class="btn btn-primary" style="text-decoration:none;">➕ Nouvel élève</a>
      <a href="/eleves/importer" class="btn btn-outline" style="text-decoration:none;">📥 Importer Excel</a>
      <button type="button" class="btn btn-primary" onclick="document.getElementById('modal-add-cycle').style.display='flex'">➕ Ajouter un cycle</button>
    </div>
    {% endif %}
  </div>

  <div class="grid-3" style="gap: 30px; margin-top: 30px;">

    {% for c in cycles %}
    <div style="position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px; background:transparent; transition:all 0.2s;">
      {% if session.role in ('admin', 'agent_admin') %}
      <button type="button" onclick="event.stopPropagation(); confirmDeleteCycle({{ c.id }}, '{{ c.nom|replace("'", "\\\\'") }}')" title="Supprimer ce cycle" style="position:absolute; top:10px; right:10px; width:28px; height:28px; border-radius:50%; border:none; background:var(--red-light); color:var(--red); cursor:pointer; font-size:0.9rem; line-height:1; z-index:2;">✕</button>
      <button type="button" onclick="event.stopPropagation(); openPhotoCycle({{ c.id }}, '{{ c.nom|replace("'", "\\\\'") }}', {{ 'true' if c.photo else 'false' }})" title="Changer la photo de ce cycle" style="position:absolute; top:10px; left:10px; width:28px; height:28px; border-radius:50%; border:none; background:var(--blue-light,#e8f1ff); color:var(--blue); cursor:pointer; font-size:0.9rem; line-height:1; z-index:2;">📷</button>
      {% endif %}
      <a href="?cycle={{ c.nom }}" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; text-decoration:none; width:100%;">
        <div style="display:flex; justify-content:center; margin-bottom:15px;">{{ cycle_icon_html(c, '180px', '6px') }}</div>
        <h3 style="color:var(--gray-900); font-size:1.4rem;">{{ c.nom }}</h3>
        <span class="badge" style="margin-top:10px; background:var(--{{ c.couleur }}-light, var(--gray-100)); color:var(--{{ c.couleur }});">Élèves {{ c.nom }}</span>
      </a>
    </div>
    {% endfor %}

    <div style="position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px; background:transparent; transition:all 0.2s;">
      <a href="?tous=1" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; text-decoration:none; width:100%;">
        <div style="display:flex; justify-content:center; margin-bottom:15px;">
          <div style="width:180px;height:180px;border-radius:50%;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;background:#fff;border:6px solid var(--purple, #FFD60A);box-shadow:0 4px 14px rgba(0,0,0,.18), inset 0 0 0 3px rgba(255,255,255,.75);flex-shrink:0;">
            <span style="font-size:90px; line-height:1;">👥</span>
          </div>
        </div>
        <h3 style="color:var(--gray-900); font-size:1.4rem;">Tous les élèves</h3>
        <span class="badge badge-purple" style="margin-top:10px;">Tous cycles et classes confondus</span>
      </a>
    </div>

  </div>
</div>

{% if session.role in ('admin', 'agent_admin') %}
<!-- 🆕 Modal Ajout d'un cycle -->
<div id="modal-add-cycle" style="display:none; position:fixed; inset:0; background:rgba(0,0,0,.5); align-items:center; justify-content:center; z-index:1000;">
  <div class="card" style="width:95%; max-width:420px; padding:25px;">
    <h3 style="margin-top:0; margin-bottom:20px; color:var(--gray-900); font-weight:700;">➕ Ajouter un cycle</h3>
    <form method="POST" action="{{ url_for('cycles_action') }}" enctype="multipart/form-data">
      <input type="hidden" name="action" value="add">
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Nom du cycle</label>
        <input type="text" name="nom" required placeholder="ex: Lycée" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
      </div>
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Icône (emoji)</label>
        <input type="text" name="icone" value="🏫" maxlength="4" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
      </div>
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Photo (optionnel — remplace l'icône)</label>
        <input type="file" name="photo" accept="image/*" style="width:100%; padding:8px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
      </div>
      <div class="form-group" style="margin-bottom:20px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Couleur</label>
        <select name="couleur" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
          <option value="blue-mid">Bleu</option>
          <option value="green">Vert</option>
          <option value="amber">Ambre</option>
          <option value="purple">Violet</option>
          <option value="red">Rouge</option>
        </select>
      </div>
      <div style="display:flex; justify-content:flex-end; gap:10px;">
        <button type="button" onclick="document.getElementById('modal-add-cycle').style.display='none'" class="btn btn-outline">Annuler</button>
        <button type="submit" class="btn btn-primary">💾 Ajouter</button>
      </div>
    </form>
  </div>
</div>

<!-- 🆕 Modal Changer la photo d'un cycle existant -->
<div id="modal-photo-cycle" style="display:none; position:fixed; inset:0; background:rgba(0,0,0,.5); align-items:center; justify-content:center; z-index:1000;">
  <div class="card" style="width:95%; max-width:420px; padding:25px;">
    <h3 style="margin-top:0; margin-bottom:5px; color:var(--gray-900); font-weight:700;">📷 Photo du cycle</h3>
    <p class="text-muted" id="photo-cycle-nom" style="margin-top:0; margin-bottom:20px;"></p>
    <form method="POST" action="{{ url_for('cycles_action') }}" enctype="multipart/form-data">
      <input type="hidden" name="action" value="photo">
      <input type="hidden" name="cycle_id" id="photo-cycle-id" value="">
      <div class="form-group" style="margin-bottom:20px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Choisir une image</label>
        <input type="file" name="photo" accept="image/*" required style="width:100%; padding:8px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
      </div>
      <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
        <button type="button" id="photo-cycle-remove-btn" onclick="removePhotoCycle()" class="btn btn-outline" style="display:none;">🗑️ Retirer la photo</button>
        <div style="display:flex; gap:10px; margin-left:auto;">
          <button type="button" onclick="document.getElementById('modal-photo-cycle').style.display='none'" class="btn btn-outline">Annuler</button>
          <button type="submit" class="btn btn-primary">💾 Enregistrer</button>
        </div>
      </div>
    </form>
  </div>
</div>

<!-- 🆕 Formulaire caché de suppression de photo, soumis via removePhotoCycle() -->
<form id="form-remove-photo-cycle" method="POST" action="{{ url_for('cycles_action') }}" style="display:none;">
  <input type="hidden" name="action" value="remove_photo">
  <input type="hidden" name="cycle_id" id="remove-photo-cycle-id" value="">
</form>

<!-- 🆕 Formulaire caché de suppression, soumis via confirmDeleteCycle() -->
<form id="form-delete-cycle" method="POST" action="{{ url_for('cycles_action') }}" style="display:none;">
  <input type="hidden" name="action" value="delete">
  <input type="hidden" name="cycle_id" id="delete-cycle-id" value="">
</form>
<script>
function confirmDeleteCycle(id, nom) {
    if (confirm('Supprimer le cycle « ' + nom + ' » ?\\n\\n(Impossible si des classes y sont encore rattachées.)')) {
        document.getElementById('delete-cycle-id').value = id;
        document.getElementById('form-delete-cycle').submit();
    }
}
function openPhotoCycle(id, nom, aUnePhoto) {
    document.getElementById('photo-cycle-id').value = id;
    document.getElementById('photo-cycle-nom').textContent = nom;
    document.getElementById('photo-cycle-remove-btn').style.display = aUnePhoto ? 'inline-flex' : 'none';
    document.getElementById('modal-photo-cycle').style.display = 'flex';
}
function removePhotoCycle() {
    if (confirm('Retirer la photo de ce cycle et revenir à l\\'emoji ?')) {
        document.getElementById('remove-photo-cycle-id').value = document.getElementById('photo-cycle-id').value;
        document.getElementById('form-remove-photo-cycle').submit();
    }
}
</script>
{% endif %}

</div></div></body></html>"""
